## BL808 BLAI/CNN NPU integration helpers.
##
## The public BL808 SDK exposes BLAI through MM clock/reset control, SRAM
## ownership, and codec bus/QoS registers. The neural-network layer programming
## path is instruction-stream based, so this module avoids pretending that the
## BLAI aperture contains simple convolution layer dimension registers.

from std/volatile import volatileLoad, volatileStore

import memmap

when defined(bl808d0) or defined(bl808m0) or defined(bl808lp):
  import core

# =============================================================================
# SDK-documented BLAI integration registers
# =============================================================================
const
  BlaiMaxInputNum*      = 8
  BlaiMaxInputNumU32*   = 8'u32
  BlaiMaxRouteInputNumU32* = BlaiMaxInputNumU32 - 1'u32
  BlaiMaxYoloMaskNum*   = 3
  BlaiMaxYoloMaskNumU32* = 3'u32
  BlaiMaxYoloTotal*     = 16
  BlaiMaxYoloTotalU32*  = 16'u32
  BlaiMaxYoloBiasNum*   = BlaiMaxYoloTotal * 2
  BlaiMaxYoloBiasNumU32* = BlaiMaxYoloTotalU32 * 2'u32
  BlaiCpuYoloInfoMaskBaseBit* = 16
  BlaiCpuYoloInfoMaskStrideBits* = 3
  BlaiCpuYoloInfoMaskBits* = 3
  BlaiCpuYoloInfoBiasWidthBaseBit* = 28
  BlaiCpuYoloInfoBiasHeightBaseBit* = 38
  BlaiCpuYoloInfoBiasStrideBits* = 20
  BlaiCpuYoloInfoBiasBits* = 10
  BlaiCpuExtraLayerMemBaseBit* = 5
  BlaiCpuExtraLayerMemStrideBits* = 7
  BlaiCpuExtraLayerMemBits* = 7
  BlaiCpuExtraLayerTfliteChannelsBaseBit* = 26
  BlaiCpuExtraLayerTfliteChannelsStrideBits* = 12
  BlaiCpuExtraLayerTfliteChannelsBits* = 12
  BlaiCpuExtraLayerRouteFracBaseBit* = 33
  BlaiCpuExtraLayerRouteFracStrideBits* = 5
  BlaiCpuExtraLayerRouteFracBits* = 5
  BlaiCpuExtraLayerRouteChannelsBaseBit* = 53
  BlaiCpuExtraLayerRouteChannelsStrideBits* = 12
  BlaiCpuExtraLayerRouteChannelsBits* = 12
  BlaiCpuExtraLayerTfliteOffsetBaseBit* = 62
  BlaiCpuExtraLayerTfliteOffsetStrideBits* = 8
  BlaiCpuExtraLayerTfliteOffsetBits* = 8
  BlaiCpuExtraLayerTfliteShiftBaseBit* = 86
  BlaiCpuExtraLayerTfliteShiftStrideBits* = 6
  BlaiCpuExtraLayerTfliteShiftBits* = 6
  BlaiCpuExtraMultiplierBaseBit* = 5
  BlaiCpuExtraMultiplierStrideBits* = 32
  BlaiCpuExtraMultiplierBits* = 32
  BlaiCpuInputLayersBaseBit* = 5
  BlaiCpuInputLayersStrideBits* = 10
  BlaiCpuInputLayersBits* = 10
  BlaiMaxWeightPatches* = 64
  BlaiMaxWeightPatchesU32* = 64'u32
  BlaiInstructionSize*  = 16
  BlaiInstructionScratchSize* = BlaiMaxInputNum * BlaiInstructionSize * 3
  BlaiNpuWeightPack*    = 4'u32
  BlaiNpuTfliteBiasPack* = 1'u32
  BlaiNpuFixedBiasPack* = BlaiNpuWeightPack
  BlaiNpuTemporaryGroupChannelLimit* = 3'u32
  BlaiNpuTemporaryWeightElementBytes* = 4'u32
  BlaiNpuBiasElementBytes* = 4'u32
  BlaiNpuLocalBufferBytes* = 4096'u32
  BlaiMemAllocPsramPatchThresholdBytes* = BlaiNpuLocalBufferBytes
  BlaiMemAllocWeightPatchThresholdBytes* = BlaiNpuLocalBufferBytes * 2'u32
  BlaiMemAllocSearchSlack* = 128'u32
  BlaiFetchMaxPatchSlots* = 30'u32
  BlaiFetchPatchGrowTries* = 5
  BlaiForwardMaxCacheRanges* = BlaiMaxInputNum + 2
  BlaiPsramCtrlSramInOffset* = 0x000
  BlaiPsramCtrlSramIn2Offset* = 0x020
  BlaiPsramCtrlSramOutOffset* = 0x024
  BlaiPsramCtrlSramMidOutOffset* = 0x044
  BlaiPsramCtrlSramWeightOffset* = 0x048
  BlaiPsramCtrlSramBiasOffset* = 0x04C
  BlaiPsramCtrlDepthwiseGroupsOffset* = 0x050
  BlaiPsramCtrlWeightPatchCountOffset* = 0x054
  BlaiPsramCtrlLinePatchCountOffset* = 0x058
  BlaiPsramCtrlLineW0Offset* = 0x05C
  BlaiPsramCtrlWeightPatchOutCOffset* = 0x060
  BlaiPsramCtrlLinePatchWOffset* = 0x160
  BlaiPsramCtrlPsramCountOffset* = 0x260
  BlaiPsramCtrlPsramPatchSizeOffset* = 0x264
  BlaiPsramCtrlPsramPatchCountOffset* = 0x268
  BlaiPsramCtrlPsramMidPatchCountOffset* = 0x26C
  BlaiPsramCtrlSize* = 0x270
  MmCnnClock*       = MmGlbBase + 0x04'u  # MM_GLB_MM_CLK_CPU
  MmCnnReset*       = MmGlbBase + 0x4C'u  # MM_GLB_SW_RESET_CODEC_SUB
  MmVramCtrl*       = MmMiscBase + 0x50'u # MM_MISC_VRAM_CTRL
  MmBlaiCommandStatus* = MmMiscBase + 0x80'u # MM_MISC codec_misc_1
  MmMiscIntSta0*    = MmMiscBase + 0xA0'u # MM_INT_STA0
  MmMiscIntMask0*   = MmMiscBase + 0xA4'u # MM_INT_MASK0
  MmMiscIntClr0*    = MmMiscBase + 0xA8'u # MM_INT_CLR_0
  MmMiscIntSta1*    = MmMiscBase + 0xAC'u # MM_INT_STA1, E907 register view
  MmMiscIntMask1*   = MmMiscBase + 0xB0'u # MM_INT_MASK1, E907 register view
  MmMiscIntClr1*    = MmMiscBase + 0xB4'u # MM_INT_CLR_1, E907 register view

  CodecBusCtrl*     = CodecMiscBase + 0x00'u
  CodecQosCtrl*     = CodecMiscBase + 0x04'u
  CodecBusThreshold* = CodecMiscBase + 0x08'u
  BlaiLimiterRead*  = CodecMiscBase + 0x20'u
  BlaiLimiterWrite* = CodecMiscBase + 0x24'u

# =============================================================================
# BLAI aperture registers observed on hardware
# =============================================================================
const
  BlaiGeneralCfg*   = BlaiBase + 0x00'u # BALI_GENERAL_CFG in SDK headers
  BlaiIntCfg*       = BlaiBase + 0x04'u # BLAI_INT_CFG
  BlaiWeightAddr*   = BlaiBase + 0x10'u
  BlaiBiasAddr*     = BlaiBase + 0x14'u
  BlaiInstAddr*     = BlaiBase + 0x18'u
  BlaiImageAddr*    = BlaiBase + 0x1C'u # APU_DM0_ADDR
  BlaiSegAddr*      = BlaiBase + 0x20'u # APU_DM1_ADDR / image segment count
  BlaiTfCfg0*       = BlaiBase + 0x24'u
  BlaiActTableBase* = BlaiBase + 0x100'u

  # Names used by earlier HAL revisions before the SDK NPU map was recovered.
  BlaiCoreCfg0*     = BlaiGeneralCfg
  BlaiCoreCfg1*     = BlaiIntCfg
  BlaiCoreCfg2*     = BlaiBase + 0x08'u
  BlaiIntClear*     = BlaiIntCfg

  # Legacy aliases retained for code that only needs raw register access.
  NpuCtrl*          = BlaiGeneralCfg
  NpuStatus*        = BlaiIntCfg
  NpuIntSts*        = BlaiIntCfg
  NpuIntClr*        = BlaiIntClear

