  BlaiImgiUnsignShift*  = 0
  BlaiImgiUnsignMask*   = 1'u32 shl BlaiImgiUnsignShift
  BlaiImageModeShift*   = 8
  BlaiImageModeMask*    = 0x03'u32 shl BlaiImageModeShift
  BlaiFtableIndexBaseShift* = 16
  BlaiFtableDataBaseShift* = 24
  BlaiFtableBaseWidth* = 6
  BlaiFtableBaseValueMask* = (1'u32 shl BlaiFtableBaseWidth) - 1'u32
  BlaiFtableIndexBaseMask* =
    BlaiFtableBaseValueMask shl BlaiFtableIndexBaseShift
  BlaiFtableDataBaseMask* =
    BlaiFtableBaseValueMask shl BlaiFtableDataBaseShift
  BlaiActivationTableEntriesPerWord* = 4
  BlaiActivationTableEntryWidth* = 8
  BlaiActivationTableEntryMask* = 0xFF'u32
  BlaiActivationTableBaseOffset* = 0x100'u32
  BlaiActivationTableWordBytes* = 4'u32
  BlaiActivationTableWordCount* = 64'u32
  BlaiAxiWriteIdle*     = 30
  BlaiAxiReadIdle*      = 31
  BlaiAxiWriteIdleMask* = 1'u32 shl BlaiAxiWriteIdle
  BlaiAxiReadIdleMask*  = 1'u32 shl BlaiAxiReadIdle

  BlaiStart*            = 0
  BlaiStop*             = 1
  BlaiResume*           = 2
  BlaiInterruptClear*   = 8
  BlaiInterruptStatus*  = 9
  BlaiReluNShift*       = 16
  BlaiReluNMask*        = 0x1F'u32 shl BlaiReluNShift
