  BlaiStopMask*         = 1'u32 shl BlaiStop
  BlaiResumeMask*       = 1'u32 shl BlaiResume
  BlaiInterruptClearMask* = 1'u32 shl BlaiInterruptClear
  BlaiInterruptStatusMask* = 1'u32 shl BlaiInterruptStatus

  BlaiTensorflowEnable* = 31
  BlaiTensorflowEnableMask* = 1'u32 shl BlaiTensorflowEnable

  NpuCnnIrqOffset* = 39'u32
  NpuCnnIrq* = 16'u32 + NpuCnnIrqOffset
  NpuCnnIrqPreemptPriority* = 7'u8
  NpuCnnIrqSubPriority* = 1'u8
  NpuD0ApuIrqOffset* = NpuCnnIrqOffset
  NpuE907ApuIrqOffset* = NpuCnnIrqOffset
  NpuM0ClicMaxIrq* = 80'u32
  NpuM0ApuHeaderExcluded* = true
  NpuGlbMcuIntSourceCount* = 64'u32
  NpuGlbMcuMmIrqAllSource* = 18'u32
  NpuGlbMcuI2c1Source* = 39'u32
  NpuGlbDspRsv39Source* = 39'u32
  NpuMmAggregateBankCount* = 2'u32
  NpuMmAggregateRawBitmapWidth* = 32'u32
  NpuMmAggregateStdBank0Known* = true
  NpuMmAggregateStdBank1Known* = false
  NpuMmAggregateE907Bank0Known* = true
  NpuMmAggregateE907Bank1Known* = true
  NpuMmAggregateBank0Known* = true
  NpuMmAggregateBank1E907Known* = true
  NpuMmAggregateNamedCnnSubrouteKnown* = false
  NpuMmAggregateNamedNpuSubrouteKnown* = false
  NpuMmAggregateNamedApuSubrouteKnown* = false
  NpuD0ApuIrq* = 16'u32 + NpuCnnIrqOffset
  NpuE907ApuIrq* = 16'u32 + NpuE907ApuIrqOffset
