# =============================================================================
# Compatibility types
# =============================================================================
type
  CnnClockResetRegs* {.bycopy.} = object
    ## Overlay rooted at MM_GLB_MM_CLK_CPU. Only the CNN clock/reset fields are
    ## named; intervening MM_GLB words remain opaque until recovered.
    mmClkCpu*: uint32
    reserved0*: array[17, uint32]
    swResetCodecSub*: uint32

  MmMiscVramRegs* {.bycopy.} = object
    ## Overlay rooted at MM_MISC_VRAM_CTRL.
    vramCtrl*: uint32

  MmMiscBlaiCommandRegs* {.bycopy.} = object
    ## Overlay rooted at MM_MISC codec_misc_1 for the BLAI command counter.
    codecMisc1*: uint32

  MmMiscInterruptRegs* {.bycopy.} = object
    ## Overlay rooted at MM_INT_STA0 for the MM aggregate interrupt surface.
    status0*: uint32
    mask0*: uint32
    clear0*: uint32
    status1*: uint32
    mask1*: uint32
    clear1*: uint32

  CodecMiscRegs* {.bycopy.} = object
    ## Codec bus/QoS/limiter registers used by the SDK BLAI integration path.
    busCtrl*: uint32
    qosCtrl*: uint32
    busThreshold*: uint32
    reserved0*: array[5, uint32]
    blaiLimiterRead*: uint32
    blaiLimiterWrite*: uint32

  BlaiRegs* {.bycopy.} = object
    ## SDK-recovered BLAI aperture. Layer execution is instruction-stream
    ## driven; this block exposes the low-level launch/configuration registers
    ## without inventing high-level layer dimension registers.
    generalCfg*: uint32
    intCfg*: uint32
    reserved0*: array[2, uint32]
    weightAddr*: uint32
    biasAddr*: uint32
    instAddr*: uint32
    imageAddr*: uint32
    imageSeg*: uint32
    tfCfg0*: uint32
    reserved1*: array[54, uint32]
    actTable*: array[64, uint32]

  NpuClockSource* = enum
    npuClk160M = 0
    npuClk240M = 1
    npuClk320M = 2

  NpuImageInputMode* = enum
    npuInputSound = 0
    npuInputYuv400 = 1
    npuInputYuv422 = 2

  NpuLayerType* = enum
    npuConv     = 0
    npuPool     = 1
    npuFC       = 2
    npuEltwise  = 3

  NpuActivation* = enum
    npuActNone    = 0
    npuActRelu    = 1
    npuActRelu6   = 2
    npuActSigmoid = 3

  NpuPoolType* = enum
    npuMaxPool = 0
    npuAvgPool = 1

  NpuError* = enum
    npuOk
    npuTimeout
    npuBusy
    npuUnsupported

  BlaiLayerType* = enum
    ## Layer type values used by the SDK BLAI instruction decoder.
    blaiConvolutional
    blaiMaxpool
    blaiAvgpool
    blaiRoute
    blaiShortcut
    blaiMatmul
    blaiUpsample
    blaiYolo
    blaiSoftmax
    blaiConvMax
    blaiRouteMax
    blaiRouteConv
    blaiRouteUpsample
    blaiReshape
    blaiRouteW
    blaiLogisticLayer
    blaiSsd
    blaiTranspose
    blaiPad
    blaiLogSoftmax
    blaiDequantize
    blaiTransposeLk
    blaiMean
    blaiGather
    blaiCustomLayer
    blaiPreTransconv
    blaiUnknown

  BlaiActivation* = enum
    ## SDK activation enum order from `blai_riscv_common.h`.
    blaiActLeaky
    blaiActRelu
    blaiActLinear
    blaiActRelu6
    blaiActMish
    blaiActElu
    blaiActRelie
    blaiActLogistic
    blaiActRamp
    blaiActTanh
    blaiActPlse
    blaiActLoggy
    blaiActStair
    blaiActHardtan
    blaiActLhtan
    blaiActSelu
    blaiActGelu
    blaiActSwish
    blaiActNormChan
    blaiActNormChanSoftmax
    blaiActNormChanSoftmaxMaxval
    blaiActReluN

  BlaiInstruction* = array[16, uint8]

  BlaiNpuInstructionBundle* {.bycopy.} = object
    ## SDK `blai_instruction_t` layout used by `instruction_encode`.
    instTflite*: BlaiInstruction
    instExtra*: BlaiInstruction
    inst*: BlaiInstruction
    allWrite*: int32
    pbCheck*: int32
    extraInfo*: int32
    useTflite*: int32

  BlaiInstructionEncodeCountResult* = object
    ## Recovered instruction_encode append counts by instruction kind.
    normalCount*: uint32
    tfliteCount*: uint32
    extraCount*: uint32
    emitted*: uint32

  BlaiInstructionEncodeResult* = object
    ## Bounded result for the recovered SDK `instruction_encode` append order.
    fits*: bool
    startCount*: uint32
    endCount*: uint32
    emitted*: uint32

  BlaiSdkInt32Field* = object
    ## Checked projection of decoded unsigned SDK fields to int32 storage.
    value*: int32
    valid*: bool

  BlaiInstructionCountAbi* = object
    ## Checked projection of a recovered instruction count to SDK `instCnt`.
    value*: int32
    valid*: bool

  BlaiAllocatorFieldAbi* = object
    ## Checked projection of recovered allocator fields to SDK int32 fields.
    value*: int32
    valid*: bool

  BlaiLayerIndexAbi* = object
    ## Checked projection of recovered layer-table indexes to SDK int32 fields.
    value*: int32
    valid*: bool

  BlaiCpuRecordIndexAbi* = object
    ## Checked projection of CPU/DSP record indexes to SDK int32 diagnostics.
    value*: int32
    valid*: bool

  BlaiOutputShapeDimAbi* = object
    ## Checked projection of output-shape dimensions to SDK int32 fields.
    value*: int32
    valid*: bool

  BlaiKernelSizeAbi* = object
    ## Checked projection of recovered kernel sizes to SDK int32 fields.
    value*: int32
    valid*: bool

  BlaiCpuExtraLayerFieldAbi* = object
    ## Checked projection of decoded EXTRA_LAYER* fields to SDK int32 storage.
    value*: int32
    valid*: bool

  BlaiCpuYoloInfoFieldAbi* = object
    ## Checked projection of decoded YOLO_INFO fields to SDK int32 storage.
    value*: int32
    valid*: bool

  BlaiCpuSsdInfoFieldAbi* = object
    ## Checked projection of decoded SSD_INFO fields to SDK int32 storage.
    value*: int32
    valid*: bool

  BlaiCpuTfliteRouteMultiplierAbi* = object
    ## Checked composition of split TFLITE route multiplier bits.
    value*: int32
    valid*: bool

  BlaiCpuLayerInfoFieldAbi* = object
    ## Checked projection of decoded LAYER_INFO fields to SDK int32 storage.
    value*: int32
    valid*: bool

  BlaiCpuGeneralFormFieldAbi* = object
    ## Checked projection of decoded GENERAL_FORM fields to SDK int32 storage.
    value*: int32
    valid*: bool

  BlaiCpuDetailGeneralFormFieldAbi* = object
    ## Checked projection of decoded DETAIL_GENERAL_FORM fields to SDK int32 storage.
    value*: int32
    valid*: bool

  BlaiCpuDspStatusInputNumAbi* = object
    ## Checked projection of decoded DSP_STATUS input count to SDK int32 storage.
    value*: int32
    valid*: bool

  BlaiCpuInputLayerFieldAbi* = object
    ## Checked projection of decoded INPUT_LAYERS entries to SDK int32 storage.
    value*: int32
    valid*: bool

  BlaiCpuGraphLayerAbi* = object
    ## Checked projection of INPUT_LAYERS graph-layer bookkeeping.
    value*: int32
    valid*: bool

  BlaiCpuTfliteMultiplierBitsAbi* = object
    ## Localized projection of raw TFLite multiplier bits to SDK int32 storage.
    value*: int32
    valid*: bool

  BlaiCpuBiasBitsAbi* = object
    ## Localized projection of raw CPU bias bits to SDK int32 storage.
    value*: int32
    valid*: bool

  BlaiOutputMismatchIndexAbi* = object
    ## Checked projection of output-compare indexes to SDK int32 diagnostics.
    value*: int32
    valid*: bool

  BlaiFetchEmitResult* = object
    ## Bounded recovered fetch emitter result.
    fits*: bool
    fetchFits*: bool
    memoryPlan*: BlaiFetchMemoryPlan
    instructions*: BlaiInstructionEncodeResult

  BlaiCpuLayerEncodeResult* = object
    ## Recovered bounded `BLAI_encode` wrapper result.
    encoded*: bool
    scratchCleared*: bool
    plan*: BlaiEncodePlan
    fetch*: BlaiFetchEmitResult

  BlaiInstructionBitCursor* = object
    ## Checked bit position inside one recovered 16-byte BLAI instruction.
    bitIndex*: int
    byteIndex*: int
    bitInByte*: int
    mask*: uint8
    valid*: bool

  BlaiInstructionFieldStrideCursor* = object
    ## Checked `base + slot * stride` bitfield projection inside one instruction.
    slotIndex*: int
    baseBit*: int
    widthBits*: int
    endBitExclusive*: int
    valid*: bool

  BlaiNpuShapeDescriptor* = object
    ## Base normal/tflite NPU descriptor dimensions from `blai_instruction_t`.
    layerW*: uint32
    layerH*: uint32
    layerC1*: uint32
    layerC2*: uint32
    layerO*: uint32

  BlaiNpuNormalDescriptor* = object
    ## Normal-quantized descriptor fields recovered after base dimensions.
    shape*: BlaiNpuShapeDescriptor
    fdata*: uint32
    fweight*: uint32
    fbias*: uint32
    froute1*: uint32
    froute2*: uint32
    fout*: uint32
    convSize*: uint32
    activation*: uint32

  BlaiDecodedNormalDescriptorInstruction* = object
    ## Decoded normal main descriptor instruction from a BLAI stream.
    shape*: BlaiNpuShapeDescriptor
    fdata*: uint32
    fweight*: uint32
    fbias*: uint32
    froute1*: uint32
    froute2*: uint32
    fout*: uint32
    convSize*: uint32
    activation*: uint32

  BlaiNpuTfliteDescriptor* = object
    ## TFLite descriptor fields recovered after base dimensions.
    shape*: BlaiNpuShapeDescriptor
    tfInput1Offset*: uint32
    tfInput2Offset*: uint32
    tfOutputOffset*: uint32
    tfOutputShift*: int32
    convSize*: uint32
    activation*: uint32

  BlaiDecodedTfliteDescriptorInstruction* = object
    ## Decoded TFLite main descriptor instruction from a BLAI stream.
    shape*: BlaiNpuShapeDescriptor
    tfInput1Offset*: uint32
    tfInput2Offset*: uint32
    tfOutputOffset*: uint32
    tfOutputShift*: int32
    convSize*: uint32
    activation*: uint32

