    pollingPreserved*: bool
    valid*: bool

  NpuInterruptCoreBindingDecision* = enum
    ## Core-specific binding decision for the recovered SDK CNN IRQ request.
    npuInterruptCoreBindingNone
    npuInterruptCoreBindingM0PollingRequired
    npuInterruptCoreBindingD0ApuCandidate
    npuInterruptCoreBindingActiveCoreReady

  NpuInterruptCoreBindingPolicy* = object
    ## Typed plan for whether the recovered CNN IRQ request can bind locally.
    lineOwnership*: NpuInterruptLineOwnership
    decision*: NpuInterruptCoreBindingDecision
    requested*: bool
    priorityMatched*: bool
    activeCoreUsesPolling*: bool
    d0ApuCandidate*: bool
    m0AliasConflict*: bool
    m0PollingRequired*: bool
    d0BindingCandidate*: bool
    activeCoreBindingVerified*: bool
    activeCoreReady*: bool
    decisionMatchesEvidence*: bool
    valid*: bool

  NpuInterruptBindingOperation* = enum
    ## Recovered SDK IRQ binding side effects represented as typed plan data.
    npuInterruptBindingRegisterHandler
    npuInterruptBindingClearPending
    npuInterruptBindingSetPriority
    npuInterruptBindingEnableIrq

  NpuInterruptBindingOperationBlock* = enum
    ## First gate that prevents applying the recovered IRQ binding sequence.
    npuInterruptBindingOperationNoBlock
    npuInterruptBindingOperationCorePolicy
    npuInterruptBindingOperationRegisterHandler
    npuInterruptBindingOperationClearPending
    npuInterruptBindingOperationSetPriority
    npuInterruptBindingOperationEnableIrq

  NpuInterruptBindingOperationPlan* = object
    ## Concrete interrupt-controller operations that become legal once the core
    ## binding policy says the active core can own the recovered CNN IRQ line.
    policy*: NpuInterruptCoreBindingPolicy
    irq*: uint32
    priority*: uint8
    operationCount*: uint8
    operations*: array[4, NpuInterruptBindingOperation]
    registerHandlerPlanned*: bool
    clearPendingPlanned*: bool
    setPriorityPlanned*: bool
    enableIrqPlanned*: bool
    activeOperationsSuppressed*: bool
    m0PollingPreserved*: bool
    d0CandidatePreserved*: bool
    valid*: bool

  NpuInterruptBindingOperationReadiness* = object
    ## Readiness projection for the recovered SDK IRQ binding side effects.
    policyValid*: bool
    activeCoreReady*: bool
    m0PollingRequired*: bool
    operationCount*: uint8
    operationSequenceKnown*: bool
    operationsPlanned*: bool
    activeOperationsSuppressed*: bool
    hasDeferredOperation*: bool
    firstDeferredOperation*: NpuInterruptBindingOperation
    firstBlock*: NpuInterruptBindingOperationBlock
    ready*: bool

  NpuInterruptBindingApiContract* = object
    ## Typed contract mapping recovered SDK IRQ side effects to HAL IRQ APIs.
    ##
    ## This remains plan data: it proves the operation sequence can be expressed
    ## through existing typed interrupt wrappers, while active M0 execution keeps
    ## those calls deferred until the CNN/APU local route is verified.
    planValid*: bool
    irqMatchesPlan*: bool
    priorityMatchesPlan*: bool
    sdkPriorityMatches*: bool
    registerHandlerApi*: bool
    clearPendingApi*: bool
    setLevelApi*: bool
    enableIrqApi*: bool
    apiSequenceComplete*: bool
    activeCallsDeferred*: bool
    m0PollingPreserved*: bool
    d0RoutePreserved*: bool
    contractMatchesPlan*: bool
    valid*: bool

  NpuInterruptBindingReadiness* = object
    ## Typed gate for binding the recovered CNN IRQ request to local hardware.
    ##
    ## The SDK asks for `CNN_IRQn` priority 7,1. This HAL keeps that request as
    ## data until the core-local interrupt source/mux ownership is verified;
    ## completion therefore remains on the polling wait primitive.
    requested*: bool
    irqMatchesSdk*: bool
    priorityMatchesSdk*: bool
    enableRequested*: bool
    lineOwnership*: NpuInterruptLineOwnership
    corePolicy*: NpuInterruptCoreBindingPolicy
    operationPlan*: NpuInterruptBindingOperationPlan
    apiContract*: NpuInterruptBindingApiContract
    d0ApuLineCandidate*: bool
    m0LineConflict*: bool
    m0BindingSafe*: bool
    activeWaitIsPolling*: bool
    bindingVerified*: bool
    ready*: bool

  NpuNetParams* = object
    ## Net-wide BLAI parameters programmed before instruction-stream execution.
    unsignedInput*: bool
    reluN*: uint32
    tensorflowMode*: bool

  NpuNetParamFieldKind* = enum
    ## Single recovered BLAI net-parameter field update.
    npuNetParamImageInputMode
    npuNetParamUnsignedInput
    npuNetParamReluN
    npuNetParamTensorflowMode

  NpuNetParamFieldPlan* = object
    ## Pure single-register field update for public net-parameter setters.
    kind*: NpuNetParamFieldKind
    initial*: uint32
    imageInputMode*: NpuImageInputMode
    enabled*: bool
    reluN*: uint32
    encoded*: uint32
    generalDecode*: NpuGeneralCfgDecode
    intDecode*: NpuIntCfgDecode
    tfDecode*: NpuTfCfgDecode
    valid*: bool

  NpuNetParamRegisterPlan* = object
    ## Pure register-word plan for applying net-wide BLAI execution parameters.
    params*: NpuNetParams
    initialGeneralCfg*: uint32
    initialIntCfg*: uint32
    initialTfCfg0*: uint32
    generalCfg*: uint32
    intCfg*: uint32
    tfCfg0*: uint32
    generalDecode*: NpuGeneralCfgDecode
    intDecode*: NpuIntCfgDecode
    tfDecode*: NpuTfCfgDecode
    valid*: bool

  NpuInitConfig* = object
    ## SDK `blai_npu_initCfg` arguments after model/pointer recovery.
    buffers*: NpuLayerBuffers
    inputBufferAddr*: uint32
    patchSize*: uint32
    netParams*: NpuNetParams
    interrupt*: NpuInterruptConfig

  NpuInitConfigRegisterPlan* = object
    ## Register-programming subset of SDK `blai_npu_initCfg`.
    config*: NpuInitConfig
    launch*: NpuLaunchRegisterPlan
    netParams*: NpuNetParamRegisterPlan
    interruptRequested*: bool
    interruptDeferred*: bool
    valid*: bool

  NpuConvCompatibilityStatus* = enum
    ## Result of adapting the legacy dimension-based convolution facade to the
    ## recovered BL808 BLAI instruction-stream hardware interface.
    npuConvInvalidDimensions
    npuConvRequiresInstructionStream

  NpuConvCompatibilityBlock* = enum
    ## First gate that prevents the legacy dimension-based convolution facade
    ## from becoming a runnable BL808 BLAI stream.
    npuConvCompatibilityNoBlock
    npuConvCompatibilityAddressSubset
    npuConvCompatibilityDimensions
    npuConvCompatibilityInstructionStream

  NpuConvCompatibilityPlan* = object
    ## Typed compatibility plan for the legacy `npuConfigureConvLayer` facade.
    ##
    ## BL808 BLAI has recovered instruction, weight, bias, and input buffer
    ## registers, but no validated direct dimension registers. This records the
    ## legacy convolution arguments, the register-backed subset that can be
    ## applied faithfully, and the reason the layer is not directly runnable.
    inputAddr*, outputAddr*, weightAddr*, biasAddr*: uint32
    inputW*, inputH*, inputC*: uint32
    outputC*: uint32
    kernelW*, kernelH*: uint32
    strideW*, strideH*: uint32
    padW*, padH*: uint32
    activation*: NpuActivation
    layerConfig*: NpuLayerConfig
    hasInputBuffer*: bool
    hasOutputBuffer*: bool
    hasWeightBuffer*: bool
    hasBiasBuffer*: bool
    outputBufferPlanOnly*: bool
    addressConfigurable*: bool
    registerBackedAddressCount*: uint32
    planOnlyAddressCount*: uint32
    nonzeroDimensions*: bool
    squareKernel*: bool
    squareStride*: bool
    squarePadding*: bool
    descriptorDimensionsRepresentable*: bool
    requiresInstructionStream*: bool
    directlyRunnable*: bool
    firstBlock*: NpuConvCompatibilityBlock
    status*: NpuConvCompatibilityStatus

  NpuConvCompatibilityApplyResult* = object
    ## Register-side effects applied for a legacy conv compatibility plan.
    addressConfigurable*: bool
    outputBufferPlanOnly*: bool
    layerBuffersApplied*: bool
    inputBufferApplied*: bool
    outputBufferApplied*: bool
    instructionStreamCleared*: bool
    applied*: bool
    firstBlock*: NpuConvCompatibilityBlock

  NpuConvCompatibilityEvidence* = object
    ## Focused evidence for the legacy dimension-based conv facade boundary.
    ## The facade can apply recovered address registers, but dimensions remain
    ## plan-only until an encoded BLAI instruction stream is materialized.
    planAddressConfigurable*: bool
    applyAddressConfigurable*: bool
    registerBackedAddresses*: bool
    outputPlanOnly*: bool
    dimensionsRepresentable*: bool
    instructionStreamRequired*: bool
    notDirectlyRunnable*: bool
    streamStateCleared*: bool
    applyMatchesPlan*: bool
    boundaryMatchesRecoveredHardware*: bool
    valid*: bool

  NpuInstructionStreamGuardEvidence* = object
    ## Focused evidence that configured-stream state is the only recovered
    ## legacy layer-run start gate, and that the dimension facade clears it.
    configuredStateCaptured*: bool
    configuredWrapperRunnable*: bool
    configuredReadinessFirstBlockClean*: bool
    configuredReadinessTimeoutCaptured*: bool
    configuredReadinessRunnable*: bool
    configuredReadinessMatchesState*: bool
    facadeClearedStream*: bool
    clearedWrapperBlocked*: bool
    clearedReadinessTimeoutCaptured*: bool
    clearedReadinessBlocked*: bool
    facadeInvalidatedConfiguredStream*: bool
    blockedRunNotStarted*: bool
    blockedRunUnsupported*: bool
    blockedRunWaitPlanNotConfigured*: bool
    guardMatchesRecoveredHardware*: bool
    valid*: bool

  BlaiReleaseLayerBlock* = enum
    ## First gate that prevents recovered release-layer analysis from completing.
    blaiReleaseLayerNoBlock
    blaiReleaseLayerReleaseListOverflow
    blaiReleaseLayerGraphMapOverflow

  BlaiReleaseLayerPlan* = object
    ## Bounded result for SDK `assign_release_layer` analysis.
    layerCount*: uint32
    graphMapFits*: bool
    releaseFits*: bool
    releaseLayerCount*: uint32
    releaseMidLayerCount*: uint32
    firstGraphMapOverflowLayer*: int32
    firstReleaseOverflowLayer*: int32
    firstBlock*: BlaiReleaseLayerBlock
    complete*: bool

  BlaiReleaseSlotCursor* = object
    ## Checked cursor for one fixed release-layer ABI array slot.
    slotIndex*: int
    valid*: bool

  BlaiGraphLayerMapCursor* = object
    ## Checked cursor from signed graph-layer id to caller-owned map storage.
    graphLayer*: int32
    mapIndex*: int
    valid*: bool

  BlaiCpuOutputShapeBlock* = enum
    ## First gate that prevents recovered `set_output_wh_later` side effects.
    blaiOutputShapeNoBlock
    blaiOutputShapeUnsupportedLayer
    blaiOutputShapeMissingTransposeMask
    blaiOutputShapeMissingPadBias
    blaiOutputShapeInvalidDimensions
    blaiOutputShapeInvalidTransposeLkParams

  BlaiCpuOutputShapeResult* = object
    ## Result for recovered CPU parser output-shape side effects.
    layerType*: BlaiLayerType
    supported*: bool
    updated*: bool
    fits*: bool
    firstBlock*: BlaiCpuOutputShapeBlock
    outputW*: uint32
    outputH*: uint32
    outputC*: uint32

  BlaiForwardEncodedLayerReadiness* = object
    ## Per-layer gate from parsed CPU records to encoded forward_NPU state.
    npuLayer*: bool
    patchReady*: bool
    instructionReady*: bool
    ready*: bool

  BlaiParsedForwardModelReadiness* = object
    ## Gate from parsed CPU records to post-encoder forward_NPU planning.
    parsed*: bool
    useTflite*: bool
    netParams*: NpuNetParams
    layerCount*: uint32
    layerStorageFits*: bool
    missingLayerCount*: uint32
    npuLayerCount*: uint32
    readyLayerCount*: uint32
    unencodedLayerCount*: uint32
    firstUnencodedLayer*: int32
    lastReadyLayer*: int32
    firstUnencodedLayerCaptured*: bool
    firstUnencodedLayerReadiness*: BlaiForwardEncodedLayerReadiness
    forwardReady*: bool

  BlaiParsedForwardModelPlan* = object
    ## Resource/workspace plan produced from parsed CPU records after encoding.
    readiness*: BlaiParsedForwardModelReadiness
    planned*: bool
    workspaceReady*: bool
    resources*: BlaiForwardModelResourcePlan
    workspace*: BlaiForwardModelWorkspacePlan

  BlaiParsedForwardModelExecuteBlock* = enum
    ## First parsed-model workspace execution gate that prevents entry.
    blaiParsedForwardModelExecuteNoBlock
    blaiParsedForwardModelExecuteParsed
    blaiParsedForwardModelExecuteForward
    blaiParsedForwardModelExecutePlan
    blaiParsedForwardModelExecuteWorkspace
    blaiParsedForwardModelExecuteWorkspaceBacking

  BlaiParsedForwardModelExecuteReadiness* = object
    ## Gate from parsed/encoded model state to reusable-workspace execution.
    parsedComplete*: bool
    forwardReady*: bool
    planMatchesLayers*: bool
    workspaceReady*: bool
    workspaceFits*: bool
    layerCount*: uint32
    expectedLayerCount*: uint32
    layerStorageFits*: bool
    missingLayerCount*: uint32
    workspaceExecution*: BlaiForwardModelWorkspaceExecuteReadiness
    firstBlock*: BlaiParsedForwardModelExecuteBlock
    executable*: bool

  BlaiParsedForwardModelExecuteResult* = object
    ## Execution result for a parsed, encoded CPU model layer table.
    plan*: BlaiParsedForwardModelPlan
    readiness*: BlaiParsedForwardModelExecuteReadiness
    workspaceFits*: bool
    firstBlock*: BlaiParsedForwardModelExecuteBlock
    executable*: bool
    execution*: BlaiForwardModelWorkspaceExecuteResult

  BlaiCpuModelForwardWorkspaceParsePlan* = object
    ## Combined raw CPU-stream parse and parsed-model workspace plan.
    parsed*: BlaiCpuModelParseResult
    plan*: BlaiParsedForwardModelPlan

