static:
  doAssert offsetof(CnnClockResetRegs, mmClkCpu) == 0x00
  doAssert offsetof(CnnClockResetRegs, swResetCodecSub) == 0x48
  doAssert sizeof(CnnClockResetRegs) == 0x4C

  doAssert offsetof(MmMiscVramRegs, vramCtrl) == 0x00
  doAssert sizeof(MmMiscVramRegs) == 0x04

  doAssert offsetof(MmMiscBlaiCommandRegs, codecMisc1) == 0x00
  doAssert sizeof(MmMiscBlaiCommandRegs) == 0x04

  doAssert offsetof(MmMiscInterruptRegs, status0) == 0x00
  doAssert offsetof(MmMiscInterruptRegs, mask0) == 0x04
  doAssert offsetof(MmMiscInterruptRegs, clear0) == 0x08
  doAssert offsetof(MmMiscInterruptRegs, status1) == 0x0C
  doAssert offsetof(MmMiscInterruptRegs, mask1) == 0x10
  doAssert offsetof(MmMiscInterruptRegs, clear1) == 0x14
  doAssert sizeof(MmMiscInterruptRegs) == 0x18

  doAssert offsetof(CodecMiscRegs, busCtrl) == 0x00
  doAssert offsetof(CodecMiscRegs, qosCtrl) == 0x04
  doAssert offsetof(CodecMiscRegs, busThreshold) == 0x08
  doAssert offsetof(CodecMiscRegs, blaiLimiterRead) == 0x20
  doAssert offsetof(CodecMiscRegs, blaiLimiterWrite) == 0x24
  doAssert sizeof(CodecMiscRegs) == 0x28

  doAssert offsetof(BlaiRegs, generalCfg) == 0x00
  doAssert offsetof(BlaiRegs, intCfg) == 0x04
