# =============================================================================
# BLAI instruction stream helpers
# =============================================================================
proc blaiInstructionBitCursor*(index: int): BlaiInstructionBitCursor =
  ## Resolve one bit inside a 16-byte BLAI instruction.
  if index < 0 or index >= 128:
    return
  result.bitIndex = index
  result.byteIndex = index div 8
  result.bitInByte = index mod 8
  result.mask = 1'u8 shl result.bitInByte
  result.valid = true

proc blaiInstructionBitCursor*(index: uint32): BlaiInstructionBitCursor =
  ## Resolve one unsigned bit offset inside a 16-byte BLAI instruction.
  if index >= 128'u32:
    return
  result.bitIndex = int(index)
  result.byteIndex = int(index div 8'u32)
  result.bitInByte = int(index mod 8'u32)
  result.mask = 1'u8 shl result.bitInByte
  result.valid = true

proc blaiInstructionFieldStrideCursor*(slotIndex, baseBit, strideBits,
                                       widthBits: int):
    BlaiInstructionFieldStrideCursor =
  ## Resolve one repeated packed instruction field without open-coded offsets.
  if slotIndex < 0 or baseBit < 0 or strideBits < 0 or widthBits <= 0:
    return
  let
    slot = slotIndex.uint64
    baseStart = baseBit.uint64
    stride = strideBits.uint64
    width = widthBits.uint64
  if stride != 0'u64 and slot > high(uint64) div stride:
    return
  let slotOffset = slot * stride
  if slotOffset > high(uint64) - baseStart:
    return
  let base = baseStart + slotOffset
  if width > high(uint64) - base:
    return
  let endExclusive = base + width
  if endExclusive > 128'u64:
    return
  result.slotIndex = slotIndex
  result.baseBit = base.int
  result.widthBits = widthBits
  result.endBitExclusive = endExclusive.int
  result.valid = true

proc blaiBit*(inst: BlaiInstruction, index: range[0 .. 127]): uint32 =
  ## Return one little-endian bit from a 16-byte BLAI instruction.
  let cursor = blaiInstructionBitCursor(uint32(index))
  doAssert cursor.valid
  if (inst[cursor.byteIndex] and cursor.mask) != 0'u8:
    1'u32
  else:
    0'u32

proc blaiBits*(inst: BlaiInstruction, base, len: Natural): uint32 =
  ## Recover the SDK `fetch_info(inst, base, len)` operation without pointer
  ## arithmetic. Bits are numbered little-endian within the 16-byte instruction.
  doAssert base + len <= 128
  var value = 0'u32
  for bit in 0 ..< len:
    value = value or (blaiBit(inst, range[0 .. 127](base + bit)) shl bit)
  value

proc blaiPutBits*(inst: var BlaiInstruction, base, len: Natural, value: uint32) =
  ## Write one recovered NPU instruction bitfield using SDK bit numbering.
  doAssert base + len <= 128
  for bit in 0 ..< len:
    let cursor = blaiInstructionBitCursor(uint32(base + bit))
    doAssert cursor.valid
    if ((value shr bit) and 1'u32) != 0:
      inst[cursor.byteIndex] = inst[cursor.byteIndex] or cursor.mask
    else:
      inst[cursor.byteIndex] = inst[cursor.byteIndex] and not cursor.mask

proc blaiInt32FromBits*(bits: uint32): int32 {.inline.} =
  ## Reinterpret recovered SDK uint32 fields that are stored in signed ABI slots.
  if bits > high(int32).uint32:
    (bits.uint64 - 0x1_0000_0000'u64).int64.int32
  else:
    bits.int32

proc blaiUint32FromInt32Bits*(value: int32): uint32 {.inline.} =
  ## Reinterpret signed ABI slots back to the SDK instruction bit pattern.
  let wide = value.int64
  if wide < 0:
    (wide + 0x1_0000_0000'i64).uint64.uint32
  else:
    wide.uint64.uint32

proc blaiSignedFieldBits*(value: int32): uint32 {.inline.} =
  ## Encode a signed SDK bitfield using the shared int32 bit-pattern projection.
  blaiUint32FromInt32Bits(value)

proc blaiSignedBits*(inst: BlaiInstruction, base: Natural,
                     len: range[1 .. 31]): int32 =
  ## SDK `unsigned_to_signed(fetch_info(...), len)` helper.
  let
    raw = blaiBits(inst, base, len).int64
    sign = 1'i64 shl (len - 1)
  if (raw and sign) != 0:
    (raw - (1'i64 shl len)).int32
  else:
    raw.int32

proc decodeBlaiCpuInstructionType*(inst: BlaiInstruction): BlaiCpuInstructionType =
  ## Decode the 5-bit SDK CPU/DSP instruction record type.
  case blaiBits(inst, 0, 5)
  of BlaiSdkCpuDspHeaderRecord: blaiCpuDspHeader
  of BlaiSdkCpuLayerInfoRecord: blaiCpuLayerInfo
  of BlaiSdkCpuGeneralFormRecord: blaiCpuGeneralForm
  of BlaiSdkCpuDspStatusRecord: blaiCpuDspStatus
  of BlaiSdkCpuYoloInfoRecord: blaiCpuYoloInfo
  of BlaiSdkCpuExtraLayerRecord: blaiCpuExtraLayer
  of BlaiSdkCpuExtraMultiplierRecord: blaiCpuExtraMultiplier
  of BlaiSdkCpuTfliteMultiplierRecord: blaiCpuTfliteMultiplier
  of BlaiSdkCpuTfliteFloatRecord: blaiCpuTfliteFloat
  of BlaiSdkCpuExtraLayer6To8Record: blaiCpuExtraLayer6To8
  of BlaiSdkCpuExtraMultiplier6To8Record: blaiCpuExtraMultiplier6To8
  of BlaiSdkCpuSsdInfoRecord: blaiCpuSsdInfo
  of BlaiSdkCpuInputLayersRecord: blaiCpuInputLayers
  of BlaiSdkCpuDetailGeneralFormRecord: blaiCpuDetailGeneralForm
  else: blaiCpuInstructionUnknown

proc decodeBlaiCpuDspHeader*(inst: BlaiInstruction): BlaiCpuDspHeader =
  ## Decode SDK `DSP_HEADER` fields from the CPU instruction stream.
  result.version = blaiBits(inst, 5, 8)
  result.patchSize = 1'u32 shl blaiBits(inst, 13, 6)
  result.patchCount = blaiBits(inst, 19, 7)
  result.unsignedInput = blaiBits(inst, 26, 1) != 0
  result.reluN = blaiBits(inst, 27, 5)
  result.useTflite = blaiBits(inst, 32, 1) != 0
  result.layerCount = blaiBits(inst, 33, 10)
  if result.version == 0:
    result.appType = blaiBits(inst, 43, 3)
    result.useNpuAccel = blaiBits(inst, 46, 1) != 0
  else:
    result.appType = blaiBits(inst, 43, 5)
    result.useNpuAccel = blaiBits(inst, 48, 1) != 0

proc decodeBlaiCpuLayerInfo*(inst: BlaiInstruction,
                             layer: var BlaiCpuInstLayer64) =
  ## Decode SDK `LAYER_INFO` fields into a recovered CPU-layer ABI object.
  let
    wAbi = blaiCpuLayerInfoFieldAbi(blaiBits(inst, 5, 14))
    hAbi = blaiCpuLayerInfoFieldAbi(blaiBits(inst, 19, 14))
    cAbi = blaiCpuLayerInfoFieldAbi(blaiBits(inst, 33, 13))
    cn0Abi = blaiCpuLayerInfoFieldAbi(blaiBits(inst, 46, 13))
    outCAbi = blaiCpuLayerInfoFieldAbi(blaiBits(inst, 59, 13))
    imgInAbi = blaiCpuLayerInfoFieldAbi(blaiBits(inst, 72, 1))
    inLayer1MemAbi = blaiCpuLayerInfoFieldAbi(blaiBits(inst, 73, 7))
    inLayer2MemAbi = blaiCpuLayerInfoFieldAbi(blaiBits(inst, 80, 7))
    outLayerMemAbi = blaiCpuLayerInfoFieldAbi(blaiBits(inst, 87, 7))
    inputNumAbi = blaiCpuLayerInfoFieldAbi(blaiBits(inst, 94, 4))
    outWAbi = blaiCpuLayerInfoFieldAbi(blaiBits(inst, 98, 14))
    outHAbi = blaiCpuLayerInfoFieldAbi(blaiBits(inst, 112, 14))
  if not wAbi.valid or not hAbi.valid or not cAbi.valid or
      not cn0Abi.valid or not outCAbi.valid or not imgInAbi.valid or
      not inLayer1MemAbi.valid or not inLayer2MemAbi.valid or
      not outLayerMemAbi.valid or not inputNumAbi.valid or
      not outWAbi.valid or not outHAbi.valid:
    return
  layer.w = wAbi.value
  layer.h = hAbi.value
  layer.c = cAbi.value
  layer.outC = outCAbi.value
  layer.imgIn = imgInAbi.value
  layer.inLayer1Mem = inLayer1MemAbi.value
  layer.inLayer2Mem = inLayer2MemAbi.value
  layer.outLayerMem = outLayerMemAbi.value
  layer.inputNum = inputNumAbi.value
  layer.n = layer.inputNum
  layer.outW = outWAbi.value
  layer.outH = outHAbi.value
  layer.cn[0] = if layer.inputNum > 1: cn0Abi.value else: 0

proc decodeBlaiCpuGeneralForm*(inst: BlaiInstruction,
                               useTflite: bool,
                               layer: var BlaiCpuInstLayer64) =
  ## Decode SDK `GENERAL_FORM` fields. Graph/shape side effects done by the C
  ## parser are intentionally not hidden here.
  let
    layerTypeAbi = blaiCpuGeneralFormFieldAbi(blaiBits(inst, 5, 5))
    sizeAbi = blaiCpuGeneralFormFieldAbi(blaiBits(inst, 10, 5))
    activationAbi = blaiCpuGeneralFormFieldAbi(blaiBits(inst, 15, 5))
    strideAbi = blaiCpuGeneralFormFieldAbi(blaiBits(inst, 20, 3) + 1)
    dilationAbi = blaiCpuGeneralFormFieldAbi(blaiBits(inst, 23, 3) + 1)
    groupsAbi = blaiCpuGeneralFormFieldAbi(blaiBits(inst, 26, 12))
  if not layerTypeAbi.valid or not sizeAbi.valid or
      not activationAbi.valid or not strideAbi.valid or
      not dilationAbi.valid or not groupsAbi.valid:
    return
  layer.layerType = layerTypeAbi.value
  layer.size = sizeAbi.value
  layer.activation = activationAbi.value
  layer.stride = strideAbi.value
  layer.dilation = dilationAbi.value
  layer.groups = groupsAbi.value
  if not useTflite:
    let
      fdataAbi = blaiCpuGeneralFormFieldAbi(blaiBits(inst, 38, 5))
      fweightAbi = blaiCpuGeneralFormFieldAbi(blaiBits(inst, 43, 5))
      fbiasAbi = blaiCpuGeneralFormFieldAbi(blaiBits(inst, 48, 5))
      froute1Abi = blaiCpuGeneralFormFieldAbi(blaiBits(inst, 53, 5))
      froute2Abi = blaiCpuGeneralFormFieldAbi(blaiBits(inst, 58, 5))
      foutAbi = blaiCpuGeneralFormFieldAbi(blaiBits(inst, 63, 5))
    if not fdataAbi.valid or not fweightAbi.valid or not fbiasAbi.valid or
        not froute1Abi.valid or not froute2Abi.valid or not foutAbi.valid:
      return
    layer.fdata = fdataAbi.value
    layer.fweight = fweightAbi.value
    layer.fbias = fbiasAbi.value
    layer.froute1 = froute1Abi.value
    layer.froute2 = froute2Abi.value
    layer.fout = foutAbi.value
  else:
    let
      tfInput1OffsetAbi = blaiCpuGeneralFormFieldAbi(blaiBits(inst, 38, 8))
      tfInput2OffsetAbi = blaiCpuGeneralFormFieldAbi(blaiBits(inst, 46, 8))
      tfOutputOffsetAbi = blaiCpuGeneralFormFieldAbi(blaiBits(inst, 66, 8))
      quantizedActivationMinAbi =
        blaiCpuGeneralFormFieldAbi(blaiBits(inst, 80, 8))
      quantizedActivationMaxAbi =
        blaiCpuGeneralFormFieldAbi(blaiBits(inst, 88, 8))
      axisAbi = blaiCpuGeneralFormFieldAbi(blaiBits(inst, 96, 1))
      tfRouteInputShiftAbi = blaiCpuGeneralFormFieldAbi(blaiBits(inst, 97, 6))
      routeMultiplierAbi =
        blaiCpuTfliteRouteMultiplierHighAbi(blaiBits(inst, 103, 16))
      dataTypeAbi = blaiCpuGeneralFormFieldAbi(blaiBits(inst, 119, 2))
    if not tfInput1OffsetAbi.valid or not tfInput2OffsetAbi.valid or
        not tfOutputOffsetAbi.valid or not quantizedActivationMinAbi.valid or
        not quantizedActivationMaxAbi.valid or not axisAbi.valid or
        not tfRouteInputShiftAbi.valid or not routeMultiplierAbi.valid or
        not dataTypeAbi.valid:
      return
    layer.tfInput1Offset = tfInput1OffsetAbi.value
    layer.tfInput2Offset = tfInput2OffsetAbi.value
    layer.tfInput1Shift = blaiSignedBits(inst, 54, 6)
    layer.tfInput2Shift = blaiSignedBits(inst, 60, 6)
    layer.tfOutputOffset = tfOutputOffsetAbi.value
    layer.tfOutputShift = blaiSignedBits(inst, 74, 6)
    layer.quantizedActivationMin = quantizedActivationMinAbi.value
    layer.quantizedActivationMax = quantizedActivationMaxAbi.value
    layer.axis = axisAbi.value
    layer.tfLeftShift = 20
    layer.tfRouteInputShift = tfRouteInputShiftAbi.value
    layer.tfRouteInputMultiplier = routeMultiplierAbi.value
    layer.dataType = dataTypeAbi.value

proc decodeBlaiCpuDetailGeneralForm*(inst: BlaiInstruction,
                                     layer: var BlaiCpuInstLayer64) =
  ## Decode SDK `DETAIL_GENERAL_FORM` fields.
  let
    sizeXAbi = blaiCpuDetailGeneralFormFieldAbi(blaiBits(inst, 5, 10))
    sizeYAbi = blaiCpuDetailGeneralFormFieldAbi(blaiBits(inst, 15, 10))
    strideXAbi = blaiCpuDetailGeneralFormFieldAbi(blaiBits(inst, 25, 3))
    strideYAbi = blaiCpuDetailGeneralFormFieldAbi(blaiBits(inst, 28, 3))
    paddingXAbi = blaiCpuDetailGeneralFormFieldAbi(blaiBits(inst, 31, 9))
    paddingYAbi = blaiCpuDetailGeneralFormFieldAbi(blaiBits(inst, 40, 9))
  if not sizeXAbi.valid or not sizeYAbi.valid or
      not strideXAbi.valid or not strideYAbi.valid or
      not paddingXAbi.valid or not paddingYAbi.valid:
    return
  layer.sizeX = sizeXAbi.value
  layer.sizeY = sizeYAbi.value
  layer.strideX = strideXAbi.value
  layer.strideY = strideYAbi.value
  layer.paddingX = paddingXAbi.value
  layer.paddingY = paddingYAbi.value
  layer.detailLayerForm = 1

proc blaiFloat32FromBits*(bits: uint32): float32

proc decodeBlaiCpuDspStatus*(inst: BlaiInstruction): BlaiCpuDspStatus =
  ## Decode SDK `DSP_STATUS` fields that end one CPU-layer record.
  result.npuOn = blaiBits(inst, 5, 1) != 0
  result.dspOn = blaiBits(inst, 6, 1) != 0
  result.dspEnd = blaiBits(inst, 7, 1) != 0
  result.inputNum = blaiBits(inst, 8, 4)
  result.outputScaleBits = blaiBits(inst, 12, 32)
  result.outputLayer = blaiBits(inst, 44, 1) != 0

proc applyBlaiCpuDspStatus*(status: BlaiCpuDspStatus,
                            layer: var BlaiCpuInstLayer64) =
  ## Apply the SDK `DSP_STATUS` fields that live in `cpu_inst_layer_t`.
  let inputNumAbi = blaiCpuDspStatusInputNumAbi(status.inputNum)
  if not inputNumAbi.valid:
    return
  layer.npuOn = if status.npuOn: 1 else: 0
  layer.dspOn = if status.dspOn: 1 else: 0
  layer.inputNum = inputNumAbi.value
  layer.outputScale = blaiFloat32FromBits(status.outputScaleBits)
  layer.outputLayer = if status.outputLayer: 1'u8 else: 0'u8
  layer.halt = if status.dspEnd: 1 else: 0

proc blaiCpuInputLayerEntryCursor*(inputIndex: int):
    BlaiCpuInputLayerEntryCursor =
  ## Resolve one graph-input slot to the packed `INPUT_LAYERS` bitfield base.
  if inputIndex < 0 or inputIndex >= BlaiMaxInputNum:
    return
  let inputLayerField = blaiInstructionFieldStrideCursor(
    inputIndex, BlaiCpuInputLayersBaseBit, BlaiCpuInputLayersStrideBits,
    BlaiCpuInputLayersBits)
  if not inputLayerField.valid:
    return
  result.inputIndex = inputIndex
  result.inputLayerBaseBit = inputLayerField.baseBit
  result.valid = true

proc decodeBlaiCpuInputLayers*(inst: BlaiInstruction,
                               inputCount: uint32): BlaiCpuInputLayers =
  ## Decode SDK `INPUT_LAYERS`: up to eight 10-bit graph input indices.
  result.inputCount = min(inputCount, BlaiMaxInputNumU32)
  for inputIndex in 0 ..< blaiBoundedU32Count(
      result.inputCount, BlaiMaxInputNum):
    let cursor = blaiCpuInputLayerEntryCursor(inputIndex)
    if not cursor.valid:
      continue
    let inputLayerAbi = blaiCpuInputLayerFieldAbi(
      blaiBits(inst, Natural(cursor.inputLayerBaseBit), BlaiCpuInputLayersBits))
    if inputLayerAbi.valid:
      result.inputs[inputIndex] = inputLayerAbi.value

proc applyBlaiCpuInputLayers*(decoded: BlaiCpuInputLayers,
                              layerIndex: uint32,
                              layer: var BlaiCpuInstLayer64,
                              nextLayerOffset: var int32) =
  ## Apply SDK `INPUT_LAYERS` graph bookkeeping for one parsed layer.
  let combineLayer = blaiLayerTypeFromSdk(layer.layerType) in {
    blaiConvMax, blaiRouteMax, blaiRouteConv, blaiRouteUpsample}
  if layerIndex == 0'u32:
    nextLayerOffset = 0
  else:
    nextLayerOffset = layer.layerOffset + (if combineLayer: 1'i32 else: 0'i32)
  let graphLayerAbi = blaiCpuGraphLayerAbi(layerIndex, layer.layerOffset)
  if not graphLayerAbi.valid:
    return
  layer.graphLayer[0] = graphLayerAbi.value
  if combineLayer:
    layer.graphLayer[1] = layer.graphLayer[0]
    layer.graphLayer[0] = layer.graphLayer[1] + 1
  for inputIndex in 0 ..< blaiBoundedU32Count(
      decoded.inputCount, BlaiMaxInputNum):
    layer.inputLayers[inputIndex] = decoded.inputs[inputIndex]

proc blaiCpuYoloInfoEntryCursor*(entryIndex: int): BlaiCpuYoloInfoEntryCursor =
  ## Resolve one packed YOLO_INFO entry to named instruction bitfield bases.
  if entryIndex < 0 or entryIndex >= BlaiMaxYoloMaskNum:
    return
  let maskField = blaiInstructionFieldStrideCursor(
    entryIndex, BlaiCpuYoloInfoMaskBaseBit, BlaiCpuYoloInfoMaskStrideBits,
    BlaiCpuYoloInfoMaskBits)
  let biasWidthField = blaiInstructionFieldStrideCursor(
    entryIndex, BlaiCpuYoloInfoBiasWidthBaseBit,
    BlaiCpuYoloInfoBiasStrideBits, BlaiCpuYoloInfoBiasBits)
  let biasHeightField = blaiInstructionFieldStrideCursor(
    entryIndex, BlaiCpuYoloInfoBiasHeightBaseBit,
    BlaiCpuYoloInfoBiasStrideBits, BlaiCpuYoloInfoBiasBits)
  if not maskField.valid or not biasWidthField.valid or
      not biasHeightField.valid:
    return
  result.entryIndex = entryIndex
  result.maskBaseBit = maskField.baseBit
  result.biasWidthBaseBit = biasWidthField.baseBit
  result.biasHeightBaseBit = biasHeightField.baseBit
  result.valid = true

proc blaiCpuExtraLayerEntryCursor*(inputIndex, firstInput: uint32):
    BlaiCpuExtraLayerEntryCursor =
  ## Resolve one SDK extra input to named `EXTRA_LAYER*` bitfield bases.
  if inputIndex < firstInput or inputIndex >= BlaiMaxInputNumU32:
    return
  let packedIndex = inputIndex - firstInput
  let packedCursor = blaiU32ArrayIndexCursor(packedIndex, BlaiMaxInputNum)
  if not packedCursor.valid:
    return
  let inLayerMemField = blaiInstructionFieldStrideCursor(
    packedCursor.index, BlaiCpuExtraLayerMemBaseBit,
    BlaiCpuExtraLayerMemStrideBits, BlaiCpuExtraLayerMemBits)
  let tfliteChannelsField = blaiInstructionFieldStrideCursor(
    packedCursor.index, BlaiCpuExtraLayerTfliteChannelsBaseBit,
    BlaiCpuExtraLayerTfliteChannelsStrideBits,
    BlaiCpuExtraLayerTfliteChannelsBits)
  let tfliteOffsetField = blaiInstructionFieldStrideCursor(
    packedCursor.index, BlaiCpuExtraLayerTfliteOffsetBaseBit,
    BlaiCpuExtraLayerTfliteOffsetStrideBits,
    BlaiCpuExtraLayerTfliteOffsetBits)
  let tfliteShiftField = blaiInstructionFieldStrideCursor(
    packedCursor.index, BlaiCpuExtraLayerTfliteShiftBaseBit,
    BlaiCpuExtraLayerTfliteShiftStrideBits,
    BlaiCpuExtraLayerTfliteShiftBits)
  let routeFracField = blaiInstructionFieldStrideCursor(
    packedCursor.index, BlaiCpuExtraLayerRouteFracBaseBit,
    BlaiCpuExtraLayerRouteFracStrideBits, BlaiCpuExtraLayerRouteFracBits)
  let routeChannelsField = blaiInstructionFieldStrideCursor(
    packedCursor.index, BlaiCpuExtraLayerRouteChannelsBaseBit,
    BlaiCpuExtraLayerRouteChannelsStrideBits,
    BlaiCpuExtraLayerRouteChannelsBits)
  if not inLayerMemField.valid or not tfliteChannelsField.valid or
      not tfliteOffsetField.valid or not tfliteShiftField.valid or
      not routeFracField.valid or not routeChannelsField.valid:
    return
  result.inputIndex = inputIndex
  result.packedIndex = packedCursor.index
  result.inLayerMemBaseBit = inLayerMemField.baseBit
  result.tfliteChannelsBaseBit = tfliteChannelsField.baseBit
  result.tfliteOffsetBaseBit = tfliteOffsetField.baseBit
  result.tfliteShiftBaseBit = tfliteShiftField.baseBit
  result.routeFracBaseBit = routeFracField.baseBit
  result.routeChannelsBaseBit = routeChannelsField.baseBit
  result.valid = true

proc decodeBlaiCpuYoloInfo*(inst: BlaiInstruction,
                            maskCount: uint32): BlaiCpuYoloInfo =
  ## Decode SDK `YOLO_INFO` fields without allocating pointer-backed arrays.
  result.classes = blaiBits(inst, 5, 7)
  result.total = blaiBits(inst, 12, 4) + 1'u32
  result.truncated = maskCount > BlaiMaxYoloMaskNumU32
  result.maskCount = min(maskCount, BlaiMaxYoloMaskNumU32)
  for entryIndex in 0 ..< blaiBoundedU32Count(
      result.maskCount, BlaiMaxYoloMaskNum):
    let cursor = blaiCpuYoloInfoEntryCursor(entryIndex)
    if not cursor.valid:
      result.truncated = true
      continue
    let mask = blaiBits(
      inst, Natural(cursor.maskBaseBit), BlaiCpuYoloInfoMaskBits)
    result.entries[entryIndex] = BlaiCpuYoloMaskBias(
      active: true,
      mask: mask,
      biasW: blaiBits(
        inst, Natural(cursor.biasWidthBaseBit), BlaiCpuYoloInfoBiasBits),
      biasH: blaiBits(
        inst, Natural(cursor.biasHeightBaseBit), BlaiCpuYoloInfoBiasBits))

proc blaiYoloBiasPairIndex*(maskIndex, total: uint32): BlaiYoloBiasPairIndex =
  ## Project one decoded YOLO mask to the SDK width/height bias-pair indexes.
  if total == 0'u32 or total > BlaiMaxYoloTotalU32:
    return
  if maskIndex >= total or maskIndex >= BlaiMaxYoloTotalU32:
    return
  if maskIndex > high(uint32) div 2'u32:
    return
  let widthIndex = maskIndex * 2'u32
  if widthIndex == high(uint32):
    return
  result.maskIndex = maskIndex
  result.widthIndex = widthIndex
  result.heightIndex = widthIndex + 1'u32
  result.valid = true

proc blaiYoloBiasPairCursor*(maskIndex, total: uint32): BlaiYoloBiasPairCursor =
  ## Resolve one SDK YOLO mask index to its bounded width/height bias slots.
  let pairIndex = blaiYoloBiasPairIndex(maskIndex, total)
  if not pairIndex.valid:
    return
  let activeCursor = blaiU32ArrayIndexCursor(pairIndex.maskIndex, BlaiMaxYoloTotal)
  let widthCursor = blaiU32ArrayIndexCursor(pairIndex.widthIndex, BlaiMaxYoloBiasNum)
  let heightCursor = blaiU32ArrayIndexCursor(
    pairIndex.heightIndex, BlaiMaxYoloBiasNum)
  if not activeCursor.valid or not widthCursor.valid or not heightCursor.valid:
    return
  result.maskIndex = pairIndex.maskIndex
  result.activeIndex = activeCursor.index
  result.widthIndex = widthCursor.index
  result.heightIndex = heightCursor.index
  result.valid = true

proc blaiStoreYoloBiasPair*(storage: var BlaiCpuYoloStorage,
                            cursor: BlaiYoloBiasPairCursor,
                            biasW, biasH: int32): bool =
  ## Store one recovered YOLO bias pair through a checked pair cursor.
  if not cursor.valid:
    return false
  storage.biasPairActive[cursor.activeIndex] = true
  storage.biases[cursor.widthIndex] = biasW
  storage.biases[cursor.heightIndex] = biasH
  true

proc applyBlaiCpuYoloInfo*(decoded: BlaiCpuYoloInfo,
                           layer: var BlaiCpuInstLayer64,
                           storage: var BlaiCpuYoloStorage): bool =
  ## Apply decoded `YOLO_INFO` fields to a layer plus typed sidecar storage.
  ##
  ## The SDK writes `mask[k]` and `biases[mask[k] * 2 .. +1]` through allocated
  ## pointers. This pure-Nim path keeps those arrays in caller-owned storage and
  ## rejects mask values that would index beyond the decoded `total` entries.
  result = true
  let classesAbi = blaiCpuYoloInfoFieldAbi(decoded.classes)
  let totalAbi = blaiCpuYoloInfoFieldAbi(decoded.total)
  if not classesAbi.valid or not totalAbi.valid:
    return false
  if decoded.truncated or decoded.total == 0'u32 or
      decoded.total > BlaiMaxYoloTotalU32:
    result = false
  layer.classes = classesAbi.value
  layer.total = totalAbi.value
  storage.active = true
  storage.classes = layer.classes
  storage.total = layer.total
  storage.maskCount = decoded.maskCount
  for entryIndex in 0 ..< blaiBoundedU32Count(
      decoded.maskCount, BlaiMaxYoloMaskNum):
    let entry = decoded.entries[entryIndex]
    if not entry.active:
      continue
    let biasCursor = blaiYoloBiasPairCursor(entry.mask, decoded.total)
    if not biasCursor.valid:
      result = false
      continue
    let maskAbi = blaiCpuYoloInfoFieldAbi(entry.mask)
    let biasWAbi = blaiCpuYoloInfoFieldAbi(entry.biasW)
    let biasHAbi = blaiCpuYoloInfoFieldAbi(entry.biasH)
    if not maskAbi.valid or not biasWAbi.valid or not biasHAbi.valid:
      result = false
      continue
    storage.mask[entryIndex] = maskAbi.value
    if not blaiStoreYoloBiasPair(
        storage, biasCursor, biasWAbi.value, biasHAbi.value):
      result = false

proc decodeBlaiCpuExtraLayer*(inst: BlaiInstruction,
                              inputCount: uint32,
                              useTflite: bool,
                              highBank: bool): BlaiCpuExtraLayer =
  ## Decode SDK `EXTRA_LAYER` / `EXTRA_LAYER_6_8` extra-input fields.
  result.useTflite = useTflite
  result.highBank = highBank
  result.firstInput =
    if highBank:
      if useTflite: 5'u32 else: 6'u32
    else:
      2'u32
  let sdkLimit =
    if highBank:
      if useTflite: min(inputCount, 8'u32) else: min(inputCount, 10'u32)
    else:
      if useTflite: min(inputCount, 5'u32) else: min(inputCount, 6'u32)
  let boundedLimit = min(sdkLimit, BlaiMaxInputNumU32)
  if boundedLimit <= result.firstInput:
    return
  for inputIndex in result.firstInput ..< boundedLimit:
    let inputCursor = blaiU32ArrayIndexCursor(inputIndex, BlaiMaxInputNum)
    if not inputCursor.valid:
      continue
    let cursor = blaiCpuExtraLayerEntryCursor(inputIndex, result.firstInput)
    if not cursor.valid:
      continue
    result.inputs[inputCursor.index].active = true
    result.inputs[inputCursor.index].inputIndex = inputIndex
    result.inputs[inputCursor.index].inLayerMemN =
      blaiBits(
        inst, Natural(cursor.inLayerMemBaseBit), BlaiCpuExtraLayerMemBits)
    if useTflite:
      result.inputs[inputCursor.index].channels =
        blaiBits(
          inst, Natural(cursor.tfliteChannelsBaseBit),
          BlaiCpuExtraLayerTfliteChannelsBits)
      result.inputs[inputCursor.index].tfInputOffset =
        blaiBits(
          inst, Natural(cursor.tfliteOffsetBaseBit),
          BlaiCpuExtraLayerTfliteOffsetBits)
      result.inputs[inputCursor.index].tfInputShift =
        blaiSignedBits(
          inst, Natural(cursor.tfliteShiftBaseBit),
          range[1 .. 31](BlaiCpuExtraLayerTfliteShiftBits))
    else:
      result.inputs[inputCursor.index].routeFrac =
        blaiBits(
          inst, Natural(cursor.routeFracBaseBit),
          BlaiCpuExtraLayerRouteFracBits)
      result.inputs[inputCursor.index].channels =
        blaiBits(
          inst, Natural(cursor.routeChannelsBaseBit),
        BlaiCpuExtraLayerRouteChannelsBits)
    inc result.decodedInputCount

proc blaiCpuExtraMultiplierEntryCursor*(inputIndex, firstInput: uint32):
    BlaiCpuExtraMultiplierEntryCursor =
  ## Resolve one SDK extra input to its `EXTRA_MULTIPLIER*` bitfield base.
  if inputIndex < firstInput or inputIndex >= BlaiMaxInputNumU32:
    return
  let packedIndex = inputIndex - firstInput
  let packedCursor = blaiU32ArrayIndexCursor(packedIndex, BlaiMaxInputNum)
  if not packedCursor.valid:
    return
  let multiplierField = blaiInstructionFieldStrideCursor(
    packedCursor.index, BlaiCpuExtraMultiplierBaseBit,
    BlaiCpuExtraMultiplierStrideBits, BlaiCpuExtraMultiplierBits)
  if not multiplierField.valid:
    return
  result.inputIndex = inputIndex
  result.packedIndex = packedCursor.index
  result.multiplierBaseBit = multiplierField.baseBit
  result.valid = true

proc decodeBlaiCpuExtraMultiplier*(inst: BlaiInstruction,
                                   inputCount: uint32,
                                   highBank: bool): BlaiCpuExtraMultiplier =
  ## Decode SDK `EXTRA_MULTIPLIER` / `EXTRA_MULTIPLIER_6_8` fields.
  result.highBank = highBank
  result.firstInput = if highBank: 5'u32 else: 2'u32
  let sdkLimit = if highBank: min(inputCount, 8'u32) else: min(inputCount, 5'u32)
  let boundedLimit = min(sdkLimit, BlaiMaxInputNumU32)
  if boundedLimit <= result.firstInput:
    return
  for inputIndex in result.firstInput ..< boundedLimit:
    let inputCursor = blaiU32ArrayIndexCursor(inputIndex, BlaiMaxInputNum)
    if not inputCursor.valid:
      continue
    let cursor = blaiCpuExtraMultiplierEntryCursor(inputIndex, result.firstInput)
    if not cursor.valid:
      continue
    result.multipliers[inputCursor.index] =
      blaiBits(
        inst, Natural(cursor.multiplierBaseBit), BlaiCpuExtraMultiplierBits)
    inc result.decodedInputCount

proc blaiLogicalInputSlotCursor*(inputIndex, firstInput: uint32,
                                 capacity: int): BlaiLogicalInputSlotCursor =
  ## Resolve an SDK logical input number to a zero-based sidecar slot.
  if inputIndex < firstInput:
    return
  let cursor = blaiU32ArrayIndexCursor(inputIndex - firstInput, capacity)
  if not cursor.valid:
    return
  result.inputIndex = inputIndex
  result.firstInput = firstInput
  result.slotIndex = cursor.index
  result.valid = true

proc blaiCpuExtraStorageCursor*(inputIndex: uint32): BlaiCpuExtraStorageCursor =
  ## Resolve SDK logical input index to `mlayer_input_info_t` sidecar storage.
  let cursor =
    blaiLogicalInputSlotCursor(inputIndex, 2'u32, BlaiMaxInputNum - 2)
  if not cursor.valid:
    return
  result.inputIndex = inputIndex
  result.storageIndex = cursor.slotIndex
  result.valid = true

proc blaiLayerCnCursor*(inputIndex: uint32): BlaiLayerCnCursor =
  ## Resolve SDK logical input index `k` to the bounded `cn[k - 1]` slot.
  let cnCursor =
    blaiLogicalInputSlotCursor(inputIndex, 1'u32, BlaiMaxInputNum - 1)
  if not cnCursor.valid:
    return
  result.inputIndex = inputIndex
  result.cnIndex = cnCursor.slotIndex
  result.valid = true

proc blaiLayerCn*(layer: BlaiCpuInstLayer64, inputIndex: uint32): int32 =
  ## Read the SDK `cn[k - 1]` channel count through a checked cursor.
  let cursor = blaiLayerCnCursor(inputIndex)
  if cursor.valid:
    layer.cn[cursor.cnIndex]
  else:
    0'i32

proc blaiSetLayerCn*(layer: var BlaiCpuInstLayer64,
                     inputIndex: uint32,
                     channels: int32): bool =
  ## Write the SDK `cn[k - 1]` channel count through a checked cursor.
  let cursor = blaiLayerCnCursor(inputIndex)
  if cursor.valid:
    layer.cn[cursor.cnIndex] = channels
    true
  else:
    false

proc nonNegativeU32(value: int32): uint32
proc blaiUint32AppendFitInto*(bufferLen, cursor, appendCount: uint32,
                              outResult: var BlaiUint32AppendFitResult)
proc blaiUint32AddressRangeFit*(address, bytes: uint32):
                                 BlaiUint32AddressRangeFitResult

proc applyBlaiCpuExtraLayer*(decoded: BlaiCpuExtraLayer,
                             layer: var BlaiCpuInstLayer64,
                             storage: var BlaiCpuExtraInputStorage): bool =
  ## Apply decoded `EXTRA_LAYER*` fields to a layer plus typed sidecar storage.
  ##
  ## This mirrors the SDK writes to `cn[k - 1]` and `mlayer_input_info_t`
  ## arrays, while intentionally leaving the raw pointer slots in
  ## `BlaiCpuInstLayer64` untouched.
  result = true
  for inputIndex in 0 ..< BlaiMaxInputNum:
    let input = decoded.inputs[inputIndex]
    if not input.active:
      continue
    let storageCursor = blaiCpuExtraStorageCursor(input.inputIndex)
    let channelsAbi = blaiCpuExtraLayerFieldAbi(input.channels)
    let inLayerMemAbi = blaiCpuExtraLayerFieldAbi(input.inLayerMemN)
    let tfInputOffsetAbi = blaiCpuExtraLayerFieldAbi(input.tfInputOffset)
    let routeFracAbi = blaiCpuExtraLayerFieldAbi(input.routeFrac)
    if not storageCursor.valid or
        not channelsAbi.valid or
        not inLayerMemAbi.valid or
        (decoded.useTflite and not tfInputOffsetAbi.valid) or
        (not decoded.useTflite and not routeFracAbi.valid) or
        not blaiSetLayerCn(layer, input.inputIndex, channelsAbi.value):
      result = false
      continue
    storage.active = true
    storage.inLayerMemN[storageCursor.storageIndex] = inLayerMemAbi.value
    if decoded.useTflite:
      storage.tfInputOffsetExtra[storageCursor.storageIndex] =
        tfInputOffsetAbi.value
      storage.tfInputShiftExtra[storageCursor.storageIndex] = input.tfInputShift
    else:
      storage.frouten[storageCursor.storageIndex] = routeFracAbi.value

proc applyBlaiCpuExtraMultiplier*(decoded: BlaiCpuExtraMultiplier,
                                  storage: var BlaiCpuExtraInputStorage): bool =
  ## Apply decoded `EXTRA_MULTIPLIER*` fields to typed sidecar storage.
  result = true
  let endInput = min(decoded.firstInput + decoded.decodedInputCount,
                     BlaiMaxInputNumU32)
  if endInput <= decoded.firstInput:
    return
  for inputIndex in decoded.firstInput ..< endInput:
    let inputCursor = blaiU32ArrayIndexCursor(inputIndex, BlaiMaxInputNum)
    let storageCursor = blaiCpuExtraStorageCursor(inputIndex)
    if not inputCursor.valid or not storageCursor.valid:
      result = false
      continue
    let multiplier = decoded.multipliers[inputCursor.index]
    let multiplierAbi = blaiCpuTfliteMultiplierBitsAbi(multiplier)
    if not multiplierAbi.valid:
      result = false
      continue
    storage.active = true
    storage.tfInputMultiplierExtra[storageCursor.storageIndex] =
      multiplierAbi.value

proc blaiCpuRouteInputSource*(layer: BlaiCpuInstLayer64,
                              storage: BlaiCpuExtraInputStorage,
                              inputIndex: uint32): BlaiCpuRouteInputSource =
  ## Project SDK route input source fields without following raw pointer slots.
  if inputIndex >= BlaiMaxInputNumU32 or
      inputIndex >= nonNegativeU32(layer.inputNum):
    return
  result.active = true
  result.inputIndex = inputIndex
  case inputIndex
  of 0'u32:
    result.memorySlot = layer.inLayer1Mem
    result.channels = layer.c
    result.fractionalBits = layer.froute1
  of 1'u32:
    result.memorySlot = layer.inLayer2Mem
    result.channels = blaiLayerCn(layer, inputIndex)
    result.fractionalBits = layer.froute2
  else:
    let storageCursor = blaiCpuExtraStorageCursor(inputIndex)
    if not storageCursor.valid or not storage.active:
      result.active = false
      return
    result.memorySlot = storage.inLayerMemN[storageCursor.storageIndex]
    result.channels = blaiLayerCn(layer, inputIndex)
    result.fractionalBits = storage.frouten[storageCursor.storageIndex]

proc blaiCpuTfliteInputQuant*(layer: BlaiCpuInstLayer64,
                              storage: BlaiCpuExtraInputStorage,
                              inputIndex: uint32): BlaiCpuTfliteInputQuant =
  ## Project SDK per-input TFLite quantization fields.
  if inputIndex >= BlaiMaxInputNumU32 or
      inputIndex >= nonNegativeU32(layer.inputNum):
    return
  result.active = true
  result.inputIndex = inputIndex
  case inputIndex
  of 0'u32:
    result.offset = layer.tfInput1Offset
    result.multiplier = layer.tfInput1Multiplier
    result.shift = layer.tfInput1Shift
  of 1'u32:
    result.offset = layer.tfInput2Offset
    result.multiplier = layer.tfInput2Multiplier
    result.shift = layer.tfInput2Shift
  else:
    let storageCursor = blaiCpuExtraStorageCursor(inputIndex)
    if not storageCursor.valid or not storage.active:
      result.active = false
      return
    result.offset = storage.tfInputOffsetExtra[storageCursor.storageIndex]
    result.multiplier = storage.tfInputMultiplierExtra[storageCursor.storageIndex]
    result.shift = storage.tfInputShiftExtra[storageCursor.storageIndex]

proc blaiCpuParsedLayer*(layers: openArray[BlaiCpuInstLayer64],
                         extraInputs: openArray[BlaiCpuExtraInputStorage],
                         index: uint32): BlaiCpuParsedLayer =
  ## Project one aligned parser layer/sidecar pair.
  let layerCursor = blaiU32ArrayIndexCursor(index, layers.len)
  let extraCursor = blaiU32ArrayIndexCursor(index, extraInputs.len)
  if not layerCursor.valid or not extraCursor.valid:
    return
  BlaiCpuParsedLayer(
    active: true,
    index: index,
    layer: layers[layerCursor.index],
    extraInputs: extraInputs[extraCursor.index])

proc blaiCpuParsedLayerState*(
    layers: openArray[BlaiCpuInstLayer64],
    extraInputs: openArray[BlaiCpuExtraInputStorage],
    yoloStorage: openArray[BlaiCpuYoloStorage],
    index: uint32): BlaiCpuParsedLayerState =
  ## Project one aligned parser layer and all recovered sidecar storage.
  let layerCursor = blaiU32ArrayIndexCursor(index, layers.len)
  let extraCursor = blaiU32ArrayIndexCursor(index, extraInputs.len)
  let yoloCursor = blaiU32ArrayIndexCursor(index, yoloStorage.len)
  if not layerCursor.valid or not extraCursor.valid or not yoloCursor.valid:
    return
  BlaiCpuParsedLayerState(
    active: true,
    index: index,
    layer: layers[layerCursor.index],
    extraInputs: extraInputs[extraCursor.index],
    yolo: yoloStorage[yoloCursor.index])

proc blaiCpuRouteInputSource*(parsed: BlaiCpuParsedLayer,
                              inputIndex: uint32): BlaiCpuRouteInputSource =
  ## Project an SDK route input source from a parsed layer/sidecar pair.
  if not parsed.active:
    return
  blaiCpuRouteInputSource(parsed.layer, parsed.extraInputs, inputIndex)

proc blaiCpuRouteInputSource*(parsed: BlaiCpuParsedLayerState,
                              inputIndex: uint32): BlaiCpuRouteInputSource =
  ## Project an SDK route input source from parsed layer state.
  if not parsed.active:
    return
  blaiCpuRouteInputSource(parsed.layer, parsed.extraInputs, inputIndex)

proc blaiCpuTfliteInputQuant*(parsed: BlaiCpuParsedLayer,
                              inputIndex: uint32): BlaiCpuTfliteInputQuant =
  ## Project SDK per-input TFLite quantization from a parsed layer/sidecar pair.
  if not parsed.active:
    return
  blaiCpuTfliteInputQuant(parsed.layer, parsed.extraInputs, inputIndex)

proc blaiCpuTfliteInputQuant*(parsed: BlaiCpuParsedLayerState,
                              inputIndex: uint32): BlaiCpuTfliteInputQuant =
  ## Project SDK per-input TFLite quantization from parsed layer state.
  if not parsed.active:
    return
  blaiCpuTfliteInputQuant(parsed.layer, parsed.extraInputs, inputIndex)

proc decodeBlaiCpuTfliteMultiplier*(
    inst: BlaiInstruction): BlaiCpuTfliteMultiplier =
  ## Decode SDK `TFLITE_MULTIPLIER` scalar multiplier record.
  result.input1Multiplier = blaiBits(inst, 5, 32)
  result.input2Multiplier = blaiBits(inst, 37, 32)
  result.outputMultiplier = blaiBits(inst, 69, 32)
  result.routeInputMultiplierLow = blaiBits(inst, 101, 16)

proc applyBlaiCpuTfliteMultiplier*(decoded: BlaiCpuTfliteMultiplier,
                                   layer: var BlaiCpuInstLayer64) =
  ## Apply SDK `TFLITE_MULTIPLIER` fields to a CPU layer.
  let
    input1MultiplierAbi =
      blaiCpuTfliteMultiplierBitsAbi(decoded.input1Multiplier)
    input2MultiplierAbi =
      blaiCpuTfliteMultiplierBitsAbi(decoded.input2Multiplier)
    outputMultiplierAbi =
      blaiCpuTfliteMultiplierBitsAbi(decoded.outputMultiplier)
  if not input1MultiplierAbi.valid or not input2MultiplierAbi.valid or
      not outputMultiplierAbi.valid:
    return
  layer.tfInput1Multiplier = input1MultiplierAbi.value
  layer.tfInput2Multiplier = input2MultiplierAbi.value
  layer.tfOutputMultiplier = outputMultiplierAbi.value
  let routeMultiplierAbi = blaiCpuTfliteRouteMultiplierAbi(
    layer.tfRouteInputMultiplier, decoded.routeInputMultiplierLow)
  if routeMultiplierAbi.valid:
    layer.tfRouteInputMultiplier = routeMultiplierAbi.value

proc blaiFloat32FromBits*(bits: uint32): float32 =
  ## Reinterpret SDK CPU stream IEEE-754 bits as float32.
  ##
  ## This is the localized equivalent of the SDK's `*((float*)&bits)` parser
  ## operation for TFLite scale records.
  cast[float32](bits)

proc decodeBlaiCpuTfliteFloat*(inst: BlaiInstruction): BlaiCpuTfliteFloat =
  ## Decode SDK `TFLITE_FLOAT` raw scale bits.
  result.inputScaleBits = blaiBits(inst, 5, 32)
  result.outputScaleBits = blaiBits(inst, 37, 32)

proc applyBlaiCpuTfliteFloat*(decoded: BlaiCpuTfliteFloat,
                              layer: var BlaiCpuInstLayer64) =
  ## Apply SDK `TFLITE_FLOAT` input/output scales.
  layer.inputScale = blaiFloat32FromBits(decoded.inputScaleBits)
  layer.outputScale = blaiFloat32FromBits(decoded.outputScaleBits)

proc decodeBlaiCpuSsdInfo*(inst: BlaiInstruction): BlaiCpuSsdInfo =
  ## Decode SDK `SSD_INFO` fields from a CPU instruction stream record.
  result.wScale = blaiBits(inst, 5, 6)
  result.hScale = blaiBits(inst, 11, 6)
  result.xScale = blaiBits(inst, 17, 6)
  result.yScale = blaiBits(inst, 23, 6)
  result.classes = blaiBits(inst, 29, 7)
  result.maxClassesPerDetection = blaiBits(inst, 36, 3)
  result.maxDetections = blaiBits(inst, 39, 5)
  result.input2ScaleBits = blaiBits(inst, 44, 32)
  result.input3ScaleBits = blaiBits(inst, 76, 32)
  result.anchorsOffset = blaiBits(inst, 108, 8)

proc applyBlaiCpuSsdInfo*(decoded: BlaiCpuSsdInfo,
                          layer: var BlaiCpuInstLayer64) =
  ## Apply SDK `SSD_INFO` fields to a CPU layer.
  let classesAbi = blaiCpuSsdInfoFieldAbi(decoded.classes)
  let maxClassesAbi = blaiCpuSsdInfoFieldAbi(decoded.maxClassesPerDetection)
  let maxDetectionsAbi = blaiCpuSsdInfoFieldAbi(decoded.maxDetections)
  let anchorsOffsetAbi = blaiCpuSsdInfoFieldAbi(decoded.anchorsOffset)
  if not classesAbi.valid or not maxClassesAbi.valid or
      not maxDetectionsAbi.valid or not anchorsOffsetAbi.valid:
    return
  layer.wScale = decoded.wScale.float32
  layer.hScale = decoded.hScale.float32
  layer.xScale = decoded.xScale.float32
  layer.yScale = decoded.yScale.float32
  layer.classes = classesAbi.value
  layer.maxClassesPerDetection = maxClassesAbi.value
  layer.maxDetections = maxDetectionsAbi.value
  layer.input2Scale = blaiFloat32FromBits(decoded.input2ScaleBits)
  layer.input3Scale = blaiFloat32FromBits(decoded.input3ScaleBits)
  layer.anchorsOffset = anchorsOffsetAbi.value

proc blaiInitCpuModelParseResult*(outResult: var BlaiCpuModelParseResult) =
  ## Initialize bounded CPU/DSP parse state with absent-record sentinels.
  outResult = default(BlaiCpuModelParseResult)
  outResult.firstMalformedRecord = -1
  outResult.firstUnsupportedRecord = -1

proc blaiMarkCpuModelParseMalformed*(
    outResult: var BlaiCpuModelParseResult,
    recordIndex: int) =
  ## Record the first malformed CPU/DSP stream position without losing totals.
  outResult.malformed = true
  if outResult.firstMalformedRecord < 0:
    outResult.firstMalformedRecord = blaiCpuRecordIndexValue(recordIndex)

proc blaiMarkCpuModelParseUnsupported*(
    outResult: var BlaiCpuModelParseResult,
    recordIndex: int,
    kind: BlaiCpuInstructionType) =
  ## Record one recognized-but-unsupported CPU/DSP record kind.
  inc outResult.unsupportedRecordCount
  if outResult.firstUnsupportedRecord < 0:
    outResult.firstUnsupportedRecord = blaiCpuRecordIndexValue(recordIndex)
    outResult.firstUnsupportedKind = kind

proc blaiFinishCpuModelParseResult*(
    outResult: var BlaiCpuModelParseResult,
    hasPendingLayer: bool,
    endRecordIndex: int) =
  ## Finalize bounded CPU/DSP parse state after walking a record stream.
  if hasPendingLayer:
    blaiMarkCpuModelParseMalformed(outResult, endRecordIndex)
  outResult.complete = outResult.hasHeader and not outResult.malformed and
    not outResult.overflow and outResult.unsupportedRecordCount == 0 and
    (outResult.declaredLayerCount == 0 or
      outResult.parsedLayerCount == outResult.declaredLayerCount)

proc blaiParseCpuModelInstructionsInto*(
    stream: openArray[BlaiInstruction],
    layers: var openArray[BlaiCpuInstLayer64],
    outResult: var BlaiCpuModelParseResult) =
  ## Parse recovered CPU/DSP model records into a caller-owned layer table.
  ##
  ## This handles recovered scalar and graph-bookkeeping records without
  ## pointer-backed sidecars: `DSP_HEADER`, `LAYER_INFO`, `GENERAL_FORM`,
  ## `DETAIL_GENERAL_FORM`, `INPUT_LAYERS`, `TFLITE_MULTIPLIER`,
  ## `TFLITE_FLOAT`, `SSD_INFO`, and `DSP_STATUS`. Records that require SDK
  ## pointer-backed sidecars remain unsupported here so callers can choose a
  ## typed sidecar overload instead of following raw pointer fields.
  template result: untyped = outResult
  blaiInitCpuModelParseResult(result)
  var pendingLayer: BlaiCpuInstLayer64
  var hasPendingLayer = false
  var nextLayerOffset = 0'i32

  for recordIndex in 0 ..< stream.len:
    let kind = decodeBlaiCpuInstructionType(stream[recordIndex])
    result.lastRecordKind = kind
    inc result.recordCount
    case kind
    of blaiCpuDspHeader:
      if result.hasHeader or hasPendingLayer or result.parsedLayerCount != 0:
        blaiMarkCpuModelParseMalformed(result, recordIndex)
      result.header = decodeBlaiCpuDspHeader(stream[recordIndex])
      result.hasHeader = true
      result.useTflite = result.header.useTflite
      result.declaredLayerCount = result.header.layerCount
    of blaiCpuLayerInfo:
      if not result.hasHeader or hasPendingLayer:
        blaiMarkCpuModelParseMalformed(result, recordIndex)
      pendingLayer = default(BlaiCpuInstLayer64)
      pendingLayer.layerOffset = nextLayerOffset
      decodeBlaiCpuLayerInfo(stream[recordIndex], pendingLayer)
      hasPendingLayer = true
    of blaiCpuGeneralForm:
      if not hasPendingLayer:
        blaiMarkCpuModelParseMalformed(result, recordIndex)
      else:
        decodeBlaiCpuGeneralForm(
          stream[recordIndex], result.useTflite, pendingLayer)
    of blaiCpuDetailGeneralForm:
      if not hasPendingLayer:
        blaiMarkCpuModelParseMalformed(result, recordIndex)
      else:
        decodeBlaiCpuDetailGeneralForm(stream[recordIndex], pendingLayer)
    of blaiCpuInputLayers:
      if not hasPendingLayer:
        blaiMarkCpuModelParseMalformed(result, recordIndex)
      else:
        let inputCount = nonNegativeU32(pendingLayer.inputNum)
        let inputLayers = decodeBlaiCpuInputLayers(
          stream[recordIndex], inputCount)
        applyBlaiCpuInputLayers(
          inputLayers, result.parsedLayerCount, pendingLayer, nextLayerOffset)
    of blaiCpuTfliteMultiplier:
      if not hasPendingLayer:
        blaiMarkCpuModelParseMalformed(result, recordIndex)
      else:
        applyBlaiCpuTfliteMultiplier(
          decodeBlaiCpuTfliteMultiplier(stream[recordIndex]), pendingLayer)
    of blaiCpuTfliteFloat:
      if not hasPendingLayer:
        blaiMarkCpuModelParseMalformed(result, recordIndex)
      else:
        applyBlaiCpuTfliteFloat(
          decodeBlaiCpuTfliteFloat(stream[recordIndex]), pendingLayer)
    of blaiCpuSsdInfo:
      if not hasPendingLayer:
        blaiMarkCpuModelParseMalformed(result, recordIndex)
      else:
        applyBlaiCpuSsdInfo(
          decodeBlaiCpuSsdInfo(stream[recordIndex]), pendingLayer)
    of blaiCpuDspStatus:
      if not hasPendingLayer:
        blaiMarkCpuModelParseMalformed(result, recordIndex)
      else:
        result.lastStatus = decodeBlaiCpuDspStatus(stream[recordIndex])
        applyBlaiCpuDspStatus(result.lastStatus, pendingLayer)
        let layerCursor =
          blaiU32ArrayIndexCursor(result.storedLayerCount, layers.len)
        if layerCursor.valid:
          layers[layerCursor.index] = pendingLayer
          inc result.storedLayerCount
        else:
          result.overflow = true
        inc result.parsedLayerCount
        hasPendingLayer = false
        if result.declaredLayerCount != 0 and
            result.parsedLayerCount >= result.declaredLayerCount:
          break
    of blaiCpuInstructionUnknown:
      blaiMarkCpuModelParseMalformed(result, recordIndex)
    else:
      blaiMarkCpuModelParseUnsupported(result, recordIndex, kind)

  blaiFinishCpuModelParseResult(result, hasPendingLayer, stream.len)

proc blaiParseCpuModelInstructions*(
    stream: openArray[BlaiInstruction],
    layers: var openArray[BlaiCpuInstLayer64]): BlaiCpuModelParseResult =
  ## Convenience result-returning wrapper for the recovered CPU/DSP parser.
  blaiParseCpuModelInstructionsInto(stream, layers, result)

proc blaiParseCpuModelInstructionsInto*(
    stream: openArray[BlaiInstruction],
    layers: var openArray[BlaiCpuInstLayer64],
    extraInputs: var openArray[BlaiCpuExtraInputStorage],
    outResult: var BlaiCpuModelParseResult) =
  ## Parse CPU/DSP model records with typed storage for SDK extra-input sidecars.
  ##
  ## This overload handles `EXTRA_LAYER*` and `EXTRA_MULTIPLIER*` records by
  ## writing caller-owned `BlaiCpuExtraInputStorage` entries instead of using
  ## the raw pointer slots from the recovered RV64 ABI object.
  template result: untyped = outResult
  blaiInitCpuModelParseResult(result)
  var pendingLayer: BlaiCpuInstLayer64
  var pendingExtra: BlaiCpuExtraInputStorage
  var hasPendingLayer = false
  var nextLayerOffset = 0'i32

  for recordIndex in 0 ..< stream.len:
    let kind = decodeBlaiCpuInstructionType(stream[recordIndex])
    result.lastRecordKind = kind
    inc result.recordCount
    case kind
    of blaiCpuDspHeader:
      if result.hasHeader or hasPendingLayer or result.parsedLayerCount != 0:
        blaiMarkCpuModelParseMalformed(result, recordIndex)
      result.header = decodeBlaiCpuDspHeader(stream[recordIndex])
      result.hasHeader = true
      result.useTflite = result.header.useTflite
      result.declaredLayerCount = result.header.layerCount
    of blaiCpuLayerInfo:
      if not result.hasHeader or hasPendingLayer:
        blaiMarkCpuModelParseMalformed(result, recordIndex)
      pendingLayer = default(BlaiCpuInstLayer64)
      pendingExtra = default(BlaiCpuExtraInputStorage)
      pendingLayer.layerOffset = nextLayerOffset
      decodeBlaiCpuLayerInfo(stream[recordIndex], pendingLayer)
      hasPendingLayer = true
    of blaiCpuGeneralForm:
      if not hasPendingLayer:
        blaiMarkCpuModelParseMalformed(result, recordIndex)
      else:
        decodeBlaiCpuGeneralForm(
          stream[recordIndex], result.useTflite, pendingLayer)
    of blaiCpuDetailGeneralForm:
      if not hasPendingLayer:
        blaiMarkCpuModelParseMalformed(result, recordIndex)
      else:
        decodeBlaiCpuDetailGeneralForm(stream[recordIndex], pendingLayer)
    of blaiCpuInputLayers:
      if not hasPendingLayer:
        blaiMarkCpuModelParseMalformed(result, recordIndex)
      else:
        let inputCount = nonNegativeU32(pendingLayer.inputNum)
        let inputLayers = decodeBlaiCpuInputLayers(
          stream[recordIndex], inputCount)
        applyBlaiCpuInputLayers(
          inputLayers, result.parsedLayerCount, pendingLayer, nextLayerOffset)
    of blaiCpuExtraLayer, blaiCpuExtraLayer6To8:
      if not hasPendingLayer:
        blaiMarkCpuModelParseMalformed(result, recordIndex)
      else:
        let inputCount = nonNegativeU32(pendingLayer.inputNum)
        let decoded = decodeBlaiCpuExtraLayer(
          stream[recordIndex], inputCount, result.useTflite,
          highBank = kind == blaiCpuExtraLayer6To8)
        if not applyBlaiCpuExtraLayer(decoded, pendingLayer, pendingExtra):
          blaiMarkCpuModelParseMalformed(result, recordIndex)
    of blaiCpuExtraMultiplier, blaiCpuExtraMultiplier6To8:
      if not hasPendingLayer:
        blaiMarkCpuModelParseMalformed(result, recordIndex)
      else:
        let inputCount = nonNegativeU32(pendingLayer.inputNum)
        let decoded = decodeBlaiCpuExtraMultiplier(
          stream[recordIndex], inputCount,
          highBank = kind == blaiCpuExtraMultiplier6To8)
        if not applyBlaiCpuExtraMultiplier(decoded, pendingExtra):
          blaiMarkCpuModelParseMalformed(result, recordIndex)
    of blaiCpuTfliteMultiplier:
      if not hasPendingLayer:
        blaiMarkCpuModelParseMalformed(result, recordIndex)
      else:
        applyBlaiCpuTfliteMultiplier(
          decodeBlaiCpuTfliteMultiplier(stream[recordIndex]), pendingLayer)
    of blaiCpuTfliteFloat:
      if not hasPendingLayer:
        blaiMarkCpuModelParseMalformed(result, recordIndex)
      else:
        applyBlaiCpuTfliteFloat(
          decodeBlaiCpuTfliteFloat(stream[recordIndex]), pendingLayer)
    of blaiCpuSsdInfo:
      if not hasPendingLayer:
        blaiMarkCpuModelParseMalformed(result, recordIndex)
      else:
        applyBlaiCpuSsdInfo(
          decodeBlaiCpuSsdInfo(stream[recordIndex]), pendingLayer)
    of blaiCpuDspStatus:
      if not hasPendingLayer:
        blaiMarkCpuModelParseMalformed(result, recordIndex)
      else:
        result.lastStatus = decodeBlaiCpuDspStatus(stream[recordIndex])
        applyBlaiCpuDspStatus(result.lastStatus, pendingLayer)
        let layerCursor =
          blaiU32ArrayIndexCursor(result.storedLayerCount, layers.len)
        if layerCursor.valid:
          layers[layerCursor.index] = pendingLayer
          let extraCursor =
            blaiU32ArrayIndexCursor(result.storedLayerCount, extraInputs.len)
          if extraCursor.valid:
            extraInputs[extraCursor.index] = pendingExtra
          else:
            result.overflow = true
          inc result.storedLayerCount
        else:
          result.overflow = true
        inc result.parsedLayerCount
        hasPendingLayer = false
        if result.declaredLayerCount != 0 and
            result.parsedLayerCount >= result.declaredLayerCount:
          break
    of blaiCpuInstructionUnknown:
      blaiMarkCpuModelParseMalformed(result, recordIndex)
    else:
      blaiMarkCpuModelParseUnsupported(result, recordIndex, kind)

  blaiFinishCpuModelParseResult(result, hasPendingLayer, stream.len)

proc blaiParseCpuModelInstructions*(
    stream: openArray[BlaiInstruction],
    layers: var openArray[BlaiCpuInstLayer64],
    extraInputs: var openArray[BlaiCpuExtraInputStorage]): BlaiCpuModelParseResult =
  ## Convenience wrapper for parsing with extra-input sidecar storage.
  blaiParseCpuModelInstructionsInto(stream, layers, extraInputs, result)

proc blaiParseCpuModelInstructionsInto*(
    stream: openArray[BlaiInstruction],
    layers: var openArray[BlaiCpuInstLayer64],
    extraInputs: var openArray[BlaiCpuExtraInputStorage],
    yoloStorage: var openArray[BlaiCpuYoloStorage],
    outResult: var BlaiCpuModelParseResult) =
  ## Parse CPU/DSP model records with typed extra-input and YOLO sidecars.
  ##
  ## This overload handles SDK pointer-backed `EXTRA_LAYER*`,
  ## `EXTRA_MULTIPLIER*`, and `YOLO_INFO` records by writing caller-owned typed
  ## storage instead of fabricating raw pointer fields inside `cpu_inst_layer_t`.
  template result: untyped = outResult
  blaiInitCpuModelParseResult(result)
  var pendingLayer: BlaiCpuInstLayer64
  var pendingExtra: BlaiCpuExtraInputStorage
  var pendingYolo: BlaiCpuYoloStorage
  var hasPendingLayer = false
  var nextLayerOffset = 0'i32

  for recordIndex in 0 ..< stream.len:
    let kind = decodeBlaiCpuInstructionType(stream[recordIndex])
    result.lastRecordKind = kind
    inc result.recordCount
    case kind
    of blaiCpuDspHeader:
      if result.hasHeader or hasPendingLayer or result.parsedLayerCount != 0:
        blaiMarkCpuModelParseMalformed(result, recordIndex)
      result.header = decodeBlaiCpuDspHeader(stream[recordIndex])
      result.hasHeader = true
      result.useTflite = result.header.useTflite
      result.declaredLayerCount = result.header.layerCount
    of blaiCpuLayerInfo:
      if not result.hasHeader or hasPendingLayer:
        blaiMarkCpuModelParseMalformed(result, recordIndex)
      pendingLayer = default(BlaiCpuInstLayer64)
      pendingExtra = default(BlaiCpuExtraInputStorage)
      pendingYolo = default(BlaiCpuYoloStorage)
      pendingLayer.layerOffset = nextLayerOffset
      decodeBlaiCpuLayerInfo(stream[recordIndex], pendingLayer)
      hasPendingLayer = true
    of blaiCpuGeneralForm:
      if not hasPendingLayer:
        blaiMarkCpuModelParseMalformed(result, recordIndex)
      else:
        decodeBlaiCpuGeneralForm(
          stream[recordIndex], result.useTflite, pendingLayer)
    of blaiCpuDetailGeneralForm:
      if not hasPendingLayer:
        blaiMarkCpuModelParseMalformed(result, recordIndex)
      else:
        decodeBlaiCpuDetailGeneralForm(stream[recordIndex], pendingLayer)
    of blaiCpuInputLayers:
      if not hasPendingLayer:
        blaiMarkCpuModelParseMalformed(result, recordIndex)
      else:
        let inputCount = nonNegativeU32(pendingLayer.inputNum)
        let inputLayers = decodeBlaiCpuInputLayers(
          stream[recordIndex], inputCount)
        applyBlaiCpuInputLayers(
          inputLayers, result.parsedLayerCount, pendingLayer, nextLayerOffset)
    of blaiCpuYoloInfo:
      if not hasPendingLayer:
        blaiMarkCpuModelParseMalformed(result, recordIndex)
      else:
        let maskCount = nonNegativeU32(pendingLayer.n)
        let decoded = decodeBlaiCpuYoloInfo(stream[recordIndex], maskCount)
        if not applyBlaiCpuYoloInfo(decoded, pendingLayer, pendingYolo):
          blaiMarkCpuModelParseMalformed(result, recordIndex)
    of blaiCpuExtraLayer, blaiCpuExtraLayer6To8:
      if not hasPendingLayer:
        blaiMarkCpuModelParseMalformed(result, recordIndex)
      else:
        let inputCount = nonNegativeU32(pendingLayer.inputNum)
        let decoded = decodeBlaiCpuExtraLayer(
          stream[recordIndex], inputCount, result.useTflite,
          highBank = kind == blaiCpuExtraLayer6To8)
        if not applyBlaiCpuExtraLayer(decoded, pendingLayer, pendingExtra):
          blaiMarkCpuModelParseMalformed(result, recordIndex)
    of blaiCpuExtraMultiplier, blaiCpuExtraMultiplier6To8:
      if not hasPendingLayer:
        blaiMarkCpuModelParseMalformed(result, recordIndex)
      else:
        let inputCount = nonNegativeU32(pendingLayer.inputNum)
        let decoded = decodeBlaiCpuExtraMultiplier(
          stream[recordIndex], inputCount,
          highBank = kind == blaiCpuExtraMultiplier6To8)
        if not applyBlaiCpuExtraMultiplier(decoded, pendingExtra):
          blaiMarkCpuModelParseMalformed(result, recordIndex)
    of blaiCpuTfliteMultiplier:
      if not hasPendingLayer:
        blaiMarkCpuModelParseMalformed(result, recordIndex)
      else:
        applyBlaiCpuTfliteMultiplier(
          decodeBlaiCpuTfliteMultiplier(stream[recordIndex]), pendingLayer)
    of blaiCpuTfliteFloat:
      if not hasPendingLayer:
        blaiMarkCpuModelParseMalformed(result, recordIndex)
      else:
        applyBlaiCpuTfliteFloat(
          decodeBlaiCpuTfliteFloat(stream[recordIndex]), pendingLayer)
    of blaiCpuSsdInfo:
      if not hasPendingLayer:
        blaiMarkCpuModelParseMalformed(result, recordIndex)
      else:
        applyBlaiCpuSsdInfo(
          decodeBlaiCpuSsdInfo(stream[recordIndex]), pendingLayer)
    of blaiCpuDspStatus:
      if not hasPendingLayer:
        blaiMarkCpuModelParseMalformed(result, recordIndex)
      else:
        result.lastStatus = decodeBlaiCpuDspStatus(stream[recordIndex])
        applyBlaiCpuDspStatus(result.lastStatus, pendingLayer)
        let layerCursor =
          blaiU32ArrayIndexCursor(result.storedLayerCount, layers.len)
        if layerCursor.valid:
          layers[layerCursor.index] = pendingLayer
          let extraCursor =
            blaiU32ArrayIndexCursor(result.storedLayerCount, extraInputs.len)
          if extraCursor.valid:
            extraInputs[extraCursor.index] = pendingExtra
          elif pendingExtra.active:
            result.overflow = true
          let yoloCursor =
            blaiU32ArrayIndexCursor(result.storedLayerCount, yoloStorage.len)
          if yoloCursor.valid:
            yoloStorage[yoloCursor.index] = pendingYolo
          elif pendingYolo.active:
            result.overflow = true
          inc result.storedLayerCount
        else:
          result.overflow = true
        inc result.parsedLayerCount
        hasPendingLayer = false
        if result.declaredLayerCount != 0 and
            result.parsedLayerCount >= result.declaredLayerCount:
          break
    of blaiCpuInstructionUnknown:
      blaiMarkCpuModelParseMalformed(result, recordIndex)

  blaiFinishCpuModelParseResult(result, hasPendingLayer, stream.len)

proc blaiParseCpuModelInstructions*(
    stream: openArray[BlaiInstruction],
    layers: var openArray[BlaiCpuInstLayer64],
    extraInputs: var openArray[BlaiCpuExtraInputStorage],
    yoloStorage: var openArray[BlaiCpuYoloStorage]): BlaiCpuModelParseResult =
  ## Convenience wrapper for parsing with extra-input and YOLO sidecars.
  blaiParseCpuModelInstructionsInto(
    stream, layers, extraInputs, yoloStorage, result)

proc blaiParseCpuModelInstructionsInto*(
    stream: openArray[BlaiInstruction],
    parsedLayers: var openArray[BlaiCpuParsedLayerState],
    outResult: var BlaiCpuModelParseResult) =
  ## Parse CPU/DSP model records into caller-owned parsed-layer state entries.
  ##
  ## This overload keeps each layer and its recovered pointer-backed sidecars in
  ## one typed value, avoiding parallel-array ownership at downstream call sites.
  template result: untyped = outResult
  blaiInitCpuModelParseResult(result)
  var pending: BlaiCpuParsedLayerState
  var hasPendingLayer = false
  var nextLayerOffset = 0'i32

  for recordIndex in 0 ..< stream.len:
    let kind = decodeBlaiCpuInstructionType(stream[recordIndex])
    result.lastRecordKind = kind
    inc result.recordCount
    case kind
    of blaiCpuDspHeader:
      if result.hasHeader or hasPendingLayer or result.parsedLayerCount != 0:
        blaiMarkCpuModelParseMalformed(result, recordIndex)
      result.header = decodeBlaiCpuDspHeader(stream[recordIndex])
      result.hasHeader = true
      result.useTflite = result.header.useTflite
      result.declaredLayerCount = result.header.layerCount
    of blaiCpuLayerInfo:
      if not result.hasHeader or hasPendingLayer:
        blaiMarkCpuModelParseMalformed(result, recordIndex)
      pending = default(BlaiCpuParsedLayerState)
      pending.layer.layerOffset = nextLayerOffset
      decodeBlaiCpuLayerInfo(stream[recordIndex], pending.layer)
      hasPendingLayer = true
    of blaiCpuGeneralForm:
      if not hasPendingLayer:
        blaiMarkCpuModelParseMalformed(result, recordIndex)
      else:
        decodeBlaiCpuGeneralForm(
          stream[recordIndex], result.useTflite, pending.layer)
    of blaiCpuDetailGeneralForm:
      if not hasPendingLayer:
        blaiMarkCpuModelParseMalformed(result, recordIndex)
      else:
        decodeBlaiCpuDetailGeneralForm(stream[recordIndex], pending.layer)
    of blaiCpuInputLayers:
      if not hasPendingLayer:
        blaiMarkCpuModelParseMalformed(result, recordIndex)
      else:
        let inputCount = nonNegativeU32(pending.layer.inputNum)
        let inputLayers = decodeBlaiCpuInputLayers(
          stream[recordIndex], inputCount)
        applyBlaiCpuInputLayers(
          inputLayers, result.parsedLayerCount, pending.layer, nextLayerOffset)
    of blaiCpuYoloInfo:
      if not hasPendingLayer:
        blaiMarkCpuModelParseMalformed(result, recordIndex)
      else:
        let maskCount = nonNegativeU32(pending.layer.n)
        let decoded = decodeBlaiCpuYoloInfo(stream[recordIndex], maskCount)
        if not applyBlaiCpuYoloInfo(decoded, pending.layer, pending.yolo):
          blaiMarkCpuModelParseMalformed(result, recordIndex)
    of blaiCpuExtraLayer, blaiCpuExtraLayer6To8:
      if not hasPendingLayer:
        blaiMarkCpuModelParseMalformed(result, recordIndex)
      else:
        let inputCount = nonNegativeU32(pending.layer.inputNum)
        let decoded = decodeBlaiCpuExtraLayer(
          stream[recordIndex], inputCount, result.useTflite,
          highBank = kind == blaiCpuExtraLayer6To8)
        if not applyBlaiCpuExtraLayer(
            decoded, pending.layer, pending.extraInputs):
          blaiMarkCpuModelParseMalformed(result, recordIndex)
    of blaiCpuExtraMultiplier, blaiCpuExtraMultiplier6To8:
      if not hasPendingLayer:
        blaiMarkCpuModelParseMalformed(result, recordIndex)
      else:
        let inputCount = nonNegativeU32(pending.layer.inputNum)
        let decoded = decodeBlaiCpuExtraMultiplier(
          stream[recordIndex], inputCount,
          highBank = kind == blaiCpuExtraMultiplier6To8)
        if not applyBlaiCpuExtraMultiplier(decoded, pending.extraInputs):
          blaiMarkCpuModelParseMalformed(result, recordIndex)
    of blaiCpuTfliteMultiplier:
      if not hasPendingLayer:
        blaiMarkCpuModelParseMalformed(result, recordIndex)
      else:
        applyBlaiCpuTfliteMultiplier(
          decodeBlaiCpuTfliteMultiplier(stream[recordIndex]), pending.layer)
    of blaiCpuTfliteFloat:
      if not hasPendingLayer:
        blaiMarkCpuModelParseMalformed(result, recordIndex)
      else:
        applyBlaiCpuTfliteFloat(
          decodeBlaiCpuTfliteFloat(stream[recordIndex]), pending.layer)
    of blaiCpuSsdInfo:
      if not hasPendingLayer:
        blaiMarkCpuModelParseMalformed(result, recordIndex)
      else:
        applyBlaiCpuSsdInfo(
          decodeBlaiCpuSsdInfo(stream[recordIndex]), pending.layer)
    of blaiCpuDspStatus:
      if not hasPendingLayer:
        blaiMarkCpuModelParseMalformed(result, recordIndex)
      else:
        result.lastStatus = decodeBlaiCpuDspStatus(stream[recordIndex])
        applyBlaiCpuDspStatus(result.lastStatus, pending.layer)
        let parsedCursor =
          blaiU32ArrayIndexCursor(result.storedLayerCount, parsedLayers.len)
        if parsedCursor.valid:
          pending.active = true
          pending.index = result.storedLayerCount
          parsedLayers[parsedCursor.index] = pending
          inc result.storedLayerCount
        else:
          result.overflow = true
        inc result.parsedLayerCount
        hasPendingLayer = false
        if result.declaredLayerCount != 0 and
            result.parsedLayerCount >= result.declaredLayerCount:
          break
    of blaiCpuInstructionUnknown:
      blaiMarkCpuModelParseMalformed(result, recordIndex)

  blaiFinishCpuModelParseResult(result, hasPendingLayer, stream.len)

proc blaiParseCpuModelInstructions*(
    stream: openArray[BlaiInstruction],
    parsedLayers: var openArray[BlaiCpuParsedLayerState]
      ): BlaiCpuModelParseResult =
  ## Convenience wrapper for parsed-state CPU/DSP parsing.
  blaiParseCpuModelInstructionsInto(stream, parsedLayers, result)

proc blaiNetParams*(header: BlaiCpuDspHeader): NpuNetParams =
  ## Project recovered CPU model header fields to SDK NPU runtime parameters.
  NpuNetParams(
    unsignedInput: header.unsignedInput,
    reluN: header.reluN,
    tensorflowMode: header.useTflite)

proc blaiForwardEncodedLayerReadyInto*(
    layer: BlaiCpuInstLayer64,
    outResult: var BlaiForwardEncodedLayerReadiness) =
  ## Report whether a parsed layer has the post-encoder fields required by the
  ## recovered forward_NPU workspace path.
  outResult = default(BlaiForwardEncodedLayerReadiness)
  outResult.npuLayer = layer.npuOn != 0
  if not outResult.npuLayer:
    outResult.ready = true
    return

  outResult.patchReady = layer.dramPatchSize > 0
  outResult.instructionReady = layer.instCnt > 0
  outResult.ready = outResult.patchReady and outResult.instructionReady

proc blaiForwardEncodedLayerReadiness*(
    layer: BlaiCpuInstLayer64): BlaiForwardEncodedLayerReadiness =
  ## Convenience result-returning wrapper for encoded-layer readiness.
  blaiForwardEncodedLayerReadyInto(layer, result)

proc blaiForwardEncodedLayerReadyInto*(
    parsed: BlaiCpuParsedLayerState,
    outResult: var BlaiForwardEncodedLayerReadiness) =
  ## Parsed-state wrapper for encoded-layer readiness.
  blaiForwardEncodedLayerReadyInto(parsed.layer, outResult)

proc blaiForwardEncodedLayerReadiness*(
    parsed: BlaiCpuParsedLayerState): BlaiForwardEncodedLayerReadiness =
  ## Convenience parsed-state wrapper for encoded-layer readiness.
  blaiForwardEncodedLayerReadyInto(parsed, result)

proc blaiForwardEncodedLayerReady*(layer: BlaiCpuInstLayer64): bool =
  ## Return whether a parsed NPU layer has the post-encoder fields needed by
  ## the recovered forward_NPU workspace path.
  ##
  ## CPU model records provide layer metadata, but allocator/encoder recovery
  ## fills `dramPatchSize` and `instCnt`. Non-NPU layers do not block NPU
  ## forward planning.
  blaiForwardEncodedLayerReadiness(layer).ready

proc blaiForwardEncodedLayerReady*(
    parsed: BlaiCpuParsedLayerState): bool =
  ## Parsed-state boolean wrapper for encoded-layer readiness.
  blaiForwardEncodedLayerReadiness(parsed).ready

proc blaiParsedForwardModelReadinessInto*(
    parsed: BlaiCpuModelParseResult,
    layers: openArray[BlaiCpuInstLayer64],
    outResult: var BlaiParsedForwardModelReadiness) =
  ## Summarize whether parsed CPU records are ready for forward_NPU planning.
  outResult = default(BlaiParsedForwardModelReadiness)
  outResult.parsed = parsed.complete and
    parsed.storedLayerCount == parsed.parsedLayerCount
  outResult.useTflite = parsed.useTflite
  outResult.netParams = blaiNetParams(parsed.header)
  outResult.layerCount = parsed.storedLayerCount
  let layerCapacity = blaiOpenArrayLenU32(layers)
  outResult.layerStorageFits = layerCapacity >= parsed.storedLayerCount
  if not outResult.layerStorageFits:
    outResult.missingLayerCount = parsed.storedLayerCount - layerCapacity
  outResult.firstUnencodedLayer = -1
  outResult.lastReadyLayer = -1
  if not outResult.parsed:
    return

  let limit = blaiBoundedU32Count(parsed.storedLayerCount, layers.len)
  for layerIndex in 0 ..< limit:
    if layers[layerIndex].npuOn == 0:
      continue
    inc outResult.npuLayerCount
    let readiness = blaiForwardEncodedLayerReadiness(layers[layerIndex])
    if readiness.ready:
      inc outResult.readyLayerCount
      outResult.lastReadyLayer = blaiLayerIndexValue(layerIndex)
    else:
      inc outResult.unencodedLayerCount
      if outResult.firstUnencodedLayer < 0:
        outResult.firstUnencodedLayer = blaiLayerIndexValue(layerIndex)
        outResult.firstUnencodedLayerCaptured = true
        outResult.firstUnencodedLayerReadiness = readiness

  outResult.forwardReady =
    outResult.layerStorageFits and outResult.unencodedLayerCount == 0

proc blaiParsedForwardModelReadiness*(
    parsed: BlaiCpuModelParseResult,
    layers: openArray[BlaiCpuInstLayer64]): BlaiParsedForwardModelReadiness =
  ## Convenience result-returning wrapper for parsed forward_NPU readiness.
  blaiParsedForwardModelReadinessInto(parsed, layers, result)

proc blaiParsedForwardModelReadinessInto*(
    parsed: BlaiCpuModelParseResult,
    layers: openArray[BlaiCpuParsedLayerState],
    outResult: var BlaiParsedForwardModelReadiness) =
  ## Summarize forward_NPU readiness from parsed layer state entries.
  outResult = default(BlaiParsedForwardModelReadiness)
  outResult.parsed = parsed.complete and
    parsed.storedLayerCount == parsed.parsedLayerCount
  outResult.useTflite = parsed.useTflite
  outResult.netParams = blaiNetParams(parsed.header)
  outResult.layerCount = parsed.storedLayerCount
  let layerCapacity = blaiOpenArrayLenU32(layers)
  outResult.layerStorageFits = layerCapacity >= parsed.storedLayerCount
  if not outResult.layerStorageFits:
    outResult.missingLayerCount = parsed.storedLayerCount - layerCapacity
  outResult.firstUnencodedLayer = -1
  outResult.lastReadyLayer = -1
  if not outResult.parsed:
    return

  let limit = blaiBoundedU32Count(parsed.storedLayerCount, layers.len)
  for layerIndex in 0 ..< limit:
    if not layers[layerIndex].active or layers[layerIndex].layer.npuOn == 0:
      continue
    inc outResult.npuLayerCount
    let readiness = blaiForwardEncodedLayerReadiness(layers[layerIndex].layer)
    if readiness.ready:
      inc outResult.readyLayerCount
      outResult.lastReadyLayer = blaiLayerIndexValue(layerIndex)
    else:
      inc outResult.unencodedLayerCount
      if outResult.firstUnencodedLayer < 0:
        outResult.firstUnencodedLayer = blaiLayerIndexValue(layerIndex)
        outResult.firstUnencodedLayerCaptured = true
        outResult.firstUnencodedLayerReadiness = readiness

  outResult.forwardReady =
    outResult.layerStorageFits and outResult.unencodedLayerCount == 0

proc blaiParsedForwardModelReadiness*(
    parsed: BlaiCpuModelParseResult,
    layers: openArray[BlaiCpuParsedLayerState]
      ): BlaiParsedForwardModelReadiness =
  ## Convenience wrapper for parsed-state forward_NPU readiness.
  blaiParsedForwardModelReadinessInto(parsed, layers, result)

proc isBlaiExternalInstruction*(inst: BlaiInstruction): bool =
  ## SDK test: byte0 bit0 set and final halt bit clear.
  (blaiBit(inst, 0) == 1'u32) and (blaiBit(inst, 127) == 0'u32)

proc isBlaiLayerInstruction*(inst: BlaiInstruction): bool =
  ## SDK test: byte0 bit0 clear.
  blaiBit(inst, 0) == 0'u32

proc blaiInstructionHalt*(inst: BlaiInstruction): bool =
  blaiBit(inst, 127) != 0'u32

proc decodeBlaiExtraInstruction*(inst: BlaiInstruction): BlaiDecodedExtraInstruction =
  ## Decode one recovered `inst_extra` side instruction.
  result.isExtra = blaiBits(inst, 0, 1) != 0'u32
  result.inSegW = blaiBits(inst, 1, 12)
  result.outSegW = blaiBits(inst, 13, 12)
  result.outW = blaiBits(inst, 25, 12)
  result.inGroupC = blaiBits(inst, 37, 12)
  result.outGroupC = blaiBits(inst, 49, 12)
  result.outSegC = blaiBits(inst, 61, 12)
  result.outH = blaiBits(inst, 73, 12)
  result.stride = blaiBits(inst, 85, 3) + 1'u32
  result.dilation = blaiBits(inst, 88, 3) + 1'u32
  result.leftShift = blaiSignedBits(inst, 91, 6)

proc decodeBlaiExternalLayerInfo*(inst: BlaiInstruction): BlaiExternalLayerInfo =
  ## Decode the optional extension header used for stride/dilation/groups.
  let decoded = decodeBlaiExtraInstruction(inst)
  result.valid = decoded.isExtra and not blaiInstructionHalt(inst)
  if result.valid:
    result.stride = decoded.stride
    result.dilation = decoded.dilation
    result.groups = decoded.inGroupC

proc decodeBlaiLayerType*(inst: BlaiInstruction): BlaiLayerType =
  let
    op = blaiBits(inst, 100, 2)
    route = blaiBits(inst, 99, 1)
    pool = blaiBits(inst, 98, 1)
    upsample = blaiBits(inst, 125, 1)
    altPool = blaiBits(inst, 126, 1)

  if op == 1 and route == 0 and pool == 0:
    blaiConvolutional
  elif op == 1 and route == 1 and pool == 0:
    blaiRouteConv
  elif op == 1 and route == 0 and pool == 1:
    blaiConvMax
  elif op == 0 and route == 0 and pool == 1:
    blaiMaxpool
  elif op == 0 and route == 1 and pool == 0 and upsample == 0:
    blaiRoute
  elif op == 0 and route == 1 and pool == 1:
    blaiRouteMax
  elif op == 2:
    blaiShortcut
  elif op == 3:
    blaiMatmul
  elif upsample == 1 and route == 0:
    blaiUpsample
  elif op == 0 and altPool == 1:
    blaiMaxpool
  elif upsample == 1 and route == 1:
    blaiRouteUpsample
  else:
    blaiUnknown

proc decodeBlaiLayer*(inst: BlaiInstruction,
                      ext: BlaiExternalLayerInfo = BlaiExternalLayerInfo()): BlaiDecodedLayer =
  ## Decode one normal SDK NPU layer instruction. Passing the preceding external
  ## instruction, when present, applies the SDK stride/dilation/group override.
  result.layerType = decodeBlaiLayerType(inst)
  result.w = blaiBits(inst, 1, 12)
  result.h = blaiBits(inst, 13, 12)
  result.c = blaiBits(inst, 25, 12)
  result.cn0 = blaiBits(inst, 37, 12)
  result.outC = blaiBits(inst, 49, 12)
  result.fdata = blaiBits(inst, 61, 5)
  result.fweight = blaiBits(inst, 66, 5)
  result.fbias = blaiBits(inst, 71, 5)
  result.froute1 = blaiBits(inst, 76, 5)
  result.froute2 = blaiBits(inst, 81, 5)
  result.fout = blaiBits(inst, 86, 5)
  result.size = blaiBits(inst, 91, 3)
  result.activation = blaiBits(inst, 94, 5)
  result.tfOutputOffset = blaiBits(inst, 77, 8)
  result.imgIn = blaiBits(inst, 97, 1) != 0'u32
  result.maxCheck = blaiBits(inst, 98, 1) != 0'u32
  result.routeBit = blaiBits(inst, 99, 1) != 0'u32
  result.macBit = blaiBits(inst, 100, 2)
  result.inLayer1Mem = blaiBits(inst, 102, 5)
  result.inLayer2Mem = blaiBits(inst, 107, 5)
  result.outLayerMem = blaiBits(inst, 112, 5)
  result.midLayerMem = blaiBits(inst, 117, 5)
  result.midOut = blaiBits(inst, 122, 1) != 0'u32
  result.midOutState = blaiBits(inst, 123, 1) != 0'u32
  result.halt = blaiInstructionHalt(inst)
  result.upsampleBit = blaiBits(inst, 125, 1) != 0'u32
  result.macBitExt = blaiBits(inst, 126, 1) != 0'u32
  result.instEndBit = blaiBits(inst, 127, 1) != 0'u32

  if ext.valid:
    result.stride = ext.stride
    result.dilation = ext.dilation
    result.groups = ext.groups
  else:
    result.stride = 1
    result.dilation = 1
    result.groups = 1

  if result.groups == 0:
    result.groups = 1
  else:
    result.groups = result.c div result.groups

proc blaiEncodeShapeDescriptor*(shape: BlaiNpuShapeDescriptor): BlaiInstruction =
  ## Encode the five base 12-bit NPU descriptor dimensions recovered from
  ## `blai_instruction_t.{normal,tflite}`.
  ##
  ## Bit 0 remains clear, matching a normal layer instruction rather than an
  ## external descriptor.
  blaiPutBits(result, 1, 12, shape.layerW)
  blaiPutBits(result, 13, 12, shape.layerH)
  blaiPutBits(result, 25, 12, shape.layerC1)
  blaiPutBits(result, 37, 12, shape.layerC2)
  blaiPutBits(result, 49, 12, shape.layerO)

proc blaiEncodeNormalDescriptor*(desc: BlaiNpuNormalDescriptor): BlaiInstruction =
  ## Encode the normal descriptor fields recovered from `blai_instruction_t`.
  result = blaiEncodeShapeDescriptor(desc.shape)
  blaiPutBits(result, 61, 5, desc.fdata)
  blaiPutBits(result, 66, 5, desc.fweight)
  blaiPutBits(result, 71, 5, desc.fbias)
  blaiPutBits(result, 76, 5, desc.froute1)
  blaiPutBits(result, 81, 5, desc.froute2)
  blaiPutBits(result, 86, 5, desc.fout)
  blaiPutBits(result, 91, 3, desc.convSize)
  blaiPutBits(result, 94, 3, desc.activation)

proc decodeBlaiNormalDescriptorInstruction*(
    inst: BlaiInstruction): BlaiDecodedNormalDescriptorInstruction =
  ## Decode one recovered normal main descriptor instruction.
  result.shape.layerW = blaiBits(inst, 1, 12)
  result.shape.layerH = blaiBits(inst, 13, 12)
  result.shape.layerC1 = blaiBits(inst, 25, 12)
  result.shape.layerC2 = blaiBits(inst, 37, 12)
  result.shape.layerO = blaiBits(inst, 49, 12)
  result.fdata = blaiBits(inst, 61, 5)
  result.fweight = blaiBits(inst, 66, 5)
  result.fbias = blaiBits(inst, 71, 5)
  result.froute1 = blaiBits(inst, 76, 5)
  result.froute2 = blaiBits(inst, 81, 5)
  result.fout = blaiBits(inst, 86, 5)
  result.convSize = blaiBits(inst, 91, 3)
  result.activation = blaiBits(inst, 94, 3)

proc blaiEncodeTfliteDescriptor*(desc: BlaiNpuTfliteDescriptor): BlaiInstruction =
  ## Encode the recovered TFLite descriptor fields from `blai_instruction_t`.
  result = blaiEncodeShapeDescriptor(desc.shape)
  blaiPutBits(result, 61, 8, desc.tfInput1Offset)
  blaiPutBits(result, 69, 8, desc.tfInput2Offset)
  blaiPutBits(result, 77, 8, desc.tfOutputOffset)
  blaiPutBits(result, 85, 6, blaiSignedFieldBits(desc.tfOutputShift))
  blaiPutBits(result, 91, 3, desc.convSize)
  blaiPutBits(result, 94, 3, desc.activation)

proc decodeBlaiTfliteDescriptorInstruction*(
    inst: BlaiInstruction): BlaiDecodedTfliteDescriptorInstruction =
  ## Decode one recovered TFLite main descriptor instruction.
  result.shape.layerW = blaiBits(inst, 1, 12)
  result.shape.layerH = blaiBits(inst, 13, 12)
  result.shape.layerC1 = blaiBits(inst, 25, 12)
  result.shape.layerC2 = blaiBits(inst, 37, 12)
  result.shape.layerO = blaiBits(inst, 49, 12)
  result.tfInput1Offset = blaiBits(inst, 61, 8)
  result.tfInput2Offset = blaiBits(inst, 69, 8)
  result.tfOutputOffset = blaiBits(inst, 77, 8)
  result.tfOutputShift = blaiSignedBits(inst, 85, 6)
  result.convSize = blaiBits(inst, 91, 3)
  result.activation = blaiBits(inst, 94, 3)

proc blaiBoolBit(value: bool): uint32 =
  if value: 1'u32 else: 0'u32

proc blaiEncodeTfliteQuantDescriptor*(
    desc: BlaiNpuTfliteQuantDescriptor): BlaiInstruction =
  ## Encode the recovered `inst_tflite` quantization side instruction.
  blaiPutBits(result, 0, 1, blaiBoolBit(desc.isTflite))
  blaiPutBits(result, 1, 6, blaiSignedFieldBits(desc.tfInput1Shift))
  blaiPutBits(result, 7, 6, blaiSignedFieldBits(desc.tfInput2Shift))
  blaiPutBits(result, 13, 32, desc.tfInput1Multiplier)
  blaiPutBits(result, 45, 32, desc.tfInput2Multiplier)
  blaiPutBits(result, 77, 32, desc.tfOutputMultiplier)
  blaiPutBits(result, 109, 8, desc.quantizedActivationMin)
  blaiPutBits(result, 117, 8, desc.quantizedActivationMax)

proc decodeBlaiTfliteQuantInstruction*(
    inst: BlaiInstruction): BlaiDecodedTfliteQuantInstruction =
  ## Decode one recovered `inst_tflite` side instruction.
  result.isTflite = blaiBits(inst, 0, 1) != 0'u32
  result.tfInput1Shift = blaiSignedBits(inst, 1, 6)
  result.tfInput2Shift = blaiSignedBits(inst, 7, 6)
  result.tfInput1Multiplier = blaiBits(inst, 13, 32)
  result.tfInput2Multiplier = blaiBits(inst, 45, 32)
  result.tfOutputMultiplier = blaiBits(inst, 77, 32)
  result.quantizedActivationMin = blaiBits(inst, 109, 8)
  result.quantizedActivationMax = blaiBits(inst, 117, 8)

proc blaiEncodeExtraDescriptor*(desc: BlaiNpuExtraDescriptor): BlaiInstruction =
  ## Encode the recovered `inst_extra` side instruction.
  ##
  ## The SDK stores stride and dilation as minus-one values in this record.
  blaiPutBits(result, 0, 1, blaiBoolBit(desc.isExtra))
  blaiPutBits(result, 1, 12, desc.inSegW)
  blaiPutBits(result, 13, 12, desc.outSegW)
  blaiPutBits(result, 25, 12, desc.outW)
  blaiPutBits(result, 37, 12, desc.inGroupC)
  blaiPutBits(result, 49, 12, desc.outGroupC)
  blaiPutBits(result, 61, 12, desc.outSegC)
  blaiPutBits(result, 73, 12, desc.outH)
  blaiPutBits(result, 85, 3, if desc.stride == 0: 0'u32 else: desc.stride - 1'u32)
  blaiPutBits(result, 88, 3, if desc.dilation == 0: 0'u32 else: desc.dilation - 1'u32)
  blaiPutBits(result, 91, 6, blaiSignedFieldBits(desc.leftShift))

proc blaiApplyCommonDescriptor*(inst: var BlaiInstruction,
                                common: BlaiNpuCommonDescriptor) =
  ## Apply the recovered common descriptor control and memory fields shared by
  ## normal and TFLite descriptors.
  blaiPutBits(inst, 97, 1, blaiBoolBit(common.imgIn))
  blaiPutBits(inst, 98, 1, blaiBoolBit(common.maxCheck))
  blaiPutBits(inst, 99, 1, blaiBoolBit(common.routeBit))
  blaiPutBits(inst, 100, 2, common.macBit)
  blaiPutBits(inst, 102, 5, common.inLayer1Mem)
  blaiPutBits(inst, 107, 5, common.inLayer2Mem)
  blaiPutBits(inst, 112, 5, common.outLayerMem)
  blaiPutBits(inst, 117, 5, common.midLayerMem)
  blaiPutBits(inst, 122, 1, blaiBoolBit(common.midOut))
  blaiPutBits(inst, 123, 1, blaiBoolBit(common.midOutState))
  blaiPutBits(inst, 124, 1, blaiBoolBit(common.halt))
  blaiPutBits(inst, 125, 1, blaiBoolBit(common.upsampleBit))
  blaiPutBits(inst, 126, 1, blaiBoolBit(common.macBitExt))
  blaiPutBits(inst, 127, 1, blaiBoolBit(common.instEndBit))

proc blaiNormalInstructionBundle*(
    desc: BlaiNpuNormalDescriptor,
    common: BlaiNpuCommonDescriptor,
    extra: BlaiNpuExtraDescriptor = BlaiNpuExtraDescriptor()
  ): BlaiNpuInstructionBundle =
  ## Build the recovered normal `blai_instruction_t` bundle shape.
  result.inst = blaiEncodeNormalDescriptor(desc)
  blaiApplyCommonDescriptor(result.inst, common)
  if extra.isExtra:
    result.instExtra = blaiEncodeExtraDescriptor(extra)
    result.extraInfo = 1

proc blaiTfliteInstructionBundle*(
    desc: BlaiNpuTfliteDescriptor,
    common: BlaiNpuCommonDescriptor,
    quant: BlaiNpuTfliteQuantDescriptor,
    extra: BlaiNpuExtraDescriptor = BlaiNpuExtraDescriptor()
  ): BlaiNpuInstructionBundle =
  ## Build the recovered TFLite `blai_instruction_t` bundle shape.
  result.instTflite = blaiEncodeTfliteQuantDescriptor(quant)
  result.inst = blaiEncodeTfliteDescriptor(desc)
  blaiApplyCommonDescriptor(result.inst, common)
  result.useTflite = 1
  if extra.isExtra:
    result.instExtra = blaiEncodeExtraDescriptor(extra)
    result.extraInfo = 1

proc blaiLayerCount*(stream: openArray[BlaiInstruction]): uint32 =
  ## Count normal layer headers using the SDK stopping rule.
  for inst in stream:
    if isBlaiLayerInstruction(inst):
      inc result
      if blaiInstructionHalt(inst):
        break

proc blaiLayerTypeFromSdk*(value: int32): BlaiLayerType =
  ## Convert an SDK layer-type integer to the recovered Nim enum.
  case value
  of BlaiSdkConvolutionalType: blaiConvolutional
  of BlaiSdkMaxpoolType: blaiMaxpool
  of BlaiSdkAvgpoolType: blaiAvgpool
  of BlaiSdkRouteType: blaiRoute
  of BlaiSdkShortcutType: blaiShortcut
  of BlaiSdkMatmulType: blaiMatmul
  of BlaiSdkUpsampleType: blaiUpsample
  of BlaiSdkYoloType: blaiYolo
  of BlaiSdkSoftmaxType: blaiSoftmax
  of BlaiSdkConvMaxType: blaiConvMax
  of BlaiSdkRouteMaxType: blaiRouteMax
  of BlaiSdkRouteConvType: blaiRouteConv
  of BlaiSdkRouteUpsampleType: blaiRouteUpsample
  of BlaiSdkReshapeType: blaiReshape
  of BlaiSdkRouteWType: blaiRouteW
  of BlaiSdkLogisticLayerType: blaiLogisticLayer
  of BlaiSdkSsdType: blaiSsd
  of BlaiSdkTransposeType: blaiTranspose
  of BlaiSdkPadType: blaiPad
  of BlaiSdkLogSoftmaxType: blaiLogSoftmax
  of BlaiSdkDequantizeType: blaiDequantize
  of BlaiSdkTransposeLkType: blaiTransposeLk
  of BlaiSdkMeanType: blaiMean
  of BlaiSdkGatherType: blaiGather
  of BlaiSdkCustomLayerType: blaiCustomLayer
  of BlaiSdkPreTransconvType: blaiPreTransconv
  else: blaiUnknown

proc nonNegativeU32(value: int32): uint32 =
  if value <= 0:
    0'u32
  else:
    value.uint32

proc blaiShapeDescriptor*(layer: BlaiCpuInstLayer64,
                          c2: uint32 = 0'u32): BlaiNpuShapeDescriptor =
  ## Build the base descriptor dimensions used at the front of fetch emitters.
  result.layerW = nonNegativeU32(layer.w)
  result.layerH = nonNegativeU32(layer.h)
  result.layerC1 = nonNegativeU32(layer.c)
  result.layerC2 = c2
  result.layerO = nonNegativeU32(layer.outC)

proc blaiNormalDescriptor*(layer: BlaiCpuInstLayer64,
                           c2: uint32 = 0'u32): BlaiNpuNormalDescriptor =
  ## Build the recovered normal descriptor fields from a CPU-layer ABI object.
  result.shape = blaiShapeDescriptor(layer, c2)
  result.fdata = nonNegativeU32(layer.fdata)
  result.fweight = nonNegativeU32(layer.fweight)
  result.fbias = nonNegativeU32(layer.fbias)
  result.froute1 = nonNegativeU32(layer.froute1)
  result.froute2 = nonNegativeU32(layer.froute2)
  result.fout = nonNegativeU32(layer.fout)
  result.convSize = nonNegativeU32(layer.size)
  result.activation = nonNegativeU32(layer.activation)

proc blaiTfliteDescriptor*(layer: BlaiCpuInstLayer64,
                           c2: uint32 = 0'u32): BlaiNpuTfliteDescriptor =
  ## Build the recovered TFLite descriptor fields from a CPU-layer ABI object.
  result.shape = blaiShapeDescriptor(layer, c2)
  result.tfInput1Offset = nonNegativeU32(layer.tfInput1Offset)
  result.tfInput2Offset = nonNegativeU32(layer.tfInput2Offset)
  result.tfOutputOffset = nonNegativeU32(layer.tfOutputOffset)
  result.tfOutputShift = layer.tfOutputShift
  result.convSize = nonNegativeU32(layer.size)
  result.activation = nonNegativeU32(layer.activation)

proc blaiTfliteQuantDescriptor*(
    layer: BlaiCpuInstLayer64): BlaiNpuTfliteQuantDescriptor =
  ## Build the recovered `inst_tflite` side instruction fields from a CPU-layer
  ## ABI object.
  result.isTflite = true
  result.tfInput1Shift = layer.tfInput1Shift
  result.tfInput2Shift = layer.tfInput2Shift
  result.tfInput1Multiplier = blaiUint32FromInt32Bits(layer.tfInput1Multiplier)
  result.tfInput2Multiplier = blaiUint32FromInt32Bits(layer.tfInput2Multiplier)
  result.tfOutputMultiplier = blaiUint32FromInt32Bits(layer.tfOutputMultiplier)
  result.quantizedActivationMin = nonNegativeU32(layer.quantizedActivationMin)
  result.quantizedActivationMax = nonNegativeU32(layer.quantizedActivationMax)

proc blaiDivOrZero(value, divisor: uint32): uint32 =
  if divisor == 0'u32: 0'u32 else: value div divisor

proc blaiExtraDescriptor*(layer: BlaiCpuInstLayer64): BlaiNpuExtraDescriptor =
  ## Build the recovered `inst_extra` side instruction fields from a CPU-layer
  ## ABI object.
  let
    inputChannels = nonNegativeU32(layer.c)
    outputChannels = nonNegativeU32(layer.outC)
    groups = max(nonNegativeU32(layer.groups), 1'u32)
  result.isExtra = true
  result.inSegW = nonNegativeU32(layer.w)
  result.outSegW = nonNegativeU32(layer.outW)
  result.outW = nonNegativeU32(layer.outW)
  result.inGroupC = blaiDivOrZero(inputChannels, groups)
  result.outGroupC = blaiDivOrZero(outputChannels, groups)
  result.outSegC = outputChannels
  result.outH = nonNegativeU32(layer.outH)
  result.stride = nonNegativeU32(layer.stride)
  result.dilation = nonNegativeU32(layer.dilation)
  result.leftShift = layer.tfLeftShift

proc blaiCommonControlDescriptor*(layerType: BlaiLayerType): BlaiNpuCommonDescriptor =
  ## Build the recovered common descriptor operation bits for a layer type.
  case layerType
  of blaiConvolutional:
    result.macBit = 1
  of blaiRouteConv:
    result.routeBit = true
    result.macBit = 1
  of blaiConvMax:
    result.maxCheck = true
    result.macBit = 1
  of blaiMaxpool:
    result.maxCheck = true
  of blaiRoute:
    result.routeBit = true
  of blaiRouteMax:
    result.maxCheck = true
    result.routeBit = true
  of blaiShortcut:
    result.macBit = 2
  of blaiMatmul:
    result.macBit = 3
  of blaiUpsample:
    result.upsampleBit = true
  of blaiRouteUpsample:
    result.routeBit = true
    result.upsampleBit = true
  else:
    discard

proc blaiCommonDescriptor*(layer: BlaiCpuInstLayer64,
                           plan: BlaiFetchMemoryPlan,
                           descriptorHalt: bool = false,
                           midOutState: bool = false): BlaiNpuCommonDescriptor =
  ## Build recovered common descriptor fields from CPU-layer ABI and fetch plan.
  result = blaiCommonControlDescriptor(blaiLayerTypeFromSdk(layer.layerType))
  result.imgIn = layer.imgIn != 0
  if plan.inputCount > 0:
    result.inLayer1Mem = plan.inputSlots[0]
  if plan.inputCount > 1:
    result.inLayer2Mem = plan.inputSlots[1]
  result.outLayerMem = plan.outputSlot
  result.midLayerMem = plan.midOutputSlot
  result.midOut = layer.midOut != 0
  result.midOutState = midOutState
  result.halt = descriptorHalt
  result.instEndBit = layer.halt != 0

proc blaiFetchDescriptorC2*(layer: BlaiCpuInstLayer64,
                            kind: BlaiFetchMemoryKind): uint32 =
  ## Recover the `layer_c2` operand visible in `fetch_BLAI_data_*`.
  case kind
  of blaiFetchGeneral:
    if nonNegativeU32(layer.n) > 1'u32:
      blaiChannelAlign4(nonNegativeU32(blaiLayerCn(layer, 1'u32)))
    else:
      0'u32
  of blaiFetchRoute:
    if nonNegativeU32(layer.inputNum) > 1'u32:
      blaiChannelAlign4(nonNegativeU32(blaiLayerCn(layer, 1'u32)))
    else:
      0'u32

proc blaiFetchDescriptorNeedsExtra*(layer: BlaiCpuInstLayer64,
                                    ctrl: BlaiPsramCtrl): bool =
  ## Recover the `extra_info` decision before SDK `instruction_encode`.
  let layerType = blaiLayerTypeFromSdk(layer.layerType)
  if layerType in {blaiConvMax, blaiRouteMax} and
     nonNegativeU32(layer.stride) == 1'u32 and
     nonNegativeU32(layer.size) > 3'u32:
    return nonNegativeU32(ctrl.linePatchCount) > 1'u32

  nonNegativeU32(ctrl.weightPatchCount) > 1'u32 or
    nonNegativeU32(ctrl.linePatchCount) > 1'u32 or
    nonNegativeU32(layer.groups) > 1'u32 or
    nonNegativeU32(layer.stride) > 1'u32 or
    nonNegativeU32(layer.dilation) > 1'u32

proc blaiPlanFetchDescriptorOperandsInto*(
    layer: BlaiCpuInstLayer64,
    ctrl: BlaiPsramCtrl,
    kind: BlaiFetchMemoryKind,
    outResult: var BlaiFetchDescriptorOperands) =
  ## Plan descriptor operands recovered from the front of `fetch_BLAI_data_*`.
  outResult = default(BlaiFetchDescriptorOperands)
  outResult.kind = kind
  outResult.layerType = blaiLayerTypeFromSdk(layer.layerType)
  case kind
  of blaiFetchGeneral:
    outResult.multiInputC2 = nonNegativeU32(layer.n) > 1'u32
  of blaiFetchRoute:
    outResult.multiInputC2 = nonNegativeU32(layer.inputNum) > 1'u32
  outResult.alignedFirstInputChannels =
    blaiChannelAlign4(nonNegativeU32(blaiLayerCn(layer, 1'u32)))
  if outResult.multiInputC2:
    outResult.c2 = outResult.alignedFirstInputChannels

  outResult.weightPatchExtra = nonNegativeU32(ctrl.weightPatchCount) > 1'u32
  outResult.linePatchExtra = nonNegativeU32(ctrl.linePatchCount) > 1'u32
  outResult.groupedExtra = nonNegativeU32(layer.groups) > 1'u32
  outResult.strideExtra = nonNegativeU32(layer.stride) > 1'u32
  outResult.dilationExtra = nonNegativeU32(layer.dilation) > 1'u32
  outResult.maxPoolLinePatchExtra =
    outResult.layerType in {blaiConvMax, blaiRouteMax} and
    nonNegativeU32(layer.stride) == 1'u32 and
    nonNegativeU32(layer.size) > 3'u32 and
    outResult.linePatchExtra
  if outResult.layerType in {blaiConvMax, blaiRouteMax} and
     nonNegativeU32(layer.stride) == 1'u32 and
     nonNegativeU32(layer.size) > 3'u32:
    outResult.includeExtra = outResult.maxPoolLinePatchExtra
  else:
    outResult.includeExtra = outResult.weightPatchExtra or
      outResult.linePatchExtra or outResult.groupedExtra or
      outResult.strideExtra or outResult.dilationExtra

proc blaiPlanFetchDescriptorOperands*(
    layer: BlaiCpuInstLayer64,
    ctrl: BlaiPsramCtrl,
    kind: BlaiFetchMemoryKind): BlaiFetchDescriptorOperands =
  ## Convenience result-returning wrapper for fetch descriptor operands.
  blaiPlanFetchDescriptorOperandsInto(layer, ctrl, kind, result)

proc blaiRouteDescriptorNextInputCursor*(
    stepIndex, inputNum: uint32): BlaiRouteDescriptorNextInputCursor =
  ## Resolve the recovered route step to the next logical input channel slot.
  if stepIndex == high(uint32):
    return
  let stepCursor = blaiRouteDescriptorStepCursor(stepIndex)
  if not stepCursor.valid:
    return
  result.stepIndex = stepIndex
  result.logicalInput = stepIndex + 1'u32
  result.cnSlot = stepCursor.index
  result.hasChannels = result.logicalInput < inputNum
  result.valid = true

proc blaiPlanRouteDescriptorLoopInto*(
    layer: BlaiCpuInstLayer64,
    outResult: var BlaiRouteDescriptorLoopPlan) =
  ## Recover the channel-carrying loop in `fetch_BLAI_data_route`.
  ##
  ## The SDK emits one descriptor for each additional route input. Each
  ## iteration starts from the cumulative channel count so far, uses the next
  ## input channel count as the descriptor's second channel operand, then carries
  ## the sum into the next iteration.
  outResult = default(BlaiRouteDescriptorLoopPlan)
  let inputCount = max(nonNegativeU32(layer.inputNum), 2'u32)
  outResult.inputCount = inputCount
  if inputCount == 0'u32 or inputCount > BlaiMaxInputNumU32:
    return

  outResult.descriptorCount = inputCount - 1'u32
  if outResult.descriptorCount > BlaiMaxRouteInputNumU32:
    return

  var cumulative = nonNegativeU32(layer.c)
  for index in 0'u32 ..< outResult.descriptorCount:
    let nextInput = blaiRouteDescriptorNextInputCursor(
      index, nonNegativeU32(layer.inputNum))
    if not nextInput.valid:
      return
    let nextChannels =
      if nextInput.hasChannels:
        nonNegativeU32(layer.cn[nextInput.cnSlot])
      else:
        0'u32
    outResult.steps[nextInput.cnSlot] = BlaiRouteDescriptorStep(
      index: index,
      cumulativeInputChannels: cumulative,
      nextInputChannels: nextChannels,
      descriptorC1: cumulative,
      descriptorC2: nextChannels,
      cumulativeOutputChannels: cumulative + nextChannels)
    cumulative += nextChannels
  outResult.fits = true

proc blaiPlanRouteDescriptorLoop*(
    layer: BlaiCpuInstLayer64): BlaiRouteDescriptorLoopPlan =
  ## Convenience result-returning wrapper for route descriptor-loop planning.
  blaiPlanRouteDescriptorLoopInto(layer, result)

proc blaiRouteDescriptorStepPosition*(
    stepIndex, descriptorCount: uint32): BlaiRouteDescriptorStepPosition =
  ## Resolve a recovered route descriptor-loop step and whether it is terminal.
  if stepIndex >= descriptorCount:
    return
  let stepCursor = blaiRouteDescriptorStepCursor(stepIndex)
  if not stepCursor.valid:
    return
  result.stepIndex = stepIndex
  result.stepSlot = stepCursor.index
  result.last = stepIndex == descriptorCount - 1'u32
  result.valid = true

proc blaiLayerInstructionBundle*(layer: BlaiCpuInstLayer64,
                                 plan: BlaiFetchMemoryPlan,
                                 useTflite: bool,
                                 c2: uint32 = 0'u32,
                                 includeExtra: bool = false,
                                 descriptorHalt: bool = false,
                                 midOutState: bool = false): BlaiNpuInstructionBundle =
  ## Build the recovered descriptor bundle from a CPU-layer ABI object.
  ##
  ## `c2` and `includeExtra` remain explicit for callers that already resolved
  ## the surrounding `fetch_BLAI_data_*` operand decisions.
  let common = blaiCommonDescriptor(layer, plan, descriptorHalt, midOutState)
  let extra =
    if includeExtra: blaiExtraDescriptor(layer) else: BlaiNpuExtraDescriptor()
  if useTflite:
    blaiTfliteInstructionBundle(
      blaiTfliteDescriptor(layer, c2),
      common,
      blaiTfliteQuantDescriptor(layer),
      extra)
  else:
    blaiNormalInstructionBundle(
      blaiNormalDescriptor(layer, c2),
      common,
      extra)

proc blaiLayerInstructionBundle*(layer: BlaiCpuInstLayer64,
                                 plan: BlaiFetchMemoryPlan,
                                 useTflite: bool,
                                 operands: BlaiFetchDescriptorOperands,
                                 descriptorHalt: bool = false,
                                 midOutState: bool = false): BlaiNpuInstructionBundle =
  ## Build the descriptor bundle using recovered fetch operand decisions.
  blaiLayerInstructionBundle(
    layer, plan, useTflite, operands.c2, operands.includeExtra,
    descriptorHalt, midOutState)

proc blaiInstructionEncodeRequiredInto*(bundle: BlaiNpuInstructionBundle,
                                        outResult: var BlaiInstructionEncodeCountResult)
proc blaiInstructionEncodeRequired*(bundle: BlaiNpuInstructionBundle): uint32

proc blaiEncodeInstructionsInto*(bundle: BlaiNpuInstructionBundle,
                                 stream: var openArray[BlaiInstruction],
                                 startCount: uint32,
                                 outResult: var BlaiInstructionEncodeResult)

proc blaiEncodeInstructions*(bundle: BlaiNpuInstructionBundle,
                             stream: var openArray[BlaiInstruction],
                             startCount: uint32): BlaiInstructionEncodeResult

proc blaiRouteSlotCursor*(slot: uint32): BlaiRouteSlotCursor =
  ## Resolve a recovered route slot number into a bounded Nim array index.
  let cursor = blaiU32ArrayIndexCursor(slot, BlaiMaxInputNum)
  if not cursor.valid:
    return
  result.slotIndex = cursor.index
  result.valid = true

proc blaiRouteNextSlotIndex*(slot: uint32): BlaiRouteNextSlotIndex =
  ## Resolve the recovered route descriptor next-input slot projection.
  if slot == high(uint32):
    return
  let routeSlot = slot + 1'u32
  let cursor = blaiRouteSlotCursor(routeSlot)
  if not cursor.valid:
    return
  result.routeSlot = routeSlot
  result.slotIndex = cursor.slotIndex
  result.valid = true

proc blaiRouteNextSlotCursor*(slot: uint32): BlaiRouteSlotCursor =
  ## Resolve the recovered `slot + 1` route descriptor/SRAM convention.
  let nextSlot = blaiRouteNextSlotIndex(slot)
  if not nextSlot.valid:
    return
  result.slotIndex = nextSlot.slotIndex
  result.valid = true

proc blaiRoutePreviousOutputSlotCursor*(
    stepIndex, outputSlotCount: uint32): BlaiRoutePreviousOutputSlotCursor =
  ## Resolve the previous route output slot for non-initial descriptor steps.
  if stepIndex == 0'u32:
    return
  let outputSlot = stepIndex - 1'u32
  if outputSlot >= outputSlotCount:
    return
  let cursor = blaiRouteSlotCursor(outputSlot)
  if not cursor.valid:
    return
  result.outputSlot = outputSlot
  result.slotIndex = cursor.slotIndex
  result.valid = true

proc blaiRouteOutputSlotCursor*(
    stepIndex, cursor, outputW, outputH, cumulativeChannels,
    patchSize: uint32): BlaiRouteOutputSlotCursor =
  ## Resolve one recovered intermediate route output slot and cursor advance.
  if patchSize == 0'u32:
    return
  let outputSlot = blaiRouteNextSlotCursor(stepIndex)
  if not outputSlot.valid:
    return
  let elements =
    outputW.uint64 * outputH.uint64 * cumulativeChannels.uint64
  var outputElements: uint32
  if not blaiU64ExactU32Count(elements, outputElements):
    return
  let patchCount = blaiCeilDivU32(outputElements, patchSize)
  if patchCount > high(uint32) - cursor:
    return
  result.stepIndex = stepIndex
  result.slotIndex = outputSlot.slotIndex
  result.slot = cursor
  result.outputElements = outputElements
  result.patchCount = patchCount
  result.nextCursor = cursor + patchCount
  result.valid = true

proc blaiRouteStepFetchMemoryPlan(plan: BlaiFetchMemoryPlan,
                                  step: BlaiRouteDescriptorStep): BlaiFetchMemoryPlan =
  result = plan
  result.inputCount = 2
  result.inputSlots[0] =
    if step.index == 0'u32:
      plan.inputSlots[0]
    else:
      plan.outputSlot
  let nextInput = blaiRouteNextSlotCursor(step.index)
  if nextInput.valid:
    result.inputSlots[1] = plan.inputSlots[nextInput.slotIndex]
  else:
    result.inputSlots[1] = 0
  result.outputSlot = plan.outputSlot

proc blaiRouteStepFetchMemoryPlan(plan: BlaiRouteSramSlotPlan,
                                  step: BlaiRouteDescriptorStep): BlaiFetchMemoryPlan =
  result = plan.memory
  result.inputCount = 2
  let previousOutput = blaiRoutePreviousOutputSlotCursor(
    step.index, plan.outputSlotCount)
  result.inputSlots[0] =
    if step.index == 0'u32:
      plan.memory.inputSlots[0]
    elif previousOutput.valid:
      plan.outputSlots[previousOutput.slotIndex]
    else:
      0
  let nextInput = blaiRouteNextSlotCursor(step.index)
  if nextInput.valid:
    result.inputSlots[1] = plan.memory.inputSlots[nextInput.slotIndex]
  else:
    result.inputSlots[1] = 0
  result.outputSlot =
    if step.index < plan.outputSlotCount:
      let currentOutput = blaiRouteSlotCursor(step.index)
      if currentOutput.valid: plan.outputSlots[currentOutput.slotIndex] else: 0'u32
    else:
      plan.memory.outputSlot

proc blaiEmitRouteLayerInstructionsInto*(layer: var BlaiCpuInstLayer64,
                                         plan: BlaiFetchMemoryPlan,
                                         stream: var openArray[BlaiInstruction],
                                         useTflite: bool,
                                         outResult: var BlaiInstructionEncodeResult,
                                         includeExtra: bool = false,
                                         descriptorHalt: bool = false,
                                         midOutState: bool = false) =
  ## Emit the recovered `fetch_BLAI_data_route` descriptor loop.
  ##
  ## This bounded helper uses the recovered route channel-carrying loop and the
  ## existing descriptor bundle encoder. The overload accepting
  ## `BlaiRouteSramSlotPlan` is used by the default fetch wrapper for recovered
  ## per-step route output slots.
  outResult = default(BlaiInstructionEncodeResult)
  var routeLoop: BlaiRouteDescriptorLoopPlan
  blaiPlanRouteDescriptorLoopInto(layer, routeLoop)
  outResult.startCount = nonNegativeU32(layer.instCnt)
  if not routeLoop.fits:
    outResult.endCount = outResult.startCount
    return

  for stepIndex in 0'u32 ..< routeLoop.descriptorCount:
    let stepPosition =
      blaiRouteDescriptorStepPosition(stepIndex, routeLoop.descriptorCount)
    if not stepPosition.valid:
      outResult.endCount = outResult.startCount
      return
    var stagedLayer = layer
    let step = routeLoop.steps[stepPosition.stepSlot]
    stagedLayer.c = blaiRouteDescriptorChannelValue(step.descriptorC1)
    let
      stepPlan = blaiRouteStepFetchMemoryPlan(plan, step)
      bundle = blaiLayerInstructionBundle(
        stagedLayer, stepPlan, useTflite,
        c2 = step.descriptorC2,
        includeExtra = includeExtra,
        descriptorHalt = descriptorHalt and stepPosition.last,
        midOutState = midOutState)
    var count: BlaiInstructionEncodeCountResult
    blaiInstructionEncodeRequiredInto(bundle, count)
    var emittedFit: BlaiUint32AppendFitResult
    blaiUint32AppendFitInto(high(uint32), outResult.emitted, count.emitted,
      emittedFit)
    if not emittedFit.fits:
      outResult.endCount = outResult.startCount
      return
    outResult.emitted = emittedFit.requiredCount

  var streamFit: BlaiUint32AppendFitResult
  blaiUint32AppendFitInto(
    blaiOpenArrayLenU32(stream), outResult.startCount, outResult.emitted,
    streamFit)
  if not streamFit.cursorFits:
    outResult.endCount = outResult.startCount
    return
  outResult.endCount = streamFit.requiredCount
  outResult.fits = streamFit.fits
  if not outResult.fits:
    outResult.endCount = outResult.startCount
    return
  let
    startCountAbi = blaiInstructionCountAbi(outResult.startCount)
    endCountAbi = blaiInstructionCountAbi(outResult.endCount)
  if not startCountAbi.valid or not endCountAbi.valid:
    outResult.endCount = outResult.startCount
    outResult.fits = false
    return

  var count = outResult.startCount
  for stepIndex in 0'u32 ..< routeLoop.descriptorCount:
    let stepPosition =
      blaiRouteDescriptorStepPosition(stepIndex, routeLoop.descriptorCount)
    if not stepPosition.valid:
      layer.instCnt = startCountAbi.value
      return
    var stagedLayer = layer
    let step = routeLoop.steps[stepPosition.stepSlot]
    stagedLayer.c = blaiRouteDescriptorChannelValue(step.descriptorC1)
    let
      stepPlan = blaiRouteStepFetchMemoryPlan(plan, step)
      bundle = blaiLayerInstructionBundle(
        stagedLayer, stepPlan, useTflite,
        c2 = step.descriptorC2,
        includeExtra = includeExtra,
        descriptorHalt = descriptorHalt and stepPosition.last,
        midOutState = midOutState)
    var encoded: BlaiInstructionEncodeResult
    blaiEncodeInstructionsInto(bundle, stream, count, encoded)
    doAssert encoded.fits
    count = encoded.endCount
  layer.instCnt = endCountAbi.value

proc blaiEmitRouteLayerInstructions*(layer: var BlaiCpuInstLayer64,
                                     plan: BlaiFetchMemoryPlan,
                                     stream: var openArray[BlaiInstruction],
                                     useTflite: bool,
                                     includeExtra: bool = false,
                                     descriptorHalt: bool = false,
                                     midOutState: bool = false):
                                     BlaiInstructionEncodeResult {.
                                       exportc: "blaiEmitRouteLayerInstructionsMemory".} =
  ## Convenience result-returning wrapper for route descriptor-loop emission.
  blaiEmitRouteLayerInstructionsInto(
    layer, plan, stream, useTflite, result, includeExtra, descriptorHalt,
    midOutState)

proc blaiEmitRouteLayerInstructionsInto*(layer: var BlaiCpuInstLayer64,
                                         plan: BlaiRouteSramSlotPlan,
                                         stream: var openArray[BlaiInstruction],
                                         useTflite: bool,
                                         outResult: var BlaiInstructionEncodeResult,
                                         includeExtra: bool = false,
                                         descriptorHalt: bool = false,
                                         midOutState: bool = false) =
  ## Emit `fetch_BLAI_data_route` descriptors using recovered SRAM_out slots.
  outResult = default(BlaiInstructionEncodeResult)
  var routeLoop: BlaiRouteDescriptorLoopPlan
  blaiPlanRouteDescriptorLoopInto(layer, routeLoop)
  outResult.startCount = nonNegativeU32(layer.instCnt)
  if not routeLoop.fits or not plan.fits or
      plan.outputSlotCount < routeLoop.descriptorCount:
    outResult.endCount = outResult.startCount
    return

  for stepIndex in 0'u32 ..< routeLoop.descriptorCount:
    let stepPosition =
      blaiRouteDescriptorStepPosition(stepIndex, routeLoop.descriptorCount)
    if not stepPosition.valid:
      outResult.endCount = outResult.startCount
      return
    var stagedLayer = layer
    let step = routeLoop.steps[stepPosition.stepSlot]
    stagedLayer.c = blaiRouteDescriptorChannelValue(step.descriptorC1)
    let
      stepPlan = blaiRouteStepFetchMemoryPlan(plan, step)
      bundle = blaiLayerInstructionBundle(
        stagedLayer, stepPlan, useTflite,
        c2 = step.descriptorC2,
        includeExtra = includeExtra,
        descriptorHalt = descriptorHalt and stepPosition.last,
        midOutState = midOutState)
    var count: BlaiInstructionEncodeCountResult
    blaiInstructionEncodeRequiredInto(bundle, count)
    var emittedFit: BlaiUint32AppendFitResult
    blaiUint32AppendFitInto(high(uint32), outResult.emitted, count.emitted,
      emittedFit)
    if not emittedFit.fits:
      outResult.endCount = outResult.startCount
      return
    outResult.emitted = emittedFit.requiredCount

  var streamFit: BlaiUint32AppendFitResult
  blaiUint32AppendFitInto(
    blaiOpenArrayLenU32(stream), outResult.startCount, outResult.emitted,
    streamFit)
  if not streamFit.cursorFits:
    outResult.endCount = outResult.startCount
    return
  outResult.endCount = streamFit.requiredCount
  outResult.fits = streamFit.fits
  if not outResult.fits:
    outResult.endCount = outResult.startCount
    return
  let
    startCountAbi = blaiInstructionCountAbi(outResult.startCount)
    endCountAbi = blaiInstructionCountAbi(outResult.endCount)
  if not startCountAbi.valid or not endCountAbi.valid:
    outResult.endCount = outResult.startCount
    outResult.fits = false
    return

  var count = outResult.startCount
  for stepIndex in 0'u32 ..< routeLoop.descriptorCount:
    let stepPosition =
      blaiRouteDescriptorStepPosition(stepIndex, routeLoop.descriptorCount)
    if not stepPosition.valid:
      layer.instCnt = startCountAbi.value
      return
    var stagedLayer = layer
    let step = routeLoop.steps[stepPosition.stepSlot]
    stagedLayer.c = blaiRouteDescriptorChannelValue(step.descriptorC1)
    let
      stepPlan = blaiRouteStepFetchMemoryPlan(plan, step)
      bundle = blaiLayerInstructionBundle(
        stagedLayer, stepPlan, useTflite,
        c2 = step.descriptorC2,
        includeExtra = includeExtra,
        descriptorHalt = descriptorHalt and stepPosition.last,
        midOutState = midOutState)
    var encoded: BlaiInstructionEncodeResult
    blaiEncodeInstructionsInto(bundle, stream, count, encoded)
    doAssert encoded.fits
    count = encoded.endCount
  layer.instCnt = endCountAbi.value

proc blaiEmitRouteLayerInstructions*(layer: var BlaiCpuInstLayer64,
                                     plan: BlaiRouteSramSlotPlan,
                                     stream: var openArray[BlaiInstruction],
                                     useTflite: bool,
                                     includeExtra: bool = false,
                                     descriptorHalt: bool = false,
                                     midOutState: bool = false):
                                     BlaiInstructionEncodeResult {.
                                       exportc: "blaiEmitRouteLayerInstructionsSlots".} =
  ## Convenience result-returning wrapper for route SRAM-slot emission.
  blaiEmitRouteLayerInstructionsInto(
    layer, plan, stream, useTflite, result, includeExtra, descriptorHalt,
    midOutState)

proc toDecodedLayer*(layer: BlaiCpuInstLayer64): BlaiDecodedLayer =
  ## Project the recovered SDK CPU-layer ABI into the smaller decoded-layer
  ## shape used by pure Nim eligibility and instruction-header helpers.
  result.layerType = blaiLayerTypeFromSdk(layer.layerType)
  result.w = nonNegativeU32(layer.w)
  result.h = nonNegativeU32(layer.h)
  result.c = nonNegativeU32(layer.c)
  result.cn0 = nonNegativeU32(blaiLayerCn(layer, 1'u32))
  result.outC = nonNegativeU32(layer.outC)
  result.inLayer1Mem = nonNegativeU32(layer.inLayer1Mem)
  result.inLayer2Mem = nonNegativeU32(layer.inLayer2Mem)
  result.outLayerMem = nonNegativeU32(layer.outLayerMem)
  result.fdata = nonNegativeU32(layer.fdata)
  result.fweight = nonNegativeU32(layer.fweight)
  result.fbias = nonNegativeU32(layer.fbias)
  result.froute1 = nonNegativeU32(layer.froute1)
  result.froute2 = nonNegativeU32(layer.froute2)
  result.fout = nonNegativeU32(layer.fout)
  result.size = nonNegativeU32(layer.size)
  result.activation = nonNegativeU32(layer.activation)
  result.tfOutputOffset = nonNegativeU32(layer.tfOutputOffset)
  result.stride = nonNegativeU32(layer.stride)
  result.dilation = nonNegativeU32(layer.dilation)
  result.groups = nonNegativeU32(layer.groups)
  result.halt = layer.halt != 0

proc blaiChannelAlign4*(channels: uint32): uint32 =
  ## SDK `BALI_CHN_ALIGN`: round a channel count up to a multiple of four.
  ((channels + 3'u32) shr 2) shl 2

proc blaiAlign4*(bytes: uint32): uint32 =
  ## Round a byte count up to the SDK's 4-byte allocation boundary.
  ((bytes + 3'u32) shr 2) shl 2

proc blaiCeilDivU32(numerator, denominator: uint32): uint32 =
  if denominator == 0'u32:
    0'u32
  elif numerator == 0'u32:
    0'u32
  else:
    ((numerator - 1'u32) div denominator) + 1'u32

proc blaiRoundEvenU32(value: uint32): uint32 =
  if (value and 1'u32) == 1'u32: value + 1'u32 else: value

proc blaiSaturatingSubU32(value, decrement: uint32): uint32 =
  if value > decrement: value - decrement else: 0'u32

proc blaiFloorPow2U32(value: uint32): uint32 =
  if value == 0'u32:
    return 0'u32
  result = 1
  while (result shl 1) <= value:
    result = result shl 1

proc blaiIsComboMax*(layerType: BlaiLayerType,
                     stride, size: uint32): bool =
  ## SDK `check_combomax_layer`.
  layerType == blaiMaxpool and stride == 2'u32 and size == 2'u32

proc blaiIsUpsample*(layerType: BlaiLayerType): bool =
  ## SDK `check_upsample_layer`.
  layerType in {blaiUpsample, blaiRouteUpsample}

proc blaiIsConv*(layerType: BlaiLayerType): bool =
  ## SDK `check_conv_layer`.
  layerType in {blaiConvolutional, blaiConvMax, blaiRouteConv}

proc blaiUsesWeights*(layerType: BlaiLayerType): bool =
  ## SDK `check_weight_layer`.
  layerType in {blaiConvolutional, blaiConvMax, blaiRouteConv, blaiMatmul}

proc blaiCpuLoadUsesWeights*(layerType: BlaiLayerType): bool =
  ## SDK `blai_cpu_load_weights` weight stream layer predicate.
  layerType in {blaiConvolutional, blaiMatmul, blaiConvMax, blaiRouteConv,
                blaiSsd}

proc blaiCpuLoadUsesBiases*(layerType: BlaiLayerType): bool =
  ## SDK `blai_cpu_load_weights` bias stream layer predicate.
  layerType in {blaiConvolutional, blaiMatmul, blaiConvMax, blaiRouteConv}

proc blaiIsMultiInput*(layerType: BlaiLayerType): bool =
  ## SDK `check_MultiInput_layer`.
  layerType in {blaiRouteMax, blaiRouteConv, blaiRouteUpsample, blaiRoute,
                blaiShortcut, blaiRouteW, blaiSsd}

proc blaiIsRoute*(layerType: BlaiLayerType): bool =
  ## SDK `check_route_layer`.
  layerType in {blaiRouteMax, blaiRouteConv, blaiRouteUpsample, blaiRoute,
                blaiRouteW}

proc blaiIsCombine*(layerType: BlaiLayerType): bool =
  ## SDK `check_combine_layer` / `check_merge_layer` predicate.
  layerType in {blaiConvMax, blaiRouteMax, blaiRouteConv, blaiRouteUpsample}

proc blaiMergedLayerCount*(layerCount: uint32, layerType: BlaiLayerType): uint32 =
  ## SDK `check_merge_layer` effect for one parsed layer.
  if layerCount > 0'u32 and blaiIsCombine(layerType):
    layerCount - 1'u32
  else:
    layerCount

proc blaiReleaseSlotCursor*(slot: int32): BlaiReleaseSlotCursor =
  ## Resolve one recovered release-list counter to a fixed ABI array slot.
  let cursor = blaiI32ArrayIndexCursor(slot, BlaiMaxInputNum)
  if not cursor.valid:
    return
  result.slotIndex = cursor.index
  result.valid = true

proc blaiGraphLayerMapCursor*(graphLayer: int32,
                              capacity: int): BlaiGraphLayerMapCursor =
  ## Resolve a signed graph-layer id before writing caller-owned graph maps.
  let cursor = blaiI32ArrayIndexCursor(graphLayer, capacity)
  if not cursor.valid:
    return
  result.graphLayer = graphLayer
  result.mapIndex = cursor.index
  result.valid = true

proc blaiAppendReleaseLayer(layer: var BlaiCpuInstLayer64,
                            releasedLayer: uint32,
                            mid: bool): bool =
  if mid:
    let releaseCursor = blaiReleaseSlotCursor(layer.releaseMidNum)
    if not releaseCursor.valid:
      return false
    let releasedLayerAbi = blaiLayerIndexAbi(releasedLayer)
    if not releasedLayerAbi.valid:
      return false
    layer.releaseMidLayers[releaseCursor.slotIndex] = releasedLayerAbi.value
    inc layer.releaseMidNum
  else:
    let releaseCursor = blaiReleaseSlotCursor(layer.releaseNum)
    if not releaseCursor.valid:
      return false
    let releasedLayerAbi = blaiLayerIndexAbi(releasedLayer)
    if not releasedLayerAbi.valid:
      return false
    layer.releaseLayers[releaseCursor.slotIndex] = releasedLayerAbi.value
    inc layer.releaseNum
  true

proc blaiLayerConsumesGraph(layer: BlaiCpuInstLayer64,
                            graphLayer: int32): bool =
  if blaiIsMultiInput(blaiLayerTypeFromSdk(layer.layerType)):
    let inputCount = min(nonNegativeU32(layer.inputNum), BlaiMaxInputNumU32)
    for inputIndex in 0 ..< blaiBoundedU32Count(inputCount, BlaiMaxInputNum):
      if layer.inputLayers[inputIndex] == graphLayer:
        return true
  else:
    result = layer.inputLayers[0] == graphLayer

proc blaiAssignReleaseLayers*(
    layers: var openArray[BlaiCpuInstLayer64],
    graphLayerToLayer: var openArray[int32]): BlaiReleaseLayerPlan =
  ## Recover SDK `assign_release_layer` without heap allocation.
  ##
  ## The SDK builds temporary `release_layer`, `release_layer_mid`, and
  ## `graph_layer_to_layer` arrays. This proc scans the caller-owned layer table
  ## directly, fills each layer's fixed ABI release arrays, and writes the graph
  ## map into caller-owned storage.
  result.layerCount = blaiOpenArrayLenU32(layers)
  result.graphMapFits = true
  result.releaseFits = true
  result.firstGraphMapOverflowLayer = -1
  result.firstReleaseOverflowLayer = -1

  for graphIndex in 0 ..< graphLayerToLayer.len:
    graphLayerToLayer[graphIndex] = 0
  for layerIndex in 0 ..< layers.len:
    layers[layerIndex].releaseNum = 0
    layers[layerIndex].releaseMidNum = 0
    layers[layerIndex].midOut = 0

  for layerIndex in 0 ..< layers.len:
    let layerType = blaiLayerTypeFromSdk(layers[layerIndex].layerType)
    let combineLayer = blaiIsCombine(layerType)
    var releaseLayer = if layerIndex == layers.high: layerIndex else: 0
    var jump = false
    for consumerIndex in countdown(layers.high, layerIndex + 1):
      if blaiLayerConsumesGraph(
          layers[consumerIndex], layers[layerIndex].graphLayer[0]):
        releaseLayer = consumerIndex
        jump = true
      elif consumerIndex == layerIndex + 1:
        releaseLayer = consumerIndex
      if jump:
        break

    if not blaiAppendReleaseLayer(
        layers[releaseLayer], layerIndex.uint32, mid = false):
      result.releaseFits = false
      if result.firstReleaseOverflowLayer < 0:
        result.firstReleaseOverflowLayer = blaiLayerIndexValue(releaseLayer)
    else:
      inc result.releaseLayerCount

    if combineLayer:
      var releaseMidLayer = 0
      jump = false
      for consumerIndex in countdown(layers.high, layerIndex + 1):
        if blaiLayerConsumesGraph(
            layers[consumerIndex], layers[layerIndex].graphLayer[1]):
          releaseMidLayer = consumerIndex
          layers[layerIndex].midOut = 1
          jump = true
        if jump:
          break
      if releaseMidLayer != 0:
        if not blaiAppendReleaseLayer(
            layers[releaseMidLayer], layerIndex.uint32, mid = true):
          result.releaseFits = false
          if result.firstReleaseOverflowLayer < 0:
            result.firstReleaseOverflowLayer =
              blaiLayerIndexValue(releaseMidLayer)
        else:
          inc result.releaseMidLayerCount

  for layerIndex in 0 ..< layers.len:
    let graph0 = layers[layerIndex].graphLayer[0]
    let graph0Cursor = blaiGraphLayerMapCursor(graph0, graphLayerToLayer.len)
    if not graph0Cursor.valid:
      result.graphMapFits = false
      if result.firstGraphMapOverflowLayer < 0:
        result.firstGraphMapOverflowLayer = blaiLayerIndexValue(layerIndex)
    else:
      graphLayerToLayer[graph0Cursor.mapIndex] = blaiLayerIndexValue(layerIndex)
    if layers[layerIndex].midOut != 0:
      let graph1 = layers[layerIndex].graphLayer[1]
      let graph1Cursor = blaiGraphLayerMapCursor(graph1, graphLayerToLayer.len)
      if not graph1Cursor.valid:
        result.graphMapFits = false
        if result.firstGraphMapOverflowLayer < 0:
          result.firstGraphMapOverflowLayer = blaiLayerIndexValue(layerIndex)
      else:
        graphLayerToLayer[graph1Cursor.mapIndex] =
          blaiLayerIndexValue(layerIndex)

  result.complete = result.graphMapFits and result.releaseFits
  if not result.releaseFits:
    result.firstBlock = blaiReleaseLayerReleaseListOverflow
  elif not result.graphMapFits:
    result.firstBlock = blaiReleaseLayerGraphMapOverflow
  else:
    result.firstBlock = blaiReleaseLayerNoBlock

proc blaiAssignReleaseLayers*(
    layers: var openArray[BlaiCpuParsedLayerState],
    graphLayerToLayer: var openArray[int32]): BlaiReleaseLayerPlan =
  ## Apply recovered `assign_release_layer` to parsed-layer state records.
  ##
  ## This keeps extra-input and YOLO sidecar ownership bundled with each parsed
  ## layer while filling the same fixed ABI release arrays in `layer`.
  result.layerCount = blaiOpenArrayLenU32(layers)
  result.graphMapFits = true
  result.releaseFits = true
  result.firstGraphMapOverflowLayer = -1
  result.firstReleaseOverflowLayer = -1

  for graphIndex in 0 ..< graphLayerToLayer.len:
    graphLayerToLayer[graphIndex] = 0
  for layerIndex in 0 ..< layers.len:
    layers[layerIndex].layer.releaseNum = 0
    layers[layerIndex].layer.releaseMidNum = 0
    layers[layerIndex].layer.midOut = 0

  for layerIndex in 0 ..< layers.len:
    let layerType = blaiLayerTypeFromSdk(layers[layerIndex].layer.layerType)
    let combineLayer = blaiIsCombine(layerType)
    var releaseLayer = if layerIndex == layers.high: layerIndex else: 0
    var jump = false
    for consumerIndex in countdown(layers.high, layerIndex + 1):
      if blaiLayerConsumesGraph(
          layers[consumerIndex].layer, layers[layerIndex].layer.graphLayer[0]):
        releaseLayer = consumerIndex
        jump = true
      elif consumerIndex == layerIndex + 1:
        releaseLayer = consumerIndex
      if jump:
        break

    if not blaiAppendReleaseLayer(
        layers[releaseLayer].layer, layerIndex.uint32, mid = false):
      result.releaseFits = false
      if result.firstReleaseOverflowLayer < 0:
        result.firstReleaseOverflowLayer = blaiLayerIndexValue(releaseLayer)
    else:
      inc result.releaseLayerCount

    if combineLayer:
      var releaseMidLayer = 0
      jump = false
      for consumerIndex in countdown(layers.high, layerIndex + 1):
        if blaiLayerConsumesGraph(
            layers[consumerIndex].layer,
            layers[layerIndex].layer.graphLayer[1]):
          releaseMidLayer = consumerIndex
          layers[layerIndex].layer.midOut = 1
          jump = true
        if jump:
          break
      if releaseMidLayer != 0:
        if not blaiAppendReleaseLayer(
            layers[releaseMidLayer].layer, layerIndex.uint32, mid = true):
          result.releaseFits = false
          if result.firstReleaseOverflowLayer < 0:
            result.firstReleaseOverflowLayer =
              blaiLayerIndexValue(releaseMidLayer)
        else:
          inc result.releaseMidLayerCount

  for layerIndex in 0 ..< layers.len:
    let graph0 = layers[layerIndex].layer.graphLayer[0]
    let graph0Cursor = blaiGraphLayerMapCursor(graph0, graphLayerToLayer.len)
    if not graph0Cursor.valid:
      result.graphMapFits = false
      if result.firstGraphMapOverflowLayer < 0:
        result.firstGraphMapOverflowLayer = blaiLayerIndexValue(layerIndex)
    else:
      graphLayerToLayer[graph0Cursor.mapIndex] = blaiLayerIndexValue(layerIndex)
    if layers[layerIndex].layer.midOut != 0:
      let graph1 = layers[layerIndex].layer.graphLayer[1]
      let graph1Cursor = blaiGraphLayerMapCursor(graph1, graphLayerToLayer.len)
      if not graph1Cursor.valid:
        result.graphMapFits = false
        if result.firstGraphMapOverflowLayer < 0:
          result.firstGraphMapOverflowLayer = blaiLayerIndexValue(layerIndex)
      else:
        graphLayerToLayer[graph1Cursor.mapIndex] =
          blaiLayerIndexValue(layerIndex)

  result.complete = result.graphMapFits and result.releaseFits
  if not result.releaseFits:
    result.firstBlock = blaiReleaseLayerReleaseListOverflow
  elif not result.graphMapFits:
    result.firstBlock = blaiReleaseLayerGraphMapOverflow
  else:
    result.firstBlock = blaiReleaseLayerNoBlock

proc blaiSetCpuOutputShape(layer: var BlaiCpuInstLayer64,
                           outputW, outputH, outputC: uint32): bool =
  let
    outputWAbi = blaiOutputShapeDimAbi(outputW)
    outputHAbi = blaiOutputShapeDimAbi(outputH)
    outputCAbi = blaiOutputShapeDimAbi(outputC)
  if not outputWAbi.valid or not outputHAbi.valid or not outputCAbi.valid:
    return false
  layer.outW = outputWAbi.value
  layer.outH = outputHAbi.value
  layer.outC = outputCAbi.value
  true

proc blaiSetCpuOutputShapeSigned(layer: var BlaiCpuInstLayer64,
                                 outputW, outputH, outputC: int64): bool =
  if outputW < 0'i64 or outputH < 0'i64 or outputC < 0'i64:
    return false
  if outputW > int64(high(int32)) or outputH > int64(high(int32)) or
      outputC > int64(high(int32)):
    return false
  blaiSetCpuOutputShape(
    layer, outputW.uint32, outputH.uint32, outputC.uint32)

proc blaiCpuTransposeAxisDim(layer: BlaiCpuInstLayer64,
                             rank, perm: uint32): uint32 =
  ## Match SDK `set_output_wh_later` transpose axis muxing.
  if rank == 4'u32:
    if perm == 1'u32:
      nonNegativeU32(layer.h)
    elif perm == 2'u32:
      nonNegativeU32(layer.w)
    else:
      nonNegativeU32(layer.c)
  else:
    if perm == 0'u32:
      nonNegativeU32(layer.h)
    elif perm == 1'u32:
      nonNegativeU32(layer.w)
    else:
      nonNegativeU32(layer.c)

proc blaiApplyCpuTransposeOutputShape*(
    layer: var BlaiCpuInstLayer64,
    mask: BlaiCpuTfliteTransposeMask): BlaiCpuOutputShapeResult =
  ## Apply the SDK `set_output_wh_later` TRANSPOSE shape update.
  result.layerType = blaiLayerTypeFromSdk(layer.layerType)
  result.supported = result.layerType == blaiTranspose
  if not result.supported:
    result.firstBlock = blaiOutputShapeUnsupportedLayer
    return
  if not mask.active:
    result.firstBlock = blaiOutputShapeMissingTransposeMask
    return
  result.outputC = blaiCpuTransposeAxisDim(layer, mask.rank, mask.cPerm)
  result.outputW = blaiCpuTransposeAxisDim(layer, mask.rank, mask.wPerm)
  result.outputH = blaiCpuTransposeAxisDim(layer, mask.rank, mask.hPerm)
  result.fits = blaiSetCpuOutputShape(
    layer, result.outputW, result.outputH, result.outputC)
  result.updated = result.fits
  result.firstBlock =
    if result.updated: blaiOutputShapeNoBlock
    else: blaiOutputShapeInvalidDimensions

proc blaiApplyCpuPadOutputShape*(
    layer: var BlaiCpuInstLayer64,
    pad: BlaiCpuPadShapeBias): BlaiCpuOutputShapeResult =
  ## Apply the SDK `set_output_wh_later` PAD shape update.
  result.layerType = blaiLayerTypeFromSdk(layer.layerType)
  result.supported = result.layerType == blaiPad
  if not result.supported:
    result.firstBlock = blaiOutputShapeUnsupportedLayer
    return
  if not pad.active:
    result.firstBlock = blaiOutputShapeMissingPadBias
    return
  let
    outputC = int64(layer.c) + 2'i64 * int64(pad.channel)
    outputW = int64(layer.w) + 2'i64 * int64(pad.width)
    outputH = int64(layer.h) + 2'i64 * int64(pad.height)
  result.fits = blaiSetCpuOutputShapeSigned(layer, outputW, outputH, outputC)
  if result.fits:
    result.outputW = outputW.uint32
    result.outputH = outputH.uint32
    result.outputC = outputC.uint32
    result.updated = true
    result.firstBlock = blaiOutputShapeNoBlock
  else:
    result.firstBlock = blaiOutputShapeInvalidDimensions

proc blaiApplyCpuTransposeLkOutputShape*(
    layer: var BlaiCpuInstLayer64): BlaiCpuOutputShapeResult =
  ## Apply the SDK `set_output_wh_later` TRANSPOSE_LK shape update.
  result.layerType = blaiLayerTypeFromSdk(layer.layerType)
  result.supported = result.layerType == blaiTransposeLk
  if not result.supported:
    result.firstBlock = blaiOutputShapeUnsupportedLayer
    return
  let
    kernelSize = nonNegativeU32(layer.tfInput1Multiplier)
    stride = nonNegativeU32(layer.stride)
    inputW = nonNegativeU32(layer.w)
    inputH = nonNegativeU32(layer.h)
    channels = nonNegativeU32(layer.c)
    dilationW = nonNegativeU32(layer.tfInput1Offset)
    dilationH = nonNegativeU32(layer.tfInput2Offset)
  let kernelSizeAbi = blaiKernelSizeAbi(kernelSize)
  if not kernelSizeAbi.valid:
    result.firstBlock = blaiOutputShapeInvalidDimensions
    return
  layer.size = kernelSizeAbi.value
  if kernelSize == 0'u32 or stride == 0'u32 or inputW == 0'u32 or
      inputH == 0'u32 or channels == 0'u32:
    result.firstBlock = blaiOutputShapeInvalidTransposeLkParams
    return
  let
    alignedKernel = blaiChannelAlign4(kernelSize)
    sequenceLength = if inputW == 1'u32: inputH else: inputW
    dilation = if inputW == 1'u32: dilationH else: dilationW
    fetchSize = if dilation == 2'u32: kernelSize * dilation - 1'u32
                else: kernelSize
  if dilation == 0'u32 or sequenceLength < fetchSize:
    result.firstBlock = blaiOutputShapeInvalidTransposeLkParams
    return
  let outputChannels =
    blaiReferenceTransposeLkOutputChannels(channels, alignedKernel)
  if outputChannels > high(uint32).uint64:
    result.firstBlock = blaiOutputShapeInvalidDimensions
    return
  result.outputC = outputChannels.uint32
  result.outputW = inputW
  result.outputH = ((sequenceLength - fetchSize) div stride) + 1'u32
  result.fits = blaiSetCpuOutputShape(
    layer, result.outputW, result.outputH, result.outputC)
  result.updated = result.fits
  result.firstBlock =
    if result.updated: blaiOutputShapeNoBlock
    else: blaiOutputShapeInvalidDimensions

proc blaiApplyCpuOutputShapeLater*(
    layer: var BlaiCpuInstLayer64,
    transposeMask: BlaiCpuTfliteTransposeMask = BlaiCpuTfliteTransposeMask(),
    padBias: BlaiCpuPadShapeBias = BlaiCpuPadShapeBias()
      ): BlaiCpuOutputShapeResult =
  ## Apply recovered SDK `set_output_wh_later` shape side effects.
  case blaiLayerTypeFromSdk(layer.layerType)
  of blaiPad:
    blaiApplyCpuPadOutputShape(layer, padBias)
  of blaiTranspose:
    blaiApplyCpuTransposeOutputShape(layer, transposeMask)
  of blaiTransposeLk:
    blaiApplyCpuTransposeLkOutputShape(layer)
  else:
    BlaiCpuOutputShapeResult(
      layerType: blaiLayerTypeFromSdk(layer.layerType),
      supported: false,
      firstBlock: blaiOutputShapeUnsupportedLayer)

proc blaiApplyCpuOutputShapeLater*(
    parsed: var BlaiCpuParsedLayerState,
    transposeMask: BlaiCpuTfliteTransposeMask = BlaiCpuTfliteTransposeMask(),
    padBias: BlaiCpuPadShapeBias = BlaiCpuPadShapeBias()
      ): BlaiCpuOutputShapeResult =
  ## Apply recovered `set_output_wh_later` shape side effects to parsed state.
  ##
  ## The sidecar-bearing parsed record keeps its extra-input and YOLO storage
  ## bundled while only the embedded CPU layer shape fields are updated.
  blaiApplyCpuOutputShapeLater(parsed.layer, transposeMask, padBias)

proc blaiEncodeDispatch*(layerType: BlaiLayerType,
                         inputNum: uint32): BlaiEncodeDispatch =
  ## SDK `BLAI_encode` route-vs-general data emitter selection.
  if layerType in {blaiRoute, blaiRouteMax} and inputNum > 2'u32:
    blaiEncodeRoute
  else:
    blaiEncodeGeneral

proc blaiEncodeDispatch*(layer: BlaiDecodedLayer,
                         inputNum: uint32): BlaiEncodeDispatch =
  blaiEncodeDispatch(layer.layerType, inputNum)

proc blaiEncodeDispatch*(layer: BlaiCpuInstLayer64): BlaiEncodeDispatch =
  blaiEncodeDispatch(blaiLayerTypeFromSdk(layer.layerType),
                     nonNegativeU32(layer.inputNum))

proc blaiEncodeDispatch*(
    parsed: BlaiCpuParsedLayerState): BlaiEncodeDispatch =
  ## Parsed-state wrapper for SDK `BLAI_encode` route-vs-general dispatch.
  blaiEncodeDispatch(parsed.layer)

proc blaiFetchKind*(dispatch: BlaiEncodeDispatch): BlaiFetchMemoryKind =
  case dispatch
  of blaiEncodeGeneral: blaiFetchGeneral
  of blaiEncodeRoute: blaiFetchRoute

proc blaiNpuEligibilityInto*(layer: BlaiDecodedLayer,
                             outResult: var BlaiNpuEligibilityResult)
proc blaiCanRunOnNpu*(layer: BlaiDecodedLayer): bool

proc blaiPlanEncodeInto*(layer: BlaiDecodedLayer,
                         inputNum: uint32,
                         allocationSucceeded: bool,
                         outResult: var BlaiEncodePlan) =
  ## Recovered SDK `BLAI_encode` wrapper decision. This only plans the
  ## eligibility, allocator-success, dispatch, and clear-size gates.
  outResult = default(BlaiEncodePlan)
  var eligibility: BlaiNpuEligibilityResult
  blaiNpuEligibilityInto(layer, eligibility)
  outResult.eligible = eligibility.eligible
  outResult.allocationSucceeded = allocationSucceeded
  outResult.runnable = outResult.eligible and allocationSucceeded
  outResult.dispatch = blaiEncodeDispatch(layer, inputNum)
  outResult.instructionClearBytes = BlaiInstructionScratchSize.uint32

proc blaiPlanEncode*(layer: BlaiDecodedLayer,
                     inputNum: uint32,
                     allocationSucceeded: bool): BlaiEncodePlan =
  ## Convenience result-returning wrapper for `BLAI_encode` gate planning.
  blaiPlanEncodeInto(layer, inputNum, allocationSucceeded, result)

proc blaiPlanEncodeInto*(layer: BlaiCpuInstLayer64,
                         allocationSucceeded: bool,
                         outResult: var BlaiEncodePlan) =
  ## Project the CPU-layer ABI and plan the recovered `BLAI_encode` gate.
  blaiPlanEncodeInto(
    toDecodedLayer(layer), nonNegativeU32(layer.inputNum),
    allocationSucceeded, outResult)

proc blaiPlanEncode*(layer: BlaiCpuInstLayer64,
                     allocationSucceeded: bool): BlaiEncodePlan =
  ## Convenience result-returning wrapper for CPU-layer encode gate planning.
  blaiPlanEncodeInto(layer, allocationSucceeded, result)

proc blaiClearInstructionScratch*(scratch: var openArray[uint8]) =
  ## SDK `memset(l->NPU_inst, 0, MAX_Input_num*NPU_INST_SIZE_BYTE*3)`.
  doAssert scratch.len >= BlaiInstructionScratchSize
  for i in 0 ..< BlaiInstructionScratchSize:
    scratch[i] = 0

proc blaiClearInstructionStream*(stream: var openArray[BlaiInstruction]) =
  ## Clear the recovered SDK instruction scratch as typed 16-byte records.
  const scratchInstructions = BlaiInstructionScratchSize div BlaiInstructionSize
  doAssert stream.len >= scratchInstructions
  for i in 0 ..< scratchInstructions:
    stream[i] = default(BlaiInstruction)

proc blaiInstructionEncodeRequiredInto*(bundle: BlaiNpuInstructionBundle,
                                        outResult: var BlaiInstructionEncodeCountResult) =
  ## Number of 16-byte instructions SDK `instruction_encode` will append.
  outResult = default(BlaiInstructionEncodeCountResult)
  outResult.normalCount = 1
  if bundle.useTflite != 0:
    outResult.tfliteCount = 1
  if bundle.extraInfo != 0:
    outResult.extraCount = 1
  outResult.emitted =
    outResult.normalCount + outResult.tfliteCount + outResult.extraCount

proc blaiInstructionEncodeRequired*(bundle: BlaiNpuInstructionBundle): uint32 =
  ## Boolean-compatible scalar wrapper for recovered append count.
  var count: BlaiInstructionEncodeCountResult
  blaiInstructionEncodeRequiredInto(bundle, count)
  count.emitted

proc blaiEncodeInstructionsInto*(bundle: BlaiNpuInstructionBundle,
                                 stream: var openArray[BlaiInstruction],
                                 startCount: uint32,
                                 outResult: var BlaiInstructionEncodeResult) =
  ## Recover SDK `instruction_encode` without pointer arithmetic.
  ##
  ## The blob appends `inst_tflite` when `use_tflite != 0`, then `inst_extra`
  ## when `extra_info != 0`, then always appends `inst`. This bounded version
  ## leaves the stream unchanged and reports `fits=false` when the target slice
  ## cannot hold the complete append.
  outResult = default(BlaiInstructionEncodeResult)
  outResult.startCount = startCount
  var count: BlaiInstructionEncodeCountResult
  blaiInstructionEncodeRequiredInto(bundle, count)
  outResult.emitted = count.emitted
  var fit: BlaiUint32AppendFitResult
  blaiUint32AppendFitInto(
    blaiOpenArrayLenU32(stream), startCount, outResult.emitted, fit)
  outResult.endCount = fit.requiredCount
  outResult.fits = fit.fits
  if not outResult.fits:
    outResult.endCount = startCount
    return

  let startCursor = blaiInstructionStreamStartCursor(startCount, stream.len)
  if not startCursor.valid:
    outResult.endCount = startCount
    outResult.fits = false
    return
  var cursor = startCursor.index
  if bundle.useTflite != 0:
    stream[cursor] = bundle.instTflite
    inc cursor
  if bundle.extraInfo != 0:
    stream[cursor] = bundle.instExtra
    inc cursor
  stream[cursor] = bundle.inst

proc blaiEncodeInstructions*(bundle: BlaiNpuInstructionBundle,
                             stream: var openArray[BlaiInstruction],
                             startCount: uint32): BlaiInstructionEncodeResult =
  ## Convenience result-returning wrapper for instruction encoding.
  blaiEncodeInstructionsInto(bundle, stream, startCount, result)

proc blaiEmitLayerInstructionsInto*(layer: var BlaiCpuInstLayer64,
                                    plan: BlaiFetchMemoryPlan,
                                    stream: var openArray[BlaiInstruction],
                                    useTflite: bool,
                                    outResult: var BlaiInstructionEncodeResult,
                                    c2: uint32 = 0'u32,
                                    includeExtra: bool = false,
                                    descriptorHalt: bool = false,
                                    midOutState: bool = false) =
  ## Build and append recovered layer instructions, then update `instCnt`.
  ##
  ## Like `blaiEncodeInstructions`, this leaves the stream and `instCnt`
  ## unchanged when the complete append does not fit.
  let
    startCount = nonNegativeU32(layer.instCnt)
    bundle = blaiLayerInstructionBundle(
      layer, plan, useTflite, c2, includeExtra, descriptorHalt, midOutState)
  var required: BlaiInstructionEncodeCountResult
  blaiInstructionEncodeRequiredInto(bundle, required)
  var fit: BlaiUint32AppendFitResult
  blaiUint32AppendFitInto(
    blaiOpenArrayLenU32(stream), startCount, required.emitted, fit)
  let endCountAbi = blaiInstructionCountAbi(fit.requiredCount)
  if not fit.fits or not endCountAbi.valid:
    outResult = default(BlaiInstructionEncodeResult)
    outResult.startCount = startCount
    outResult.endCount = startCount
    outResult.emitted = required.emitted
    return
  blaiEncodeInstructionsInto(bundle, stream, startCount, outResult)
  if outResult.fits:
    layer.instCnt = endCountAbi.value

proc blaiEmitLayerInstructions*(layer: var BlaiCpuInstLayer64,
                                plan: BlaiFetchMemoryPlan,
                                stream: var openArray[BlaiInstruction],
                                useTflite: bool,
                                c2: uint32 = 0'u32,
                                includeExtra: bool = false,
                                descriptorHalt: bool = false,
                                midOutState: bool = false): BlaiInstructionEncodeResult =
  ## Convenience result-returning wrapper for layer instruction emission.
  blaiEmitLayerInstructionsInto(
    layer, plan, stream, useTflite, result, c2, includeExtra, descriptorHalt,
    midOutState)

proc blaiApplyMemoryPlan*(layer: var BlaiCpuInstLayer64,
                          ctrl: BlaiPsramCtrl) =
  ## Mirror the post-`BLAI_encode` copies in SDK `gen_npu_inst_layer`.
  ##
  ## `dramPatchNum` is left as allocator-owned state, matching the SDK code
  ## which uses the layer field after `BLAI_MEM_alloc`.
  layer.npuOn = 1
  layer.bufSize = layer.dramPatchNum * ctrl.psramPatchSize
  layer.dramIn = ctrl.sramIn
  layer.dramMidOut = ctrl.sramMidOut
  layer.dramOut = ctrl.sramOut
  layer.dramPatchSize = ctrl.psramPatchSize
  layer.dramWeight = ctrl.sramWeight
  layer.dramBias = ctrl.sramBias

proc blaiMarkEncodeFailed*(layer: var BlaiCpuInstLayer64) =
  ## SDK `gen_npu_inst_layer` stores false in `NPU_on` on wrapper failure.
  layer.npuOn = 0

proc blaiMemAllocSinglePatchShape*(
    layer: BlaiCpuInstLayer64): BlaiMemAllocSinglePatchShape =
  ## Recover the one-patch fallback shape used by `BLAI_MEM_alloc`.
  result.layerType = blaiLayerTypeFromSdk(layer.layerType)
  result.outputChannels = nonNegativeU32(layer.outC)
  result.alignedOutputChannels = blaiChannelAlign4(result.outputChannels)
  result.outputWidth = nonNegativeU32(layer.outW)
  result.outputHeight = nonNegativeU32(layer.outH)
  result.inputWidth = nonNegativeU32(layer.w)
  result.inputHeight = nonNegativeU32(layer.h)
  result.inputChannels = nonNegativeU32(layer.c)
  result.outputElements = result.outputWidth * result.outputHeight
  result.psramPatchSize = result.outputElements * result.alignedOutputChannels
  if layer.midOut == 1 and result.psramPatchSize > 0'u32:
    if result.layerType == blaiSoftmax:
      result.midSource = blaiMemAllocSinglePatchMidSoftmaxOutputChannels
      result.midInputElements =
        result.inputWidth * result.inputHeight * result.outputChannels
    else:
      result.midSource = blaiMemAllocSinglePatchMidInputChannels
      result.midInputElements =
        result.inputWidth * result.inputHeight * result.inputChannels
    result.psramMidPatchCount =
      blaiCeilDivU32(result.midInputElements, result.psramPatchSize)
  result.valid = true

proc blaiPlanSinglePatchMemAllocInto*(layer: BlaiCpuInstLayer64,
                                      outResult: var BlaiMemAllocSinglePatchPlan) =
  ## Recover the small-layer `BLAI_MEM_alloc` stores at the one-patch fallback.
  ##
  ## The full allocator chooses whether this branch is valid. This helper only
  ## mirrors the fields written once that branch is selected.
  outResult = default(BlaiMemAllocSinglePatchPlan)
  let shape = blaiMemAllocSinglePatchShape(layer)
  outResult.weightPatchCount = 1
  outResult.firstWeightPatchOutC = shape.outputChannels
  outResult.psramPatchCount = 1
  outResult.psramPatchSize = shape.psramPatchSize
  outResult.midSource = shape.midSource
  outResult.midInputElements = shape.midInputElements
  outResult.psramMidPatchCount = shape.psramMidPatchCount

proc blaiPlanSinglePatchMemAlloc*(layer: BlaiCpuInstLayer64): BlaiMemAllocSinglePatchPlan =
  ## Convenience result-returning wrapper for the one-patch allocator branch.
  blaiPlanSinglePatchMemAllocInto(layer, result)

proc blaiMemAllocSinglePatchApplyPlan*(
    plan: BlaiMemAllocSinglePatchPlan): BlaiMemAllocSinglePatchApplyPlan =
  ## Recover checked one-patch allocator stores before mutating `PSRAM_ctrl`.
  let
    weightPatchCount = blaiAllocatorFieldAbi(plan.weightPatchCount)
    firstWeightPatchOutC = blaiAllocatorFieldAbi(plan.firstWeightPatchOutC)
    psramPatchSize = blaiAllocatorFieldAbi(plan.psramPatchSize)
    psramPatchCount = blaiAllocatorFieldAbi(plan.psramPatchCount)
    psramMidPatchCount = blaiAllocatorFieldAbi(plan.psramMidPatchCount)
  if not weightPatchCount.valid or not firstWeightPatchOutC.valid or
     not psramPatchSize.valid or not psramPatchCount.valid or
     not psramMidPatchCount.valid:
    return
  result.weightPatchCount = weightPatchCount.value
  result.firstWeightPatchOutC = firstWeightPatchOutC.value
  result.psramPatchSize = psramPatchSize.value
  result.psramPatchCount = psramPatchCount.value
  result.psramMidPatchCount = psramMidPatchCount.value
  result.valid = true

proc blaiApplySinglePatchMemAlloc*(ctrl: var BlaiPsramCtrl,
                                   plan: BlaiMemAllocSinglePatchPlan) =
  ## Apply the recovered one-patch `BLAI_MEM_alloc` stores to `PSRAM_ctrl`.
  let applyPlan = blaiMemAllocSinglePatchApplyPlan(plan)
  doAssert applyPlan.valid
  ctrl.weightPatchCount = applyPlan.weightPatchCount
  ctrl.weightPatchOutC[0] = applyPlan.firstWeightPatchOutC
  ctrl.psramPatchSize = applyPlan.psramPatchSize
  ctrl.psramPatchCount = applyPlan.psramPatchCount
  ctrl.psramMidPatchCount = applyPlan.psramMidPatchCount

proc blaiMemAllocRouteInputCursor*(
    extraInputIndex: uint32): BlaiMemAllocRouteInputCursor =
  ## Resolve recovered route extra-input order to the matching `cn[]` slot.
  if extraInputIndex == high(uint32):
    return
  let logicalInput = extraInputIndex + 1'u32
  let cnCursor = blaiLayerCnCursor(logicalInput)
  if not cnCursor.valid:
    return
  result.extraInputIndex = extraInputIndex
  result.logicalInput = logicalInput
  result.cnIndex = cnCursor.cnIndex
  result.valid = true

proc blaiMemAllocRouteChannels(layer: BlaiCpuInstLayer64): tuple[channels: uint32,
                                                                 routed: bool] =
  let layerType = blaiLayerTypeFromSdk(layer.layerType)
  result.channels = nonNegativeU32(layer.c)
  result.routed = layerType in {blaiRoute, blaiRouteMax, blaiRouteConv,
                                blaiRouteUpsample}
  if result.routed:
    let extraInputs = min(blaiSaturatingSubU32(nonNegativeU32(layer.inputNum), 1'u32),
                          BlaiMaxRouteInputNumU32)
    for i in 0'u32 ..< extraInputs:
      let routeInput = blaiMemAllocRouteInputCursor(i)
      if routeInput.valid:
        result.channels += nonNegativeU32(layer.cn[routeInput.cnIndex])

proc blaiMemAllocStartPatchPressure*(
    layer: BlaiCpuInstLayer64): BlaiMemAllocStartPatchPressure =
  ## Recover the initial input/output pressure for allocator split search.
  let route = blaiMemAllocRouteChannels(layer)
  result.layerType = blaiLayerTypeFromSdk(layer.layerType)
  result.routed = route.routed
  result.routeChannels = route.channels
  result.inputWidth = nonNegativeU32(layer.w)
  result.outputWidth = nonNegativeU32(layer.outW)
  result.outputChannels = nonNegativeU32(layer.outC)
  result.shortcutDoubleInput = result.layerType == blaiShortcut
  result.suppressConvOutput = result.layerType == blaiConvolutional
  if result.shortcutDoubleInput:
    result.inputBytes = result.inputWidth * result.routeChannels * 2'u32
  else:
    result.inputBytes = result.inputWidth * result.routeChannels
  if not result.suppressConvOutput:
    result.outputBytes = result.outputWidth * result.outputChannels
  result.inputPatchCount =
    blaiCeilDivU32(result.inputBytes, BlaiNpuLocalBufferBytes)
  result.outputPatchCount =
    blaiCeilDivU32(result.outputBytes, BlaiNpuLocalBufferBytes)
  result.startPatchCount =
    max(result.inputPatchCount, result.outputPatchCount)

proc blaiPlanMemAllocStartPatchInto*(
    layer: BlaiCpuInstLayer64,
    outResult: var BlaiMemAllocStartPatchPlan) =
  ## Recover the initial 4 KiB split pressure used by `BLAI_MEM_alloc`.
  outResult = default(BlaiMemAllocStartPatchPlan)
  let pressure = blaiMemAllocStartPatchPressure(layer)
  outResult.layerType = pressure.layerType
  outResult.routed = pressure.routed
  outResult.routeChannels = pressure.routeChannels
  outResult.inputWidth = pressure.inputWidth
  outResult.outputWidth = pressure.outputWidth
  outResult.outputChannels = pressure.outputChannels
  outResult.shortcutDoubleInput = pressure.shortcutDoubleInput
  outResult.suppressConvOutput = pressure.suppressConvOutput
  outResult.inputBytes = pressure.inputBytes
  outResult.outputBytes = pressure.outputBytes
  outResult.inputPatchCount = pressure.inputPatchCount
  outResult.outputPatchCount = pressure.outputPatchCount
  outResult.startPatchCount = pressure.startPatchCount

proc blaiPlanMemAllocStartPatch*(
    layer: BlaiCpuInstLayer64): BlaiMemAllocStartPatchPlan =
  ## Convenience result-returning wrapper for line-patch search pressure.
  blaiPlanMemAllocStartPatchInto(layer, result)

proc blaiMemAllocPatchSegmentCursor*(
    patchIndex, patchCount: uint32): BlaiMemAllocPatchSegmentCursor =
  ## Resolve a recovered allocator patch index into bounded plan storage.
  if patchIndex >= patchCount:
    return
  let patchCursor = blaiWeightPatchCursor(patchIndex)
  if not patchCursor.valid:
    return
  result.patchIndex = patchIndex
  result.patchSlot = patchCursor.index
  result.last = patchIndex == patchCount - 1'u32
  result.valid = true

proc blaiMemAllocLinePatchProbe*(
    layer: BlaiCpuInstLayer64,
    patchCount, routeChannels: uint32,
    routed, upsampleLayer: bool): BlaiMemAllocLinePatchProbe =
  ## Recover one candidate byte-pressure check from the line-patch search.
  if patchCount == 0'u32:
    return
  let
    inputWidth = nonNegativeU32(layer.w)
    outputWidth = nonNegativeU32(layer.outW)
    outputChannels = nonNegativeU32(layer.outC)
    midOut = layer.midOut == 1
  result.patchCount = patchCount
  result.inputLine = blaiRoundEvenU32(blaiCeilDivU32(inputWidth, patchCount))
  result.outputLineBase =
    if upsampleLayer:
      result.inputLine * 2'u32
    else:
      blaiRoundEvenU32(blaiCeilDivU32(outputWidth, patchCount))
  result.routeKernelPadding =
    if midOut and routed:
      if nonNegativeU32(layer.dilation) > 1'u32:
        6'u32
      elif nonNegativeU32(layer.size) <= 3'u32:
        2'u32
      else:
        6'u32
    else:
      0'u32
  result.inputLineBytes = (result.inputLine + result.routeKernelPadding) *
    routeChannels
  result.outputBytes = result.outputLineBase * outputChannels
  result.routeBytes = result.inputLine * routeChannels
  result.outputLineBytes = max(result.outputBytes, result.routeBytes)
  result.fits =
    result.inputLineBytes <= BlaiNpuLocalBufferBytes and
    result.outputLineBytes <= BlaiNpuLocalBufferBytes

proc blaiPlanLinePatchMemAllocInto*(layer: BlaiCpuInstLayer64,
                                    outResult: var BlaiMemAllocLinePatchPlan,
                                    upsampleLayer: bool = false) =
  ## Recover the bounded `BLAI_MEM_alloc` line-patch search and stores.
  ##
  ## The SDK starts from the larger 4 KiB input/output split count, then tries
  ## up to 128 wider split counts. This helper mirrors that search and the
  ## resulting `line_patch_num` / `line_patch_w[]` writes. The later weight and
  ## PSRAM patch branches remain separate recovered helpers.
  outResult = default(BlaiMemAllocLinePatchPlan)
  let
    route = blaiMemAllocRouteChannels(layer)
    inputWidth = nonNegativeU32(layer.w)
  blaiPlanMemAllocStartPatchInto(layer, outResult.start)
  outResult.startPatchCount = outResult.start.startPatchCount
  if outResult.startPatchCount <= 1'u32:
    if inputWidth <= BlaiNpuLocalBufferBytes:
      outResult.fits = true
      outResult.linePatchCount = 1
      outResult.linePatchW[0] = inputWidth
    return

  let stopPatchCount = outResult.startPatchCount + BlaiMemAllocSearchSlack
  for patchCount in outResult.startPatchCount ..< stopPatchCount:
    let probe = blaiMemAllocLinePatchProbe(
      layer, patchCount, route.channels, route.routed, upsampleLayer)
    if probe.fits:
      outResult.fits = true
      outResult.linePatchCount = patchCount
      outResult.inputLineBytes = probe.inputLineBytes
      outResult.outputLineBytes = probe.outputLineBytes
      var remaining = inputWidth
      for i in 0'u32 ..< min(patchCount, BlaiMaxWeightPatchesU32):
        let patchSegment = blaiMemAllocPatchSegmentCursor(i, patchCount)
        if not patchSegment.valid:
          return
        let patchWidth =
          if patchSegment.last:
            remaining
          else:
            probe.inputLine
        outResult.linePatchW[patchSegment.patchSlot] = patchWidth
        remaining = blaiSaturatingSubU32(remaining, probe.inputLine)
      break

proc blaiPlanLinePatchMemAlloc*(layer: BlaiCpuInstLayer64,
                                upsampleLayer: bool = false): BlaiMemAllocLinePatchPlan =
  ## Convenience result-returning wrapper for line-patch allocator planning.
  blaiPlanLinePatchMemAllocInto(layer, result, upsampleLayer)

proc blaiMemAllocLinePatchApplyPlan*(
    plan: BlaiMemAllocLinePatchPlan): BlaiMemAllocLinePatchApplyPlan =
  ## Recover checked line-patch allocator stores before mutating `PSRAM_ctrl`.
  if not plan.fits:
    return
  let linePatchCount = blaiAllocatorFieldAbi(plan.linePatchCount)
  if not linePatchCount.valid:
    return
  result.linePatchCount = linePatchCount.value
  for i in 0 ..< BlaiMaxWeightPatches:
    let lineWidth = blaiAllocatorFieldAbi(plan.linePatchW[i])
    if not lineWidth.valid:
      result = default(BlaiMemAllocLinePatchApplyPlan)
      return
    result.linePatchW[i] = lineWidth.value
  result.valid = true

proc blaiApplyLinePatchMemAlloc*(ctrl: var BlaiPsramCtrl,
                                 plan: BlaiMemAllocLinePatchPlan) =
  ## Apply recovered `line_patch_num` and `line_patch_w[]` allocator stores.
  let applyPlan = blaiMemAllocLinePatchApplyPlan(plan)
  doAssert applyPlan.valid
  ctrl.linePatchCount = applyPlan.linePatchCount
  for i in 0 ..< BlaiMaxWeightPatches:
    ctrl.linePatchW[i] = applyPlan.linePatchW[i]

proc blaiMemAllocWeightPatchPressure*(
    layer: BlaiCpuInstLayer64): BlaiMemAllocWeightPatchPressure =
  ## Recover the weight pressure expression used by `BLAI_MEM_alloc`.
  let
    route = blaiMemAllocRouteChannels(layer)
    layerType = blaiLayerTypeFromSdk(layer.layerType)
  result.layerType = layerType
  result.routed = route.routed
  result.routeChannels = route.channels
  result.outputChannels = nonNegativeU32(layer.outC)
  result.groups = max(nonNegativeU32(layer.groups), 1'u32)
  result.size = nonNegativeU32(layer.size)
  result.dilation = nonNegativeU32(layer.dilation)
  result.channelProduct = result.routeChannels * result.outputChannels
  if result.size == 1'u32:
    result.mode = blaiWeightPressureOneByOne
    result.bytes = result.channelProduct div (result.groups * 8'u32)
  elif result.dilation > 1'u32 or result.size > 3'u32:
    result.mode = blaiWeightPressureDilatedOrLarge
    result.bytes = (9'u32 * result.channelProduct) div result.groups
  else:
    result.mode = blaiWeightPressureSmallKernel
    result.bytes =
      (result.size * result.channelProduct * result.size) div
      (9'u32 * result.groups)

proc blaiEstimateWeightPatchBytes*(layer: BlaiCpuInstLayer64): uint32 =
  ## Compatibility wrapper for the recovered weight pressure byte estimate.
  blaiMemAllocWeightPatchPressure(layer).bytes

proc blaiMemAllocPsramPatchPressure*(
    layer: BlaiCpuInstLayer64,
    linePlan: BlaiMemAllocLinePatchPlan): BlaiMemAllocPsramPatchPressure =
  ## Recover the lower-threshold PSRAM pressure expression in `BLAI_MEM_alloc`.
  if not linePlan.fits or linePlan.linePatchCount == 0'u32:
    return
  result.layerType = blaiLayerTypeFromSdk(layer.layerType)
  result.linePatchCount = linePlan.linePatchCount
  result.outputChannels = nonNegativeU32(layer.outC)
  result.outputWidth = nonNegativeU32(layer.outW)
  result.inputWidth = nonNegativeU32(layer.w)
  result.baseBytes =
    (result.outputWidth div result.linePatchCount) * result.outputChannels
  result.bytes = result.baseBytes
  result.valid = true
  if result.layerType == blaiConvMax:
    result.convMaxFloorBytes =
      (result.inputWidth div result.linePatchCount) * result.outputWidth
    result.bytes = max(result.bytes, result.convMaxFloorBytes)

proc blaiEstimatePsramPatchBytes*(layer: BlaiCpuInstLayer64,
                                  linePlan: BlaiMemAllocLinePatchPlan): uint32 =
  ## Compatibility wrapper for the recovered PSRAM pressure byte estimate.
  blaiMemAllocPsramPatchPressure(layer, linePlan).bytes

proc blaiMemAllocWeightPatchStoreEntry*(
    patchIndex, weightPatchCount, emittedChannels, outputChannels,
    outputChannelPatch, outputElements, inputElements: uint32,
    midOut: bool): BlaiMemAllocWeightPatchStoreEntry =
  ## Recover one `wei_patch_out_c[]` write and PSRAM patch-size contribution.
  let patchSegment = blaiMemAllocPatchSegmentCursor(patchIndex, weightPatchCount)
  if not patchSegment.valid:
    return
  result.patchIndex = patchIndex
  result.patchSlot = patchSegment.patchSlot
  result.last = patchSegment.last
  result.emittedChannels = emittedChannels
  result.remainingChannels =
    blaiSaturatingSubU32(outputChannels, emittedChannels)
  result.outputChannelPatch = outputChannelPatch
  result.patchOutC =
    if result.last:
      result.remainingChannels
    else:
      min(outputChannelPatch, result.remainingChannels)
  if result.patchOutC == 0'u32:
    return
  result.outputPatchBytes = result.patchOutC * outputElements
  result.fullPatchBytes = outputChannelPatch * outputElements
  result.psramPatchSize = max(result.outputPatchBytes, result.fullPatchBytes)
  if midOut:
    result.midChannelBytes = result.patchOutC * inputElements
    result.midFullBytes = outputChannelPatch * inputElements
    result.psramPatchSize = max(result.psramPatchSize,
                                max(result.midChannelBytes,
                                    result.midFullBytes))
  result.nextEmittedChannels = emittedChannels + result.patchOutC
  result.valid = true

proc blaiMemAllocPatchCountPlan*(
    layerType: BlaiLayerType,
    outputChannels, outputElements, inputElements, routeChannels,
    weightPatchCount, psramPatchSize: uint32,
    midOut: bool): BlaiMemAllocPatchCountPlan =
  ## Recover final `PSRAM_patch_num` and optional mid-patch count stores.
  if psramPatchSize == 0'u32:
    return
  result.layerType = layerType
  result.outputChannels = outputChannels
  result.outputElements = outputElements
  result.inputElements = inputElements
  result.routeChannels = routeChannels
  result.weightPatchCount = weightPatchCount
  result.psramPatchSize = psramPatchSize
  result.psramPatchCount =
    (outputChannels * outputElements) div psramPatchSize + weightPatchCount
  if midOut:
    result.midElements =
      if layerType == blaiConvMax:
        inputElements * outputChannels
      else:
        inputElements * routeChannels
    result.psramMidPatchCount = result.midElements div psramPatchSize
    if layerType == blaiConvMax:
      result.convMaxMidPatchExtra = true
      result.psramMidPatchCount += weightPatchCount
  result.valid = true

proc blaiFillPatchStores(layer: BlaiCpuInstLayer64,
                         initialPatches: uint32,
                         result: var BlaiMemAllocWeightPatchPlan) =
  let
    outputChannels = nonNegativeU32(layer.outC)
    outputElements = nonNegativeU32(layer.outW) * nonNegativeU32(layer.outH)
    inputElements = nonNegativeU32(layer.w) * nonNegativeU32(layer.h)
    route = blaiMemAllocRouteChannels(layer)
    outputPerPatchBase = blaiFloorPow2U32(
      outputChannels div max(initialPatches, 1'u32))
  result.outputChannelPatch = max(outputPerPatchBase, 1'u32)
  result.weightPatchCount = blaiCeilDivU32(outputChannels, result.outputChannelPatch)
  result.active = true
  if result.weightPatchCount == 0'u32 or
     result.weightPatchCount > BlaiMaxWeightPatchesU32:
    return

  var emittedChannels = 0'u32
  for patchIndex in 0'u32 ..< result.weightPatchCount:
    let patchStore = blaiMemAllocWeightPatchStoreEntry(
      patchIndex, result.weightPatchCount, emittedChannels, outputChannels,
      result.outputChannelPatch, outputElements, inputElements,
      layer.midOut == 1)
    if not patchStore.valid:
      return
    result.weightPatchOutC[patchStore.patchSlot] = patchStore.patchOutC
    result.psramPatchSize = patchStore.psramPatchSize
    emittedChannels = patchStore.nextEmittedChannels

  let countPlan = blaiMemAllocPatchCountPlan(
    blaiLayerTypeFromSdk(layer.layerType), outputChannels, outputElements,
    inputElements, route.channels, result.weightPatchCount,
    result.psramPatchSize, layer.midOut == 1)
  if not countPlan.valid:
    return
  result.psramPatchCount = countPlan.psramPatchCount
  result.psramMidPatchCount = countPlan.psramMidPatchCount
  result.fits = true

proc blaiPlanHighWeightPatchMemAllocInto*(layer: BlaiCpuInstLayer64,
                                          linePlan: BlaiMemAllocLinePatchPlan,
                                          outResult: var BlaiMemAllocWeightPatchPlan) =
  ## Recover the high-weight patch branch after line splitting.
  ##
  ## The SDK enters this branch when the estimated weight pressure exceeds the
  ## recovered 8192-byte threshold and the layer is weight-bearing. It chooses a
  ## power-of-two output-channel patch width, stores every `wei_patch_out_c[]`
  ## entry, then leaves the global PSRAM patch fields set from the final patch.
  outResult = default(BlaiMemAllocWeightPatchPlan)
  outResult.estimatedWeightBytes = blaiEstimateWeightPatchBytes(layer)
  if not linePlan.fits or
     not blaiUsesWeights(blaiLayerTypeFromSdk(layer.layerType)) or
     outResult.estimatedWeightBytes <= BlaiMemAllocWeightPatchThresholdBytes:
    return

  blaiFillPatchStores(layer,
    blaiCeilDivU32(outResult.estimatedWeightBytes,
                   BlaiMemAllocWeightPatchThresholdBytes),
    outResult)

proc blaiPlanHighWeightPatchMemAlloc*(layer: BlaiCpuInstLayer64,
                                      linePlan: BlaiMemAllocLinePatchPlan): BlaiMemAllocWeightPatchPlan =
  ## Convenience result-returning wrapper for high-weight patch planning.
  blaiPlanHighWeightPatchMemAllocInto(layer, linePlan, result)

proc blaiPlanPsramPatchMemAllocInto*(layer: BlaiCpuInstLayer64,
                                     linePlan: BlaiMemAllocLinePatchPlan,
                                     outResult: var BlaiMemAllocWeightPatchPlan) =
  ## Recover the lower-threshold PSRAM patch branch after line splitting.
  outResult = default(BlaiMemAllocWeightPatchPlan)
  outResult.estimatedWeightBytes = blaiEstimateWeightPatchBytes(layer)
  outResult.estimatedPsramBytes = blaiEstimatePsramPatchBytes(layer, linePlan)
  if not linePlan.fits or
     not blaiUsesWeights(blaiLayerTypeFromSdk(layer.layerType)) or
     outResult.estimatedWeightBytes > BlaiMemAllocWeightPatchThresholdBytes or
     outResult.estimatedPsramBytes <= BlaiMemAllocPsramPatchThresholdBytes:
    return

  blaiFillPatchStores(layer,
    blaiCeilDivU32(outResult.estimatedPsramBytes,
                   BlaiMemAllocPsramPatchThresholdBytes),
    outResult)

proc blaiPlanPsramPatchMemAlloc*(layer: BlaiCpuInstLayer64,
                                 linePlan: BlaiMemAllocLinePatchPlan): BlaiMemAllocWeightPatchPlan =
  ## Convenience result-returning wrapper for PSRAM patch planning.
  blaiPlanPsramPatchMemAllocInto(layer, linePlan, result)

proc blaiMemAllocWeightPatchApplyPlan*(
    plan: BlaiMemAllocWeightPatchPlan): BlaiMemAllocWeightPatchApplyPlan =
  ## Recover checked weight/PSRAM patch stores before mutating `PSRAM_ctrl`.
  if not plan.fits or not plan.active:
    return
  let
    weightPatchCount = blaiAllocatorFieldAbi(plan.weightPatchCount)
    psramPatchSize = blaiAllocatorFieldAbi(plan.psramPatchSize)
    psramPatchCount = blaiAllocatorFieldAbi(plan.psramPatchCount)
    psramMidPatchCount = blaiAllocatorFieldAbi(plan.psramMidPatchCount)
  if not weightPatchCount.valid or not psramPatchSize.valid or
     not psramPatchCount.valid or not psramMidPatchCount.valid:
    return
  result.weightPatchCount = weightPatchCount.value
  for i in 0 ..< BlaiMaxWeightPatches:
    let patchOutC = blaiAllocatorFieldAbi(plan.weightPatchOutC[i])
    if not patchOutC.valid:
      result = default(BlaiMemAllocWeightPatchApplyPlan)
      return
    result.weightPatchOutC[i] = patchOutC.value
  result.psramPatchSize = psramPatchSize.value
  result.psramPatchCount = psramPatchCount.value
  result.psramMidPatchCount = psramMidPatchCount.value
  result.valid = true

proc blaiApplyHighWeightPatchMemAlloc*(ctrl: var BlaiPsramCtrl,
                                       plan: BlaiMemAllocWeightPatchPlan) =
  ## Apply recovered high-weight patch stores to `PSRAM_ctrl`.
  let applyPlan = blaiMemAllocWeightPatchApplyPlan(plan)
  doAssert applyPlan.valid
  ctrl.weightPatchCount = applyPlan.weightPatchCount
  for i in 0 ..< BlaiMaxWeightPatches:
    ctrl.weightPatchOutC[i] = applyPlan.weightPatchOutC[i]
  ctrl.psramPatchSize = applyPlan.psramPatchSize
  ctrl.psramPatchCount = applyPlan.psramPatchCount
  ctrl.psramMidPatchCount = applyPlan.psramMidPatchCount

proc blaiPlanPatchMemAllocBranchInto*(layer: BlaiCpuInstLayer64,
                                      linePlan: BlaiMemAllocLinePatchPlan,
                                      outResult: var BlaiMemAllocPatchBranchPlan) =
  ## Recover the selected weight/PSRAM patch allocator branch after line split.
  outResult = default(BlaiMemAllocPatchBranchPlan)
  var patchPlan: BlaiMemAllocWeightPatchPlan
  blaiPlanHighWeightPatchMemAllocInto(layer, linePlan, patchPlan)
  if patchPlan.fits:
    outResult.branch = blaiMemAllocHighWeightPatch
    outResult.patch = patchPlan
    outResult.valid = true
    return

  blaiPlanPsramPatchMemAllocInto(layer, linePlan, patchPlan)
  if patchPlan.fits:
    outResult.branch = blaiMemAllocPsramPatch
    outResult.patch = patchPlan
    outResult.valid = true

proc blaiPlanPatchMemAllocBranch*(
    layer: BlaiCpuInstLayer64,
    linePlan: BlaiMemAllocLinePatchPlan): BlaiMemAllocPatchBranchPlan =
  ## Convenience result-returning wrapper for patch-branch selection.
  blaiPlanPatchMemAllocBranchInto(layer, linePlan, result)

proc blaiPlanMemAllocInto*(layer: BlaiCpuInstLayer64,
                           outResult: var BlaiMemAllocPlan) =
  ## Compose the recovered `BLAI_MEM_alloc` branch decisions.
  ##
  ## This is still bounded to the recovered branch set: line split search,
  ## high-weight patching, lower-threshold PSRAM patching, and the one-patch
  ## fallback. The caller applies the selected branch to a typed `BlaiPsramCtrl`.
  outResult = default(BlaiMemAllocPlan)
  blaiPlanLinePatchMemAllocInto(
    layer, outResult.line,
    blaiIsUpsample(blaiLayerTypeFromSdk(layer.layerType)))
  if not outResult.line.fits:
    outResult.branch = blaiMemAllocFailed
    return

  let patchBranch = blaiPlanPatchMemAllocBranch(layer, outResult.line)
  if patchBranch.valid:
    outResult.branch = patchBranch.branch
    outResult.patch = patchBranch.patch
    outResult.fits = true
    return

  blaiPlanSinglePatchMemAllocInto(layer, outResult.single)
  outResult.branch = blaiMemAllocSinglePatch
  outResult.fits = true

proc blaiPlanMemAlloc*(layer: BlaiCpuInstLayer64): BlaiMemAllocPlan =
  ## Convenience result-returning wrapper for recovered `BLAI_MEM_alloc`.
  blaiPlanMemAllocInto(layer, result)

proc blaiMemAllocControlApplyPlan*(
    plan: BlaiMemAllocPlan): BlaiMemAllocControlApplyPlan =
  ## Recover checked `PSRAM_ctrl` stores for the selected allocator branch.
  if not plan.fits:
    return
  result.branch = plan.branch
  case plan.branch
  of blaiMemAllocFailed:
    discard
  of blaiMemAllocSinglePatch:
    result.single = blaiMemAllocSinglePatchApplyPlan(plan.single)
    result.valid = result.single.valid
  of blaiMemAllocHighWeightPatch, blaiMemAllocPsramPatch:
    result.line = blaiMemAllocLinePatchApplyPlan(plan.line)
    result.patch = blaiMemAllocWeightPatchApplyPlan(plan.patch)
    result.valid = result.line.valid and result.patch.valid

proc blaiApplyMemAllocControlApplyPlan*(
    ctrl: var BlaiPsramCtrl,
    applyPlan: BlaiMemAllocControlApplyPlan) =
  ## Apply pre-checked allocator stores to `PSRAM_ctrl`.
  doAssert applyPlan.valid
  case applyPlan.branch
  of blaiMemAllocFailed:
    doAssert false
  of blaiMemAllocSinglePatch:
    ctrl.weightPatchCount = applyPlan.single.weightPatchCount
    ctrl.weightPatchOutC[0] = applyPlan.single.firstWeightPatchOutC
    ctrl.psramPatchSize = applyPlan.single.psramPatchSize
    ctrl.psramPatchCount = applyPlan.single.psramPatchCount
    ctrl.psramMidPatchCount = applyPlan.single.psramMidPatchCount
  of blaiMemAllocHighWeightPatch, blaiMemAllocPsramPatch:
    ctrl.linePatchCount = applyPlan.line.linePatchCount
    for i in 0 ..< BlaiMaxWeightPatches:
      ctrl.linePatchW[i] = applyPlan.line.linePatchW[i]
    ctrl.weightPatchCount = applyPlan.patch.weightPatchCount
    for i in 0 ..< BlaiMaxWeightPatches:
      ctrl.weightPatchOutC[i] = applyPlan.patch.weightPatchOutC[i]
    ctrl.psramPatchSize = applyPlan.patch.psramPatchSize
    ctrl.psramPatchCount = applyPlan.patch.psramPatchCount
    ctrl.psramMidPatchCount = applyPlan.patch.psramMidPatchCount

proc blaiApplyMemAllocPlan*(ctrl: var BlaiPsramCtrl,
                            plan: BlaiMemAllocPlan) =
  ## Apply a selected recovered `BLAI_MEM_alloc` branch to `PSRAM_ctrl`.
  let applyPlan = blaiMemAllocControlApplyPlan(plan)
  doAssert applyPlan.valid
  blaiApplyMemAllocControlApplyPlan(ctrl, applyPlan)

proc blaiFetchInputCount(layer: BlaiCpuInstLayer64,
                         kind: BlaiFetchMemoryKind): uint32 =
  let inputNum = nonNegativeU32(layer.inputNum)
  case kind
  of blaiFetchGeneral:
    if inputNum > 1'u32: 2'u32 else: 1'u32
  of blaiFetchRoute:
    max(inputNum, 2'u32)

proc blaiFetchPatchBudgetPlan*(
    kind: BlaiFetchMemoryKind,
    inputCount, psramPatchCount: uint32): BlaiFetchPatchBudgetPlan =
  ## Resolve the recovered fetch descriptor patch-slot budget.
  result.kind = kind
  result.inputCount = inputCount
  result.psramPatchCount = psramPatchCount
  case kind
  of blaiFetchGeneral:
    result.budget = BlaiFetchMaxPatchSlots
  of blaiFetchRoute:
    if inputCount == 0'u32:
      return
    result.routeDescriptorCount = inputCount - 1'u32
    result.budget = result.routeDescriptorCount * psramPatchCount
  result.valid = true

proc blaiFetchInputPatchCursor*(
    layer: BlaiCpuInstLayer64,
    inputIndex, totalPatches, patchSize: uint32): BlaiFetchInputPatchCursor =
  ## Resolve one recovered fetch input patch count and total-patch advance.
  if patchSize == 0'u32:
    return
  let inputCursor = blaiU32ArrayIndexCursor(inputIndex, BlaiMaxInputNum)
  if not inputCursor.valid:
    return
  let channels =
    if inputIndex == 0'u32:
      nonNegativeU32(layer.c)
    else:
      nonNegativeU32(blaiLayerCn(layer, inputIndex))
  let elements =
    nonNegativeU32(layer.w).uint64 * nonNegativeU32(layer.h).uint64 *
    channels.uint64
  var inputElements: uint32
  if not blaiU64ExactU32Count(elements, inputElements):
    return
  let patchCount = blaiCeilDivU32(inputElements, patchSize)
  if patchCount > high(uint32) - totalPatches:
    return
  result.inputIndex = inputIndex
  result.slotIndex = inputCursor.index
  result.inputElements = inputElements
  result.patchCount = patchCount
  result.totalPatches = totalPatches
  result.nextTotalPatches = totalPatches + patchCount
  result.valid = true

proc blaiFetchInputSlotCursor*(
    inputIndex, slot: uint32,
    inputPatchCount: openArray[uint32]): BlaiFetchInputSlotCursor =
  ## Resolve one recovered fetch input SRAM slot and next-slot advance.
  let inputCursor = blaiU32ArrayIndexCursor(inputIndex, inputPatchCount.len)
  if not inputCursor.valid:
    return
  let patchCount = inputPatchCount[inputCursor.index]
  if patchCount > high(uint32) - slot:
    return
  result.inputIndex = inputIndex
  result.slotIndex = inputCursor.index
  result.slot = slot
  result.patchCount = patchCount
  result.nextSlot = slot + patchCount
  result.valid = true

proc blaiFetchOutputSlotPlan*(
    inputCursor, psramMidPatchCount,
    psramPatchCount: uint32): BlaiFetchOutputSlotPlan =
  ## Recover final fetch mid/output/DRAM patch slots after input slots.
  if psramMidPatchCount > high(uint32) - inputCursor:
    return
  let outputSlot = inputCursor + psramMidPatchCount
  if psramPatchCount > high(uint32) - outputSlot:
    return
  result.midOutputSlot = inputCursor
  result.psramMidPatchCount = psramMidPatchCount
  result.outputSlot = outputSlot
  result.psramPatchCount = psramPatchCount
  result.dramPatchCount = outputSlot + psramPatchCount
  result.valid = true

proc blaiPlanFetchMemoryInto*(layer: BlaiCpuInstLayer64,
                              ctrl: BlaiPsramCtrl,
                              kind: BlaiFetchMemoryKind,
                              outResult: var BlaiFetchMemoryPlan) =
  ## Recover the fetch_BLAI_data_* PSRAM slot planning before descriptor emit.
  ##
  ## The SDK doubles `PSRAM_patch_size` up to five times until input patch slots
  ## fit the emitter's instruction budget. Descriptor bit packing remains a
  ## separate recovery step.
  outResult = default(BlaiFetchMemoryPlan)
  outResult.kind = kind
  outResult.inputCount = min(blaiFetchInputCount(layer, kind),
                             BlaiMaxInputNumU32)
  outResult.patchSize = nonNegativeU32(ctrl.psramPatchSize)
  if outResult.patchSize == 0'u32:
    return

  for attempt in 0 ..< BlaiFetchPatchGrowTries:
    outResult.growAttempts = attempt.uint32 + 1'u32
    var totalInputPatches = 0'u32
    for inputIndex in 0 ..< outResult.inputCount:
      let inputPatch = blaiFetchInputPatchCursor(
        layer, inputIndex, totalInputPatches, outResult.patchSize)
      if not inputPatch.valid:
        return
      outResult.inputPatchCount[inputPatch.slotIndex] = inputPatch.patchCount
      totalInputPatches = inputPatch.nextTotalPatches
    outResult.totalInputPatches = totalInputPatches

    let budgetPlan = blaiFetchPatchBudgetPlan(
      kind, outResult.inputCount, nonNegativeU32(ctrl.psramPatchCount))
    if not budgetPlan.valid:
      return
    outResult.patchBudget = budgetPlan.budget

    if totalInputPatches <= budgetPlan.budget:
      outResult.fits = true
      break
    if attempt + 1 < BlaiFetchPatchGrowTries:
      outResult.patchSize = outResult.patchSize * 2'u32
      inc outResult.patchGrowCount

  if not outResult.fits:
    return

  var cursor = 0'u32
  for inputIndex in 0 ..< outResult.inputCount:
    let inputSlot = blaiFetchInputSlotCursor(
      inputIndex, cursor, outResult.inputPatchCount)
    if not inputSlot.valid:
      return
    outResult.inputSlots[inputSlot.slotIndex] = inputSlot.slot
    cursor = inputSlot.nextSlot
  let outputSlots = blaiFetchOutputSlotPlan(
    cursor, nonNegativeU32(ctrl.psramMidPatchCount),
    nonNegativeU32(ctrl.psramPatchCount))
  if not outputSlots.valid:
    return
  outResult.midOutputSlot = outputSlots.midOutputSlot
  outResult.outputSlot = outputSlots.outputSlot
  outResult.dramPatchCount = outputSlots.dramPatchCount

proc blaiPlanFetchMemory*(layer: BlaiCpuInstLayer64,
                          ctrl: BlaiPsramCtrl,
                          kind: BlaiFetchMemoryKind): BlaiFetchMemoryPlan =
  ## Convenience result-returning wrapper for fetch memory planning.
  blaiPlanFetchMemoryInto(layer, ctrl, kind, result)

proc blaiForwardWorkspaceInstructionStreamEvidenceInto*(
    layer: BlaiCpuInstLayer64,
    ctrl: BlaiPsramCtrl,
    stream: openArray[BlaiInstruction],
    useTflite: bool,
    outResult: var BlaiForwardWorkspaceInstructionStreamEvidence,
    kind: BlaiFetchMemoryKind = blaiFetchGeneral) =
  ## Decode and rebuild one materialized active instruction stream.
  outResult = default(BlaiForwardWorkspaceInstructionStreamEvidence)
  outResult.fetchPlan = blaiPlanFetchMemory(layer, ctrl, kind)
  outResult.operands = blaiPlanFetchDescriptorOperands(layer, ctrl, kind)
  outResult.bundle = blaiLayerInstructionBundle(
    layer, outResult.fetchPlan, useTflite, operands = outResult.operands)
  var rebuilt: array[3, BlaiInstruction]
  outResult.encode = blaiEncodeInstructions(outResult.bundle, rebuilt, 0)
  if stream.len >= 1:
    outResult.decodedQuant = decodeBlaiTfliteQuantInstruction(stream[0])
  if stream.len >= 2:
    outResult.decodedExt = decodeBlaiExternalLayerInfo(stream[1])
  outResult.layerInstructionIndex =
    if outResult.decodedExt.valid: 2'u32 else: 1'u32
  outResult.noExternalLayerInfo = not outResult.decodedExt.valid
  outResult.defaultLayerInstructionIndex =
      outResult.layerInstructionIndex == 1'u32
  outResult.noExtra =
    outResult.noExternalLayerInfo and outResult.defaultLayerInstructionIndex
  let streamCapacity = blaiOpenArrayLenU32(stream)
  let layerInstructionCursor =
    blaiInstructionStreamCursor(outResult.layerInstructionIndex, stream.len)
  if layerInstructionCursor.valid:
    outResult.decodedLayer =
      decodeBlaiLayer(stream[layerInstructionCursor.index],
        outResult.decodedExt)
    if useTflite:
      outResult.decodedTfliteDescriptor =
        decodeBlaiTfliteDescriptorInstruction(
          stream[layerInstructionCursor.index])
  outResult.bundleEndCountInBounds =
    outResult.encode.endCount <= streamCapacity
  let bundleCompareCount = blaiInstructionStreamCountCursor(
    outResult.encode.endCount, min(rebuilt.len, stream.len))
  outResult.bundleBytesEqual =
    outResult.encode.fits and outResult.bundleEndCountInBounds and
      bundleCompareCount.valid
  if outResult.bundleBytesEqual:
    for index in 0 ..< bundleCompareCount.count:
      if rebuilt[index] != stream[index]:
        outResult.bundleBytesEqual = false
  outResult.bundleMatches =
    outResult.encode.fits and outResult.bundleEndCountInBounds and
      outResult.bundleBytesEqual
  outResult.fetchPlanFits = outResult.fetchPlan.fits
  outResult.encodeFits = outResult.encode.fits
  outResult.layerInstructionInBounds =
    layerInstructionCursor.valid
  outResult.valid =
    outResult.fetchPlanFits and outResult.encodeFits and
      outResult.bundleMatches and outResult.layerInstructionInBounds

proc blaiForwardWorkspaceInstructionStreamEvidence*(
    layer: BlaiCpuInstLayer64,
    ctrl: BlaiPsramCtrl,
    stream: openArray[BlaiInstruction],
    useTflite: bool,
    kind: BlaiFetchMemoryKind = blaiFetchGeneral):
    BlaiForwardWorkspaceInstructionStreamEvidence =
  ## Convenience wrapper for materialized active instruction-stream evidence.
  blaiForwardWorkspaceInstructionStreamEvidenceInto(
    layer, ctrl, stream, useTflite, result, kind)

proc blaiForwardWorkspaceInstructionStreamSemanticEvidenceInto*(
    evidence: BlaiForwardWorkspaceInstructionStreamEvidence,
    layer: BlaiCpuInstLayer64,
    stream: openArray[BlaiInstruction],
    outResult: var BlaiForwardWorkspaceInstructionStreamSemanticEvidence) =
  ## Check SDK-level active stream semantics from decoded stream evidence.
  outResult = default(BlaiForwardWorkspaceInstructionStreamSemanticEvidence)
  let
    operands = evidence.operands
    quant = evidence.decodedQuant
    tfliteDescriptor = evidence.decodedTfliteDescriptor
    decoded = evidence.decodedLayer
  outResult.operandC2ZeroMatches = operands.c2 == 0'u32
  outResult.operandNoExtraInfoMatches = not operands.includeExtra
  outResult.operandSingleInputC2Matches = not operands.multiInputC2
  outResult.operandNoWeightPatchExtraMatches = not operands.weightPatchExtra
  outResult.operandNoLinePatchExtraMatches = not operands.linePatchExtra
  outResult.operandNoGroupedExtraMatches = not operands.groupedExtra
  outResult.operandNoStrideExtraMatches = not operands.strideExtra
  outResult.operandNoDilationExtraMatches = not operands.dilationExtra
  outResult.operandPlanMatches =
    outResult.operandC2ZeroMatches and outResult.operandNoExtraInfoMatches and
      outResult.operandSingleInputC2Matches and
      outResult.operandNoWeightPatchExtraMatches and
      outResult.operandNoLinePatchExtraMatches and
      outResult.operandNoGroupedExtraMatches and
      outResult.operandNoStrideExtraMatches and
      outResult.operandNoDilationExtraMatches
  outResult.instructionCountMatches = layer.instCnt == 2
  outResult.decodedLayerCountMatches = blaiLayerCount(stream) == 1'u32
  outResult.oneLayer =
    outResult.instructionCountMatches and outResult.decodedLayerCountMatches
  outResult.layerLinearActivationMatches =
    blaiActivationFromSdk(layer.activation) == blaiActLinear
  outResult.layerDataTypeMatches = layer.dataType == 1
  outResult.layerSemanticsMatch =
    outResult.layerLinearActivationMatches and outResult.layerDataTypeMatches
  outResult.streamFetchPlanFits = evidence.fetchPlanFits
  outResult.streamEncodeFits = evidence.encodeFits
  outResult.streamBundleEndCountInBounds = evidence.bundleEndCountInBounds
  outResult.streamBundleBytesEqual = evidence.bundleBytesEqual
  outResult.streamBundleMatches = evidence.bundleMatches
  outResult.streamLayerInstructionInBounds = evidence.layerInstructionInBounds
  outResult.streamEvidenceValid = evidence.valid
  outResult.noExternalLayerInfo = evidence.noExternalLayerInfo
  outResult.defaultLayerInstructionIndex = evidence.defaultLayerInstructionIndex
  outResult.noExtra = evidence.noExtra
  outResult.halt = decoded.halt
  outResult.typeMatches = decoded.layerType == blaiConvolutional
  outResult.widthMatches = decoded.w == nonNegativeU32(layer.w)
  outResult.heightMatches = decoded.h == nonNegativeU32(layer.h)
  outResult.inputChannelsMatch = decoded.c == nonNegativeU32(layer.c)
  outResult.outputChannelsMatch = decoded.outC == nonNegativeU32(layer.outC)
  outResult.kernelSizeMatches = decoded.size == nonNegativeU32(layer.size)
  outResult.shapeMatches =
    outResult.widthMatches and outResult.heightMatches and
      outResult.inputChannelsMatch and outResult.outputChannelsMatch and
      outResult.kernelSizeMatches
  outResult.c2Matches = decoded.cn0 == operands.c2
  outResult.inputSlotMatches =
    decoded.inLayer1Mem == nonNegativeU32(layer.dramIn[0])
  outResult.outputSlotMatches =
    decoded.outLayerMem == nonNegativeU32(layer.dramOut[0])
  outResult.slotsMatch =
    outResult.inputSlotMatches and outResult.outputSlotMatches
  outResult.strideStepMatches = decoded.stride == nonNegativeU32(layer.stride)
  outResult.dilationMatches = decoded.dilation == nonNegativeU32(layer.dilation)
  outResult.groupsMatches = decoded.groups == nonNegativeU32(layer.groups)
  outResult.strideMatches =
    outResult.strideStepMatches and outResult.dilationMatches and
      outResult.groupsMatches
  outResult.fdataMatches = decoded.fdata == nonNegativeU32(layer.fdata)
  outResult.fweightMatches = decoded.fweight == nonNegativeU32(layer.fweight)
  outResult.fbiasMatches = decoded.fbias == nonNegativeU32(layer.fbias)
  outResult.foutMatches = decoded.fout == nonNegativeU32(layer.fout)
  outResult.fractionsMatch =
    outResult.fdataMatches and outResult.fweightMatches and
      outResult.fbiasMatches and outResult.foutMatches
  outResult.activationKindMatches =
    decoded.activation == nonNegativeU32(layer.activation)
  outResult.tfOutputOffsetMatches =
    tfliteDescriptor.tfOutputOffset == nonNegativeU32(layer.tfOutputOffset)
  outResult.tfliteInput1OffsetMatches =
    tfliteDescriptor.tfInput1Offset == nonNegativeU32(layer.tfInput1Offset)
  outResult.tfliteInput2OffsetMatches =
    tfliteDescriptor.tfInput2Offset == nonNegativeU32(layer.tfInput2Offset)
  outResult.tfliteOutputOffsetMatches = outResult.tfOutputOffsetMatches
  outResult.tfliteOutputShiftMatches =
    tfliteDescriptor.tfOutputShift == layer.tfOutputShift
  outResult.tfliteDescriptorMatches =
    outResult.tfliteInput1OffsetMatches and
      outResult.tfliteInput2OffsetMatches and
      outResult.tfliteOutputOffsetMatches and
      outResult.tfliteOutputShiftMatches
  outResult.activationMatches =
    outResult.activationKindMatches and outResult.tfliteDescriptorMatches
  if stream.len > 0:
    outResult.quantTfliteFlagMatches =
      quant.isTflite
    outResult.quantInput1ShiftMatches =
      quant.tfInput1Shift == layer.tfInput1Shift
    outResult.quantInput2ShiftMatches =
      quant.tfInput2Shift == layer.tfInput2Shift
    outResult.quantSideMatches =
      outResult.quantTfliteFlagMatches and
        outResult.quantInput1ShiftMatches and
        outResult.quantInput2ShiftMatches
    outResult.quantInput1MultiplierMatches =
      quant.tfInput1Multiplier == blaiUint32FromInt32Bits(layer.tfInput1Multiplier)
    outResult.quantInput2MultiplierMatches =
      quant.tfInput2Multiplier == blaiUint32FromInt32Bits(layer.tfInput2Multiplier)
    outResult.quantOutputMultiplierMatches =
      quant.tfOutputMultiplier == blaiUint32FromInt32Bits(layer.tfOutputMultiplier)
    outResult.quantMultipliersMatch =
      outResult.quantInput1MultiplierMatches and
        outResult.quantInput2MultiplierMatches and
        outResult.quantOutputMultiplierMatches
    outResult.quantActivationMinMatches =
      quant.quantizedActivationMin == nonNegativeU32(layer.quantizedActivationMin)
    outResult.quantActivationMaxMatches =
      quant.quantizedActivationMax == nonNegativeU32(layer.quantizedActivationMax)
    outResult.quantClampMatches =
      outResult.quantActivationMinMatches and outResult.quantActivationMaxMatches
  if evidence.layerInstructionInBounds:
    outResult.commonImgInMatches =
      decoded.imgIn == (layer.imgIn != 0)
    outResult.commonMaxCheckMatches = not decoded.maxCheck
    outResult.commonRouteBitMatches = not decoded.routeBit
    outResult.commonMacBitMatches = decoded.macBit == 1'u32
    outResult.commonMidLayerMatches =
      decoded.midLayerMem == evidence.fetchPlan.midOutputSlot
    outResult.commonMidOutMatches =
      decoded.midOut == (layer.midOut != 0)
    outResult.commonMidOutStateClear = not decoded.midOutState
    outResult.commonUpsampleClear = not decoded.upsampleBit
    outResult.commonMacBitExtClear = not decoded.macBitExt
    outResult.commonInstEndMatches = decoded.instEndBit == (layer.halt != 0)
    outResult.commonControlMatches =
      outResult.commonImgInMatches and outResult.commonMaxCheckMatches and
        outResult.commonRouteBitMatches and outResult.commonMacBitMatches and
        outResult.commonMidLayerMatches and outResult.commonMidOutMatches and
        outResult.commonMidOutStateClear and outResult.commonUpsampleClear and
        outResult.commonMacBitExtClear and outResult.commonInstEndMatches
  outResult.bundleFetchFits = evidence.fetchPlan.fits
  outResult.bundleTfliteModeMatches = evidence.bundle.useTflite == 1
  outResult.bundleExtraInfoMatches = evidence.bundle.extraInfo == 0
  outResult.bundleEncodeFits = evidence.encode.fits
  outResult.bundleEndCountMatches = evidence.encode.endCount == 2'u32
  outResult.bundlePlanValid =
    outResult.bundleFetchFits and outResult.bundleTfliteModeMatches and
      outResult.bundleExtraInfoMatches and outResult.bundleEncodeFits and
      outResult.bundleEndCountMatches
  outResult.bundleBytesMatch = evidence.bundleMatches
  outResult.valid =
    outResult.operandPlanMatches and outResult.oneLayer and
      outResult.layerSemanticsMatch and outResult.streamEvidenceValid and
      outResult.noExtra and outResult.halt and outResult.typeMatches and
      outResult.shapeMatches and outResult.c2Matches and
      outResult.slotsMatch and outResult.strideMatches and
      outResult.fractionsMatch and outResult.activationMatches and
      outResult.quantSideMatches and outResult.quantMultipliersMatch and
      outResult.quantClampMatches and outResult.commonControlMatches and
      outResult.bundlePlanValid and outResult.bundleBytesMatch

proc blaiForwardWorkspaceInstructionStreamSemanticEvidence*(
    evidence: BlaiForwardWorkspaceInstructionStreamEvidence,
    layer: BlaiCpuInstLayer64,
    stream: openArray[BlaiInstruction]):
    BlaiForwardWorkspaceInstructionStreamSemanticEvidence =
  ## Convenience wrapper for active stream semantic evidence.
  blaiForwardWorkspaceInstructionStreamSemanticEvidenceInto(
    evidence, layer, stream, result)

proc blaiRouteInputPatchTotalCursor*(
    inputIndex, totalPatches: uint32,
    inputPatchCount: openArray[uint32]): BlaiRouteInputPatchTotalCursor =
  ## Accumulate one recovered route input patch count into the output cursor.
  let inputCursor = blaiU32ArrayIndexCursor(inputIndex, inputPatchCount.len)
  if not inputCursor.valid:
    return
  let patchCount = inputPatchCount[inputCursor.index]
  if patchCount > high(uint32) - totalPatches:
    return
  result.inputIndex = inputIndex
  result.slotIndex = inputCursor.index
  result.patchCount = patchCount
  result.totalPatches = totalPatches
  result.nextTotalPatches = totalPatches + patchCount
  result.valid = true

proc blaiRouteFirstOutputSlotPlan*(
    totalInputPatches, psramPatchCount: uint32): BlaiRouteFirstOutputSlotPlan =
  ## Recover the first route SRAM output slot and post-output patch cursor.
  if psramPatchCount > high(uint32) - totalInputPatches:
    return
  result.totalInputPatches = totalInputPatches
  result.psramPatchCount = psramPatchCount
  result.outputSlot = totalInputPatches
  result.outputSlotCount = 1
  result.nextCursor = totalInputPatches + psramPatchCount
  result.valid = true

proc blaiRouteIntermediateChannelCursor*(
    stepIndex, cumulativeChannels: uint32,
    cn: openArray[int32]): BlaiRouteIntermediateChannelCursor =
  ## Recover one route intermediate channel accumulation step from `cn[]`.
  let stepCursor = blaiRouteDescriptorStepCursor(stepIndex)
  if not stepCursor.valid or stepCursor.index >= cn.len:
    return
  let inputChannels = nonNegativeU32(cn[stepCursor.index])
  if inputChannels > high(uint32) - cumulativeChannels:
    return
  result.stepIndex = stepIndex
  result.cnSlot = stepCursor.index
  result.inputChannels = inputChannels
  result.cumulativeChannels = cumulativeChannels
  result.nextCumulativeChannels = cumulativeChannels + inputChannels
  result.valid = true

proc blaiRouteIntermediateOutputSlotPlan*(
    stepIndex, cursor, outW, outH, cumulativeChannels, patchSize,
    outputSlotCount: uint32): BlaiRouteIntermediateOutputSlotPlan =
  ## Recover one route intermediate output-slot commit.
  let outputSlot = blaiRouteOutputSlotCursor(
    stepIndex, cursor, outW, outH, cumulativeChannels, patchSize)
  if not outputSlot.valid or outputSlotCount == high(uint32):
    return
  result.stepIndex = stepIndex
  result.slotIndex = outputSlot.slotIndex
  result.outputSlot = outputSlot.slot
  result.outputSlotCount = outputSlotCount
  result.nextOutputSlotCount = outputSlotCount + 1'u32
  result.nextCursor = outputSlot.nextCursor
  result.valid = true

proc blaiRouteSramLayerApplyPlan*(
    linePatchW0, groups: int32,
    finalPatchCursor: uint32): BlaiRouteSramLayerApplyPlan =
  ## Recover the layer-side assignments made by `fetch_BLAI_data_route`.
  let dramPatchNum = blaiAllocatorFieldAbi(finalPatchCursor)
  if not dramPatchNum.valid:
    return
  result.lineW0 = linePatchW0
  result.groups = if groups <= 0: 1'i32 else: groups
  result.dramPatchNum = dramPatchNum.value
  result.valid = true

proc blaiFetchLayerApplyPlan*(
    dramPatchCount: uint32): BlaiFetchLayerApplyPlan =
  ## Recover the layer-side assignment made by `fetch_BLAI_data_general`.
  let dramPatchNum = blaiAllocatorFieldAbi(dramPatchCount)
  if not dramPatchNum.valid:
    return
  result.dramPatchNum = dramPatchNum.value
  result.valid = true

proc blaiFetchInputSlotApplyPlan*(
    inputIndex: uint32,
    inputSlots: openArray[uint32]): BlaiFetchInputSlotApplyPlan =
  ## Recover one `SRAM_in[]` assignment from a planned fetch input slot.
  let inputCursor = blaiU32ArrayIndexCursor(inputIndex, inputSlots.len)
  if not inputCursor.valid:
    return
  let sramSlot = blaiAllocatorFieldAbi(inputSlots[inputCursor.index])
  if not sramSlot.valid:
    return
  result.inputIndex = inputIndex
  result.slotIndex = inputCursor.index
  result.sramSlot = sramSlot.value
  result.valid = true

proc blaiFetchOutputSlotApplyPlan*(
    midOutputSlot, outputSlot: uint32): BlaiFetchOutputSlotApplyPlan =
  ## Recover `SRAM_mid_out` and first `SRAM_out[]` application for general fetch.
  let
    midOut = blaiAllocatorFieldAbi(midOutputSlot)
    out0 = blaiAllocatorFieldAbi(outputSlot)
  if not midOut.valid or not out0.valid:
    return
  result.sramMidOut = midOut.value
  result.sramOut0 = out0.value
  result.valid = true

proc blaiFetchPatchSizeApplyPlan*(
    patchSize: uint32): BlaiFetchPatchSizeApplyPlan =
  ## Recover `PSRAM_patch_size` application for general and route fetch plans.
  let field = blaiAllocatorFieldAbi(patchSize)
  if not field.valid:
    return
  result.patchSize = field.value
  result.valid = true

proc blaiRouteOutputSlotApplyPlan*(
    outputIndex: uint32,
    outputSlots: openArray[uint32]): BlaiRouteOutputSlotApplyPlan =
  ## Recover one `SRAM_out[]` assignment from a planned route output slot.
  let outputCursor = blaiRouteSlotCursor(outputIndex)
  if not outputCursor.valid or outputCursor.slotIndex >= outputSlots.len:
    return
  let sramSlot = blaiAllocatorFieldAbi(outputSlots[outputCursor.slotIndex])
  if not sramSlot.valid:
    return
  result.outputIndex = outputIndex
  result.slotIndex = outputCursor.slotIndex
  result.sramSlot = sramSlot.value
  result.valid = true

proc blaiPlanRouteSramSlotsInto*(layer: BlaiCpuInstLayer64,
                                 ctrl: BlaiPsramCtrl,
                                 outResult: var BlaiRouteSramSlotPlan) =
  ## Recover the `fetch_BLAI_data_route` SRAM output-slot choreography.
  outResult = default(BlaiRouteSramSlotPlan)
  blaiPlanFetchMemoryInto(layer, ctrl, blaiFetchRoute, outResult.memory)
  if not outResult.memory.fits:
    return

  var totalInputPatches = 0'u32
  for inputIndex in 0 ..< outResult.memory.inputCount:
    let inputTotal = blaiRouteInputPatchTotalCursor(
      inputIndex, totalInputPatches, outResult.memory.inputPatchCount)
    if not inputTotal.valid:
      return
    totalInputPatches = inputTotal.nextTotalPatches

  let firstOutput = blaiRouteFirstOutputSlotPlan(
    totalInputPatches, nonNegativeU32(ctrl.psramPatchCount))
  if not firstOutput.valid:
    return
  outResult.outputSlots[0] = firstOutput.outputSlot
  outResult.outputSlotCount = firstOutput.outputSlotCount

  var
    cursor = firstOutput.nextCursor
    cumulativeChannels = nonNegativeU32(layer.c)
  let intermediateCount =
    if outResult.memory.inputCount > 2'u32:
      outResult.memory.inputCount - 2'u32
    else:
      0'u32
  for index in 0'u32 ..< intermediateCount:
    if index < BlaiMaxRouteInputNumU32:
      let channelCursor = blaiRouteIntermediateChannelCursor(
        index, cumulativeChannels, layer.cn)
      if not channelCursor.valid:
        return
      cumulativeChannels = channelCursor.nextCumulativeChannels
    let outputCommit = blaiRouteIntermediateOutputSlotPlan(
      index, cursor, nonNegativeU32(layer.outW), nonNegativeU32(layer.outH),
      cumulativeChannels, outResult.memory.patchSize,
      outResult.outputSlotCount)
    if not outputCommit.valid:
      return
    outResult.outputSlots[outputCommit.slotIndex] = outputCommit.outputSlot
    outResult.outputSlotCount = outputCommit.nextOutputSlotCount
    cursor = outputCommit.nextCursor

  outResult.finalPatchCursor = cursor
  outResult.fits = true

proc blaiPlanRouteSramSlots*(layer: BlaiCpuInstLayer64,
                             ctrl: BlaiPsramCtrl): BlaiRouteSramSlotPlan =
  ## Convenience result-returning wrapper for route SRAM slot planning.
  blaiPlanRouteSramSlotsInto(layer, ctrl, result)

proc blaiApplyRouteSramSlotPlan*(ctrl: var BlaiPsramCtrl,
                                 layer: var BlaiCpuInstLayer64,
                                 plan: BlaiRouteSramSlotPlan) =
  ## Apply recovered route SRAM slots to typed `PSRAM_ctrl` and layer state.
  doAssert plan.fits
  for i in 0 ..< BlaiMaxInputNum:
    ctrl.sramIn[i] = 0
    ctrl.sramOut[i] = 0
  let patchSizeApply = blaiFetchPatchSizeApplyPlan(plan.memory.patchSize)
  doAssert patchSizeApply.valid
  ctrl.psramPatchSize = patchSizeApply.patchSize
  for inputIndex in 0 ..< blaiBoundedU32Count(
      plan.memory.inputCount, BlaiMaxInputNum):
    let inputApply = blaiFetchInputSlotApplyPlan(
      inputIndex.uint32, plan.memory.inputSlots)
    doAssert inputApply.valid
    ctrl.sramIn[inputApply.slotIndex] = inputApply.sramSlot
  for outputIndex in 0 ..< blaiBoundedU32Count(
      plan.outputSlotCount, BlaiMaxInputNum):
    let outputApply = blaiRouteOutputSlotApplyPlan(
      outputIndex.uint32, plan.outputSlots)
    doAssert outputApply.valid
    ctrl.sramOut[outputApply.slotIndex] = outputApply.sramSlot
  let layerApply = blaiRouteSramLayerApplyPlan(
    ctrl.linePatchW[0], layer.groups, plan.finalPatchCursor)
  doAssert layerApply.valid
  ctrl.lineW0 = layerApply.lineW0
  layer.groups = layerApply.groups
  layer.dramPatchNum = layerApply.dramPatchNum

proc blaiApplyFetchMemoryPlan*(ctrl: var BlaiPsramCtrl,
                               layer: var BlaiCpuInstLayer64,
                               plan: BlaiFetchMemoryPlan) =
  ## Apply the recovered fetch_BLAI_data_* slot fields to typed objects.
  doAssert plan.fits
  for i in 0 ..< BlaiMaxInputNum:
    ctrl.sramIn[i] = 0
    ctrl.sramOut[i] = 0
  let patchSizeApply = blaiFetchPatchSizeApplyPlan(plan.patchSize)
  doAssert patchSizeApply.valid
  ctrl.psramPatchSize = patchSizeApply.patchSize
  for inputIndex in 0 ..< blaiBoundedU32Count(
      plan.inputCount, BlaiMaxInputNum):
    let inputApply = blaiFetchInputSlotApplyPlan(
      inputIndex.uint32, plan.inputSlots)
    doAssert inputApply.valid
    ctrl.sramIn[inputApply.slotIndex] = inputApply.sramSlot
  let outputApply = blaiFetchOutputSlotApplyPlan(
    plan.midOutputSlot, plan.outputSlot)
  doAssert outputApply.valid
  ctrl.sramMidOut = outputApply.sramMidOut
  ctrl.sramOut[0] = outputApply.sramOut0
  let layerApply = blaiFetchLayerApplyPlan(plan.dramPatchCount)
  doAssert layerApply.valid
  layer.dramPatchNum = layerApply.dramPatchNum

proc blaiEmitFetchLayerInstructionsInto*(layer: var BlaiCpuInstLayer64,
                                         ctrl: var BlaiPsramCtrl,
                                         stream: var openArray[BlaiInstruction],
                                         kind: BlaiFetchMemoryKind,
                                         useTflite: bool,
                                         outResult: var BlaiFetchEmitResult,
                                         c2: uint32 = 0'u32,
                                         includeExtra: bool = false,
                                         descriptorHalt: bool = false,
                                         midOutState: bool = false) =
  ## Plan fetch memory, emit recovered layer instructions, then commit state.
  ##
  ## The caller-owned layer, ctrl, and stream are unchanged unless both the
  ## fetch memory plan and full instruction append fit.
  outResult = default(BlaiFetchEmitResult)
  var
    stagedLayer = layer
    stagedCtrl = ctrl
  if kind == blaiFetchRoute:
    var routePlan: BlaiRouteSramSlotPlan
    blaiPlanRouteSramSlotsInto(stagedLayer, stagedCtrl, routePlan)
    outResult.memoryPlan = routePlan.memory
    outResult.fetchFits = routePlan.fits
    if not outResult.fetchFits:
      return
    blaiApplyRouteSramSlotPlan(stagedCtrl, stagedLayer, routePlan)
    blaiEmitRouteLayerInstructionsInto(
      stagedLayer, routePlan, stream, useTflite, outResult.instructions,
      includeExtra, descriptorHalt, midOutState)
  else:
    blaiPlanFetchMemoryInto(
      stagedLayer, stagedCtrl, kind, outResult.memoryPlan)
    outResult.fetchFits = outResult.memoryPlan.fits
    if not outResult.fetchFits:
      return
    blaiApplyFetchMemoryPlan(stagedCtrl, stagedLayer, outResult.memoryPlan)
    blaiEmitLayerInstructionsInto(
      stagedLayer, outResult.memoryPlan, stream, useTflite,
      outResult.instructions, c2, includeExtra, descriptorHalt, midOutState)
  outResult.fits = outResult.instructions.fits
  if outResult.fits:
    layer = stagedLayer
    ctrl = stagedCtrl

proc blaiEmitFetchLayerInstructions*(layer: var BlaiCpuInstLayer64,
                                     ctrl: var BlaiPsramCtrl,
                                     stream: var openArray[BlaiInstruction],
                                     kind: BlaiFetchMemoryKind,
                                     useTflite: bool,
                                     c2: uint32 = 0'u32,
                                     includeExtra: bool = false,
                                     descriptorHalt: bool = false,
                                     midOutState: bool = false): BlaiFetchEmitResult =
  ## Convenience result-returning wrapper for fetch instruction emission.
  blaiEmitFetchLayerInstructionsInto(
    layer, ctrl, stream, kind, useTflite, result, c2, includeExtra,
    descriptorHalt, midOutState)

proc blaiEncodeCpuLayerInto*(layer: var BlaiCpuInstLayer64,
                             ctrl: var BlaiPsramCtrl,
                             stream: var openArray[BlaiInstruction],
                             allocationSucceeded: bool,
                             useTflite: bool,
                             outResult: var BlaiCpuLayerEncodeResult,
                             c2: uint32 = 0'u32,
                             includeExtra: bool = false,
                             descriptorHalt: bool = false,
                             midOutState: bool = false) =
  ## Recovered bounded `BLAI_encode` wrapper around the pure fetch emitter.
  ##
  ## This low-level variant accepts an explicit allocator success flag and a
  ## caller-populated `BlaiPsramCtrl`, which keeps allocator oracle tests
  ## separate from the allocator-backed wrapper.
  outResult = default(BlaiCpuLayerEncodeResult)
  blaiPlanEncodeInto(layer, allocationSucceeded, outResult.plan)
  if not outResult.plan.runnable:
    blaiMarkEncodeFailed(layer)
    return

  blaiClearInstructionStream(stream)
  outResult.scratchCleared = true
  layer.instCnt = 0
  blaiEmitFetchLayerInstructionsInto(
    layer, ctrl, stream, blaiFetchKind(outResult.plan.dispatch),
    useTflite, outResult.fetch, c2, includeExtra, descriptorHalt, midOutState)
  outResult.encoded = outResult.fetch.fits
  if outResult.encoded:
    blaiApplyMemoryPlan(layer, ctrl)
  else:
    blaiMarkEncodeFailed(layer)

proc blaiEncodeCpuLayer*(layer: var BlaiCpuInstLayer64,
                         ctrl: var BlaiPsramCtrl,
                         stream: var openArray[BlaiInstruction],
                         allocationSucceeded: bool,
                         useTflite: bool,
                         c2: uint32 = 0'u32,
                         includeExtra: bool = false,
                         descriptorHalt: bool = false,
                         midOutState: bool = false): BlaiCpuLayerEncodeResult =
  ## Convenience result-returning wrapper for the recovered encoder.
  blaiEncodeCpuLayerInto(
    layer, ctrl, stream, allocationSucceeded, useTflite, result,
    c2, includeExtra, descriptorHalt, midOutState)

proc blaiEncodeCpuLayerWithAllocatorInto*(layer: var BlaiCpuInstLayer64,
                                          ctrl: var BlaiPsramCtrl,
                                          stream: var openArray[BlaiInstruction],
                                          outResult: var BlaiCpuLayerAllocEncodeResult,
                                          useTflite: bool,
                                          c2: uint32 = 0'u32,
                                          includeExtra: bool = false,
                                          descriptorHalt: bool = false,
                                          midOutState: bool = false) =
  ## Recovered bounded `BLAI_encode` wrapper including `BLAI_MEM_alloc`.
  outResult = default(BlaiCpuLayerAllocEncodeResult)
  blaiPlanMemAllocInto(layer, outResult.allocation)
  if outResult.allocation.fits:
    blaiApplyMemAllocPlan(ctrl, outResult.allocation)
  blaiEncodeCpuLayerInto(
    layer, ctrl, stream, outResult.allocation.fits,
    useTflite, outResult.encode, c2, includeExtra, descriptorHalt, midOutState)
  outResult.encoded = outResult.encode.encoded

proc blaiEncodeCpuLayerWithAllocator*(layer: var BlaiCpuInstLayer64,
                                      ctrl: var BlaiPsramCtrl,
                                      stream: var openArray[BlaiInstruction],
                                      useTflite: bool,
                                      c2: uint32 = 0'u32,
                                      includeExtra: bool = false,
                                      descriptorHalt: bool = false,
                                      midOutState: bool = false): BlaiCpuLayerAllocEncodeResult =
  ## Convenience result-returning wrapper for the recovered allocator-backed
  ## `BLAI_encode` path.
  blaiEncodeCpuLayerWithAllocatorInto(
    layer, ctrl, stream, result,
    useTflite, c2, includeExtra, descriptorHalt, midOutState)

