proc blaiIsUpsample*(layer: BlaiCpuInstLayer64): bool =
  blaiIsUpsample(blaiLayerTypeFromSdk(layer.layerType))

proc blaiIsConv*(layer: BlaiCpuInstLayer64): bool =
  blaiIsConv(blaiLayerTypeFromSdk(layer.layerType))

proc blaiUsesWeights*(layer: BlaiCpuInstLayer64): bool =
  blaiUsesWeights(blaiLayerTypeFromSdk(layer.layerType))

proc blaiCpuLoadUsesWeights*(layer: BlaiCpuInstLayer64): bool =
  blaiCpuLoadUsesWeights(blaiLayerTypeFromSdk(layer.layerType))

proc blaiCpuLoadUsesBiases*(layer: BlaiCpuInstLayer64): bool =
  blaiCpuLoadUsesBiases(blaiLayerTypeFromSdk(layer.layerType))

proc blaiIsMultiInput*(layer: BlaiCpuInstLayer64): bool =
  blaiIsMultiInput(blaiLayerTypeFromSdk(layer.layerType))

proc blaiIsRoute*(layer: BlaiCpuInstLayer64): bool =
  blaiIsRoute(blaiLayerTypeFromSdk(layer.layerType))

proc blaiIsCombine*(layer: BlaiCpuInstLayer64): bool =
