proc blaiWeightBufferPlanInto*(layerType: BlaiLayerType,
                               dramWeightCount, dramBiasCount: uint32,
                               outResult: var BlaiWeightBufferPlan) =
  ## Recover SDK `forward_NPU` weight/bias temporary allocation sizing.
  outResult = default(BlaiWeightBufferPlan)
  outResult.usesWeights = blaiUsesWeights(layerType)
  if outResult.usesWeights:
    outResult.weightBytes = dramWeightCount
    outResult.alignedWeightBytes = blaiAlign4(outResult.weightBytes)
    if not blaiBiasWordCountBytes(dramBiasCount, outResult.biasBytes):
      outResult.biasBytes = high(uint32)
    outResult.biasOffset = outResult.alignedWeightBytes
    var totalFit: BlaiUint32AppendFitResult
    blaiUint32AppendFitInto(
      high(uint32), outResult.alignedWeightBytes, outResult.biasBytes, totalFit)
    outResult.totalBytes = totalFit.requiredCount

proc blaiWeightBufferPlan*(layerType: BlaiLayerType,
                           dramWeightCount, dramBiasCount: uint32): BlaiWeightBufferPlan =
  ## Convenience result-returning wrapper for forward_NPU weight/bias sizing.
  blaiWeightBufferPlanInto(layerType, dramWeightCount, dramBiasCount, result)

proc blaiWeightBufferPlanInto*(layer: BlaiDecodedLayer,
                               dramWeightCount, dramBiasCount: uint32,
                               outResult: var BlaiWeightBufferPlan) =
  blaiWeightBufferPlanInto(
    layer.layerType, dramWeightCount, dramBiasCount, outResult)

proc blaiWeightBufferPlan*(layer: BlaiDecodedLayer,
                           dramWeightCount, dramBiasCount: uint32): BlaiWeightBufferPlan =
  blaiWeightBufferPlanInto(layer, dramWeightCount, dramBiasCount, result)

proc blaiWeightBufferPlanInto*(layer: BlaiCpuInstLayer64,
                               outResult: var BlaiWeightBufferPlan) =
  blaiWeightBufferPlanInto(
    blaiLayerTypeFromSdk(layer.layerType),
    nonNegativeU32(layer.dramNWeight),
    nonNegativeU32(layer.dramNBias),
    outResult)

proc blaiWeightBufferPlan*(layer: BlaiCpuInstLayer64): BlaiWeightBufferPlan =
  blaiWeightBufferPlanInto(layer, result)

proc blaiWeightBufferFitsInto*(plan: BlaiWeightBufferPlan,
                               weightBufBytes, biasBufBytes: uint32,
                               outResult: var BlaiWeightBufferFitResult) =
  ## Check caller-provided split buffers against the recovered SDK sizes.
  outResult = default(BlaiWeightBufferFitResult)
  outResult.usesWeights = plan.usesWeights
  outResult.requiredWeightBytes = plan.alignedWeightBytes
  outResult.requiredBiasBytes = plan.biasBytes
  if not plan.usesWeights:
    outResult.weightFits = true
    outResult.biasFits = true
    outResult.fits = true
    return
  outResult.weightFits = weightBufBytes >= plan.alignedWeightBytes
  outResult.biasFits = biasBufBytes >= plan.biasBytes
  outResult.fits = outResult.weightFits and outResult.biasFits

proc blaiWeightBufferFits*(plan: BlaiWeightBufferPlan,
                           weightBufBytes, biasBufBytes: uint32): bool =
  ## Boolean wrapper for recovered split weight/bias buffer checks.
  var fit: BlaiWeightBufferFitResult
  blaiWeightBufferFitsInto(plan, weightBufBytes, biasBufBytes, fit)
  fit.fits

proc blaiRouteConvExtraInputCount*(inputNum: int32): uint32 =
  ## Count recovered ROUTE_CONV side inputs used to expand weight channels.
  if inputNum <= 1:
    return 0'u32
  min(nonNegativeU32(inputNum - 1), BlaiMaxRouteInputNumU32)

proc blaiNpuWeightEffectiveInputChannels*(layer: BlaiCpuInstLayer64): uint32 =
  ## SDK `Load_NPU_weights` temporarily expands ROUTE_CONV input channels.
  ##
  ## The blob starts from `c` and adds `cn[0 ..< input_num - 1]` before
  ## restoring `c` after weight loading.
  result = nonNegativeU32(layer.c)
  if blaiLayerTypeFromSdk(layer.layerType) == blaiRouteConv and layer.inputNum > 1:
    let extraCount = blaiRouteConvExtraInputCount(layer.inputNum)
    for i in 0 ..< blaiBoundedU32Count(extraCount, BlaiMaxInputNum - 1):
      result += nonNegativeU32(layer.cn[i])

proc blaiNpuWeightKernel*(layer: BlaiCpuInstLayer64): BlaiNpuWeightKernel =
  ## Recover the helper dispatch in SDK `Load_NPU_weights`.
  let size = nonNegativeU32(layer.size)
  let dilation = nonNegativeU32(layer.dilation)
  if size <= 3'u32:
    if dilation > 1'u32:
      if size == 3'u32:
        blaiNpuWeightKernel3x3Dilated
      else:
        blaiNpuWeightKernelUnsupported
    else:
      blaiNpuWeightKernel3x3
  elif size == 5'u32:
    if dilation <= 1'u32:
      blaiNpuWeightKernel5x5
    else:
      blaiNpuWeightKernelUnsupported
  elif size == 7'u32:
    if dilation <= 1'u32:
      blaiNpuWeightKernel7x7
    else:
      blaiNpuWeightKernelUnsupported
  else:
    blaiNpuWeightKernelUnsupported

proc blaiNpuTemporaryWeightBytes*(elements: uint32,
                                  outBytes: var uint32): bool =
  ## Project SDK temporary int32 grouped-weight elements into bytes exactly.
  blaiU64ExactU32Count(
    elements.uint64 * BlaiNpuTemporaryWeightElementBytes.uint64, outBytes)

proc blaiPlanNpuWeightLoadInto*(layer: BlaiCpuInstLayer64,
                                useTflite: bool,
                                outResult: var BlaiNpuWeightLoadPlan) =
  ## Plan SDK `Load_NPU_weights` decisions without touching model buffers.
  outResult = default(BlaiNpuWeightLoadPlan)
  outResult.active = blaiUsesWeights(layer)
  outResult.kernel = blaiNpuWeightKernel(layer)
  outResult.supportedKernel = outResult.kernel != blaiNpuWeightKernelUnsupported
  outResult.groups = nonNegativeU32(layer.groups)
  outResult.effectiveInputChannels = blaiNpuWeightEffectiveInputChannels(layer)
  outResult.outputChannels = nonNegativeU32(layer.outC)
  outResult.weightPadding = if useTflite: layer.tfInput2Offset else: 0'i32
  outResult.biasPack =
    if useTflite: BlaiNpuTfliteBiasPack else: BlaiNpuFixedBiasPack

  if outResult.groups > 1'u32:
    outResult.groupChannelLimit =
      min(outResult.effectiveInputChannels, outResult.outputChannels) div
        outResult.groups
    if outResult.groupChannelLimit <= BlaiNpuTemporaryGroupChannelLimit:
      outResult.usesTemporaryGroupBuffer = true
      outResult.temporaryWeightElements = nonNegativeU32(layer.dramNWeight)
      if not blaiNpuTemporaryWeightBytes(
          outResult.temporaryWeightElements,
          outResult.temporaryWeightBytes):
        outResult.temporaryWeightBytes = high(uint32)

proc blaiPlanNpuWeightLoad*(layer: BlaiCpuInstLayer64,
                            useTflite: bool): BlaiNpuWeightLoadPlan =
  ## Convenience result-returning wrapper for `Load_NPU_weights` planning.
  blaiPlanNpuWeightLoadInto(layer, useTflite, result)

proc blaiNpuWeightScheduleTileUnits(
    schedule: openArray[BlaiNpuWeightScheduleItem]): uint32 =
  ## Count PACK x PACK tiles emitted by a recovered sparse kernel schedule.
  var units: uint64
  for item in schedule:
    case item.kind
    of blaiNpuWeightSchedulePixel:
      inc units
    of blaiNpuWeightScheduleZero:
      units += item.countOrTap.uint64
    if units > high(uint32).uint64:
      return blaiU64SaturatedU32Count(units)
  blaiU64SaturatedU32Count(units)

proc blaiNpuWeightScheduleSummary*(
    schedule: openArray[BlaiNpuWeightScheduleItem],
    expectedPixelOps, expectedZeroTileUnits, expectedMaxPixelTap: uint32):
    BlaiNpuWeightScheduleSummary =
  ## Summarize one recovered sparse `CONV_WEI_DUMP_*` schedule.
  result.itemCount = blaiOpenArrayLenU32(schedule)
  for item in schedule:
    case item.kind
    of blaiNpuWeightSchedulePixel:
      inc result.pixelOps
      result.maxPixelTap = max(result.maxPixelTap, item.countOrTap)
    of blaiNpuWeightScheduleZero:
      result.zeroTileUnits += item.countOrTap
  result.totalTileUnits = result.pixelOps + result.zeroTileUnits
  result.valid =
    result.pixelOps == expectedPixelOps and
    result.zeroTileUnits == expectedZeroTileUnits and
    result.maxPixelTap == expectedMaxPixelTap and
    result.totalTileUnits == blaiNpuWeightScheduleTileUnits(schedule)

proc blaiNpuKernelTapCountInto*(kernelSize: uint32,
                                outCount: var uint32): bool =
  ## Project the recovered square-kernel tap count exactly into the uint32 ABI.
  blaiU64ExactU32Count(kernelSize.uint64 * kernelSize.uint64, outCount)

proc blaiNpuKernelTapCount*(kernelSize: uint32): uint32 =
  ## Saturating wrapper for recovered square-kernel tile counts.
  var count: uint32
  if blaiNpuKernelTapCountInto(kernelSize, count):
    count
  else:
    high(uint32)

proc blaiNpuPackTileBytes*(pack: uint32, outBytes: var uint32): bool =
  ## Project one recovered `PACK x PACK` NPU weight tile byte count exactly.
  blaiU64ExactU32Count(pack.uint64 * pack.uint64, outBytes)

proc blaiNpuPackedWeightGroupBytes*(
    inputTileCount, tileUnits, tileBytes: uint32): uint64 =
  ## Project one recovered PACK-expanded input/tap tile group without wrapping.
  blaiU64SaturatedMul(
    blaiU64SaturatedMul(inputTileCount.uint64, tileUnits.uint64),
    tileBytes.uint64)

proc blaiNpuWeightKernelTileUnits*(layer: BlaiCpuInstLayer64,
                                   plan: BlaiNpuWeightLoadPlan): uint32 =
  ## Count PACK x PACK tiles emitted per output/input channel tile.
  case plan.kernel
  of blaiNpuWeightKernel3x3:
    blaiNpuKernelTapCount(nonNegativeU32(layer.size))
  of blaiNpuWeightKernel3x3Dilated:
    blaiNpuWeightScheduleTileUnits(BlaiNpuWeight3x3DilatedSchedule)
  of blaiNpuWeightKernel5x5:
    blaiNpuWeightScheduleTileUnits(BlaiNpuWeight5x5Schedule)
  of blaiNpuWeightKernel7x7:
    blaiNpuWeightScheduleTileUnits(BlaiNpuWeight7x7Schedule)
  of blaiNpuWeightKernelUnsupported:
    0'u32

proc blaiNpuWeightChannelRange*(plan: BlaiNpuWeightLoadPlan,
                                outIn: uint32): tuple[cStart, cEnd: uint32]

proc blaiNpuWeightGroupPartition*(
    outputChannels, effectiveInputChannels, groups, outIn: uint32):
    BlaiNpuWeightGroupPartition =
  ## Resolve recovered grouped output/input channel partitioning.
  result.groups = if groups == 0'u32: 1'u32 else: groups
  result.outIn = outIn
  result.outputChannels = outputChannels
  result.effectiveInputChannels = effectiveInputChannels
  if result.groups <= 1'u32:
    return
  result.outputsPerGroup = outputChannels div result.groups
  result.inputsPerGroup = effectiveInputChannels div result.groups
  if result.outputsPerGroup == 0'u32 or result.inputsPerGroup == 0'u32:
    return
  result.groupIndex = outIn div result.outputsPerGroup
  result.cStart = result.groupIndex * result.inputsPerGroup
  result.cEnd =
    min(effectiveInputChannels, result.cStart + result.inputsPerGroup)
  result.valid = true

proc blaiPlanNpuWeightChannelRangeInto*(
    plan: BlaiNpuWeightLoadPlan,
    outIn: uint32,
    outResult: var BlaiNpuWeightChannelRangePlan) =
  ## Plan the grouped `c_start`/`c_end` calculation in `Load_NPU_weights`.
  outResult = default(BlaiNpuWeightChannelRangePlan)
  outResult.groups = if plan.groups == 0'u32: 1'u32 else: plan.groups
  outResult.grouped = outResult.groups > 1'u32
  outResult.outIn = outIn
  outResult.outputChannels = plan.outputChannels
  outResult.effectiveInputChannels = plan.effectiveInputChannels
  if not outResult.grouped:
    outResult.cStart = 0'u32
    outResult.cEnd = plan.effectiveInputChannels
    outResult.valid = true
    return
  let partition = blaiNpuWeightGroupPartition(
    plan.outputChannels, plan.effectiveInputChannels, outResult.groups, outIn)
  if not partition.valid:
    return
  outResult.outputsPerGroup = partition.outputsPerGroup
  outResult.inputsPerGroup = partition.inputsPerGroup
  outResult.groupIndex = partition.groupIndex
  outResult.cStart = partition.cStart
  outResult.cEnd = partition.cEnd
  outResult.valid = true

proc blaiPlanNpuWeightChannelRange*(
    plan: BlaiNpuWeightLoadPlan,
    outIn: uint32): BlaiNpuWeightChannelRangePlan =
  ## Convenience wrapper for grouped NPU weight channel-range planning.
  blaiPlanNpuWeightChannelRangeInto(plan, outIn, result)

proc blaiNpuWeightChannelRange*(plan: BlaiNpuWeightLoadPlan,
                                outIn: uint32): tuple[cStart, cEnd: uint32] =
  ## Compatibility tuple wrapper for the typed channel-range plan.
  let rangePlan = blaiPlanNpuWeightChannelRange(plan, outIn)
  (rangePlan.cStart, rangePlan.cEnd)

proc blaiPlanNpuPackedWeightSizeInto*(layer: BlaiCpuInstLayer64,
                                      useTflite: bool,
                                      outResult: var BlaiNpuPackedWeightSizePlan,
                                      pack: uint32 = BlaiNpuWeightPack) =
  ## Plan the PACK-expanded NPU weight byte stream without materializing it.
  outResult = default(BlaiNpuPackedWeightSizePlan)
  outResult.pack = pack
  if pack == 0'u32:
    return
  var loadPlan: BlaiNpuWeightLoadPlan
  blaiPlanNpuWeightLoadInto(layer, useTflite, loadPlan)
  outResult.active = loadPlan.active
  outResult.supportedKernel = loadPlan.supportedKernel
  if not outResult.active or not outResult.supportedKernel:
    return
  outResult.tileUnits = blaiNpuWeightKernelTileUnits(layer, loadPlan)
  let tileBytesFit = blaiNpuPackTileBytes(pack, outResult.tileBytes)
  if outResult.tileUnits == 0'u32 or not tileBytesFit:
    outResult.overflow = not tileBytesFit
    return

  var total: uint64
  var outIn = 0'u32
  while outIn < loadPlan.outputChannels:
    inc outResult.outputTileGroups
    let channelRange = blaiNpuWeightChannelRange(loadPlan, outIn)
    if channelRange.cEnd < channelRange.cStart:
      outResult.overflow = true
      outResult.totalBytes = blaiU64SaturatedU32Count(high(uint64))
      return
    let firstCin = blaiCeilDivU32(channelRange.cStart, pack) * pack
    if firstCin < channelRange.cEnd:
      let inputTileCount =
        ((channelRange.cEnd - 1'u32 - firstCin) div pack) + 1'u32
      outResult.inputTileGroups += inputTileCount
      total = blaiU64SaturatedAdd(
        total,
        blaiNpuPackedWeightGroupBytes(
          inputTileCount, outResult.tileUnits, outResult.tileBytes))
      if total > high(uint32).uint64:
        outResult.overflow = true
        outResult.totalBytes = blaiU64SaturatedU32Count(total)
        return
    if pack > high(uint32) - outIn:
      break
    outIn += pack
  outResult.totalBytes = blaiU64SaturatedU32Count(total)
  outResult.valid = true

proc blaiPlanNpuPackedWeightSize*(layer: BlaiCpuInstLayer64,
                                  useTflite: bool,
                                  pack: uint32 = BlaiNpuWeightPack):
    BlaiNpuPackedWeightSizePlan =
  ## Convenience wrapper for PACK-expanded NPU weight stream sizing.
  blaiPlanNpuPackedWeightSizeInto(layer, useTflite, result, pack)

proc blaiNpuPackedWeightBytes*(layer: BlaiCpuInstLayer64,
                               useTflite: bool,
                               pack: uint32 = BlaiNpuWeightPack): uint32 =
  ## Size the packed NPU byte stream emitted by `Load_NPU_weights`.
  ##
  ## CPU model streams keep their logical `dramNWeight` length. The NPU
  ## execution workspace must instead fit the PACK-expanded tile stream that the
  ## materializer writes, including padding tiles for partial channel packs.
  let plan = blaiPlanNpuPackedWeightSize(layer, useTflite, pack)
  if plan.valid or plan.overflow:
    plan.totalBytes
  else:
    0'u32

proc blaiNpuWeightByte*(value: int32): uint8 =
  ## SDK `CONV_WEI_DUMP_*` stores the low byte of an `int` weight/padding value
  ## into the fixed-point NPU weight stream.
  uint8(value and 0xFF'i32)

proc blaiNpuPackedWeightBiasEvidenceInto*(
    plan: BlaiNpuWeightLoadPlan,
    packedWeightBytes: uint32,
    materializedWeightBytes: uint32,
    materializedWeightCursor: uint32,
    tileUnits: uint32,
    weightBuf: openArray[uint8],
    expectedFirstWeight: uint8,
    expectedWeightPadding: int32,
    materializedBiasBytes: uint32,
    materializedBiasCursor: uint32,
    biasBuf: openArray[int32],
    expectedFirstBias: int32,
    outResult: var BlaiNpuPackedWeightBiasEvidence,
    expectedKernel: BlaiNpuWeightKernel = blaiNpuWeightKernel3x3,
    expectedInputChannels: uint32 = 1,
    expectedOutputChannels: uint32 = 1,
    expectedGroups: uint32 = 1,
    expectedBiasPack: uint32 = 1,
    expectedPackedWeightBytes: uint32 = 16) =
  ## Derive focused evidence for packed NPU weight and bias stream output.
  outResult = default(BlaiNpuPackedWeightBiasEvidence)
  outResult.planActive = plan.active
  outResult.supportedKernel = plan.supportedKernel
  outResult.kernelMatches = plan.kernel == expectedKernel
  outResult.effectiveInputChannelsMatch =
    plan.effectiveInputChannels == expectedInputChannels
  outResult.outputChannelsMatch = plan.outputChannels == expectedOutputChannels
  outResult.groupsMatch = plan.groups == expectedGroups
  outResult.weightPaddingMatches = plan.weightPadding == expectedWeightPadding
  outResult.biasPackMatches = plan.biasPack == expectedBiasPack
  outResult.noTemporaryGroupBuffer = not plan.usesTemporaryGroupBuffer
  outResult.packedWeightBytesMatch =
    packedWeightBytes == expectedPackedWeightBytes
  outResult.materializedWeightBytesMatch =
    materializedWeightBytes == packedWeightBytes
  outResult.weightCursorMatches = materializedWeightCursor == packedWeightBytes
  outResult.tileUnitsMatch = tileUnits == 1'u32
  outResult.firstWeightBytePresent = weightBuf.len >= 1
  if outResult.firstWeightBytePresent:
    outResult.firstWeightByteMatches = weightBuf[0] == expectedFirstWeight
  outResult.firstPaddingByteMatches =
    weightBuf.len >= 2 and weightBuf[1] == blaiNpuWeightByte(plan.weightPadding)
  outResult.lastPaddingByteMatches =
    weightBuf.len >= 16 and weightBuf[15] == blaiNpuWeightByte(plan.weightPadding)
  outResult.biasBytesMatch = materializedBiasBytes == BlaiNpuBiasElementBytes
  outResult.biasCursorMatches = materializedBiasCursor == 1'u32
  outResult.firstBiasPresent = biasBuf.len >= 1
  if outResult.firstBiasPresent:
    outResult.firstBiasMatches = biasBuf[0] == expectedFirstBias
  outResult.planValid =
    outResult.planActive and outResult.supportedKernel and
      outResult.kernelMatches and outResult.effectiveInputChannelsMatch and
      outResult.outputChannelsMatch and outResult.groupsMatch and
      outResult.weightPaddingMatches and outResult.biasPackMatches and
      outResult.noTemporaryGroupBuffer
  outResult.packedBytesValid =
    outResult.packedWeightBytesMatch and
      outResult.materializedWeightBytesMatch and
      outResult.weightCursorMatches
  outResult.tileValid =
    outResult.tileUnitsMatch and outResult.firstWeightBytePresent and
      outResult.firstWeightByteMatches and
      outResult.firstPaddingByteMatches and outResult.lastPaddingByteMatches
  outResult.biasValid =
    outResult.biasBytesMatch and outResult.biasCursorMatches and
      outResult.firstBiasPresent and outResult.firstBiasMatches
  outResult.valid =
    outResult.planValid and outResult.packedBytesValid and
      outResult.tileValid and outResult.biasValid

proc blaiNpuPackedWeightBiasEvidence*(
    plan: BlaiNpuWeightLoadPlan,
    packedWeightBytes: uint32,
    materializedWeightBytes: uint32,
    materializedWeightCursor: uint32,
    tileUnits: uint32,
    weightBuf: openArray[uint8],
    expectedFirstWeight: uint8,
    expectedWeightPadding: int32,
    materializedBiasBytes: uint32,
    materializedBiasCursor: uint32,
    biasBuf: openArray[int32],
    expectedFirstBias: int32,
    expectedKernel: BlaiNpuWeightKernel = blaiNpuWeightKernel3x3,
    expectedInputChannels: uint32 = 1,
    expectedOutputChannels: uint32 = 1,
    expectedGroups: uint32 = 1,
    expectedBiasPack: uint32 = 1,
    expectedPackedWeightBytes: uint32 = 16): BlaiNpuPackedWeightBiasEvidence =
  ## Convenience wrapper for packed NPU weight and bias stream evidence.
  blaiNpuPackedWeightBiasEvidenceInto(
    plan, packedWeightBytes, materializedWeightBytes, materializedWeightCursor,
    tileUnits, weightBuf, expectedFirstWeight, expectedWeightPadding,
    materializedBiasBytes, materializedBiasCursor, biasBuf, expectedFirstBias,
    result, expectedKernel, expectedInputChannels, expectedOutputChannels,
    expectedGroups, expectedBiasPack, expectedPackedWeightBytes)

proc blaiNpuWeightKernelDispatchEvidenceInto*(
    normal3x3Ok: bool,
    normal3x3Cursor: uint32,
    normal3x3FirstByte: uint8,
    normal3x3LastByte: uint8,
    dilated3x3Ok: bool,
    dilated3x3Cursor: uint32,
    dilated3x3FirstByte: uint8,
    dilated3x3FirstTapByte: uint8,
    kernel5x5Ok: bool,
    kernel5x5Cursor: uint32,
    kernel5x5FirstByte: uint8,
    kernel5x5LastByte: uint8,
    kernel7x7Ok: bool,
    kernel7x7Cursor: uint32,
    kernel7x7FirstByte: uint8,
    kernel7x7LastByte: uint8,
    unsupportedOk: bool,
    unsupportedCursor: uint32,
    zeroPackOk: bool,
    unalignedCursor: uint32,
    shortOk: bool,
    shortCursor: uint32,
    outResult: var BlaiNpuWeightKernelDispatchEvidence) =
  ## Derive focused evidence for recovered kernel-dispatch stream branches.
  outResult = default(BlaiNpuWeightKernelDispatchEvidence)
  outResult.normal3x3Dispatched =
    normal3x3Ok and normal3x3Cursor == 36'u32
  outResult.dilated3x3Dispatched =
    dilated3x3Ok and dilated3x3Cursor == 324'u32
  outResult.kernel5x5Dispatched =
    kernel5x5Ok and kernel5x5Cursor == 324'u32
  outResult.kernel7x7Dispatched =
    kernel7x7Ok and kernel7x7Cursor == 324'u32
  outResult.unsupportedRejected =
    not unsupportedOk and unsupportedCursor == 7'u32
  outResult.zeroPackRejected = not zeroPackOk
  outResult.unalignedNoCommit = unalignedCursor == 0'u32
  outResult.shortBufferRejected =
    not shortOk and shortCursor < kernel5x5Cursor
  outResult.firstBytesMatch =
    normal3x3FirstByte == 0'u8 and dilated3x3FirstTapByte == 4'u8 and
      kernel5x5FirstByte == 6'u8 and kernel7x7FirstByte == 16'u8
  outResult.trailingPaddingMatches =
    normal3x3LastByte == 53'u8 and dilated3x3FirstByte == 0xF9'u8 and
      kernel5x5LastByte == 0xF9'u8 and kernel7x7LastByte == 0xF9'u8
  outResult.cursorPlanMatches =
    outResult.normal3x3Dispatched and outResult.dilated3x3Dispatched and
      outResult.kernel5x5Dispatched and outResult.kernel7x7Dispatched
  outResult.valid =
    outResult.cursorPlanMatches and outResult.unsupportedRejected and
      outResult.zeroPackRejected and outResult.unalignedNoCommit and
      outResult.shortBufferRejected and outResult.firstBytesMatch and
      outResult.trailingPaddingMatches

proc blaiNpuWeightKernelDispatchEvidence*(
    normal3x3Ok: bool,
    normal3x3Cursor: uint32,
    normal3x3FirstByte: uint8,
    normal3x3LastByte: uint8,
    dilated3x3Ok: bool,
    dilated3x3Cursor: uint32,
    dilated3x3FirstByte: uint8,
    dilated3x3FirstTapByte: uint8,
    kernel5x5Ok: bool,
    kernel5x5Cursor: uint32,
    kernel5x5FirstByte: uint8,
    kernel5x5LastByte: uint8,
    kernel7x7Ok: bool,
    kernel7x7Cursor: uint32,
    kernel7x7FirstByte: uint8,
    kernel7x7LastByte: uint8,
    unsupportedOk: bool,
    unsupportedCursor: uint32,
    zeroPackOk: bool,
    unalignedCursor: uint32,
    shortOk: bool,
    shortCursor: uint32): BlaiNpuWeightKernelDispatchEvidence =
  ## Convenience wrapper for recovered kernel-dispatch evidence.
  blaiNpuWeightKernelDispatchEvidenceInto(
    normal3x3Ok, normal3x3Cursor, normal3x3FirstByte, normal3x3LastByte,
    dilated3x3Ok, dilated3x3Cursor, dilated3x3FirstByte,
    dilated3x3FirstTapByte, kernel5x5Ok, kernel5x5Cursor, kernel5x5FirstByte,
    kernel5x5LastByte, kernel7x7Ok, kernel7x7Cursor, kernel7x7FirstByte,
    kernel7x7LastByte, unsupportedOk, unsupportedCursor, zeroPackOk,
    unalignedCursor, shortOk, shortCursor, result)

proc blaiUint32AppendFitInto*(bufferLen, cursor, appendCount: uint32,
                              outResult: var BlaiUint32AppendFitResult) =
  ## Check a recovered uint32 cursor append against caller-owned storage.
  outResult = default(BlaiUint32AppendFitResult)
  outResult.cursor = cursor
  outResult.appendCount = appendCount
  outResult.cursorFits = cursor <= bufferLen
  if not outResult.cursorFits:
    return
  if appendCount > high(uint32) - cursor:
    outResult.requiredCount = high(uint32)
    return
  outResult.requiredCount = cursor + appendCount
  outResult.appendFits = bufferLen - cursor >= appendCount
  outResult.fits = outResult.appendFits

proc blaiUint32AppendFits*(bufferLen, cursor, appendCount: uint32): bool =
  ## Boolean wrapper for recovered uint32 cursor append checks.
  var fit: BlaiUint32AppendFitResult
  blaiUint32AppendFitInto(bufferLen, cursor, appendCount, fit)
  fit.fits

proc blaiUint32AddressEndExclusive*(address, bytes: uint32): uint64 =
  ## Project a 32-bit half-open bus range end without wrapping uint32.
  address.uint64 + bytes.uint64

proc blaiUint32AddressRangeEndFits*(address, bytes: uint32): bool =
  ## Check that `[address, address + bytes)` stays inside the 32-bit bus space.
  blaiUint32AddressEndExclusive(address, bytes) <= high(uint32).uint64 + 1'u64

proc blaiCanNpuAppendWeightBytesInto*(weightBufLen, cursor, bytes: uint32,
                                      outResult: var BlaiNpuAppendBytesFitResult) =
  ## Check one recovered NPU weight byte-stream append against caller storage.
  outResult = default(BlaiNpuAppendBytesFitResult)
  var fit: BlaiUint32AppendFitResult
  blaiUint32AppendFitInto(weightBufLen, cursor, bytes, fit)
  outResult.cursor = fit.cursor
  outResult.appendBytes = fit.appendCount
  outResult.requiredBytes = fit.requiredCount
  outResult.cursorFits = fit.cursorFits
  outResult.appendFits = fit.appendFits
  outResult.fits = fit.fits

proc blaiCanNpuAppendWeightBytes*(weightBufLen, cursor, bytes: uint32): bool =
  ## Boolean wrapper for recovered NPU weight byte-stream append checks.
  var fit: BlaiNpuAppendBytesFitResult
  blaiCanNpuAppendWeightBytesInto(weightBufLen, cursor, bytes, fit)
  fit.fits

proc blaiNpuAppendWeightByte(weightBuf: var openArray[uint8],
                             weightCursor: var uint32,
                             value: uint8): bool =
  ## Append one recovered `Load_NPU_weights` byte and advance the typed cursor.
  let cursor = blaiNpuWeightBufferCursor(weightCursor, weightBuf.len)
  if not cursor.valid:
    return false
  weightBuf[cursor.index] = value
  inc weightCursor
  true

proc blaiNpuAppendRepeatedWeightByte(weightBuf: var openArray[uint8],
                                     weightCursor: var uint32,
                                     value: uint8,
                                     count: uint32): bool =
  ## Append a bounded run of repeated recovered NPU weight bytes.
  var appendFit: BlaiNpuAppendBytesFitResult
  blaiCanNpuAppendWeightBytesInto(
    blaiOpenArrayLenU32(weightBuf), weightCursor, count, appendFit)
  if not appendFit.fits:
    return false
  for _ in 0 ..< count:
    if not blaiNpuAppendWeightByte(weightBuf, weightCursor, value):
      return false
  true

proc blaiNpuDumpZero*(num: uint32,
                      weightPadding: int32,
                      pack: uint32,
                      weightBuf: var openArray[uint8],
                      weightCursor: var uint32): bool =
  ## Pure Nim `CONV_DUMP_ZERO`: append `num * PACK * PACK` padding bytes.
  let bytes = num * pack * pack
  var appendFit: BlaiNpuAppendBytesFitResult
  blaiCanNpuAppendWeightBytesInto(
    blaiOpenArrayLenU32(weightBuf), weightCursor, bytes, appendFit)
  if not appendFit.fits:
    return false
  let padding = blaiNpuWeightByte(weightPadding)
  blaiNpuAppendRepeatedWeightByte(weightBuf, weightCursor, padding, bytes)

proc blaiRowMajorIndex*(row, column, columns: uint32): BlaiRowMajorIndex

proc blaiNpuWeightSourceProjection*(
    inputChannelsPerGroup, outChannel, inputOffset, weightTap,
    kernelTaps: uint32): BlaiNpuWeightSourceProjection =
  ## Project one recovered `Load_NPU_weights` logical source coordinate.
  result.outputChannel = outChannel
  result.inputOffset = inputOffset
  result.weightTap = weightTap
  result.inputChannelsPerGroup = inputChannelsPerGroup
  result.kernelTaps = kernelTaps
  if inputChannelsPerGroup == 0'u32 or kernelTaps == 0'u32 or
      inputOffset >= inputChannelsPerGroup or weightTap >= kernelTaps:
    return
  let channelIndex =
    blaiRowMajorIndex(outChannel, inputOffset, inputChannelsPerGroup)
  if not channelIndex.valid:
    return
  let sourceIndex = blaiRowMajorIndex(channelIndex.index, weightTap, kernelTaps)
  if not sourceIndex.valid:
    return
  result.channelIndex = channelIndex
  result.index = sourceIndex.index
  result.valid = true

proc blaiNpuWeightSourceProjection*(layer: BlaiCpuInstLayer64,
                                    outIn, inputChannel, weightTap, cStart,
                                    groups: uint32): BlaiNpuWeightSourceProjection =
  ## Resolve the source coordinate used by `CONV_WEI_DUMP_PIXEL`.
  let groupCount = if groups == 0'u32: 1'u32 else: groups
  let inputChannels = blaiNpuWeightEffectiveInputChannels(layer)
  if inputChannel < cStart:
    return
  let kernelSize = nonNegativeU32(layer.size)
  if kernelSize == 0'u32:
    return
  let kernelShape = blaiRowMajorIndex(kernelSize - 1'u32, kernelSize - 1'u32,
                                     kernelSize)
  if not kernelShape.valid or kernelShape.index == high(uint32):
    return
  blaiNpuWeightSourceProjection(
    inputChannels div groupCount, outIn, inputChannel - cStart, weightTap,
    kernelShape.index + 1'u32)

proc blaiNpuWeightSourceIndex*(layer: BlaiCpuInstLayer64,
                               outIn, inputChannel, weightTap, cStart,
                               groups: uint32): uint32 =
  ## Compatibility wrapper for the recovered logical source-weight index.
  blaiNpuWeightSourceProjection(
    layer, outIn, inputChannel, weightTap, cStart, groups).index

proc blaiNpuWeightPackAlignment*(
    outIn, cin, pack: uint32): BlaiNpuWeightPackAlignment =
  ## Resolve the recovered PACK-aligned output/input tile gate.
  result.outIn = outIn
  result.cin = cin
  result.pack = pack
  if pack == 0'u32:
    return
  result.outputAligned = outIn mod pack == 0'u32
  result.inputAligned = cin mod pack == 0'u32
  result.aligned = result.outputAligned and result.inputAligned
  result.valid = true

proc blaiNpuWeightPackEntryCursor*(
    outIn, cin, outOffset, inputOffset, outputChannels, cEnd, pack: uint32):
    BlaiNpuWeightPackEntryCursor =
  ## Resolve one recovered PACK tile entry without duplicating channel math.
  if outOffset >= pack or inputOffset >= pack:
    return
  if outIn > high(uint32) - outOffset or cin > high(uint32) - inputOffset:
    return
  result.outOffset = outOffset
  result.inputOffset = inputOffset
  result.outChannel = outIn + outOffset
  result.inputChannel = cin + inputOffset
  result.inOutputRange = result.outChannel < outputChannels
  result.inInputRange = result.inputChannel < cEnd
  result.valid = true

proc blaiNpuDumpWeightPixel*(layer: BlaiCpuInstLayer64,
                             outIn, cin, weightTap, cStart, cEnd: uint32,
                             weightPadding: int32,
                             groups, pack: uint32,
                             weightBuf: var openArray[uint8],
                             weightsIn: openArray[int32],
                             weightCursor: var uint32): bool =
  ## Pure Nim `CONV_WEI_DUMP_PIXEL`: append one `PACK x PACK` weight tile.
  var appendFit: BlaiNpuAppendBytesFitResult
  blaiCanNpuAppendWeightBytesInto(
    blaiOpenArrayLenU32(weightBuf), weightCursor, pack * pack, appendFit)
  if not appendFit.fits:
    return false
  let padding = blaiNpuWeightByte(weightPadding)
  let outChannels = nonNegativeU32(layer.outC)
  for outOffset in 0'u32 ..< pack:
    for inOffset in 0'u32 ..< pack:
      let entryCursor = blaiNpuWeightPackEntryCursor(
        outIn, cin, outOffset, inOffset, outChannels, cEnd, pack)
      if not entryCursor.valid:
        return false
      if not entryCursor.inOutputRange or not entryCursor.inInputRange:
        if not blaiNpuAppendWeightByte(weightBuf, weightCursor, padding):
          return false
      else:
        if entryCursor.inputChannel < cStart:
          return false
        let sourceProjection = blaiNpuWeightSourceProjection(
          layer, entryCursor.outChannel, entryCursor.inputChannel, weightTap,
          cStart, groups)
        if not sourceProjection.valid:
          return false
        let sourceCursor =
          blaiNpuWeightSourceCursor(sourceProjection.index, weightsIn.len)
        if not sourceCursor.valid:
          return false
        if not blaiNpuAppendWeightByte(
            weightBuf, weightCursor,
            blaiNpuWeightByte(weightsIn[sourceCursor.index])):
          return false
  true

proc blaiNpuDumpWeights3x3*(layer: BlaiCpuInstLayer64,
                            outIn, cin, cStart, cEnd: uint32,
                            weightPadding: int32,
                            groups, pack: uint32,
                            weightBuf: var openArray[uint8],
                            weightsIn: openArray[int32],
                            weightCursor: var uint32): bool =
  ## Pure Nim `CONV_WEI_DUMP_3x3`: emit aligned `PACK x PACK` tiles for
  ## each recovered kernel tap. The SDK uses this helper for kernels up to 3x3.
  let alignment = blaiNpuWeightPackAlignment(outIn, cin, pack)
  if not alignment.valid:
    return false
  let kernelSize = nonNegativeU32(layer.size)
  for weightTap in 0'u32 ..< kernelSize * kernelSize:
    if alignment.aligned:
      if not blaiNpuDumpWeightPixel(
          layer, outIn, cin, weightTap, cStart, cEnd, weightPadding,
          groups, pack, weightBuf, weightsIn, weightCursor):
        return false
  true

proc blaiNpuDumpWeights3x3Dilated*(layer: BlaiCpuInstLayer64,
                                   outIn, cin, cStart, cEnd: uint32,
                                   weightPadding: int32,
                                   groups, pack: uint32,
                                   weightBuf: var openArray[uint8],
                                   weightsIn: openArray[int32],
                                   weightCursor: var uint32): bool =
  ## Pure Nim `CONV_WEI_DUMP_3x3_DIL`: emit the recovered sparse 5x5 stream
  ## for a dilated 3x3 kernel.
  let alignment = blaiNpuWeightPackAlignment(outIn, cin, pack)
  if not alignment.valid:
    return false
  if not alignment.aligned:
    return true
  for item in BlaiNpuWeight3x3DilatedSchedule:
    case item.kind
    of blaiNpuWeightSchedulePixel:
      if not blaiNpuDumpWeightPixel(
          layer, outIn, cin, item.countOrTap, cStart, cEnd, weightPadding,
          groups, pack, weightBuf, weightsIn, weightCursor):
        return false
    of blaiNpuWeightScheduleZero:
      if not blaiNpuDumpZero(
          item.countOrTap, weightPadding, pack, weightBuf, weightCursor):
        return false
  true

proc blaiNpuDumpWeights5x5*(layer: BlaiCpuInstLayer64,
                            outIn, cin, cStart, cEnd: uint32,
                            weightPadding: int32,
                            groups, pack: uint32,
                            weightBuf: var openArray[uint8],
                            weightsIn: openArray[int32],
                            weightCursor: var uint32): bool =
  ## Pure Nim `CONV_WEI_DUMP_5x5`: emit the recovered sparse 5x5 stream.
  let alignment = blaiNpuWeightPackAlignment(outIn, cin, pack)
  if not alignment.valid:
    return false
  if not alignment.aligned:
    return true
  for item in BlaiNpuWeight5x5Schedule:
    case item.kind
    of blaiNpuWeightSchedulePixel:
      if not blaiNpuDumpWeightPixel(
          layer, outIn, cin, item.countOrTap, cStart, cEnd, weightPadding,
          groups, pack, weightBuf, weightsIn, weightCursor):
        return false
    of blaiNpuWeightScheduleZero:
      if not blaiNpuDumpZero(
          item.countOrTap, weightPadding, pack, weightBuf, weightCursor):
        return false
  true

proc blaiNpuDumpWeights7x7*(layer: BlaiCpuInstLayer64,
                            outIn, cin, cStart, cEnd: uint32,
                            weightPadding: int32,
                            groups, pack: uint32,
                            weightBuf: var openArray[uint8],
                            weightsIn: openArray[int32],
                            weightCursor: var uint32): bool =
  ## Pure Nim `CONV_WEI_DUMP_7x7`: emit the recovered sparse 7x7 stream.
  let alignment = blaiNpuWeightPackAlignment(outIn, cin, pack)
  if not alignment.valid:
    return false
  if not alignment.aligned:
    return true
  for item in BlaiNpuWeight7x7Schedule:
    case item.kind
    of blaiNpuWeightSchedulePixel:
      if not blaiNpuDumpWeightPixel(
          layer, outIn, cin, item.countOrTap, cStart, cEnd, weightPadding,
          groups, pack, weightBuf, weightsIn, weightCursor):
        return false
    of blaiNpuWeightScheduleZero:
      if not blaiNpuDumpZero(
          item.countOrTap, weightPadding, pack, weightBuf, weightCursor):
        return false
  true

proc blaiNpuDumpWeightKernel*(layer: BlaiCpuInstLayer64,
                              outIn, cin, cStart, cEnd: uint32,
                              plan: BlaiNpuWeightLoadPlan,
                              pack: uint32,
                              weightBuf: var openArray[uint8],
                              weightsIn: openArray[int32],
                              weightCursor: var uint32): bool =
  ## Dispatch the recovered SDK `Load_NPU_weights` size/dilation helper call.
  if not plan.active or not plan.supportedKernel or pack == 0'u32:
    return false
  case plan.kernel
  of blaiNpuWeightKernel3x3:
    blaiNpuDumpWeights3x3(
      layer, outIn, cin, cStart, cEnd, plan.weightPadding, plan.groups, pack,
      weightBuf, weightsIn, weightCursor)
  of blaiNpuWeightKernel3x3Dilated:
    blaiNpuDumpWeights3x3Dilated(
      layer, outIn, cin, cStart, cEnd, plan.weightPadding, plan.groups, pack,
      weightBuf, weightsIn, weightCursor)
  of blaiNpuWeightKernel5x5:
    blaiNpuDumpWeights5x5(
      layer, outIn, cin, cStart, cEnd, plan.weightPadding, plan.groups, pack,
      weightBuf, weightsIn, weightCursor)
  of blaiNpuWeightKernel7x7:
    blaiNpuDumpWeights7x7(
      layer, outIn, cin, cStart, cEnd, plan.weightPadding, plan.groups, pack,
      weightBuf, weightsIn, weightCursor)
  of blaiNpuWeightKernelUnsupported:
    false

proc blaiCanNpuAppendBiasWordsInto*(biasBufLen, cursor, words: uint32,
                                    outResult: var BlaiNpuAppendWordsFitResult) =
  ## Check one recovered NPU bias int32-stream append against caller storage.
  outResult = default(BlaiNpuAppendWordsFitResult)
  var fit: BlaiUint32AppendFitResult
  blaiUint32AppendFitInto(biasBufLen, cursor, words, fit)
  outResult.cursor = fit.cursor
  outResult.appendWords = fit.appendCount
  outResult.requiredWords = fit.requiredCount
  outResult.cursorFits = fit.cursorFits
  outResult.appendFits = fit.appendFits
  outResult.fits = fit.fits

proc blaiCanNpuAppendBiasWords*(biasBufLen, cursor, words: uint32): bool =
  ## Boolean wrapper for recovered NPU bias int32-stream append checks.
  var fit: BlaiNpuAppendWordsFitResult
  blaiCanNpuAppendBiasWordsInto(biasBufLen, cursor, words, fit)
  fit.fits

proc blaiNpuAppendBiasWord(biasBuf: var openArray[int32],
                           biasCursor: var uint32,
                           value: int32): bool =
  ## Append one recovered `Load_NPU_weights` bias word and advance the cursor.
  let cursor = blaiNpuBiasBufferCursor(biasCursor, biasBuf.len)
  if not cursor.valid:
    return false
  biasBuf[cursor.index] = value
  inc biasCursor
  true

proc blaiNpuBiasPackCursor*(outIn, biasPack: uint32): BlaiNpuBiasPackCursor =
  ## Resolve recovered bias-pack alignment for one output channel.
  result.outIn = outIn
  result.biasPack = biasPack
  if biasPack == 0'u32:
    return
  result.aligned = outIn mod biasPack == 0'u32
  result.valid = true

proc blaiNpuBiasPackEntryCursor*(
    outIn, biasOffset, outputChannels, biasPack: uint32):
    BlaiNpuBiasPackEntryCursor =
  ## Resolve one recovered bias-pack entry to its source output channel.
  if biasOffset >= biasPack or outIn > high(uint32) - biasOffset:
    return
  result.biasOffset = biasOffset
  result.outChannel = outIn + biasOffset
  result.inOutputRange = result.outChannel < outputChannels
  result.valid = true

proc blaiNpuDumpBiasPack*(outIn: uint32,
                          plan: BlaiNpuWeightLoadPlan,
                          biasBuf: var openArray[int32],
                          biasesIn: openArray[int32],
                          biasCursor: var uint32): bool =
  ## Emit the recovered `Load_NPU_weights` bias pack for one output channel.
  let biasPackCursor = blaiNpuBiasPackCursor(outIn, plan.biasPack)
  if not plan.active or not biasPackCursor.valid:
    return false
  if not biasPackCursor.aligned:
    return true
  var appendFit: BlaiNpuAppendWordsFitResult
  blaiCanNpuAppendBiasWordsInto(
    blaiOpenArrayLenU32(biasBuf), biasCursor, biasPackCursor.biasPack,
    appendFit)
  if not appendFit.fits:
    return false
  for biasOffset in 0'u32 ..< biasPackCursor.biasPack:
    let entryCursor = blaiNpuBiasPackEntryCursor(
      outIn, biasOffset, plan.outputChannels, biasPackCursor.biasPack)
    if not entryCursor.valid:
      return false
    if entryCursor.inOutputRange:
      let sourceCursor =
        blaiNpuBiasSourceCursor(entryCursor.outChannel, biasesIn.len)
      if not sourceCursor.valid:
        return false
      if not blaiNpuAppendBiasWord(
          biasBuf, biasCursor, biasesIn[sourceCursor.index]):
        return false
    else:
      if not blaiNpuAppendBiasWord(biasBuf, biasCursor, 0):
        return false
  true

proc blaiNpuTemporaryGroupCount*(plan: BlaiNpuWeightLoadPlan,
                                 pack: uint32): uint32 =
  ## Group count used by the SDK temporary grouped-weight reorder path.
  if pack == 0'u32:
    return 0
  min(plan.effectiveInputChannels, plan.outputChannels) div pack

proc blaiPlanNpuTemporaryGroupsInto*(
    layer: BlaiCpuInstLayer64,
    plan: BlaiNpuWeightLoadPlan,
    pack: uint32,
    outResult: var BlaiNpuTemporaryGroupPlan) =
  ## Plan the SDK temporary grouped-weight reorder dimensions.
  outResult = default(BlaiNpuTemporaryGroupPlan)
  outResult.active = plan.active and plan.usesTemporaryGroupBuffer
  outResult.pack = pack
  if not outResult.active or pack == 0'u32:
    return
  outResult.originalGroups = if plan.groups == 0'u32: 1'u32 else: plan.groups
  outResult.temporaryGroups = blaiNpuTemporaryGroupCount(plan, pack)
  if outResult.originalGroups <= 1'u32 or outResult.temporaryGroups == 0'u32:
    return
  outResult.originalInputsPerGroup =
    plan.effectiveInputChannels div outResult.originalGroups
  outResult.originalOutputsPerGroup =
    plan.outputChannels div outResult.originalGroups
  if outResult.originalInputsPerGroup == 0'u32 or
      outResult.originalOutputsPerGroup == 0'u32:
    return
  if not blaiNpuKernelTapCountInto(
      nonNegativeU32(layer.size), outResult.kernelTaps):
    return
  if outResult.kernelTaps == 0'u32:
    return
  outResult.valid = true

proc blaiPlanNpuTemporaryGroups*(
    layer: BlaiCpuInstLayer64,
    plan: BlaiNpuWeightLoadPlan,
    pack: uint32): BlaiNpuTemporaryGroupPlan =
  ## Convenience wrapper for temporary grouped-weight reorder planning.
  blaiPlanNpuTemporaryGroupsInto(layer, plan, pack, result)

proc blaiNpuTemporaryGroupSourceCursor*(
    outIn, cin, cStart: uint32,
    groupPlan: BlaiNpuTemporaryGroupPlan): BlaiNpuTemporaryGroupSourceCursor =
  ## Resolve original grouped source coordinates for the temporary reorder path.
  result.outIn = outIn
  result.cin = cin
  result.cStart = cStart
  if not groupPlan.valid or groupPlan.originalInputsPerGroup == 0'u32 or
      groupPlan.originalOutputsPerGroup == 0'u32 or cin < cStart:
    return
  result.inputOffset =
    (cin - cStart) mod groupPlan.originalInputsPerGroup
  result.outputGroup = outIn div groupPlan.originalOutputsPerGroup
  result.inputGroup = cin div groupPlan.originalInputsPerGroup
  result.sameOriginalGroup = result.inputGroup == result.outputGroup
  result.valid = true

proc blaiStoreTemporaryGroupedWeight(temporaryWeights: var openArray[int32],
                                     destIndex: uint32,
                                     value: int32): bool =
  ## Store one recovered grouped temporary weight with a checked destination.
  let destCursor = blaiNpuTemporaryWeightCursor(destIndex, temporaryWeights.len)
  if not destCursor.valid:
    return false
  temporaryWeights[destCursor.index] = value
  true

proc blaiNpuMaterializeTemporaryGroupedWeights*(
    layer: BlaiCpuInstLayer64,
    plan: BlaiNpuWeightLoadPlan,
    pack: uint32,
    weightsIn: openArray[int32],
    temporaryWeights: var openArray[int32]): bool =
  ## Materialize the SDK grouped temporary `int` weight buffer.
  ##
  ## The temporary buffer is arranged as if the grouped convolution had
  ## `min(c, out_c) / PACK` groups. Entries crossing the original group boundary
  ## are filled with `weightPadding`.
  let groupPlan = blaiPlanNpuTemporaryGroups(layer, plan, pack)
  if not groupPlan.valid:
    return false
  var temporaryPlan = plan
  temporaryPlan.groups = groupPlan.temporaryGroups
  temporaryPlan.usesTemporaryGroupBuffer = false
  for outIn in 0'u32 ..< plan.outputChannels:
    let channelRange = blaiNpuWeightChannelRange(temporaryPlan, outIn)
    for cin in channelRange.cStart ..< channelRange.cEnd:
      for weightTap in 0'u32 ..< groupPlan.kernelTaps:
        let destProjection = blaiNpuWeightSourceProjection(
          layer, outIn, cin, weightTap, channelRange.cStart,
          groupPlan.temporaryGroups)
        if not destProjection.valid:
          return false
        let groupSource = blaiNpuTemporaryGroupSourceCursor(
          outIn, cin, channelRange.cStart, groupPlan)
        if not groupSource.valid:
          return false
        if groupSource.sameOriginalGroup:
          let sourceProjection =
            blaiNpuWeightSourceProjection(
              groupPlan.originalInputsPerGroup, outIn,
              groupSource.inputOffset, weightTap, groupPlan.kernelTaps)
          if not sourceProjection.valid:
            return false
          let sourceCursor =
            blaiNpuWeightSourceCursor(sourceProjection.index, weightsIn.len)
          if not sourceCursor.valid:
            return false
          if not blaiStoreTemporaryGroupedWeight(
              temporaryWeights, destProjection.index, weightsIn[sourceCursor.index]):
            return false
        else:
          if not blaiStoreTemporaryGroupedWeight(
              temporaryWeights, destProjection.index, plan.weightPadding):
            return false
  true

proc blaiNpuDumpWeightStreamInto*(layer: BlaiCpuInstLayer64,
                                  plan: BlaiNpuWeightLoadPlan,
                                  pack: uint32,
                                  weightBuf: var openArray[uint8],
                                  weightsIn: openArray[int32],
                                  biasBuf: var openArray[int32],
                                  biasesIn: openArray[int32],
                                  outResult: var BlaiNpuWeightStreamResult,
                                  weightCursorStart: uint32 = 0,
                                  biasCursorStart: uint32 = 0) =
  ## Run the recovered `Load_NPU_weights` output/input-channel loops.
  ##
  ## Small grouped convolutions still require the SDK's temporary weight
  ## reorder buffer, so callers must handle that path before using this loop.
  outResult = default(BlaiNpuWeightStreamResult)
  outResult.weightCursor = weightCursorStart
  outResult.biasCursor = biasCursorStart
  if not plan.active or not plan.supportedKernel or
      plan.usesTemporaryGroupBuffer or pack == 0'u32:
    return
  for outIn in 0'u32 ..< plan.outputChannels:
    if not blaiNpuDumpBiasPack(
        outIn, plan, biasBuf, biasesIn, outResult.biasCursor):
      return
    let channelRange = blaiNpuWeightChannelRange(plan, outIn)
    if channelRange.cEnd < channelRange.cStart:
      return
    for cin in channelRange.cStart ..< channelRange.cEnd:
      if not blaiNpuDumpWeightKernel(
          layer, outIn, cin, channelRange.cStart, channelRange.cEnd, plan, pack,
          weightBuf, weightsIn, outResult.weightCursor):
        return
  outResult.materialized = true

proc blaiNpuDumpWeightStream*(layer: BlaiCpuInstLayer64,
                              plan: BlaiNpuWeightLoadPlan,
                              pack: uint32,
                              weightBuf: var openArray[uint8],
                              weightsIn: openArray[int32],
                              weightCursor: var uint32,
                              biasBuf: var openArray[int32],
                              biasesIn: openArray[int32],
                              biasCursor: var uint32): bool =
  ## Compatibility wrapper for the caller-owned stream result form.
  var stream: BlaiNpuWeightStreamResult
  blaiNpuDumpWeightStreamInto(
    layer, plan, pack, weightBuf, weightsIn, biasBuf, biasesIn, stream,
    weightCursorStart = weightCursor, biasCursorStart = biasCursor)
  weightCursor = stream.weightCursor
  biasCursor = stream.biasCursor
  stream.materialized

proc blaiNpuDumpWeightStreamWithTemporaryInto*(
    layer: BlaiCpuInstLayer64,
    plan: BlaiNpuWeightLoadPlan,
    pack: uint32,
    weightBuf: var openArray[uint8],
    weightsIn: openArray[int32],
    temporaryWeights: var openArray[int32],
    biasBuf: var openArray[int32],
    biasesIn: openArray[int32],
    outResult: var BlaiNpuWeightStreamResult,
    weightCursorStart: uint32 = 0,
    biasCursorStart: uint32 = 0) =
  ## Run `Load_NPU_weights` stream materialization, including grouped temp data.
  outResult = default(BlaiNpuWeightStreamResult)
  outResult.weightCursor = weightCursorStart
  outResult.biasCursor = biasCursorStart
  if not plan.usesTemporaryGroupBuffer:
    blaiNpuDumpWeightStreamInto(
      layer, plan, pack, weightBuf, weightsIn, biasBuf, biasesIn, outResult,
      weightCursorStart = outResult.weightCursor,
      biasCursorStart = outResult.biasCursor)
    return
  if not blaiNpuMaterializeTemporaryGroupedWeights(
      layer, plan, pack, weightsIn, temporaryWeights):
    return
  var streamPlan = plan
  streamPlan.groups = blaiNpuTemporaryGroupCount(plan, pack)
  streamPlan.usesTemporaryGroupBuffer = false
  streamPlan.temporaryWeightElements = 0
  streamPlan.temporaryWeightBytes = 0
  blaiNpuDumpWeightStreamInto(
    layer, streamPlan, pack, weightBuf, temporaryWeights, biasBuf, biasesIn,
    outResult, weightCursorStart = outResult.weightCursor,
    biasCursorStart = outResult.biasCursor)

proc blaiNpuDumpWeightStreamWithTemporary*(
    layer: BlaiCpuInstLayer64,
    plan: BlaiNpuWeightLoadPlan,
    pack: uint32,
    weightBuf: var openArray[uint8],
    weightsIn: openArray[int32],
    temporaryWeights: var openArray[int32],
    weightCursor: var uint32,
    biasBuf: var openArray[int32],
    biasesIn: openArray[int32],
    biasCursor: var uint32): bool =
  ## Compatibility wrapper for the caller-owned temporary stream result form.
  var stream: BlaiNpuWeightStreamResult
  blaiNpuDumpWeightStreamWithTemporaryInto(
    layer, plan, pack, weightBuf, weightsIn, temporaryWeights,
    biasBuf, biasesIn, stream,
    weightCursorStart = weightCursor, biasCursorStart = biasCursor)
  weightCursor = stream.weightCursor
  biasCursor = stream.biasCursor
  stream.materialized

proc blaiNpuWeightMaterializeReadinessInto*(
    materialization: BlaiNpuWeightMaterializeResult,
    outResult: var BlaiNpuWeightMaterializeReadiness) =
  ## Derive the first blocking gate for bounded `Load_NPU_weights`.
  outResult = default(BlaiNpuWeightMaterializeReadiness)
  outResult.active = materialization.active
  outResult.supported = materialization.supported
  outResult.bufferFits = materialization.bufferFits
  outResult.temporaryFits = materialization.temporaryFits
  outResult.weightsMaterialized = materialization.materialized
  if not outResult.active:
    outResult.firstBlock = blaiNpuWeightMaterializeInactive
  elif not outResult.supported:
    outResult.firstBlock = blaiNpuWeightMaterializeUnsupported
  elif not outResult.bufferFits:
    outResult.firstBlock = blaiNpuWeightMaterializeBuffer
  elif not outResult.temporaryFits:
    outResult.firstBlock = blaiNpuWeightMaterializeTemporary
  elif not outResult.weightsMaterialized:
    outResult.firstBlock = blaiNpuWeightMaterializeStream
  else:
    outResult.firstBlock = blaiNpuWeightMaterializeNoBlock
  outResult.materialized =
    outResult.active and outResult.supported and outResult.bufferFits and
    outResult.temporaryFits and outResult.weightsMaterialized

proc blaiNpuWeightMaterializeReadiness*(
    materialization: BlaiNpuWeightMaterializeResult):
    BlaiNpuWeightMaterializeReadiness =
  ## Convenience wrapper for bounded NPU weight materialization readiness.
  blaiNpuWeightMaterializeReadinessInto(materialization, result)

proc blaiNpuMaterializeWeightBuffersInto*(
    layer: BlaiCpuInstLayer64,
    useTflite: bool,
    weightBuf: var openArray[uint8],
    biasBuf: var openArray[int32],
    weightsIn: openArray[int32],
    biasesIn: openArray[int32],
    temporaryWeights: var openArray[int32],
    outResult: var BlaiNpuWeightMaterializeResult,
    pack: uint32 = BlaiNpuWeightPack) =
  ## Bounded pure-Nim `Load_NPU_weights` materialization.
  ##
  ## This mirrors the SDK path after `forward_NPU` has obtained caller-owned
  ## weight and bias buffers. It deliberately does not allocate or own memory.
  outResult = default(BlaiNpuWeightMaterializeResult)
  blaiWeightBufferPlanInto(layer, outResult.weightPlan)
  blaiPlanNpuWeightLoadInto(layer, useTflite, outResult.loadPlan)
  outResult.active = outResult.weightPlan.usesWeights and outResult.loadPlan.active
  outResult.supported = outResult.loadPlan.supportedKernel and pack != 0'u32
  var bufferFit: BlaiWeightBufferFitResult
  blaiWeightBufferFitsInto(
    outResult.weightPlan, blaiOpenArrayLenU32(weightBuf),
    blaiInt32BufferBytes(biasBuf),
    bufferFit)
  outResult.bufferFit = bufferFit
  outResult.bufferFits = bufferFit.fits
  outResult.requiredTemporaryElements =
    outResult.loadPlan.temporaryWeightElements
  outResult.providedTemporaryElements = blaiOpenArrayLenU32(temporaryWeights)
  outResult.temporaryFits = (not outResult.loadPlan.usesTemporaryGroupBuffer) or
    (blaiOpenArrayLenU32(temporaryWeights) >=
      outResult.loadPlan.temporaryWeightElements)
  if not outResult.active or not outResult.supported or
      not outResult.bufferFits or not outResult.temporaryFits:
    blaiNpuWeightMaterializeReadinessInto(outResult, outResult.readiness)
    outResult.firstBlock = outResult.readiness.firstBlock
    outResult.materialized = outResult.readiness.materialized
    return
  var stream: BlaiNpuWeightStreamResult
  blaiNpuDumpWeightStreamWithTemporaryInto(
    layer, outResult.loadPlan, pack,
    weightBuf = weightBuf, weightsIn = weightsIn,
    temporaryWeights = temporaryWeights,
    biasBuf = biasBuf, biasesIn = biasesIn,
    outResult = stream,
    weightCursorStart = outResult.weightCursor,
    biasCursorStart = outResult.biasCursor)
  outResult.materialized = stream.materialized
  outResult.weightCursor = stream.weightCursor
  outResult.biasCursor = stream.biasCursor
  blaiNpuWeightMaterializeReadinessInto(outResult, outResult.readiness)
  outResult.firstBlock = outResult.readiness.firstBlock
  outResult.materialized = outResult.readiness.materialized

proc blaiNpuMaterializeWeightBuffers*(
    layer: BlaiCpuInstLayer64,
    useTflite: bool,
    weightBuf: var openArray[uint8],
    biasBuf: var openArray[int32],
    weightsIn: openArray[int32],
    biasesIn: openArray[int32],
    temporaryWeights: var openArray[int32],
    pack: uint32 = BlaiNpuWeightPack): BlaiNpuWeightMaterializeResult =
  ## Convenience result-returning wrapper for NPU weight materialization.
  blaiNpuMaterializeWeightBuffersInto(
    layer, useTflite, weightBuf, biasBuf, weightsIn, biasesIn,
    temporaryWeights, result, pack)

proc blaiEffectiveGroups*(layer: BlaiCpuInstLayer64): uint32 =
  ## SDK CPU weight loader treats zero groups as one.
  let groups = nonNegativeU32(layer.groups)
  if groups == 0'u32: 1'u32 else: groups

proc blaiEffectiveKernelW*(layer: BlaiCpuInstLayer64): uint32 =
  ## SDK CPU weight loader uses detail size_x when present, otherwise size.
  let sizeX = nonNegativeU32(layer.sizeX)
  if sizeX > 0'u32: sizeX else: nonNegativeU32(layer.size)

proc blaiEffectiveKernelH*(layer: BlaiCpuInstLayer64): uint32 =
  ## SDK CPU weight loader uses detail size_y when present, otherwise size.
  let sizeY = nonNegativeU32(layer.sizeY)
  if sizeY > 0'u32: sizeY else: nonNegativeU32(layer.size)

proc blaiCpuWeightInputChannels*(layer: BlaiCpuInstLayer64): uint32 =
  ## SDK CPU weight loader adds cn[0] for multi-input weight layers.
  result = nonNegativeU32(layer.c)
  if layer.inputNum > 1:
    result += nonNegativeU32(blaiLayerCn(layer, 1'u32))

proc blaiCpuWeightElementCount*(layer: BlaiCpuInstLayer64): uint32 =
  ## Recovered `layer_weight_size` from SDK `blai_cpu_load_weights`.
  if not blaiCpuLoadUsesWeights(layer):
    return 0
  if blaiLayerTypeFromSdk(layer.layerType) == blaiSsd:
    return nonNegativeU32(layer.w) *
           nonNegativeU32(layer.h) *
           nonNegativeU32(layer.c)
  let groups = blaiEffectiveGroups(layer)
  if groups == 0'u32:
    return 0
  (blaiEffectiveKernelW(layer) *
    blaiEffectiveKernelH(layer) *
    nonNegativeU32(layer.outC) *
    blaiCpuWeightInputChannels(layer)) div groups

proc blaiCpuBiasElementCount*(layer: BlaiCpuInstLayer64): uint32 =
  ## Recovered `layer_biases_size` from SDK `blai_cpu_load_weights`.
  if blaiCpuLoadUsesBiases(layer):
    nonNegativeU32(layer.outC)
  else:
    0'u32

proc blaiCpuBiasBytesPerElement*(useTflite: bool): uint32 =
  ## SDK CPU bias stream reads 4 bytes per TFLite bias, otherwise 1 byte.
  if useTflite: 4'u32 else: 1'u32

proc blaiCpuBiasStreamBytes*(layer: BlaiCpuInstLayer64,
                             useTflite: bool): uint32 =
  blaiCpuBiasElementCount(layer) * blaiCpuBiasBytesPerElement(useTflite)

proc blaiCpuWeightStorage*(layer: BlaiCpuInstLayer64): BlaiCpuWeightStorage =
  if layer.dataType == 1:
    blaiCpuWeightI8
  else:
    blaiCpuWeightI32

proc blaiFindNextCpuWeightLayer*(layers: openArray[BlaiCpuInstLayer64],
                                 startIndex: Natural): int32 =
  ## SDK weight-stream cursor: next DSP layer that consumes weight bytes.
  for i in startIndex ..< layers.len:
    if layers[i].dspOn == 1 and blaiCpuLoadUsesWeights(layers[i]):
      return blaiLayerIndexValue(i)
  -1

proc blaiFindNextCpuWeightLayer*(
    layers: openArray[BlaiCpuParsedLayerState],
    startIndex: Natural): int32 =
  ## SDK weight-stream cursor over active parsed layer state.
  for i in startIndex ..< layers.len:
    if layers[i].active and layers[i].layer.dspOn == 1 and
        blaiCpuLoadUsesWeights(layers[i].layer):
      return blaiLayerIndexValue(i)
  -1

proc blaiFindNextCpuBiasLayer*(layers: openArray[BlaiCpuInstLayer64],
                               startIndex: Natural): int32 =
  ## SDK bias-stream cursor: next DSP layer that consumes bias entries.
  for i in startIndex ..< layers.len:
    if layers[i].dspOn == 1 and blaiCpuLoadUsesBiases(layers[i]):
      return blaiLayerIndexValue(i)
  -1

proc blaiFindNextCpuBiasLayer*(
    layers: openArray[BlaiCpuParsedLayerState],
    startIndex: Natural): int32 =
  ## SDK bias-stream cursor over active parsed layer state.
  for i in startIndex ..< layers.len:
    if layers[i].active and layers[i].layer.dspOn == 1 and
        blaiCpuLoadUsesBiases(layers[i].layer):
      return blaiLayerIndexValue(i)
  -1

proc blaiFillCpuWeightStreamPlan(layer: BlaiCpuInstLayer64,
                                 index: int32,
                                 outResult: var BlaiCpuWeightStreamPlan) =
  outResult.active = true
  outResult.layerIndex = index
  outResult.layerType = blaiLayerTypeFromSdk(layer.layerType)
  outResult.usesWeights = blaiCpuLoadUsesWeights(layer)
  outResult.groups = blaiEffectiveGroups(layer)
  outResult.kernelW = blaiEffectiveKernelW(layer)
  outResult.kernelH = blaiEffectiveKernelH(layer)
  outResult.inputChannels = blaiCpuWeightInputChannels(layer)
  outResult.outputChannels = nonNegativeU32(layer.outC)
  outResult.elementCount = blaiCpuWeightElementCount(layer)
  outResult.streamBytes = outResult.elementCount
  outResult.storage = blaiCpuWeightStorage(layer)

proc blaiFillCpuBiasStreamPlan(layer: BlaiCpuInstLayer64,
                               index: int32,
                               useTflite: bool,
                               outResult: var BlaiCpuBiasStreamPlan) =
  outResult.active = true
  outResult.layerIndex = index
  outResult.layerType = blaiLayerTypeFromSdk(layer.layerType)
  outResult.usesBiases = blaiCpuLoadUsesBiases(layer)
  outResult.outputChannels = nonNegativeU32(layer.outC)
  outResult.elementCount = blaiCpuBiasElementCount(layer)
  outResult.bytesPerElement = blaiCpuBiasBytesPerElement(useTflite)
  outResult.streamBytes = outResult.elementCount * outResult.bytesPerElement

proc blaiCpuWeightStreamPlanInto*(layers: openArray[BlaiCpuInstLayer64],
                                  startIndex: Natural,
                                  outResult: var BlaiCpuWeightStreamPlan) =
  outResult = default(BlaiCpuWeightStreamPlan)
  let index = blaiFindNextCpuWeightLayer(layers, startIndex)
  let layerCursor = blaiI32ArrayIndexCursor(index, layers.len)
  if not layerCursor.valid:
    return
  blaiFillCpuWeightStreamPlan(layers[layerCursor.index], index, outResult)

proc blaiCpuWeightStreamPlan*(layers: openArray[BlaiCpuInstLayer64],
                              startIndex: Natural): BlaiCpuWeightStreamPlan =
  ## Convenience result-returning wrapper for CPU weight-stream planning.
  blaiCpuWeightStreamPlanInto(layers, startIndex, result)

proc blaiCpuWeightStreamPlanInto*(
    layers: openArray[BlaiCpuParsedLayerState],
    startIndex: Natural,
    outResult: var BlaiCpuWeightStreamPlan) =
  outResult = default(BlaiCpuWeightStreamPlan)
  let index = blaiFindNextCpuWeightLayer(layers, startIndex)
  let layerCursor = blaiI32ArrayIndexCursor(index, layers.len)
  if not layerCursor.valid:
    return
  blaiFillCpuWeightStreamPlan(layers[layerCursor.index].layer, index, outResult)

proc blaiCpuWeightStreamPlan*(
    layers: openArray[BlaiCpuParsedLayerState],
    startIndex: Natural): BlaiCpuWeightStreamPlan =
  ## Convenience result-returning wrapper for parsed CPU weight-stream planning.
  blaiCpuWeightStreamPlanInto(layers, startIndex, result)

proc blaiCpuBiasStreamPlanInto*(layers: openArray[BlaiCpuInstLayer64],
                                startIndex: Natural,
                                useTflite: bool,
                                outResult: var BlaiCpuBiasStreamPlan) =
  outResult = default(BlaiCpuBiasStreamPlan)
  let index = blaiFindNextCpuBiasLayer(layers, startIndex)
  let layerCursor = blaiI32ArrayIndexCursor(index, layers.len)
  if not layerCursor.valid:
    return
  blaiFillCpuBiasStreamPlan(
    layers[layerCursor.index], index, useTflite, outResult)

proc blaiCpuBiasStreamPlan*(layers: openArray[BlaiCpuInstLayer64],
                            startIndex: Natural,
                            useTflite: bool): BlaiCpuBiasStreamPlan =
  ## Convenience result-returning wrapper for CPU bias-stream planning.
  blaiCpuBiasStreamPlanInto(layers, startIndex, useTflite, result)

proc blaiCpuBiasStreamPlanInto*(
    layers: openArray[BlaiCpuParsedLayerState],
    startIndex: Natural,
    useTflite: bool,
    outResult: var BlaiCpuBiasStreamPlan) =
  outResult = default(BlaiCpuBiasStreamPlan)
  let index = blaiFindNextCpuBiasLayer(layers, startIndex)
  let layerCursor = blaiI32ArrayIndexCursor(index, layers.len)
  if not layerCursor.valid:
    return
  blaiFillCpuBiasStreamPlan(
    layers[layerCursor.index].layer, index, useTflite, outResult)

proc blaiCpuBiasStreamPlan*(
    layers: openArray[BlaiCpuParsedLayerState],
    startIndex: Natural,
    useTflite: bool): BlaiCpuBiasStreamPlan =
  ## Convenience result-returning wrapper for parsed CPU bias-stream planning.
  blaiCpuBiasStreamPlanInto(layers, startIndex, useTflite, result)

proc blaiCpuStreamCursor*(layerIndex: int32 = 0,
                          byteOffset: uint32 = 0): BlaiCpuStreamCursor =
  BlaiCpuStreamCursor(layerIndex: layerIndex, byteOffset: byteOffset)

proc blaiCpuStreamStartCursor*(cursor: BlaiCpuStreamCursor):
    BlaiCpuStreamStartCursor =
  ## Resolve a recovered CPU stream byte cursor to a Nim openArray start index.
  result.byteOffset = cursor.byteOffset
  if not blaiU32ExactIntCount(cursor.byteOffset, result.startIndex):
    return
  result.valid = true

proc blaiCpuStreamCursorStepInto*(
    cursor: BlaiCpuStreamCursor,
    nextLayerIndex: int32,
    streamBytes, availableBytes: uint32,
    outResult: var BlaiCpuStreamCursorStep) =
  ## Advance one recovered CPU stream cursor without duplicating fit arithmetic.
  outResult = default(BlaiCpuStreamCursorStep)
  outResult.cursor = cursor
  outResult.nextCursor = cursor
  outResult.streamBytes = streamBytes
  outResult.availableBytes = availableBytes
  outResult.active = cursor.byteOffset <= availableBytes
  if not outResult.active:
    return
  outResult.fits = availableBytes - cursor.byteOffset >= streamBytes
  outResult.nextCursor.layerIndex = nextLayerIndex
  outResult.nextCursor.byteOffset = cursor.byteOffset + streamBytes

proc blaiCpuStreamCursorStep*(
    cursor: BlaiCpuStreamCursor,
    nextLayerIndex: int32,
    streamBytes, availableBytes: uint32): BlaiCpuStreamCursorStep =
  ## Convenience wrapper for CPU stream cursor advancement.
  blaiCpuStreamCursorStepInto(
    cursor, nextLayerIndex, streamBytes, availableBytes, result)

proc blaiCompareCpuStreamCursorInto*(expected, actual: BlaiCpuStreamCursor,
                                     outResult: var BlaiCpuStreamCursorCompareResult) =
  ## Compare recovered CPU stream cursors without losing layer/byte diagnostics.
  outResult = default(BlaiCpuStreamCursorCompareResult)
  outResult.expected = expected
  outResult.actual = actual
  outResult.layerIndexMatches = expected.layerIndex == actual.layerIndex
  outResult.byteOffsetMatches = expected.byteOffset == actual.byteOffset
  outResult.matched = outResult.layerIndexMatches and outResult.byteOffsetMatches

proc blaiCompareCpuStreamCursor*(expected, actual: BlaiCpuStreamCursor):
    BlaiCpuStreamCursorCompareResult =
  ## Convenience wrapper for CPU stream cursor comparison.
  blaiCompareCpuStreamCursorInto(expected, actual, result)

proc blaiCpuWeightStreamSegmentInto*(layers: openArray[BlaiCpuInstLayer64],
                                     cursor: BlaiCpuStreamCursor,
                                     availableBytes: uint32,
                                     outResult: var BlaiCpuWeightStreamSegment) =
  ## Recover one SDK weight-stream cursor step.
  outResult = default(BlaiCpuWeightStreamSegment)
  let startLayer = blaiCpuStreamStartLayerCursor(cursor, layers.len)
  outResult.cursor = cursor
  outResult.nextCursor = cursor
  if not startLayer.valid or cursor.byteOffset > availableBytes:
    return
  blaiCpuWeightStreamPlanInto(layers, startLayer.index, outResult.plan)
  outResult.active = outResult.plan.active
  if not outResult.active:
    return
  let step = blaiCpuStreamCursorStep(
    cursor, outResult.plan.layerIndex + 1, outResult.plan.streamBytes,
    availableBytes)
  outResult.fits = step.fits
  outResult.nextCursor = step.nextCursor

proc blaiCpuWeightStreamSegment*(layers: openArray[BlaiCpuInstLayer64],
                                 cursor: BlaiCpuStreamCursor,
                                 availableBytes: uint32): BlaiCpuWeightStreamSegment =
  ## Convenience result-returning wrapper for one weight-stream cursor step.
  blaiCpuWeightStreamSegmentInto(layers, cursor, availableBytes, result)

proc blaiCpuWeightStreamSegmentInto*(
    layers: openArray[BlaiCpuParsedLayerState],
    cursor: BlaiCpuStreamCursor,
    availableBytes: uint32,
    outResult: var BlaiCpuWeightStreamSegment) =
  ## Recover one SDK weight-stream cursor step over parsed layer state.
  outResult = default(BlaiCpuWeightStreamSegment)
  let startLayer = blaiCpuStreamStartLayerCursor(cursor, layers.len)
  outResult.cursor = cursor
  outResult.nextCursor = cursor
  if not startLayer.valid or cursor.byteOffset > availableBytes:
    return
  blaiCpuWeightStreamPlanInto(layers, startLayer.index, outResult.plan)
  outResult.active = outResult.plan.active
  if not outResult.active:
    return
  let step = blaiCpuStreamCursorStep(
    cursor, outResult.plan.layerIndex + 1, outResult.plan.streamBytes,
    availableBytes)
  outResult.fits = step.fits
  outResult.nextCursor = step.nextCursor

proc blaiCpuWeightStreamSegment*(
    layers: openArray[BlaiCpuParsedLayerState],
    cursor: BlaiCpuStreamCursor,
    availableBytes: uint32): BlaiCpuWeightStreamSegment =
  ## Convenience wrapper for a parsed weight-stream cursor step.
  blaiCpuWeightStreamSegmentInto(layers, cursor, availableBytes, result)

proc blaiCpuBiasStreamSegmentInto*(layers: openArray[BlaiCpuInstLayer64],
                                   cursor: BlaiCpuStreamCursor,
                                   availableBytes: uint32,
                                   useTflite: bool,
                                   outResult: var BlaiCpuBiasStreamSegment) =
