    layers, cursor, availableBytes, useTflite, result)

proc blaiCpuStreamEndCursorsInto*(layers: openArray[BlaiCpuInstLayer64],
                                  useTflite: bool,
                                  weightCursor: var BlaiCpuStreamCursor,
                                  biasCursor: var BlaiCpuStreamCursor) =
  ## Return the expected end cursors for complete CPU weight/bias streams.
  weightCursor = blaiCpuStreamCursor()
  biasCursor = blaiCpuStreamCursor()
  var weightSegment: BlaiCpuWeightStreamSegment
  while true:
    blaiCpuWeightStreamSegmentInto(
      layers, weightCursor, high(uint32), weightSegment)
    if not weightSegment.active:
      break
    weightCursor = weightSegment.nextCursor
  var biasSegment: BlaiCpuBiasStreamSegment
  while true:
    blaiCpuBiasStreamSegmentInto(
      layers, biasCursor, high(uint32), useTflite, biasSegment)
    if not biasSegment.active:
      break
    biasCursor = biasSegment.nextCursor

proc blaiCpuStreamEndCursorsInto*(
    layers: openArray[BlaiCpuParsedLayerState],
    useTflite: bool,
    weightCursor: var BlaiCpuStreamCursor,
    biasCursor: var BlaiCpuStreamCursor) =
  ## Return expected end cursors for parsed CPU weight/bias streams.
  weightCursor = blaiCpuStreamCursor()
  biasCursor = blaiCpuStreamCursor()
  var weightSegment: BlaiCpuWeightStreamSegment
  while true:
    blaiCpuWeightStreamSegmentInto(
      layers, weightCursor, high(uint32), weightSegment)
    if not weightSegment.active:
      break
    weightCursor = weightSegment.nextCursor
  var biasSegment: BlaiCpuBiasStreamSegment
  while true:
    blaiCpuBiasStreamSegmentInto(
      layers, biasCursor, high(uint32), useTflite, biasSegment)
    if not biasSegment.active:
      break
    biasCursor = biasSegment.nextCursor

proc blaiCpuStreamTotalsInto*(
    layers: openArray[BlaiCpuInstLayer64],
    useTflite: bool,
    outResult: var BlaiCpuStreamTotals) =
  ## Summarize complete SDK CPU weight/bias stream requirements.
  outResult = default(BlaiCpuStreamTotals)
  outResult.useTflite = useTflite
  outResult.firstWeightLayer = -1
  outResult.firstBiasLayer = -1
  var weightCursor = blaiCpuStreamCursor()
  var weightSegment: BlaiCpuWeightStreamSegment
  while true:
    blaiCpuWeightStreamSegmentInto(
      layers, weightCursor, high(uint32), weightSegment)
    if not weightSegment.active:
      break
    inc outResult.weightLayerCount
    if outResult.firstWeightLayer < 0:
      outResult.firstWeightLayer = weightSegment.plan.layerIndex
    outResult.cpuWeightStreamBytes += weightSegment.plan.streamBytes
    weightCursor.layerIndex = weightSegment.nextCursor.layerIndex
    weightCursor.byteOffset = 0

  var biasCursor = blaiCpuStreamCursor()
  var biasSegment: BlaiCpuBiasStreamSegment
  while true:
    blaiCpuBiasStreamSegmentInto(
      layers, biasCursor, high(uint32), useTflite, biasSegment)
    if not biasSegment.active:
      break
    inc outResult.biasLayerCount
    if outResult.firstBiasLayer < 0:
      outResult.firstBiasLayer = biasSegment.plan.layerIndex
    outResult.cpuBiasStreamBytes += biasSegment.plan.streamBytes
    biasCursor.layerIndex = biasSegment.nextCursor.layerIndex
    biasCursor.byteOffset = 0

proc blaiCpuStreamTotals*(
    layers: openArray[BlaiCpuInstLayer64],
    useTflite: bool): BlaiCpuStreamTotals =
  ## Convenience result-returning wrapper for CPU stream totals.
  blaiCpuStreamTotalsInto(layers, useTflite, result)

proc blaiCpuStreamTotalsInto*(
    layers: openArray[BlaiCpuParsedLayerState],
    useTflite: bool,
    outResult: var BlaiCpuStreamTotals) =
  ## Summarize complete CPU stream requirements from parsed layer state.
  outResult = default(BlaiCpuStreamTotals)
  outResult.useTflite = useTflite
  outResult.firstWeightLayer = -1
  outResult.firstBiasLayer = -1
  for layerIndex in 0 ..< layers.len:
    let layerState = layers[layerIndex]
    if not layerState.active or layerState.layer.dspOn != 1:
      continue
    if blaiCpuLoadUsesWeights(layerState.layer):
      inc outResult.weightLayerCount
      if outResult.firstWeightLayer < 0:
        outResult.firstWeightLayer = blaiLayerIndexValue(layerIndex)
      outResult.cpuWeightStreamBytes +=
        blaiCpuWeightElementCount(layerState.layer)
    if blaiCpuLoadUsesBiases(layerState.layer):
      inc outResult.biasLayerCount
      if outResult.firstBiasLayer < 0:
        outResult.firstBiasLayer = blaiLayerIndexValue(layerIndex)
      outResult.cpuBiasStreamBytes +=
        blaiCpuBiasStreamBytes(layerState.layer, useTflite)

proc blaiCpuStreamTotals*(
    layers: openArray[BlaiCpuParsedLayerState],
    useTflite: bool): BlaiCpuStreamTotals =
  ## Convenience result-returning wrapper for parsed CPU stream totals.
  blaiCpuStreamTotalsInto(layers, useTflite, result)

proc blaiCpuWeightStreamTotalBytes*(layers: openArray[BlaiCpuInstLayer64]): uint32 =
  ## Total SDK CPU weight stream bytes consumed by all DSP weight layers.
  blaiCpuStreamTotals(layers, useTflite = false).cpuWeightStreamBytes

proc blaiCpuWeightStreamTotalBytes*(
    layers: openArray[BlaiCpuParsedLayerState]): uint32 =
  ## Total SDK CPU weight stream bytes consumed by parsed layer state.
  blaiCpuStreamTotals(layers, useTflite = false).cpuWeightStreamBytes

proc blaiCpuBiasStreamTotalBytes*(layers: openArray[BlaiCpuInstLayer64],
                                  useTflite: bool): uint32 =
  ## Total SDK CPU bias stream bytes consumed by all DSP bias layers.
  blaiCpuStreamTotals(layers, useTflite).cpuBiasStreamBytes

proc blaiCpuBiasStreamTotalBytes*(
    layers: openArray[BlaiCpuParsedLayerState],
    useTflite: bool): uint32 =
  ## Total SDK CPU bias stream bytes consumed by parsed layer state.
  blaiCpuStreamTotals(layers, useTflite).cpuBiasStreamBytes

proc blaiReferenceParsedCeilDim(input, stride: uint32): uint32 =
  if input == 0'u32 or stride == 0'u32:
    0'u32
  else:
    ((input - 1'u32) div stride) + 1'u32

proc blaiReferenceParsedFoldedDim(windowCount: uint32): uint32 =
  (windowCount + 1'u32) div 2'u32

proc blaiU64SaturatedMul*(left, right: uint64): uint64 =
  ## Multiply recovered shape counts without wrapping uint64 diagnostics.
  if left != 0'u64 and right > high(uint64) div left:
    high(uint64)
  else:
    left * right

proc blaiU64SaturatedAdd*(left, right: uint64): uint64 =
  ## Add recovered shape counts without wrapping uint64 diagnostics.
  let sum = left + right
  if sum < left: high(uint64) else: sum

proc blaiReferenceHwcElementCount*(w, h, c: uint32): uint64 =
  ## Project one recovered HWC tensor shape into a saturated element count.
  blaiU64SaturatedMul(blaiU64SaturatedMul(w.uint64, h.uint64), c.uint64)

proc blaiReferenceHwcElementCount*(w, h: uint32, c: uint64): uint64 =
  ## Project one recovered HWC tensor with a widened channel count.
  blaiU64SaturatedMul(blaiU64SaturatedMul(w.uint64, h.uint64), c)

proc blaiReferenceParsedTensorElements(w, h, c: uint32,
                                       elements: var uint32): bool =
  if w == 0'u32 or h == 0'u32 or c == 0'u32:
    return false
  let count = blaiReferenceHwcElementCount(w, h, c)
  if count > high(uint32).uint64:
    return false
  elements = count.uint32
  true

proc blaiHwcIndex*(y, x, width, channel, channels: uint32): BlaiHwcIndex =
  ## Project one recovered HWC coordinate to a flat element index exactly.
  if width == 0'u32 or channels == 0'u32 or x >= width or channel >= channels:
    return
  let index =
    blaiU64SaturatedAdd(
      blaiU64SaturatedMul(
        blaiU64SaturatedAdd(
          blaiU64SaturatedMul(y.uint64, width.uint64), x.uint64),
        channels.uint64),
      channel.uint64)
  var index32: uint32
  if not blaiU64ExactU32Count(index, index32):
    return
  result.y = y
  result.x = x
  result.width = width
  result.channel = channel
  result.channels = channels
  result.index = index32
  result.valid = true

proc blaiHwcIndexWithBase*(base: uint32, hwc: BlaiHwcIndex,
                           outIndex: var uint32): bool =
  ## Add a recovered DATA-slot base offset to a checked HWC element index.
  if not hwc.valid:
    return false
  blaiU64ExactU32Count(base.uint64 + hwc.index.uint64, outIndex)

proc blaiHwcStrideIndex*(y, x, width, channel, strideC: uint32): BlaiHwcIndex =
  ## Project one HWC coordinate where each pixel row uses a channel stride.
  blaiHwcIndex(y, x, width, channel, strideC)

proc blaiRowMajorIndex*(row, column, columns: uint32): BlaiRowMajorIndex =
  ## Project one recovered row-major matrix coordinate to a flat index exactly.
  if columns == 0'u32 or column >= columns:
    return
  let index =
    blaiU64SaturatedAdd(
      blaiU64SaturatedMul(row.uint64, columns.uint64), column.uint64)
  var index32: uint32
  if not blaiU64ExactU32Count(index, index32):
    return
  result.row = row
  result.column = column
  result.columns = columns
  result.index = index32
  result.valid = true

proc blaiReferenceHwcStrideExtent*(w, h, channels, strideC: uint32): uint64 =
  ## Highest element touched by recovered HWC-with-channel-stride loops, plus one.
  let pixels = blaiU64SaturatedMul(w.uint64, h.uint64)
  if pixels == 0'u64:
    0'u64
  else:
    let lastPixelOffset =
      blaiU64SaturatedMul(pixels - 1'u64, strideC.uint64)
    let extent = lastPixelOffset + channels.uint64
    if extent < lastPixelOffset: high(uint64) else: extent

proc blaiReferenceRouteInputExtent*(
    offset, w, h, channels: uint32): uint64 =
  ## Highest element required by recovered route input sidecar windows, plus one.
  let dataExtent = blaiReferenceHwcElementCount(w, h, channels)
  blaiU64SaturatedAdd(offset.uint64, dataExtent)

proc blaiReferenceScaledDimExtent*(dim, stride: uint32): uint64 =
  ## Project the recovered upsample-expanded dimension without wrapping.
  blaiU64SaturatedMul(dim.uint64, stride.uint64)

proc blaiReferenceUpsampleOutputExtent*(
    inputW, inputH, writtenC, stride, outputW, outputC: uint32): uint64 =
  ## Highest output element written by recovered upsample loops, plus one.
  let scaledW = blaiReferenceScaledDimExtent(inputW, stride)
  let scaledH = blaiReferenceScaledDimExtent(inputH, stride)
  if scaledW == 0'u64 or scaledH == 0'u64:
    return 0'u64
  let rowStride = blaiU64SaturatedMul(outputW.uint64, outputC.uint64)
  let lastRowOffset = blaiU64SaturatedMul(scaledH - 1'u64, rowStride)
  let lastColOffset = blaiU64SaturatedMul(scaledW - 1'u64, outputC.uint64)
  blaiU64SaturatedAdd(
    blaiU64SaturatedAdd(lastRowOffset, lastColOffset), writtenC.uint64)

proc blaiReferenceTfliteRouteWSegmentExtent*(
    offset, axis, height, outputW, outputC, channels: uint32): uint64 =
  ## Highest element required by one recovered ROUTE_W input segment, plus one.
  let segmentExtent =
    case axis
    of 0'u32:
      blaiU64SaturatedMul(
        blaiU64SaturatedMul(height.uint64, channels.uint64), outputC.uint64)
    of 1'u32:
      blaiU64SaturatedMul(
        blaiU64SaturatedMul(channels.uint64, outputW.uint64), outputC.uint64)
    else:
      0'u64
  blaiU64SaturatedAdd(offset.uint64, segmentExtent)

proc blaiReferenceMatmulActivationElements*(height, channels: uint32): uint64 =
  ## Project recovered MATMUL activation/output rows by channel count.
  blaiU64SaturatedMul(height.uint64, channels.uint64)

proc blaiReferenceMatmulWeightElements*(inputC, outputC: uint32): uint64 =
  ## Project recovered MATMUL weight matrix elements.
  blaiU64SaturatedMul(inputC.uint64, outputC.uint64)

proc blaiReferenceDepthwiseOutputChannels*(
    inputC, channelMultiplier: uint32): uint64 =
  ## Project recovered depthwise output channels without wrapping.
  blaiU64SaturatedMul(inputC.uint64, channelMultiplier.uint64)

proc blaiReferencePaddedDim*(before, core, after: uint32): uint32 =
  ## Project one recovered PAD output dimension, returning zero on overflow.
  let padded = blaiU64SaturatedAdd(
    blaiU64SaturatedAdd(before.uint64, core.uint64), after.uint64)
  if padded > high(uint32).uint64: 0'u32 else: padded.uint32

proc blaiReferenceTransposeLkInputElements*(
    sequenceLength, channels: uint32): uint64 =
  ## Project recovered TRANSPOSELK input sequence/channel elements.
  blaiU64SaturatedMul(sequenceLength.uint64, channels.uint64)

proc blaiReferenceTransposeLkOutputChannels*(
    channels, alignedKernelSize: uint32): uint64 =
  ## Project recovered TRANSPOSELK output channels from channels/aligned-kernel.
  blaiU64SaturatedMul(channels.uint64, alignedKernelSize.uint64)

proc blaiReferenceTransposeLkOutputElements*(
    windowCount, channels, alignedKernelSize: uint32): uint64 =
  ## Project recovered TRANSPOSELK window/channel/aligned-kernel elements.
  blaiU64SaturatedMul(
    blaiU64SaturatedMul(windowCount.uint64, channels.uint64),
    alignedKernelSize.uint64)

proc blaiReferenceGroupedKernelElementCount*(
    outputC, inputPerGroup, kernelSize: uint32): uint64 =
  ## Project recovered grouped convolution weight elements without wrapping.
  let channelWeights =
    blaiU64SaturatedMul(outputC.uint64, inputPerGroup.uint64)
  blaiU64SaturatedMul(
    channelWeights, blaiNpuKernelTapCount(kernelSize).uint64)

proc blaiReferenceKernelElementCount*(
    outputC, inputC, kernelW, kernelH: uint32): uint64 =
  ## Project recovered non-grouped convolution kernel elements without wrapping.
  let channelWeights = blaiU64SaturatedMul(outputC.uint64, inputC.uint64)
  blaiU64SaturatedMul(
    channelWeights, blaiU64SaturatedMul(kernelW.uint64, kernelH.uint64))

proc blaiReferenceKernelElementCount*(
    outputC: uint64, kernelW, kernelH: uint32): uint64 =
  ## Project recovered depthwise kernel elements without wrapping.
  blaiU64SaturatedMul(
    outputC, blaiU64SaturatedMul(kernelW.uint64, kernelH.uint64))


proc blaiReferenceParsedTfliteStart(stride: uint32): uint32 =
  if stride == 2'u32: 1'u32 else: 0'u32

proc blaiReferenceParsedTfliteWindowCount(input, start, stride: uint32): uint32 =
  if stride == 0'u32 or input <= start:
    0'u32
  else:
    ((input - 1'u32 - start) div stride) + 1'u32

proc blaiReferenceFixedParsedActivationElements(
    layer: BlaiCpuInstLayer64,
    elements: var uint32): bool =
  ## Shape-only output element count for simple fixed parsed-model fixtures.
  let layerType = blaiLayerTypeFromSdk(layer.layerType)
  case layerType
  of blaiConvolutional:
    blaiReferenceParsedTensorElements(
      blaiReferenceParsedCeilDim(nonNegativeU32(layer.w),
                                 nonNegativeU32(layer.stride)),
      blaiReferenceParsedCeilDim(nonNegativeU32(layer.h),
                                 nonNegativeU32(layer.stride)),
      nonNegativeU32(layer.outC), elements)
  of blaiConvMax:
    let
      windowW = blaiReferenceParsedCeilDim(nonNegativeU32(layer.w),
                                           nonNegativeU32(layer.stride))
      windowH = blaiReferenceParsedCeilDim(nonNegativeU32(layer.h),
                                           nonNegativeU32(layer.stride))
      foldedW = blaiReferenceParsedFoldedDim(windowW)
      foldedH = blaiReferenceParsedFoldedDim(windowH)
      outputW = if layer.outW > 0: nonNegativeU32(layer.outW) else: foldedW
      outputH = if layer.outH > 0: nonNegativeU32(layer.outH) else: foldedH
    if outputW < foldedW or outputH < foldedH:
      return false
    blaiReferenceParsedTensorElements(outputW, outputH,
                                      nonNegativeU32(layer.outC), elements)
  of blaiMatmul:
    blaiReferenceParsedTensorElements(
      1'u32, nonNegativeU32(layer.h), nonNegativeU32(layer.outC), elements)
  of blaiMaxpool:
    blaiReferenceParsedTensorElements(
      blaiReferenceParsedCeilDim(nonNegativeU32(layer.w),
                                 nonNegativeU32(layer.stride)),
      blaiReferenceParsedCeilDim(nonNegativeU32(layer.h),
                                 nonNegativeU32(layer.stride)),
      nonNegativeU32(layer.c), elements)
  of blaiUpsample:
    blaiReferenceParsedTensorElements(
      nonNegativeU32(layer.outW), nonNegativeU32(layer.outH),
      nonNegativeU32(layer.outC), elements)
  of blaiShortcut:
    blaiReferenceParsedTensorElements(
      nonNegativeU32(layer.w), nonNegativeU32(layer.h),
      nonNegativeU32(layer.c), elements)
  else:
    false

proc blaiReferenceTfliteParsedActivationElements(
    layer: BlaiCpuInstLayer64,
    elements: var uint32): bool =
  ## Shape-only output element count for simple TFLite parsed-model fixtures.
  let layerType = blaiLayerTypeFromSdk(layer.layerType)
  case layerType
  of blaiConvolutional:
    let
      start = blaiReferenceParsedTfliteStart(nonNegativeU32(layer.stride))
      windowW = blaiReferenceParsedTfliteWindowCount(
        nonNegativeU32(layer.w), start, nonNegativeU32(layer.stride))
      windowH = blaiReferenceParsedTfliteWindowCount(
        nonNegativeU32(layer.h), start, nonNegativeU32(layer.stride))
      outputW = if layer.outW > 0: nonNegativeU32(layer.outW) else: windowW
      outputH = if layer.outH > 0: nonNegativeU32(layer.outH) else: windowH
    if outputW < windowW or outputH < windowH:
      return false
    blaiReferenceParsedTensorElements(outputW, outputH,
                                      nonNegativeU32(layer.outC), elements)
  of blaiConvMax:
    let
      start = blaiReferenceParsedTfliteStart(nonNegativeU32(layer.stride))
      windowW = blaiReferenceParsedTfliteWindowCount(
        nonNegativeU32(layer.w), start, nonNegativeU32(layer.stride))
      windowH = blaiReferenceParsedTfliteWindowCount(
        nonNegativeU32(layer.h), start, nonNegativeU32(layer.stride))
      foldedW = blaiReferenceParsedFoldedDim(windowW)
      foldedH = blaiReferenceParsedFoldedDim(windowH)
      outputW = if layer.outW > 0: nonNegativeU32(layer.outW) else: foldedW
      outputH = if layer.outH > 0: nonNegativeU32(layer.outH) else: foldedH
    if outputW < foldedW or outputH < foldedH:
      return false
    blaiReferenceParsedTensorElements(outputW, outputH,
                                      nonNegativeU32(layer.outC), elements)
  of blaiMaxpool:
    let
      start = blaiReferenceParsedTfliteStart(nonNegativeU32(layer.stride))
      windowW = blaiReferenceParsedTfliteWindowCount(
        nonNegativeU32(layer.w), start, nonNegativeU32(layer.stride))
      windowH = blaiReferenceParsedTfliteWindowCount(
        nonNegativeU32(layer.h), start, nonNegativeU32(layer.stride))
      outputW = if layer.outW > 0: nonNegativeU32(layer.outW) else: windowW
      outputH = if layer.outH > 0: nonNegativeU32(layer.outH) else: windowH
    if outputW < windowW or outputH < windowH:
      return false
    blaiReferenceParsedTensorElements(outputW, outputH,
                                      nonNegativeU32(layer.c), elements)
  of blaiAvgpool, blaiMean:
    blaiReferenceParsedTensorElements(1'u32, 1'u32,
                                      nonNegativeU32(layer.c), elements)
  of blaiShortcut, blaiSoftmax, blaiLogisticLayer:
    blaiReferenceParsedTensorElements(
      nonNegativeU32(layer.w), nonNegativeU32(layer.h),
      nonNegativeU32(layer.c), elements)
  of blaiPad, blaiPreTransconv:
    blaiReferenceParsedTensorElements(
      nonNegativeU32(layer.outW), nonNegativeU32(layer.outH),
      nonNegativeU32(layer.c), elements)
  of blaiReshape:
    let
      width = nonNegativeU32(layer.w)
      height = nonNegativeU32(layer.h)
      inputC = nonNegativeU32(layer.c)
      outputC = nonNegativeU32(layer.outC)
    if width == 0'u32 or height == 0'u32 or inputC == 0'u32 or
        outputC == 0'u32:
      return false
    let sampleCount = blaiReferenceHwcElementCount(width, height, inputC)
    if sampleCount == 0'u64 or sampleCount > high(uint32).uint64:
      return false
    elements = sampleCount.uint32
    true
  else:
    false

proc blaiReferenceFixedParsedBufferSupportInto*(
    plan: BlaiReferenceFixedParsedBufferPlan,
    outResult: var BlaiReferenceFixedParsedBufferSupport) =
  ## Derive fixed parsed-model oracle buffer support state.
  outResult = default(BlaiReferenceFixedParsedBufferSupport)
  outResult.layerCount = plan.layerCount
  outResult.activeLayerCount = plan.activeLayerCount
  outResult.unsupportedActivationShapeCount =
    plan.unsupportedActivationShapeCount
  outResult.unsupportedWeightStorageCount =
    plan.unsupportedWeightStorageCount
  outResult.firstUnsupportedActivationShapeLayer =
    plan.firstUnsupportedActivationShapeLayer
  outResult.firstUnsupportedWeightStorageLayer =
    plan.firstUnsupportedWeightStorageLayer
  outResult.activationShapesSupported =
    outResult.unsupportedActivationShapeCount == 0
  outResult.weightStorageSupported =
    outResult.unsupportedWeightStorageCount == 0
  outResult.supported = outResult.activationShapesSupported and
    outResult.weightStorageSupported

proc blaiReferenceFixedParsedBufferSupport*(
    plan: BlaiReferenceFixedParsedBufferPlan):
    BlaiReferenceFixedParsedBufferSupport =
  ## Convenience wrapper for fixed parsed-model buffer support.
  blaiReferenceFixedParsedBufferSupportInto(plan, result)

proc blaiReferenceFixedParsedBufferPlanInto*(
    layers: openArray[BlaiCpuParsedLayerState],
    outResult: var BlaiReferenceFixedParsedBufferPlan) =
  ## Report decoded-buffer sizes needed by the fixed parsed-model oracle.
  ##
  ## The parsed reference runner reuses one decoded weight buffer and one
  ## decoded bias buffer for each active layer. These counts are therefore
  ## per-layer maxima, not sums across the whole model.
  outResult = default(BlaiReferenceFixedParsedBufferPlan)
  outResult.layerCount = blaiOpenArrayLenU32(layers)
  blaiCpuStreamTotalsInto(layers, useTflite = false, outResult.cpuStreams)
  outResult.cpuWeightStreamBytes = outResult.cpuStreams.cpuWeightStreamBytes
  outResult.cpuBiasStreamBytes = outResult.cpuStreams.cpuBiasStreamBytes
  outResult.allWeightStorageSupported = true
  outResult.allActivationShapesSupported = true
  outResult.firstUnsupportedActivationShapeLayer = -1
  outResult.firstUnsupportedWeightStorageLayer = -1
  var firstActive = -1
  var lastActive = -1
  for i in 0 ..< layers.len:
    if layers[i].active:
      if firstActive < 0:
        firstActive = i
      lastActive = i
  if firstActive >= 0:
    var inputElements = 0'u32
    if blaiReferenceParsedTensorElements(
        nonNegativeU32(layers[firstActive].layer.w),
        nonNegativeU32(layers[firstActive].layer.h),
        nonNegativeU32(layers[firstActive].layer.c),
        inputElements):
      outResult.modelInputElements = inputElements
    else:
      outResult.allActivationShapesSupported = false
      inc outResult.unsupportedActivationShapeCount
      if outResult.firstUnsupportedActivationShapeLayer < 0:
        outResult.firstUnsupportedActivationShapeLayer =
          blaiLayerIndexValue(firstActive)
  for layerIndex in 0 ..< layers.len:
    let layerState = layers[layerIndex]
    if not layerState.active:
      continue
    inc outResult.activeLayerCount
    let layer = layerState.layer
    var activationElements = 0'u32
    if blaiReferenceFixedParsedActivationElements(layer, activationElements):
      if layerIndex == lastActive:
        outResult.outputElements = activationElements
      else:
        outResult.scratchElements =
          max(outResult.scratchElements, activationElements)
    else:
      outResult.allActivationShapesSupported = false
      inc outResult.unsupportedActivationShapeCount
      if outResult.firstUnsupportedActivationShapeLayer < 0:
        outResult.firstUnsupportedActivationShapeLayer =
          blaiLayerIndexValue(layerIndex)
    if layer.dspOn != 1:
      continue
    if blaiCpuLoadUsesWeights(layer):
      let elementCount = blaiCpuWeightElementCount(layer)
      if blaiCpuWeightStorage(layer) == blaiCpuWeightI8:
        outResult.decodedWeightElements =
          max(outResult.decodedWeightElements, elementCount)
      else:
        outResult.allWeightStorageSupported = false
        inc outResult.unsupportedWeightStorageCount
        if outResult.firstUnsupportedWeightStorageLayer < 0:
          outResult.firstUnsupportedWeightStorageLayer =
            blaiLayerIndexValue(layerIndex)
    if blaiCpuLoadUsesBiases(layer):
      outResult.decodedBiasElements =
        max(outResult.decodedBiasElements, blaiCpuBiasElementCount(layer))
  blaiReferenceFixedParsedBufferSupportInto(outResult, outResult.support)

proc blaiReferenceFixedParsedBufferPlan*(
    layers: openArray[BlaiCpuParsedLayerState]):
    BlaiReferenceFixedParsedBufferPlan =
  ## Convenience wrapper for fixed parsed-model oracle buffer planning.
  blaiReferenceFixedParsedBufferPlanInto(layers, result)

proc blaiReferenceTfliteParsedBufferSupportInto*(
    plan: BlaiReferenceTfliteParsedBufferPlan,
    outResult: var BlaiReferenceTfliteParsedBufferSupport) =
  ## Derive TFLite parsed-model oracle buffer support state.
  outResult = default(BlaiReferenceTfliteParsedBufferSupport)
  outResult.layerCount = plan.layerCount
  outResult.activeLayerCount = plan.activeLayerCount
  outResult.unsupportedActivationShapeCount =
    plan.unsupportedActivationShapeCount
  outResult.firstUnsupportedActivationShapeLayer =
    plan.firstUnsupportedActivationShapeLayer
  outResult.activationShapesSupported =
    outResult.unsupportedActivationShapeCount == 0
  outResult.supported = outResult.activationShapesSupported

proc blaiReferenceTfliteParsedBufferSupport*(
    plan: BlaiReferenceTfliteParsedBufferPlan):
    BlaiReferenceTfliteParsedBufferSupport =
  ## Convenience wrapper for TFLite parsed-model buffer support.
  blaiReferenceTfliteParsedBufferSupportInto(plan, result)

proc blaiReferenceTfliteParsedBufferPlanInto*(
    layers: openArray[BlaiCpuParsedLayerState],
    outResult: var BlaiReferenceTfliteParsedBufferPlan) =
  ## Report decoded-buffer sizes needed by the TFLite parsed-model oracle.
  ##
  ## TFLite reference layers consume bounded weight-stream byte slices directly.
  ## Only per-layer int32 CPU biases need a reusable decoded workspace.
  outResult = default(BlaiReferenceTfliteParsedBufferPlan)
  outResult.layerCount = blaiOpenArrayLenU32(layers)
  blaiCpuStreamTotalsInto(layers, useTflite = true, outResult.cpuStreams)
  outResult.cpuWeightStreamBytes = outResult.cpuStreams.cpuWeightStreamBytes
  outResult.cpuBiasStreamBytes = outResult.cpuStreams.cpuBiasStreamBytes
  outResult.allActivationShapesSupported = true
  outResult.firstUnsupportedActivationShapeLayer = -1
  var firstActive = -1
  var lastActive = -1
  for i in 0 ..< layers.len:
    if layers[i].active:
      if firstActive < 0:
        firstActive = i
      lastActive = i
  if firstActive >= 0:
    var inputElements = 0'u32
    if blaiReferenceParsedTensorElements(
        nonNegativeU32(layers[firstActive].layer.w),
        nonNegativeU32(layers[firstActive].layer.h),
        nonNegativeU32(layers[firstActive].layer.c),
        inputElements):
      outResult.modelInputElements = inputElements
    else:
      outResult.allActivationShapesSupported = false
      inc outResult.unsupportedActivationShapeCount
      if outResult.firstUnsupportedActivationShapeLayer < 0:
        outResult.firstUnsupportedActivationShapeLayer =
          blaiLayerIndexValue(firstActive)
  for layerIndex in 0 ..< layers.len:
    let layerState = layers[layerIndex]
    if not layerState.active:
      continue
    inc outResult.activeLayerCount
    let layer = layerState.layer
    var activationElements = 0'u32
    if blaiReferenceTfliteParsedActivationElements(layer, activationElements):
      if layerIndex == lastActive:
        outResult.outputElements = activationElements
      else:
        outResult.scratchElements =
          max(outResult.scratchElements, activationElements)
    else:
      outResult.allActivationShapesSupported = false
      inc outResult.unsupportedActivationShapeCount
      if outResult.firstUnsupportedActivationShapeLayer < 0:
        outResult.firstUnsupportedActivationShapeLayer =
          blaiLayerIndexValue(layerIndex)
    if layer.dspOn == 1 and blaiCpuLoadUsesBiases(layer):
      outResult.decodedBiasElements =
        max(outResult.decodedBiasElements, blaiCpuBiasElementCount(layer))
  blaiReferenceTfliteParsedBufferSupportInto(outResult, outResult.support)

proc blaiReferenceTfliteParsedBufferPlan*(
    layers: openArray[BlaiCpuParsedLayerState]):
    BlaiReferenceTfliteParsedBufferPlan =
  ## Convenience wrapper for TFLite parsed-model oracle buffer planning.
  blaiReferenceTfliteParsedBufferPlanInto(layers, result)

proc blaiReferenceFixedParsedBuffersFitInto*(
    plan: BlaiReferenceFixedParsedBufferPlan,
    cpuWeightBytes, cpuBiasBytes: uint32,
    decodedWeightElements, decodedBiasElements: uint32,
    scratchAElements, scratchBElements, outputElements: uint32,
    outResult: var BlaiReferenceFixedParsedBufferFitResult,
    modelInputElements: uint32 = high(uint32)) =
  ## Check caller-owned buffers against a fixed parsed-model oracle plan.
  outResult = default(BlaiReferenceFixedParsedBufferFitResult)
  outResult.activationShapesSupported = plan.support.activationShapesSupported
  outResult.weightStorageSupported = plan.support.weightStorageSupported
  outResult.modelInputFit = modelInputElements >= plan.modelInputElements
  outResult.requiredCpuStreams = plan.cpuStreams
  outResult.providedCpuStreams = BlaiCpuStreamTotals(
    useTflite: plan.cpuStreams.useTflite,
    weightLayerCount: plan.cpuStreams.weightLayerCount,
    biasLayerCount: plan.cpuStreams.biasLayerCount,
    firstWeightLayer: plan.cpuStreams.firstWeightLayer,
    firstBiasLayer: plan.cpuStreams.firstBiasLayer,
    cpuWeightStreamBytes: cpuWeightBytes,
    cpuBiasStreamBytes: cpuBiasBytes)
  outResult.cpuWeightsFit = cpuWeightBytes >= plan.cpuWeightStreamBytes
  outResult.cpuBiasesFit = cpuBiasBytes >= plan.cpuBiasStreamBytes
  outResult.decodedWeightsFit = decodedWeightElements >= plan.decodedWeightElements
  outResult.decodedBiasesFit = decodedBiasElements >= plan.decodedBiasElements
  outResult.scratchAFit = scratchAElements >= plan.scratchElements
  outResult.scratchBFit = scratchBElements >= plan.scratchElements
  outResult.outputFit = outputElements >= plan.outputElements
  outResult.fits =
    outResult.activationShapesSupported and outResult.weightStorageSupported and
    outResult.modelInputFit and outResult.cpuWeightsFit and
    outResult.cpuBiasesFit and outResult.decodedWeightsFit and
    outResult.decodedBiasesFit and outResult.scratchAFit and
    outResult.scratchBFit and outResult.outputFit

