proc blaiCpuByteSpanFitsInto*(
    startIndex: Natural,
    spanBytes: uint32,
    byteCount: uint64,
    outResult: var BlaiCpuByteSpanFit) =
  ## Check one recovered CPU-stream byte span against caller-owned bytes.
  outResult = default(BlaiCpuByteSpanFit)
  let start = startIndex.uint64
  outResult.startIndex = blaiU64SaturatedU32Count(start)
  outResult.spanBytes = spanBytes
  outResult.startFits = start <= byteCount
  if not outResult.startFits:
    return
  let required = start + spanBytes.uint64
  outResult.requiredBytes = blaiU64SaturatedU32Count(required)
  outResult.bytesFit = byteCount - start >= spanBytes.uint64
  outResult.fits = outResult.bytesFit

proc blaiCpuByteSpanFits*(
    startIndex: Natural,
    spanBytes: uint32,
    byteCount: uint64): bool =
  ## Boolean wrapper for recovered CPU-stream byte-span checks.
  var fit: BlaiCpuByteSpanFit
  blaiCpuByteSpanFitsInto(startIndex, spanBytes, byteCount, fit)
  fit.fits

proc blaiU32ExactIntCount*(count: uint32, outCount: var int): bool =
  ## Project a recovered uint32 count into Nim's index domain without clamping.
  if count.uint64 > high(int).uint64:
    return false
  outCount = count.int
  true

proc blaiCheckedIntByteWindow*(offset, bytes: uint32): BlaiCheckedByteWindow =
  ## Convert a checked uint32 byte range into int indexes for Nim openArray views.
  let rangeFit = blaiUint32AddressRangeFit(offset, bytes)
  if not rangeFit.fits or rangeFit.endExclusive > high(int).uint64:
    return
  if not blaiU32ExactIntCount(offset, result.start):
    return
  if not blaiU32ExactIntCount(bytes, result.count):
    return
  result.fits = true

proc blaiCheckedByteIndex*(byteIndex: int): BlaiCheckedByteIndex =
  ## Validate one byte index before it is used against a typed byte stream.
  if byteIndex < 0:
    return
  result.byteIndex = byteIndex
  result.valid = true

proc blaiFixedRowByteCursor*(rowIndex, byteIndex, rowBytes: int):
    BlaiFixedRowByteCursor =
  ## Resolve one byte inside a fixed-width recovered row layout.
  let byte = blaiCheckedByteIndex(byteIndex)
  if rowIndex < 0 or rowBytes <= 0 or not byte.valid or
      byte.byteIndex >= rowBytes:
    return
  if rowIndex > (high(int) - byte.byteIndex) div rowBytes:
    return
  result.rowIndex = rowIndex
  result.byteIndex = byte.byteIndex
  result.rowBytes = rowBytes
  result.absoluteIndex = rowIndex * rowBytes + byte.byteIndex
  result.valid = true

proc blaiCanReadCpuBiasInto*(bytes: openArray[uint8],
                             startIndex: Natural,
                             useTflite: bool,
                             outResult: var BlaiCpuByteReadFitResult) =
  ## Check a little-endian CPU bias read against caller-provided bytes.
  outResult = default(BlaiCpuByteReadFitResult)
  outResult.readBytes = blaiCpuBiasBytesPerElement(useTflite)
  var spanFit: BlaiCpuByteSpanFit
  blaiCpuByteSpanFitsInto(
    startIndex, outResult.readBytes, bytes.len.uint64, spanFit)
  outResult.startFits = spanFit.startFits
  outResult.bytesFit = spanFit.bytesFit
  outResult.startIndex = spanFit.startIndex
  outResult.requiredBytes = spanFit.requiredBytes
  outResult.fits = spanFit.fits

proc blaiCanReadCpuBias*(bytes: openArray[uint8],
                         startIndex: Natural,
                         useTflite: bool): bool =
  ## Boolean wrapper for CPU bias byte-read bounds checks.
  var fit: BlaiCpuByteReadFitResult
  blaiCanReadCpuBiasInto(bytes, startIndex, useTflite, fit)
  fit.fits

proc blaiCpuBiasReadWindow*(bytes: openArray[uint8],
                            startIndex: Natural,
                            useTflite: bool): BlaiCpuByteWindow =
  ## Checked view over the bytes consumed by one CPU bias stream value.
  blaiCanReadCpuBiasInto(bytes, startIndex, useTflite, result.fit)
  if not result.fit.fits or result.fit.readBytes == 0:
    return
  let window =
    blaiCheckedIntByteWindow(result.fit.startIndex, result.fit.readBytes)
  if not window.fits:
    return
  result.start = window.start
  result.count = window.count
  result.fits = true

template blaiCpuByteOpenArray(bytes: untyped,
                              window: BlaiCpuByteWindow): untyped =
  bytes.toOpenArray(window.start, window.start + window.count - 1)

proc blaiLe32ByteCursor*(byteIndex: int): BlaiLe32ByteCursor
proc blaiLe32Byte*(value: uint32, cursor: BlaiLe32ByteCursor): uint8
proc blaiLe32MergeByte*(value: var uint32,
                        byte: uint8,
                        cursor: BlaiLe32ByteCursor)

proc blaiReadCpuBiasWindow*(bytes: openArray[uint8],
                            window: BlaiCpuByteWindow): uint32 =
  ## SDK bias stream little-endian accumulation over a checked byte window.
  doAssert window.fits
  for k in 0 ..< window.count:
    let cursor = blaiLe32ByteCursor(k)
    doAssert cursor.valid
    blaiLe32MergeByte(result, blaiCpuByteOpenArray(bytes, window)[k], cursor)

proc blaiReadCpuBias*(bytes: openArray[uint8],
                      startIndex: Natural,
                      useTflite: bool): uint32 =
  ## SDK bias stream little-endian byte accumulation.
  blaiReadCpuBiasWindow(
    bytes, blaiCpuBiasReadWindow(bytes, startIndex, useTflite))

proc blaiCpuWeightValue*(byte: uint8): int32 =
  ## SDK CPU weight loader stores `fixed_point_t` bytes, sign-extended when the
  ## destination is an `int` array.
  if byte >= 0x80'u8:
    byte.int32 - 0x100'i32
  else:
    byte.int32

proc blaiCpuWeightI8Value*(byte: uint8): int8 =
  blaiCpuWeightValue(byte).int8

proc blaiCanStoreCpuWeightsInto*(plan: BlaiCpuWeightStreamPlan,
                                 bytes: openArray[uint8],
                                 startIndex: Natural,
                                 weightElements: uint32,
                                 outResult: var BlaiCpuStreamStoreFitResult) =
  ## Check one CPU weight stream copy against source bytes and destination items.
  outResult = default(BlaiCpuStreamStoreFitResult)
  outResult.active = plan.active
  outResult.streamBytes = plan.streamBytes
  outResult.requiredElements = plan.elementCount
  outResult.availableElements = weightElements
  outResult.startIndex = blaiU64SaturatedU32Count(startIndex.uint64)
  if not plan.active:
    outResult.startFits = true
    outResult.bytesFit = true
    outResult.elementsFit = true
    outResult.fits = true
    return
  var spanFit: BlaiCpuByteSpanFit
  blaiCpuByteSpanFitsInto(
    startIndex, plan.streamBytes, bytes.len.uint64, spanFit)
  outResult.startFits = spanFit.startFits
  outResult.bytesFit = spanFit.bytesFit
  outResult.startIndex = spanFit.startIndex
  outResult.requiredBytes = spanFit.requiredBytes
  outResult.elementsFit = weightElements >= plan.elementCount
  outResult.fits =
    outResult.startFits and outResult.bytesFit and outResult.elementsFit

proc blaiCanStoreCpuWeights*(plan: BlaiCpuWeightStreamPlan,
                             bytes: openArray[uint8],
                             startIndex: Natural,
                             weightElements: uint32): bool =
  ## Boolean wrapper for CPU weight stream store bounds checks.
  var fit: BlaiCpuStreamStoreFitResult
  blaiCanStoreCpuWeightsInto(plan, bytes, startIndex, weightElements, fit)
  fit.fits

proc blaiCpuStreamWindowFromFit(
    fit: BlaiCpuStreamStoreFitResult): BlaiCpuStreamWindow =
  ## Convert an existing CPU stream fit result into a concrete byte window.
  result.fit = fit
  result.active = fit.active
  if not fit.active:
    result.fits = fit.fits
    return
  if not fit.fits:
    return
  if fit.streamBytes == 0'u32 and fit.requiredElements != 0'u32:
    return
  let window = blaiCheckedIntByteWindow(fit.startIndex, fit.streamBytes)
  if not window.fits:
    return
  result.start = window.start
  result.count = window.count
  if not blaiU32ExactIntCount(fit.requiredElements, result.elements):
    return
  result.fits = true

proc blaiCpuWeightStreamWindow*(plan: BlaiCpuWeightStreamPlan,
                                bytes: openArray[uint8],
                                startIndex: Natural,
                                weightElements: uint32): BlaiCpuStreamWindow =
  ## Checked view over one CPU weight stream segment.
  var fit: BlaiCpuStreamStoreFitResult
  blaiCanStoreCpuWeightsInto(plan, bytes, startIndex, weightElements, fit)
  blaiCpuStreamWindowFromFit(fit)

template blaiCpuStreamOpenArray(bytes: untyped,
                                window: BlaiCpuStreamWindow): untyped =
  bytes.toOpenArray(window.start, window.start + window.count - 1)

proc blaiStoreCpuWeightsI8Into*(plan: BlaiCpuWeightStreamPlan,
                                bytes: openArray[uint8],
                                startIndex: Natural,
                                weights: var openArray[int8],
                                outResult: var BlaiCpuWeightStoreResult) =
  ## Store one SDK CPU weight stream segment into a fixed-point weight buffer.
  outResult = default(BlaiCpuWeightStoreResult)
  outResult.active = plan.active
  outResult.storageMatches = true
  if not plan.active:
    outResult.fits = true
    outResult.stored = true
    return
  if plan.storage != blaiCpuWeightI8:
    outResult.storageMatches = false
    return
  let window = blaiCpuWeightStreamWindow(
    plan, bytes, startIndex, blaiOpenArrayLenU32(weights))
  outResult.fits = window.fits
  if not outResult.fits:
    return
  for i in 0 ..< window.elements:
    weights[i] =
      blaiCpuWeightI8Value(blaiCpuStreamOpenArray(bytes, window)[i])
  outResult.stored = true

proc blaiStoreCpuWeightsI8*(plan: BlaiCpuWeightStreamPlan,
                            bytes: openArray[uint8],
                            startIndex: Natural,
                            weights: var openArray[int8]): bool =
  ## Compatibility wrapper for the caller-owned fixed-point weight store result.
  var store: BlaiCpuWeightStoreResult
  blaiStoreCpuWeightsI8Into(plan, bytes, startIndex, weights, store)
  store.stored

proc blaiStoreCpuWeightsI32Into*(plan: BlaiCpuWeightStreamPlan,
                                 bytes: openArray[uint8],
                                 startIndex: Natural,
                                 weights: var openArray[int32],
                                 outResult: var BlaiCpuWeightStoreResult) =
  ## Store one SDK CPU weight stream segment into an `int`-style weight buffer.
  outResult = default(BlaiCpuWeightStoreResult)
  outResult.active = plan.active
  outResult.storageMatches = true
  if not plan.active:
    outResult.fits = true
    outResult.stored = true
    return
  if plan.storage != blaiCpuWeightI32:
    outResult.storageMatches = false
    return
  let window = blaiCpuWeightStreamWindow(
    plan, bytes, startIndex, blaiOpenArrayLenU32(weights))
  outResult.fits = window.fits
  if not outResult.fits:
    return
  for i in 0 ..< window.elements:
    weights[i] =
      blaiCpuWeightValue(blaiCpuStreamOpenArray(bytes, window)[i])
  outResult.stored = true

proc blaiStoreCpuWeightsI32*(plan: BlaiCpuWeightStreamPlan,
                             bytes: openArray[uint8],
                             startIndex: Natural,
                             weights: var openArray[int32]): bool =
  ## Compatibility wrapper for the caller-owned int-style weight store result.
  var store: BlaiCpuWeightStoreResult
  blaiStoreCpuWeightsI32Into(plan, bytes, startIndex, weights, store)
  store.stored

proc blaiStoreCpuWeightValuesInto*(plan: BlaiCpuWeightStreamPlan,
                                   bytes: openArray[uint8],
                                   startIndex: Natural,
                                   weights: var openArray[int32],
                                   outResult: var BlaiCpuWeightStoreResult) =
  ## Store one CPU weight stream segment as sign-extended values for NPU reorder.
  ##
  ## The recovered NPU weight materializer consumes int-like source values and
  ## later emits only the low byte into the hardware weight stream. This helper
  ## accepts either CPU stream storage mode and keeps that boundary explicit.
  outResult = default(BlaiCpuWeightStoreResult)
  outResult.active = plan.active
  outResult.storageMatches = true
  if not plan.active:
    outResult.fits = true
    outResult.stored = true
    return
  let window = blaiCpuWeightStreamWindow(
    plan, bytes, startIndex, blaiOpenArrayLenU32(weights))
  outResult.fits = window.fits
  if not outResult.fits:
    return
  for i in 0 ..< window.elements:
    weights[i] =
      blaiCpuWeightValue(blaiCpuStreamOpenArray(bytes, window)[i])
  outResult.stored = true

proc blaiStoreCpuWeightValues*(plan: BlaiCpuWeightStreamPlan,
                               bytes: openArray[uint8],
                               startIndex: Natural,
                               weights: var openArray[int32]): bool =
  ## Compatibility wrapper for caller-owned CPU weight value store results.
  var store: BlaiCpuWeightStoreResult
  blaiStoreCpuWeightValuesInto(plan, bytes, startIndex, weights, store)
  store.stored

proc blaiCanStoreCpuBiasesInto*(plan: BlaiCpuBiasStreamPlan,
                                bytes: openArray[uint8],
                                startIndex: Natural,
                                biasElements: uint32,
                                outResult: var BlaiCpuStreamStoreFitResult) =
  ## Check one CPU bias stream copy against source bytes and destination items.
  outResult = default(BlaiCpuStreamStoreFitResult)
  outResult.active = plan.active
  outResult.streamBytes = plan.streamBytes
  outResult.requiredElements = plan.elementCount
  outResult.availableElements = biasElements
  outResult.startIndex = blaiU64SaturatedU32Count(startIndex.uint64)
  if not plan.active:
    outResult.startFits = true
    outResult.bytesFit = true
    outResult.elementsFit = true
    outResult.fits = true
    return
  var spanFit: BlaiCpuByteSpanFit
  blaiCpuByteSpanFitsInto(
    startIndex, plan.streamBytes, bytes.len.uint64, spanFit)
  outResult.startFits = spanFit.startFits
  outResult.bytesFit = spanFit.bytesFit
  outResult.startIndex = spanFit.startIndex
  outResult.requiredBytes = spanFit.requiredBytes
  outResult.elementsFit = biasElements >= plan.elementCount
  outResult.fits =
    outResult.startFits and outResult.bytesFit and outResult.elementsFit

proc blaiCanStoreCpuBiases*(plan: BlaiCpuBiasStreamPlan,
                            bytes: openArray[uint8],
                            startIndex: Natural,
                            biasElements: uint32): bool =
  ## Boolean wrapper for CPU bias stream store bounds checks.
  var fit: BlaiCpuStreamStoreFitResult
  blaiCanStoreCpuBiasesInto(plan, bytes, startIndex, biasElements, fit)
  fit.fits

proc blaiCpuBiasStreamWindow*(plan: BlaiCpuBiasStreamPlan,
                              bytes: openArray[uint8],
                              startIndex: Natural,
                              biasElements: uint32): BlaiCpuStreamWindow =
  ## Checked view over one CPU bias stream segment.
  var fit: BlaiCpuStreamStoreFitResult
  blaiCanStoreCpuBiasesInto(plan, bytes, startIndex, biasElements, fit)
  blaiCpuStreamWindowFromFit(fit)

proc blaiCpuBiasElementWidth*(plan: BlaiCpuBiasStreamPlan,
                              outWidth: var int): bool =
  ## Resolve one recovered CPU-bias element width for little-endian lane loops.
  var maxWidth: int
  if not blaiU32ExactIntCount(BlaiNpuBiasElementBytes, maxWidth):
    return false
  if not blaiU32ExactIntCount(plan.bytesPerElement, outWidth):
    return false
  outWidth > 0 and outWidth <= maxWidth

proc blaiStoreCpuBiasesInto*(plan: BlaiCpuBiasStreamPlan,
                             bytes: openArray[uint8],
                             startIndex: Natural,
                             biases: var openArray[int32],
                             outResult: var BlaiCpuBiasStoreResult) =
  ## Store one SDK CPU bias stream segment as little-endian accumulated `int`
  ## values. Fixed-point models still use unsigned one-byte bias entries.
  outResult = default(BlaiCpuBiasStoreResult)
  outResult.active = plan.active
  if not plan.active:
    outResult.fits = true
    outResult.stored = true
    return
  let window = blaiCpuBiasStreamWindow(
    plan, bytes, startIndex, blaiOpenArrayLenU32(biases))
  outResult.fits = window.fits
  if not outResult.fits:
    return
  var width: int
  if not blaiCpuBiasElementWidth(plan, width):
    return
  for i in 0 ..< window.elements:
    var value = 0'u32
    let base = i * width
    for k in 0 ..< width:
      let cursor = blaiLe32ByteCursor(k)
      doAssert cursor.valid
      blaiLe32MergeByte(
        value, blaiCpuStreamOpenArray(bytes, window)[base + k], cursor)
    let biasAbi = blaiCpuBiasBitsAbi(value)
    if not biasAbi.valid:
      return
    biases[i] = biasAbi.value
  outResult.stored = true

proc blaiStoreCpuBiases*(plan: BlaiCpuBiasStreamPlan,
                         bytes: openArray[uint8],
                         startIndex: Natural,
                         biases: var openArray[int32]): bool =
  ## Compatibility wrapper for caller-owned CPU bias store results.
  var store: BlaiCpuBiasStoreResult
  blaiStoreCpuBiasesInto(plan, bytes, startIndex, biases, store)
  store.stored

proc blaiSpatialElements*(w, h: uint32): uint32 =
  w * h

proc blaiMainInputChannels*(layer: BlaiCpuInstLayer64,
                            layerIndex: uint32): uint32 =
  ## SDK `Store_tensor_data_to_NPU` first-input channel count.
  result = nonNegativeU32(layer.c)
  if layerIndex == 0'u32 and result == 3'u32:
    result = 4

proc blaiMainInputRowPadded*(layer: BlaiCpuInstLayer64,
                             layerIndex: uint32): bool =
  let channels = nonNegativeU32(layer.c)
  let firstLayerPad = layerIndex == 0'u32 and
    (channels == 3'u32 or channels == 1'u32)
  not (channels mod 4'u32 == 0'u32 or firstLayerPad)

proc blaiNpuInputTransferPlanInto*(layer: BlaiCpuInstLayer64,
                                   layerIndex: uint32,
                                   inputIndex: range[0 .. 7],
                                   outResult: var BlaiTensorTransferPlan) =
  ## Recover SDK `Store_tensor_data_to_NPU` byte counts for one input tensor.
  outResult = default(BlaiTensorTransferPlan)
  let
    w = nonNegativeU32(layer.w)
    h = nonNegativeU32(layer.h)
    spatial = blaiSpatialElements(w, h)
  outResult.active = inputIndex == 0 or
    (inputIndex.uint32 < nonNegativeU32(layer.inputNum) and blaiIsMultiInput(layer))
  if not outResult.active:
    return
  outResult.slot = nonNegativeU32(layer.dramIn[inputIndex])
  if inputIndex == 0:
    outResult.actualChannels = nonNegativeU32(layer.c)
    outResult.paddedChannels = blaiMainInputChannels(layer, layerIndex)
    outResult.rowPadded = blaiMainInputRowPadded(layer, layerIndex)
    if outResult.rowPadded:
      outResult.paddedChannels = blaiChannelAlign4(outResult.actualChannels)
  else:
    outResult.actualChannels = nonNegativeU32(
      blaiLayerCn(layer, inputIndex.uint32))
    outResult.paddedChannels = if outResult.actualChannels mod 4'u32 == 0'u32:
      outResult.actualChannels
    else:
      blaiChannelAlign4(outResult.actualChannels)
    outResult.rowPadded = outResult.paddedChannels != outResult.actualChannels
  outResult.elements = spatial * outResult.paddedChannels
  outResult.bytes = outResult.elements

proc blaiNpuInputTransferPlan*(layer: BlaiCpuInstLayer64,
                               layerIndex: uint32,
                               inputIndex: range[0 .. 7]): BlaiTensorTransferPlan =
  ## Convenience result-returning wrapper for input tensor staging counts.
  blaiNpuInputTransferPlanInto(layer, layerIndex, inputIndex, result)

proc blaiRouteMidInputChannels*(layer: BlaiCpuInstLayer64): uint32 =
  ## SDK mid-output route input channel accumulation.
  result = nonNegativeU32(layer.c)
  if blaiLayerTypeFromSdk(layer.layerType) in {blaiRouteConv, blaiRouteMax,
      blaiRouteUpsample, blaiRoute}:
    let count = max(nonNegativeU32(layer.n), 1'u32) - 1'u32
    for i in 0 ..< blaiBoundedU32Count(count, BlaiMaxInputNum - 1):
      result += nonNegativeU32(layer.cn[i])

proc blaiNpuOutputTransferPlanInto*(layer: BlaiCpuInstLayer64,
                                    outResult: var BlaiNpuOutputTransferPlan) =
  ## Recover SDK `Load_NPU_data_to_tensor` byte counts.
  outResult = default(BlaiNpuOutputTransferPlan)
  let
    outC = nonNegativeU32(layer.outC)
    outputPaddedC = blaiChannelAlign4(outC)
    outputSpatial =
      if outputPaddedC == outC:
        blaiSpatialElements(nonNegativeU32(layer.outW), nonNegativeU32(layer.outH))
      else:
        blaiSpatialElements(nonNegativeU32(layer.w), nonNegativeU32(layer.h))
  outResult.output.active = true
  outResult.output.slot = nonNegativeU32(layer.dramOut[0])
  outResult.output.actualChannels = outC
  outResult.output.paddedChannels = outputPaddedC
  outResult.output.rowPadded = outputPaddedC != outC
  outResult.output.elements = outputSpatial * outputPaddedC
  outResult.output.bytes = outResult.output.elements

  if layer.midOut != 0:
    let layerType = blaiLayerTypeFromSdk(layer.layerType)
    let midChannels = if layerType == blaiConvMax:
      outC
    else:
      blaiRouteMidInputChannels(layer)
    outResult.midOutput.active = true
    outResult.midOutput.slot = nonNegativeU32(layer.dramMidOut)
    outResult.midOutput.actualChannels = midChannels
    outResult.midOutput.paddedChannels = midChannels
    outResult.midOutput.elements =
      blaiSpatialElements(nonNegativeU32(layer.w), nonNegativeU32(layer.h)) * midChannels
    outResult.midOutput.bytes = outResult.midOutput.elements

proc blaiNpuOutputTransferPlan*(layer: BlaiCpuInstLayer64): BlaiNpuOutputTransferPlan =
  ## Convenience result-returning wrapper for output tensor readback counts.
  blaiNpuOutputTransferPlanInto(layer, result)

proc blaiPatchSlotOffset*(slot, patchSize: uint32): BlaiPatchSlotOffset =
  ## Resolve a recovered PSRAM/DATA patch slot to a bounded byte offset.
  result.slot = slot
  result.patchSize = patchSize
  if patchSize != 0'u32 and slot > high(uint32) div patchSize:
    return
  result.offset = slot * patchSize
  result.valid = true

proc blaiPatchSlotOffset*(slot: int32,
                          patchSize: uint32): BlaiPatchSlotOffset =
  ## Resolve a signed SDK memory slot, rejecting negative pointer-side values.
  if slot < 0:
    return
  blaiPatchSlotOffset(slot.uint32, patchSize)

proc blaiTensorBufferOffset*(plan: BlaiTensorTransferPlan,
                             patchSize: uint32): uint32 =
  let offset = blaiPatchSlotOffset(plan.slot, patchSize)
  if offset.valid: offset.offset else: high(uint32)

proc blaiDataBufferRangeFitsInto*(
    active: bool,
    offset, bytes, bufferBytes: uint32,
    outResult: var BlaiDataBufferRangeFit) =
  ## Check a DATA-buffer-relative byte range and caller-owned capacity.
  outResult = default(BlaiDataBufferRangeFit)
  outResult.active = active
  outResult.offsetFits = true
  outResult.offset = offset
  outResult.bytes = bytes
  if not active:
    outResult.bufferFits = true
    outResult.fits = true
    return
  var rangeFit: BlaiUint32AppendFitResult
  blaiUint32AppendFitInto(high(uint32), offset, bytes, rangeFit)
  outResult.requiredBytes = rangeFit.requiredCount
  if not rangeFit.fits:
    outResult.offsetFits = false
    return
  var bufferFit: BlaiUint32AppendFitResult
  blaiUint32AppendFitInto(bufferBytes, offset, bytes, bufferFit)
  outResult.bufferFits = bufferFit.fits
  outResult.fits = outResult.offsetFits and outResult.bufferFits

proc blaiDataBufferRangeFits*(
    active: bool,
    offset, bytes, bufferBytes: uint32): bool =
  ## Boolean wrapper for DATA-buffer-relative range fit checks.
  var fit: BlaiDataBufferRangeFit
  blaiDataBufferRangeFitsInto(active, offset, bytes, bufferBytes, fit)
  fit.fits

proc blaiTensorBufferFitsInto*(plan: BlaiTensorTransferPlan,
                               patchSize: uint32,
                               bufferBytes: uint32,
                               outResult: var BlaiTensorBufferFitResult) =
  ## Check DATA-buffer slot arithmetic and caller-owned capacity.
  outResult = default(BlaiTensorBufferFitResult)
  outResult.active = plan.active
  outResult.offsetFits = true
  outResult.bytes = plan.bytes
  if not plan.active:
    outResult.bufferFits = true
    outResult.fits = true
    return
  let slotOffset = blaiPatchSlotOffset(plan.slot, patchSize)
  if not slotOffset.valid:
    outResult.offsetFits = false
    outResult.offset = high(uint32)
    outResult.requiredBytes = high(uint32)
    return
  var rangeFit: BlaiDataBufferRangeFit
  blaiDataBufferRangeFitsInto(
    plan.active, slotOffset.offset, plan.bytes, bufferBytes, rangeFit)
  outResult.offsetFits = rangeFit.offsetFits
  outResult.bufferFits = rangeFit.bufferFits
  outResult.offset = rangeFit.offset
  outResult.requiredBytes = rangeFit.requiredBytes
  outResult.fits = rangeFit.fits

proc blaiTensorBufferFits*(plan: BlaiTensorTransferPlan,
                           patchSize: uint32,
                           bufferBytes: uint32): bool =
  ## Boolean wrapper for DATA-buffer tensor bounds checks.
  var fit: BlaiTensorBufferFitResult
  blaiTensorBufferFitsInto(plan, patchSize, bufferBytes, fit)
  fit.fits

proc blaiBufferLenU32*(bufferLen: int): uint32 =
  ## Convert a Nim openArray length to the recovered uint32 capacity domain.
  if bufferLen <= 0:
    0'u32
  elif bufferLen.uint64 > high(uint32).uint64:
    high(uint32)
  else:
    bufferLen.uint32

proc blaiU64ExactU32Count*(count: uint64, outCount: var uint32): bool =
  ## Project a recovered uint64 element count into uint32 only when exact.
  if count > high(uint32).uint64:
    return false
  outCount = count.uint32
  true

proc blaiU64ExactI32Count*(count: uint64, outCount: var uint32): bool =
  ## Project a recovered uint64 count that will be consumed through int32 math.
  if count > high(int32).uint64:
    return false
  outCount = count.uint32
  true

proc blaiU64SaturatedU32Count*(count: uint64): uint32 =
  ## Project a recovered diagnostic count into a saturating uint32 SDK field.
  if count > high(uint32).uint64:
    high(uint32)
  else:
    count.uint32

proc blaiU64MaxExactU32Count*(count: uint64, outCount: var uint32): bool =
  ## Keep the largest recovered uint64 element count that fits the uint32 ABI.
  var projected: uint32
  if not blaiU64ExactU32Count(count, projected):
    return false
  outCount = max(outCount, projected)
  true

proc blaiOpenArrayLenU32*[T](items: openArray[T]): uint32 =
  ## Convert a Nim openArray element count to the recovered uint32 domain.
  blaiBufferLenU32(items.len)

proc blaiBoundedU32Count*(count: uint32, capacity: int): int =
  ## Bound a recovered uint32 count to a Nim container capacity before indexing.
  if capacity <= 0:
    return 0
  let bounded = min(count, blaiBufferLenU32(capacity))
  discard blaiU32ExactIntCount(bounded, result)

proc blaiU32ArrayIndexCursor*(index: uint32,
                              capacity: int): BlaiU32ArrayIndexCursor =
  ## Validate a recovered uint32 index before using it on a Nim container.
  if capacity <= 0:
    return
  if index >= blaiBufferLenU32(capacity):
    return
  if not blaiU32ExactIntCount(index, result.index):
    return
  result.valid = true

proc blaiU32CountCursor*(count: uint32,
                         capacity: int): BlaiU32CountCursor =
  ## Validate a recovered uint32 count before using it as a Nim loop bound.
  if capacity < 0:
    return
  if count > blaiBufferLenU32(capacity):
    return
  if not blaiU32ExactIntCount(count, result.count):
    return
  result.valid = true

proc blaiZeroBasedOpenArrayStop*(count: uint32,
                                 capacity: int,
                                 outStop: var int): bool =
  ## Resolve a non-empty recovered count to a zero-based openArray stop index.
  let cursor = blaiU32CountCursor(count, capacity)
  if not cursor.valid or cursor.count <= 0:
    return false
  outStop = cursor.count - 1
  true

proc blaiStartedOpenArrayStop*(startIndex: int,
                               count: uint32,
                               capacity: int,
                               outStop: var int): bool =
  ## Resolve a non-empty recovered span to a started openArray stop index.
  if startIndex < 0 or startIndex > capacity:
    return false
  let cursor = blaiU32CountCursor(count, capacity - startIndex)
  if not cursor.valid or cursor.count <= 0:
    return false
  if startIndex > high(int) - cursor.count + 1:
    return false
  outStop = startIndex + cursor.count - 1
  true

proc blaiI32ArrayIndexCursor*(index: int32,
                              capacity: int): BlaiU32ArrayIndexCursor =
  ## Validate a recovered signed cursor index, preserving negative sentinels.
  if index < 0:
    return
  blaiU32ArrayIndexCursor(index.uint32, capacity)

proc blaiRouteDescriptorStepCursor*(index: uint32): BlaiU32ArrayIndexCursor =
  ## Resolve one recovered route descriptor-loop step to the fixed step table.
  blaiU32ArrayIndexCursor(index, BlaiMaxInputNum - 1)

proc blaiSdkInt32Field*(value: uint32): BlaiSdkInt32Field =
  ## Project a decoded unsigned SDK scalar into signed int32 field storage.
  ##
  ## This is for semantic non-negative fields recovered as uint32. Raw
  ## bit-pattern fields must use the dedicated `blaiInt32FromBits` helpers.
  if value > high(int32).uint32:
    return
  result.value = value.int32
  result.valid = true

proc blaiRouteDescriptorChannelAbi*(channels: uint32): BlaiRouteDescriptorChannelAbi =
  ## Resolve a recovered route descriptor channel count before SDK `c` stores.
  let field = blaiSdkInt32Field(channels)
  result.value = field.value
  result.valid = field.valid

proc blaiRouteDescriptorChannelValue(channels: uint32): int32 =
  let field = blaiRouteDescriptorChannelAbi(channels)
  doAssert field.valid
  field.value

proc blaiWeightPatchCursor*(patchIndex: uint32): BlaiU32ArrayIndexCursor =
  ## Resolve one recovered BLAI_MEM_alloc patch slot to fixed patch arrays.
  blaiU32ArrayIndexCursor(patchIndex, BlaiMaxWeightPatches)

proc blaiRecoveredLayerCursor*(layerIndex: uint32,
                               capacity: int): BlaiU32ArrayIndexCursor =
  ## Resolve one recovered layer-table index before reading caller-owned layers.
  blaiU32ArrayIndexCursor(layerIndex, capacity)

proc blaiReferenceRouteInputCursor*(inputIndex: uint32): BlaiU32ArrayIndexCursor =
  ## Resolve one recovered route input to fixed route reference-plan arrays.
  blaiU32ArrayIndexCursor(inputIndex, BlaiMaxInputNum)

proc blaiForwardInputCursor*(inputIndex: uint32): BlaiU32ArrayIndexCursor =
  ## Resolve one recovered forward_NPU DATA input selector.
  blaiU32ArrayIndexCursor(inputIndex, BlaiMaxInputNum)

proc blaiInstructionStreamCursor*(instructionIndex: uint32,
                                  capacity: int): BlaiU32ArrayIndexCursor =
  ## Resolve one recovered BLAI instruction-stream record selector.
  blaiU32ArrayIndexCursor(instructionIndex, capacity)

proc blaiInstructionStreamCountCursor*(instructionCount: uint32,
                                       capacity: int): BlaiU32CountCursor =
  ## Resolve a recovered BLAI instruction-stream count before row iteration.
  blaiU32CountCursor(instructionCount, capacity)

proc blaiInstructionStreamStartCursor*(instructionIndex: uint32,
                                       capacity: int): BlaiU32ArrayIndexCursor =
  ## Resolve a recovered instruction-append start before writing a stream.
  blaiU32ArrayIndexCursor(instructionIndex, capacity)

proc blaiInstructionCountAbi*(count: uint32): BlaiInstructionCountAbi =
  ## Resolve a recovered instruction count before storing SDK `instCnt`.
  let field = blaiSdkInt32Field(count)
  result.value = field.value
  result.valid = field.valid

proc blaiAllocatorFieldAbi*(u32Value: uint32): BlaiAllocatorFieldAbi =
  ## Resolve a recovered allocator value before storing SDK int32 state.
  let field = blaiSdkInt32Field(u32Value)
  result.value = field.value
  result.valid = field.valid

proc blaiLayerIndexAbi*(index: uint32): BlaiLayerIndexAbi =
  ## Resolve a recovered layer-table index before storing SDK int32 state.
  let field = blaiSdkInt32Field(index)
  result.value = field.value
  result.valid = field.valid

proc blaiLayerIndexAbi*(index: int): BlaiLayerIndexAbi =
  ## Resolve a Nim layer-table index before storing SDK int32 state.
  if index < 0 or index > high(int32).int:
    return
  result.value = index.int32
  result.valid = true

proc blaiLayerIndexValue(index: uint32): int32 =
  let field = blaiLayerIndexAbi(index)
  doAssert field.valid
  field.value

proc blaiLayerIndexValue(index: int): int32 =
  let field = blaiLayerIndexAbi(index)
  doAssert field.valid
  field.value

proc blaiCpuRecordIndexAbi*(index: int): BlaiCpuRecordIndexAbi =
  ## Resolve a CPU/DSP record index before storing SDK int32 diagnostics.
  if index < 0 or index > high(int32).int:
    return
  result.value = index.int32
  result.valid = true

proc blaiCpuRecordIndexValue(index: int): int32 =
  let field = blaiCpuRecordIndexAbi(index)
  doAssert field.valid
  field.value

proc blaiOutputMismatchIndexAbi*(index: int): BlaiOutputMismatchIndexAbi =
  ## Resolve an output-compare element index before storing int32 diagnostics.
  if index < 0 or index > high(int32).int:
    return
  result.value = index.int32
  result.valid = true

proc blaiOutputMismatchIndexValue(index: int): int32 =
  let field = blaiOutputMismatchIndexAbi(index)
  doAssert field.valid
  field.value

proc blaiOutputShapeDimAbi*(dim: uint32): BlaiOutputShapeDimAbi =
  ## Resolve an output-shape dimension before storing SDK int32 shape fields.
  let field = blaiSdkInt32Field(dim)
  result.value = field.value
  result.valid = field.valid

proc blaiKernelSizeAbi*(kernelSize: uint32): BlaiKernelSizeAbi =
  ## Resolve a recovered kernel size before storing SDK int32 layer fields.
  let field = blaiSdkInt32Field(kernelSize)
  result.value = field.value
  result.valid = field.valid

proc blaiCpuExtraLayerFieldAbi*(field: uint32): BlaiCpuExtraLayerFieldAbi =
  ## Resolve decoded EXTRA_LAYER* scalar fields before SDK int32 writes.
  let sdkField = blaiSdkInt32Field(field)
  result.value = sdkField.value
  result.valid = sdkField.valid

proc blaiCpuYoloInfoFieldAbi*(field: uint32): BlaiCpuYoloInfoFieldAbi =
  ## Resolve decoded YOLO_INFO scalar fields before SDK int32 writes.
  let sdkField = blaiSdkInt32Field(field)
  result.value = sdkField.value
  result.valid = sdkField.valid

proc blaiCpuSsdInfoFieldAbi*(field: uint32): BlaiCpuSsdInfoFieldAbi =
  ## Resolve decoded SSD_INFO scalar fields before SDK int32 writes.
  let sdkField = blaiSdkInt32Field(field)
  result.value = sdkField.value
  result.valid = sdkField.valid

proc blaiCpuTfliteRouteMultiplierAbi*(highHalf: int32,
    lowHalf: uint32): BlaiCpuTfliteRouteMultiplierAbi =
  ## Compose the split SDK route multiplier from GENERAL_FORM and
  ## TFLITE_MULTIPLIER records before storing the int32 ABI field.
  if lowHalf > 0xFFFF'u32:
    return
  let encoded =
    (blaiUint32FromInt32Bits(highHalf) and 0xFFFF_0000'u32) or lowHalf
  result.value = blaiInt32FromBits(encoded)
  result.valid = true

proc blaiCpuTfliteRouteMultiplierHighAbi*(highBits: uint32):
    BlaiCpuTfliteRouteMultiplierAbi =
  ## Compose the GENERAL_FORM high route multiplier bits with an empty low half.
  if highBits > 0xFFFF'u32:
    return
  result.value = blaiInt32FromBits(highBits shl 16)
  result.valid = true

proc blaiCpuLayerInfoFieldAbi*(field: uint32): BlaiCpuLayerInfoFieldAbi =
  ## Resolve decoded LAYER_INFO scalar fields before SDK int32 writes.
  let sdkField = blaiSdkInt32Field(field)
  result.value = sdkField.value
  result.valid = sdkField.valid

proc blaiCpuGeneralFormFieldAbi*(field: uint32): BlaiCpuGeneralFormFieldAbi =
  ## Resolve decoded GENERAL_FORM scalar fields before SDK int32 writes.
  let sdkField = blaiSdkInt32Field(field)
  result.value = sdkField.value
  result.valid = sdkField.valid

proc blaiCpuDetailGeneralFormFieldAbi*(field: uint32):
    BlaiCpuDetailGeneralFormFieldAbi =
  ## Resolve decoded DETAIL_GENERAL_FORM scalar fields before SDK int32 writes.
  let sdkField = blaiSdkInt32Field(field)
  result.value = sdkField.value
  result.valid = sdkField.valid

proc blaiCpuDspStatusInputNumAbi*(inputNum: uint32):
    BlaiCpuDspStatusInputNumAbi =
  ## Resolve decoded DSP_STATUS input count before SDK int32 writes.
  let field = blaiSdkInt32Field(inputNum)
  result.value = field.value
  result.valid = field.valid

proc blaiCpuInputLayerFieldAbi*(field: uint32): BlaiCpuInputLayerFieldAbi =
  ## Resolve decoded INPUT_LAYERS graph input before SDK int32 writes.
  let sdkField = blaiSdkInt32Field(field)
  result.value = sdkField.value
  result.valid = sdkField.valid

proc blaiCpuGraphLayerAbi*(layerIndex: uint32,
                           layerOffset: int32): BlaiCpuGraphLayerAbi =
  ## Resolve SDK graph-layer bookkeeping from parser layer index plus offset.
  let indexField = blaiSdkInt32Field(layerIndex)
  if not indexField.valid:
    return
  let combined = indexField.value.int64 + layerOffset.int64
  if combined < low(int32).int64 or combined > high(int32).int64:
    return
  result.value = combined.int32
  result.valid = true

proc blaiCpuTfliteMultiplierBitsAbi*(bits: uint32):
    BlaiCpuTfliteMultiplierBitsAbi =
  ## Reinterpret raw SDK TFLite multiplier bits for int32 ABI storage.
  result.value = blaiInt32FromBits(bits)
  result.valid = true

proc blaiCpuBiasBitsAbi*(bits: uint32): BlaiCpuBiasBitsAbi =
  ## Reinterpret raw little-endian SDK CPU bias bits for int32 ABI storage.
  result.value = blaiInt32FromBits(bits)
  result.valid = true

proc blaiByteBufferCursor*(byteIndex: uint32,
                           capacity: int): BlaiU32ArrayIndexCursor =
  ## Resolve one recovered byte offset before indexing caller-owned byte storage.
  blaiU32ArrayIndexCursor(byteIndex, capacity)

proc blaiForwardWeightByteCountCursor*(byteCount: uint32,
                                       capacity: int): BlaiU32CountCursor =
  ## Resolve a recovered forward_NPU weight byte count before byte iteration.
  blaiU32CountCursor(byteCount, capacity)

proc blaiForwardBiasWordCountCursor*(biasCount: uint32,
                                     capacity: int): BlaiU32CountCursor =
  ## Resolve a recovered forward_NPU int32 bias count before word iteration.
  blaiU32CountCursor(biasCount, capacity)

proc blaiNpuWeightBufferCursor*(weightCursor: uint32,
                                capacity: int): BlaiU32ArrayIndexCursor =
  ## Resolve one recovered `Load_NPU_weights` output byte cursor.
  blaiU32ArrayIndexCursor(weightCursor, capacity)

proc blaiNpuWeightSourceCursor*(sourceIndex: uint32,
                                capacity: int): BlaiU32ArrayIndexCursor =
  ## Resolve one recovered logical weight source index.
  blaiU32ArrayIndexCursor(sourceIndex, capacity)

proc blaiNpuBiasBufferCursor*(biasCursor: uint32,
                              capacity: int): BlaiU32ArrayIndexCursor =
  ## Resolve one recovered `Load_NPU_weights` output bias cursor.
  blaiU32ArrayIndexCursor(biasCursor, capacity)

proc blaiNpuBiasSourceCursor*(sourceIndex: uint32,
                              capacity: int): BlaiU32ArrayIndexCursor =
  ## Resolve one recovered logical bias source index.
  blaiU32ArrayIndexCursor(sourceIndex, capacity)

proc blaiNpuTemporaryWeightCursor*(destIndex: uint32,
                                   capacity: int): BlaiU32ArrayIndexCursor =
  ## Resolve one recovered temporary grouped-weight destination index.
  blaiU32ArrayIndexCursor(destIndex, capacity)

proc blaiCpuStreamStartLayerCursor*(cursor: BlaiCpuStreamCursor,
                                    capacity: int): BlaiU32ArrayIndexCursor =
  ## Resolve a CPU stream cursor start layer, treating negative cursors as zero.
  let startLayer = if cursor.layerIndex <= 0: 0'i32 else: cursor.layerIndex
  blaiI32ArrayIndexCursor(startLayer, capacity)

proc blaiForwardCacheRangeCount*(count: uint32): int =
  ## Bound recovered forward_NPU cache range counts to the fixed cache array.
  blaiBoundedU32Count(count, BlaiForwardMaxCacheRanges)

proc blaiInt32BufferBytes*(items: openArray[int32]): uint32 =
  ## Convert an int32 buffer length to bytes without wrapping uint32 capacity.
  let count = blaiOpenArrayLenU32(items)
  if not blaiBiasWordCountBytes(count, result):
    result = high(uint32)

proc blaiCheckedByteWindow(bufferLen: int,
                           offset, bytes: uint32): BlaiCheckedByteWindow

proc blaiTensorBufferWindow(plan: BlaiTensorTransferPlan,
                            patchSize: uint32,
                            bufferLen: int): BlaiTensorBufferWindow =
  ## Resolve a recovered DATA-buffer slot to a checked byte-window.
  ##
  ## The SDK expresses tensor movement through DRAM slots and patch size. Keep
  ## that arithmetic here so tensor store/load helpers work on bounded windows.
  result.active = plan.active
  if bufferLen < 0:
    return
  blaiTensorBufferFitsInto(
    plan, patchSize, blaiBufferLenU32(bufferLen), result.fit)
  result.active = result.fit.active
  if not result.fit.active or not result.fit.fits:
    return
  let window = blaiCheckedByteWindow(
    bufferLen, result.fit.offset, result.fit.bytes)
  if not window.fits:
    return
  result.start = window.start
  result.count = window.count
  result.fits = true

template blaiTensorBufferOpenArray(buffer: untyped,
                                   window: BlaiTensorBufferWindow): untyped =
  buffer.toOpenArray(window.start, window.start + window.count - 1)

proc blaiCacheRangeInto*(operation: BlaiCacheOperation,
                         plan: BlaiTensorTransferPlan,
                         patchSize: uint32,
                         outResult: var BlaiCacheRange) =
  ## Cache range used by SDK tensor staging/readback around the DATA buffer.
  outResult = default(BlaiCacheRange)
  if not plan.active:
    return
  outResult.active = true
  outResult.operation = operation
  outResult.offset = blaiTensorBufferOffset(plan, patchSize)
  outResult.bytes = plan.bytes

proc blaiCacheRange*(operation: BlaiCacheOperation,
                     plan: BlaiTensorTransferPlan,
                     patchSize: uint32): BlaiCacheRange =
  ## Convenience result-returning wrapper for DATA-buffer cache ranges.
  blaiCacheRangeInto(operation, plan, patchSize, result)

proc blaiCacheRangeFitsInto*(range: BlaiCacheRange,
                             bufferBytes: uint32,
                             outResult: var BlaiCacheRangeFitResult) =
  ## Check DATA-buffer-relative cache range arithmetic and caller capacity.
  outResult = default(BlaiCacheRangeFitResult)
  outResult.active = range.active
  outResult.offsetFits = true
  outResult.offset = range.offset
  outResult.bytes = range.bytes
  if not range.active:
    outResult.bufferFits = true
    outResult.fits = true
    return
  var rangeFit: BlaiDataBufferRangeFit
  blaiDataBufferRangeFitsInto(
    range.active, range.offset, range.bytes, bufferBytes, rangeFit)
  outResult.offsetFits = rangeFit.offsetFits
  outResult.bufferFits = rangeFit.bufferFits
  outResult.requiredBytes = rangeFit.requiredBytes
  outResult.fits = rangeFit.fits

proc blaiCacheRangeFits*(range: BlaiCacheRange,
                         bufferBytes: uint32): bool =
  ## Boolean wrapper for DATA-buffer-relative cache range bounds checks.
  var fit: BlaiCacheRangeFitResult
  blaiCacheRangeFitsInto(range, bufferBytes, fit)
  fit.fits

proc blaiClampI32(value: int64): int32 =
  if value > high(int32).int64:
    high(int32)
  elif value < low(int32).int64:
    low(int32)
  else:
    value.int32

proc blaiAbsI64(value: int64): int64 =
  if value < 0: -value else: value

proc blaiFixed32ToFixed32*(input: int32, fractionalBits: int32): int32 =
  ## SDK `fixed32_to_fixed32`, used by fixed-point activation references.
  let shifted =
    if fractionalBits > 0:
      input.int64 shr fractionalBits
    else:
      input.int64 shl (-fractionalBits)
  var rounded = shifted
  if fractionalBits > 0:
    let base = shifted shl fractionalBits
    let diff = blaiAbsI64(blaiAbsI64(input.int64) - blaiAbsI64(base))
    let half = 1'i64 shl (fractionalBits - 1)
    if (input > 0 and diff >= half) or (input < 0 and diff > half):
      inc rounded
  blaiClampI32(rounded)

proc blaiFixed32ToFixed8*(input: int32, fractionalBits: int32): int8 =
  ## SDK `fixed32_to_fixed8` with saturation and asymmetric tie handling.
  let shifted =
    if fractionalBits > 0:
      input shr fractionalBits
    else:
      blaiClampI32(input.int64 shl (-fractionalBits))
  var output = shifted
  if fractionalBits > 0:
    let base = shifted.int64 shl fractionalBits
    let diff = blaiAbsI64(blaiAbsI64(input.int64) - blaiAbsI64(base))
    let half = 1'i64 shl (fractionalBits - 1)
    if output < high(int8).int32 and
        ((input > 0 and diff >= half) or (input < 0 and diff > half)):
      inc output
  if shifted > high(int8).int32:
    high(int8)
  elif shifted < low(int8).int32:
    low(int8)
  else:
    output.int8

proc blaiFixed8ToFixed8*(input: int8, fractionalBits: int32): int8 =
  ## SDK `fixed8_to_fixed8` with saturation and asymmetric tie handling.
  let input32 = input.int32
  let shifted =
    if fractionalBits > 0:
      input32 shr fractionalBits
    else:
      blaiClampI32(input32.int64 shl (-fractionalBits))
  var output = shifted
  if fractionalBits > 0:
    let base = shifted.int64 shl fractionalBits
    let diff = blaiAbsI64(blaiAbsI64(input32.int64) - blaiAbsI64(base))
    let half = 1'i64 shl (fractionalBits - 1)
    if output < high(int8).int32 and
        ((input32 > 0 and diff >= half) or (input32 < 0 and diff > half)):
      inc output
  if shifted > high(int8).int32:
    high(int8)
  elif shifted < low(int8).int32:
    low(int8)
  else:
    output.int8

proc blaiFixed8ToFixed32*(input: int8, fractionalBits: int32): int32 =
  ## SDK `fixed8_to_fixed32`; positive shifts intentionally preserve sign.
  if fractionalBits > 0:
    input.int32 shr fractionalBits
  else:
    blaiClampI32(input.int64 shl (-fractionalBits))

proc blaiReferenceInputSampleValue*(sample: int8,
                                    unsignedInput: bool): int32 =
  ## Project fixed-point input samples for SDK first-layer unsigned mode.
  if unsignedInput and sample < 0:
    sample.int32 + 0x100'i32
  else:
    sample.int32

proc blaiPeRelu*(value: int32): int32 =
  if value > 0: value else: 0

proc blaiPeLeaky*(value: int32): int32 =
  ## SDK `PE_LEAKY`: alpha is `float_to_fixed(0.1, 9)` = 51.
  if value > 0: value else: blaiClampI32(51'i64 * value.int64)

proc blaiPeRelu6*(value: int32, fractionalBits: int32): int32 =
  let fixed6 = blaiFixed32ToFixed32(6, -fractionalBits)
  min(blaiPeRelu(value), fixed6)

proc blaiApplyReferenceActivation*(value: int32,
                                   activation: BlaiActivation,
                                   fractionalBits: int32): int32 =
  case activation
  of blaiActLeaky:
    blaiPeLeaky(value)
  of blaiActRelu:
    blaiPeRelu(value)
  of blaiActRelu6:
    blaiPeRelu6(value, fractionalBits)
  else:
    value

proc blaiReferenceConvOutputDim*(input, stride: uint32): uint32 =
  if stride == 0'u32: 0'u32 else: (input + stride - 1'u32) div stride

proc blaiReferenceFoldedOutputDim(windowCount: uint32): uint32 =
  (windowCount + 1'u32) div 2'u32

proc blaiReferenceConvReadinessInto*(
    plan: BlaiReferenceConv2d,
    inputLen, weightLen, biasLen, outputLen: int,
    outResult: var BlaiReferenceConvResult)

proc blaiReferenceConvFits*(plan: BlaiReferenceConv2d,
                            inputLen, weightLen, biasLen, outputLen: int): bool =
  var readiness: BlaiReferenceConvResult
  blaiReferenceConvReadinessInto(
    plan, inputLen, weightLen, biasLen, outputLen, readiness)
  readiness.fits

proc blaiReferenceConvReadinessInto*(
    plan: BlaiReferenceConv2d,
    inputLen, weightLen, biasLen, outputLen: int,
    outResult: var BlaiReferenceConvResult) =
  outResult = BlaiReferenceConvResult()
  outResult.outputW = blaiReferenceConvOutputDim(plan.inputW, plan.stride)
  outResult.outputH = blaiReferenceConvOutputDim(plan.inputH, plan.stride)
  outResult.outputC = plan.outputC
  outResult.validInputShape =
    plan.inputW != 0'u32 and plan.inputH != 0'u32 and
      plan.inputC != 0'u32 and plan.outputC != 0'u32 and
      plan.kernelSize != 0'u32 and plan.stride != 0'u32 and
      plan.dilation != 0'u32 and plan.groups != 0'u32
  outResult.supportedKernel = (plan.kernelSize and 1'u32) == 1'u32
  outResult.validGroupShape =
    outResult.validInputShape and
      plan.inputC mod plan.groups == 0'u32 and
      plan.outputC mod plan.groups == 0'u32
  let inputPerGroup =
    if outResult.validGroupShape: plan.inputC div plan.groups else: 0'u32
  let inputNeed =
    blaiReferenceHwcElementCount(plan.inputW, plan.inputH, plan.inputC)
  let weightNeed =
    blaiReferenceGroupedKernelElementCount(
      plan.outputC, inputPerGroup, plan.kernelSize)
  let biasNeed = plan.outputC.uint64
  let outputNeed =
    blaiReferenceHwcElementCount(
      outResult.outputW, outResult.outputH, plan.outputC)
  discard blaiU64ExactU32Count(inputNeed, outResult.inputElements)
  discard blaiU64ExactU32Count(weightNeed, outResult.weightElements)
  discard blaiU64ExactU32Count(biasNeed, outResult.biasElements)
  discard blaiU64ExactU32Count(outputNeed, outResult.requiredOutputElements)
  outResult.inputFits = inputNeed <= inputLen.uint64
  outResult.weightsFit = weightNeed <= weightLen.uint64
  outResult.biasFits = biasNeed <= biasLen.uint64
  outResult.outputFits = outputNeed <= outputLen.uint64
  if not outResult.validInputShape:
    outResult.firstBlock = blaiConvInputShape
  elif not outResult.supportedKernel:
    outResult.firstBlock = blaiConvKernel
  elif not outResult.validGroupShape:
    outResult.firstBlock = blaiConvGroupShape
  elif not outResult.inputFits:
    outResult.firstBlock = blaiConvInputBuffer
  elif not outResult.weightsFit:
    outResult.firstBlock = blaiConvWeightBuffer
  elif not outResult.biasFits:
    outResult.firstBlock = blaiConvBiasBuffer
  elif not outResult.outputFits:
    outResult.firstBlock = blaiConvOutputBuffer
  else:
    outResult.firstBlock = blaiConvNoBlock
    outResult.fits = true

proc blaiReferenceInputSample(input: openArray[int8],
                              plan: BlaiReferenceConv2d,
                              x, y, c: int32): int8 =
  if x < 0 or y < 0 or c < 0 or
      x >= plan.inputW.int32 or y >= plan.inputH.int32 or
      c >= plan.inputC.int32:
    0'i8
  else:
    let inputHwc =
      blaiHwcIndex(y.uint32, x.uint32, plan.inputW, c.uint32, plan.inputC)
    if inputHwc.valid:
      input[inputHwc.index.int]
    else:
      0'i8

proc blaiReferenceConv2d*(plan: BlaiReferenceConv2d,
                          input: openArray[int8],
                          weights: openArray[int8],
                          biases: openArray[int8],
                          output: var openArray[int8]): BlaiReferenceConvResult =
  ## CPU fixture for SDK `forward_CONVOLUTIONAL` over HWC int8 tensors.
  blaiReferenceConvReadinessInto(
    plan, input.len, weights.len, biases.len, output.len, result)
  if not result.fits:
    return

  let kernelStep = plan.kernelSize.int32 div 2
  let inputPerGroup = plan.inputC div plan.groups
  let outputPerGroup = plan.outputC div plan.groups
  let activationFrac = plan.fdata + plan.fweight
  for outC in 0'u32 ..< plan.outputC:
    let groupIndex = outC div outputPerGroup
    let cStart = groupIndex * inputPerGroup
    let cEnd = cStart + inputPerGroup
    for outY in 0'u32 ..< result.outputH:
      let centerY = (outY * plan.stride).int32
      for outX in 0'u32 ..< result.outputW:
        let centerX = (outX * plan.stride).int32
        var acc = 0'i32
        for inC in cStart ..< cEnd:
          var channelAcc = 0'i32
          for ky in 0'u32 ..< plan.kernelSize:
            let inputY = centerY + (ky.int32 - kernelStep) * plan.dilation.int32
            for kx in 0'u32 ..< plan.kernelSize:
              let inputX = centerX + (kx.int32 - kernelStep) * plan.dilation.int32
              let sample = blaiReferenceInputSample(input, plan, inputX, inputY, inC.int32)
              let weightColumns = inputPerGroup * plan.kernelSize * plan.kernelSize
              let weightColumn =
                (inC - cStart) * plan.kernelSize * plan.kernelSize +
                ky * plan.kernelSize + kx
              let weightIndex =
                blaiRowMajorIndex(outC, weightColumn, weightColumns)
              if not weightIndex.valid:
                return
              let sampleValue = blaiReferenceInputSampleValue(
                sample, plan.firstLayerUnsignedInput)
              channelAcc += sampleValue * weights[weightIndex.index.int].int32
          acc = blaiClampI32(acc.int64 + channelAcc.int64)
        let biasShift = plan.fbias - plan.fdata - plan.fweight
        acc = blaiClampI32(acc.int64 + blaiFixed8ToFixed32(biases[outC.int], biasShift).int64)
        acc = blaiApplyReferenceActivation(acc, plan.activation, activationFrac)
        let alphaShift =
          if plan.activation == blaiActLeaky and acc < 0:
            9'i32
          else:
            0'i32
        let outputShift = plan.fdata + plan.fweight + alphaShift - plan.fout
        let outputHwc =
          blaiHwcIndex(outY, outX, result.outputW, outC, plan.outputC)
        if not outputHwc.valid:
          return
        output[outputHwc.index.int] = blaiFixed32ToFixed8(acc, outputShift)

proc blaiActivationFromSdk(value: int32): BlaiActivation =
  ## Convert an SDK activation integer to the recovered Nim enum.
  case value
  of BlaiSdkActLeaky: blaiActLeaky
  of BlaiSdkActRelu: blaiActRelu
  of BlaiSdkActLinear: blaiActLinear
  of BlaiSdkActRelu6: blaiActRelu6
  of BlaiSdkActMish: blaiActMish
  of BlaiSdkActElu: blaiActElu
  of BlaiSdkActRelie: blaiActRelie
  of BlaiSdkActLogistic: blaiActLogistic
  of BlaiSdkActRamp: blaiActRamp
  of BlaiSdkActTanh: blaiActTanh
  of BlaiSdkActPlse: blaiActPlse
  of BlaiSdkActLoggy: blaiActLoggy
  of BlaiSdkActStair: blaiActStair
  of BlaiSdkActHardtan: blaiActHardtan
  of BlaiSdkActLhtan: blaiActLhtan
  of BlaiSdkActSelu: blaiActSelu
  of BlaiSdkActGelu: blaiActGelu
  of BlaiSdkActSwish: blaiActSwish
  of BlaiSdkActNormChan: blaiActNormChan
  of BlaiSdkActNormChanSoftmax: blaiActNormChanSoftmax
  of BlaiSdkActNormChanSoftmaxMaxval: blaiActNormChanSoftmaxMaxval
  of BlaiSdkActReluN: blaiActReluN
  else: blaiActLinear

proc blaiReferenceConvMaxReadinessInto*(
    plan: BlaiReferenceConvMax2d,
    inputLen, weightLen, biasLen, outputLen: int,
    outResult: var BlaiReferenceConvMaxResult)

proc blaiReferenceConvMaxFits*(plan: BlaiReferenceConvMax2d,
                               inputLen, weightLen, biasLen, outputLen: int): bool =
  var readiness: BlaiReferenceConvMaxResult
  blaiReferenceConvMaxReadinessInto(
    plan, inputLen, weightLen, biasLen, outputLen, readiness)
  readiness.fits

proc blaiReferenceConvMaxReadinessInto*(
    plan: BlaiReferenceConvMax2d,
    inputLen, weightLen, biasLen, outputLen: int,
    outResult: var BlaiReferenceConvMaxResult) =
  outResult = BlaiReferenceConvMaxResult()
  outResult.windowW = blaiReferenceConvOutputDim(plan.inputW, plan.stride)
  outResult.windowH = blaiReferenceConvOutputDim(plan.inputH, plan.stride)
  let foldedW = blaiReferenceFoldedOutputDim(outResult.windowW)
  let foldedH = blaiReferenceFoldedOutputDim(outResult.windowH)
  outResult.outputW = if plan.outputW == 0'u32: foldedW else: plan.outputW
  outResult.outputH = if plan.outputH == 0'u32: foldedH else: plan.outputH
  outResult.outputC = plan.outputC
  outResult.validInputShape =
    plan.inputW != 0'u32 and plan.inputH != 0'u32 and
      plan.inputC != 0'u32 and plan.outputC != 0'u32 and
      plan.kernelSize != 0'u32 and plan.stride != 0'u32 and
      plan.dilation != 0'u32 and plan.groups != 0'u32
  outResult.supportedKernel = (plan.kernelSize and 1'u32) == 1'u32
  outResult.validGroupShape =
    outResult.validInputShape and
      plan.inputC mod plan.groups == 0'u32 and
      plan.outputC mod plan.groups == 0'u32
  outResult.validOutputShape =
    outResult.outputW >= foldedW and outResult.outputH >= foldedH
  let inputPerGroup =
    if outResult.validGroupShape: plan.inputC div plan.groups else: 0'u32
  let inputNeed =
    blaiReferenceHwcElementCount(plan.inputW, plan.inputH, plan.inputC)
  let weightNeed =
    blaiReferenceGroupedKernelElementCount(
      plan.outputC, inputPerGroup, plan.kernelSize)
  let biasNeed = plan.outputC.uint64
  let outputNeed =
    blaiReferenceHwcElementCount(
      outResult.outputW, outResult.outputH, plan.outputC)
  discard blaiU64ExactU32Count(inputNeed, outResult.inputElements)
  discard blaiU64ExactU32Count(weightNeed, outResult.weightElements)
  discard blaiU64ExactU32Count(biasNeed, outResult.biasElements)
  discard blaiU64ExactU32Count(outputNeed, outResult.requiredOutputElements)
  outResult.inputFits = inputNeed <= inputLen.uint64
  outResult.weightsFit = weightNeed <= weightLen.uint64
  outResult.biasFits = biasNeed <= biasLen.uint64
  outResult.outputFits = outputNeed <= outputLen.uint64
  if not outResult.validInputShape:
    outResult.firstBlock = blaiConvMaxInputShape
  elif not outResult.supportedKernel:
    outResult.firstBlock = blaiConvMaxKernel
  elif not outResult.validGroupShape:
    outResult.firstBlock = blaiConvMaxGroupShape
  elif not outResult.validOutputShape:
    outResult.firstBlock = blaiConvMaxOutputShape
  elif not outResult.inputFits:
    outResult.firstBlock = blaiConvMaxInputBuffer
  elif not outResult.weightsFit:
    outResult.firstBlock = blaiConvMaxWeightBuffer
  elif not outResult.biasFits:
    outResult.firstBlock = blaiConvMaxBiasBuffer
  elif not outResult.outputFits:
    outResult.firstBlock = blaiConvMaxOutputBuffer
  else:
    outResult.firstBlock = blaiConvMaxNoBlock
    outResult.fits = true

proc blaiReferenceConvMaxSample(
    plan: BlaiReferenceConvMax2d,
    input: openArray[int8],
    x, y: int32,
    channel: uint32): int8 =
  if x < 0 or y < 0 or x >= plan.inputW.int32 or y >= plan.inputH.int32:
    0'i8
  else:
    let inputHwc =
      blaiHwcIndex(y.uint32, x.uint32, plan.inputW, channel, plan.inputC)
    if inputHwc.valid:
      input[inputHwc.index.int]
    else:
      0'i8

proc blaiReferenceConvMaxValue(
    plan: BlaiReferenceConvMax2d,
    input: openArray[int8],
    weights: openArray[int8],
    biases: openArray[int8],
    outC, windowY, windowX: uint32): int8 =
  let kernelStep = plan.kernelSize.int32 div 2
  let inputPerGroup = plan.inputC div plan.groups
  let outputPerGroup = plan.outputC div plan.groups
  let groupIndex = outC div outputPerGroup
  let cStart = groupIndex * inputPerGroup
  let cEnd = cStart + inputPerGroup
  let centerY = (windowY * plan.stride).int32
  let centerX = (windowX * plan.stride).int32
  var acc = 0'i32
  for inC in cStart ..< cEnd:
    var channelAcc = 0'i32
    for ky in 0'u32 ..< plan.kernelSize:
      let inputY = centerY + (ky.int32 - kernelStep) * plan.dilation.int32
      for kx in 0'u32 ..< plan.kernelSize:
        let inputX = centerX + (kx.int32 - kernelStep) * plan.dilation.int32
        let sample = blaiReferenceConvMaxSample(
          plan, input, inputX, inputY, inC)
        let weightColumns = inputPerGroup * plan.kernelSize * plan.kernelSize
        let weightColumn =
          (inC - cStart) * plan.kernelSize * plan.kernelSize +
          ky * plan.kernelSize + kx
        let weightIndex = blaiRowMajorIndex(outC, weightColumn, weightColumns)
        if not weightIndex.valid:
          return 0'i8
        let sampleValue = blaiReferenceInputSampleValue(
          sample, plan.firstLayerUnsignedInput)
        channelAcc = blaiClampI32(
          channelAcc.int64 + sampleValue.int64 *
            weights[weightIndex.index.int].int64)
    acc = blaiClampI32(acc.int64 + channelAcc.int64)
  let biasShift = plan.fbias - plan.fdata - plan.fweight
  acc = blaiClampI32(
    acc.int64 + blaiFixed8ToFixed32(biases[outC.int], biasShift).int64)
  acc = blaiApplyReferenceActivation(acc, plan.activation, plan.fdata + plan.fweight)
  let alphaShift =
    if plan.activation == blaiActLeaky and acc < 0:
      9'i32
    else:
      0'i32
  let outputShift = plan.fdata + plan.fweight + alphaShift - plan.fout
  blaiFixed32ToFixed8(acc, outputShift)

proc blaiReferenceConvMax2d*(plan: BlaiReferenceConvMax2d,
                             input: openArray[int8],
                             weights: openArray[int8],
                             biases: openArray[int8],
                             output: var openArray[int8]): BlaiReferenceConvMaxResult =
  ## CPU fixture for odd-kernel SDK `forward_CONV_MAX` over HWC int8 tensors.
  blaiReferenceConvMaxReadinessInto(
    plan, input.len, weights.len, biases.len, output.len, result)
  if not result.fits:
    return

  for outC in 0'u32 ..< plan.outputC:
    for windowY in 0'u32 ..< result.windowH:
      for windowX in 0'u32 ..< result.windowW:
        let passData = blaiReferenceConvMaxValue(
          plan, input, weights, biases, outC, windowY, windowX)
        let outputHwc =
          blaiHwcIndex(windowY div 2'u32, windowX div 2'u32,
            result.outputW, outC, result.outputC)
        if not outputHwc.valid:
          return
        let outputIndex = outputHwc.index
        if windowY mod 2'u32 == 0'u32 and windowX mod 2'u32 == 0'u32:
          output[outputIndex.int] = passData
        elif output[outputIndex.int] < passData:
          output[outputIndex.int] = passData

proc blaiReferenceMatmulReadinessInto*(
    plan: BlaiReferenceMatmul2d,
    inputLen, weightsLen, biasLen, outputLen: int,
    outResult: var BlaiReferenceMatmulResult)

proc blaiReferenceMatmulFits*(plan: BlaiReferenceMatmul2d,
                              inputLen, weightsLen, biasLen, outputLen: int): bool =
  var readiness: BlaiReferenceMatmulResult
  blaiReferenceMatmulReadinessInto(
    plan, inputLen, weightsLen, biasLen, outputLen, readiness)
  readiness.fits

proc blaiReferenceMatmulReadinessInto*(
    plan: BlaiReferenceMatmul2d,
    inputLen, weightsLen, biasLen, outputLen: int,
    outResult: var BlaiReferenceMatmulResult) =
  outResult = BlaiReferenceMatmulResult()
  outResult.outputW = 1
  outResult.outputH = plan.height
  outResult.outputC = plan.outputC
  outResult.validInputShape =
    plan.width != 0'u32 and plan.height != 0'u32 and
      plan.inputC != 0'u32 and plan.outputC != 0'u32
  let inputNeed =
    blaiReferenceMatmulActivationElements(plan.height, plan.inputC)
  let weightNeed =
    blaiReferenceMatmulWeightElements(plan.inputC, plan.outputC)
  let biasNeed = plan.outputC.uint64
  let outputNeed =
    blaiReferenceMatmulActivationElements(plan.height, plan.outputC)
  discard blaiU64ExactU32Count(inputNeed, outResult.inputElements)
  discard blaiU64ExactU32Count(weightNeed, outResult.weightElements)
  discard blaiU64ExactU32Count(biasNeed, outResult.biasElements)
  discard blaiU64ExactU32Count(outputNeed, outResult.requiredOutputElements)
  outResult.inputFits = inputNeed <= inputLen.uint64
  outResult.weightsFit = weightNeed <= weightsLen.uint64
  outResult.biasFits = biasNeed <= biasLen.uint64
  outResult.outputFits = outputNeed <= outputLen.uint64
  if not outResult.validInputShape:
    outResult.firstBlock = blaiMatmulInputShape
  elif not outResult.inputFits:
    outResult.firstBlock = blaiMatmulInputBuffer
  elif not outResult.weightsFit:
    outResult.firstBlock = blaiMatmulWeightBuffer
  elif not outResult.biasFits:
    outResult.firstBlock = blaiMatmulBiasBuffer
  elif not outResult.outputFits:
    outResult.firstBlock = blaiMatmulOutputBuffer
  else:
    outResult.firstBlock = blaiMatmulNoBlock
    outResult.fits = true

proc blaiReferenceMatmul2d*(plan: BlaiReferenceMatmul2d,
                            input: openArray[int8],
                            weights: openArray[int8],
                            biases: openArray[int8],
                            output: var openArray[int8]): BlaiReferenceMatmulResult =
  ## CPU fixture for SDK `forward_MATMUL` over H-by-C fixed-point int8 tensors.
  blaiReferenceMatmulReadinessInto(
    plan, input.len, weights.len, biases.len, output.len, result)
  if not result.fits:
    return

  let activationFrac = plan.fdata + plan.fweight
  for y in 0'u32 ..< plan.height:
    for _ in 0'u32 ..< plan.width:
      for outC in 0'u32 ..< plan.outputC:
        var acc = 0'i32
        for inC in 0'u32 ..< plan.inputC:
          let inputHwc = blaiHwcIndex(y, 0'u32, 1'u32, inC, plan.inputC)
          if not inputHwc.valid:
            return
          let weightIndex = blaiRowMajorIndex(outC, inC, plan.inputC)
          if not weightIndex.valid:
            return
          let sample = blaiReferenceInputSampleValue(
            input[inputHwc.index.int], plan.firstLayerUnsignedInput)
          acc = blaiClampI32(
            acc.int64 + sample.int64 * weights[weightIndex.index.int].int64)
        let biasShift = plan.fbias - plan.fdata - plan.fweight
        acc = blaiClampI32(
          acc.int64 + blaiFixed8ToFixed32(biases[outC.int], biasShift).int64)
        acc = blaiApplyReferenceActivation(acc, plan.activation, activationFrac)
        let alphaShift =
          if plan.activation == blaiActLeaky and acc < 0:
            9'i32
        else:
          0'i32
        let outputShift = plan.fdata + plan.fweight + alphaShift - plan.fout
        let outputHwc = blaiHwcIndex(y, 0'u32, 1'u32, outC, plan.outputC)
        if not outputHwc.valid:
          return
        output[outputHwc.index.int] = blaiFixed32ToFixed8(acc, outputShift)

proc blaiRoundingDivideByPowerOfTwo*(dividend: int32, exponent: int32): int32 =
  ## NMSIS `riscv_nn_divide_by_power_of_two`.
  if exponent <= 0:
    return dividend
  let remainderMask = (1'i32 shl exponent) - 1
  let remainder = dividend and remainderMask
  var quotient = dividend shr exponent
  var threshold = remainderMask shr 1
  if quotient < 0:
    inc threshold
  if remainder > threshold:
    inc quotient
  quotient

proc blaiDoublingHighMulNoSat*(a, b: int32): int32 =
  ## NMSIS `riscv_nn_doubling_high_mult_no_sat`.
  (((1'i64 shl 30) + a.int64 * b.int64) shr 31).int32

proc blaiNmsisRequantize*(value, multiplier, shift: int32): int32 =
  ## NMSIS `riscv_nn_requantize`.
  let leftShift = if shift > 0: shift else: 0
  let rightShift = if shift > 0: 0 else: -shift
  let shifted = blaiClampI32(value.int64 shl leftShift)
  blaiRoundingDivideByPowerOfTwo(
    blaiDoublingHighMulNoSat(shifted, multiplier), rightShift.int32)

proc blaiTfliteSaturatingRoundingDoublingHighMul*(a, b: int32): int32 =
  ## SDK `BL_SaturatingRoundingDoublingHighMul`.
  if a == low(int32) and b == low(int32):
    return high(int32)
  let product = a.int64 * b.int64
  let nudge =
    if product >= 0:
      1'i64 shl 30
    else:
      1'i64 - (1'i64 shl 30)
  var high32 = ((product + nudge) shr 31).int32
  if high32 < 0:
    inc high32
  high32

proc blaiTfliteMultiplyByQuantizedMultiplier*(
    value, multiplier, shift: int32): int32 =
  ## SDK `BL_MultiplyByQuantizedMultiplier`.
  let leftShift = if shift > 0: shift else: 0
  let rightShift = if shift > 0: 0 else: -shift
  let shifted =
    if leftShift >= 31:
      if value >= 0: high(int32) else: low(int32)
    else:
      blaiClampI32(value.int64 shl leftShift)
  blaiRoundingDivideByPowerOfTwo(
    blaiTfliteSaturatingRoundingDoublingHighMul(shifted, multiplier),
    rightShift.int32)

proc blaiTfliteMultiplyByQuantizedMultiplierSmallerThanOneExp*(
    value, multiplier, leftShift: int32): int32 =
  ## SDK `BL_MultiplyByQuantizedMultiplierSmallerThanOneExp`.
  if leftShift > 0:
    return blaiTfliteSaturatingRoundingDoublingHighMul(value, multiplier)
  blaiRoundingDivideByPowerOfTwo(
    blaiTfliteSaturatingRoundingDoublingHighMul(value, multiplier), -leftShift)

proc blaiReferenceDepthwiseOutputDim*(input, padding, kernel, stride: uint32): uint32 =
  if stride == 0'u32:
    return 0'u32
  let padded = input.uint64 + 2'u64 * padding.uint64
  if padded < kernel.uint64:
    0'u32
  else:
    ((padded - kernel.uint64) div stride.uint64 + 1'u64).uint32

proc blaiReferenceDepthwiseConvReadinessInto*(
    plan: BlaiReferenceDepthwiseConv2d,
    inputLen, kernelLen, biasLen, outputLen: int,
    outResult: var BlaiReferenceDepthwiseConvResult)

proc blaiReferenceDepthwiseConvFits*(plan: BlaiReferenceDepthwiseConv2d,
                                     inputLen, kernelLen, biasLen, outputLen: int): bool =
  var readiness: BlaiReferenceDepthwiseConvResult
  blaiReferenceDepthwiseConvReadinessInto(
    plan, inputLen, kernelLen, biasLen, outputLen, readiness)
  readiness.fits

proc blaiReferenceDepthwiseConvReadinessInto*(
    plan: BlaiReferenceDepthwiseConv2d,
    inputLen, kernelLen, biasLen, outputLen: int,
    outResult: var BlaiReferenceDepthwiseConvResult) =
  outResult = BlaiReferenceDepthwiseConvResult()
  outResult.outputW = blaiReferenceDepthwiseOutputDim(
    plan.inputW, plan.paddingX, plan.kernelW, plan.strideX)
  outResult.outputH = blaiReferenceDepthwiseOutputDim(
    plan.inputH, plan.paddingY, plan.kernelH, plan.strideY)
  let outputCNeed =
    blaiReferenceDepthwiseOutputChannels(plan.inputC, plan.channelMultiplier)
  let outputCFits = blaiU64ExactU32Count(outputCNeed, outResult.outputC)
  outResult.validInputShape =
    plan.inputW != 0'u32 and plan.inputH != 0'u32 and
      plan.inputC != 0'u32 and plan.kernelW != 0'u32 and
      plan.kernelH != 0'u32 and plan.strideX != 0'u32 and
      plan.strideY != 0'u32 and plan.channelMultiplier != 0'u32
  outResult.validOutputShape =
    outResult.outputW != 0'u32 and outResult.outputH != 0'u32 and
      outputCNeed != 0'u64 and outputCFits

  let inputNeed =
    blaiReferenceHwcElementCount(plan.inputW, plan.inputH, plan.inputC)
  let kernelNeed =
    blaiReferenceKernelElementCount(outputCNeed, plan.kernelW, plan.kernelH)
  let biasNeed = outputCNeed
  let outputNeed =
    blaiReferenceHwcElementCount(outResult.outputW, outResult.outputH,
                                 outputCNeed)
  discard blaiU64ExactU32Count(inputNeed, outResult.inputElements)
  discard blaiU64ExactU32Count(kernelNeed, outResult.kernelElements)
  discard blaiU64ExactU32Count(biasNeed, outResult.biasElements)
  discard blaiU64ExactU32Count(outputNeed, outResult.requiredOutputElements)

  outResult.inputFits = inputNeed <= inputLen.uint64
  outResult.kernelFits = kernelNeed <= kernelLen.uint64
  outResult.biasFits = biasNeed <= biasLen.uint64
  outResult.outputFits = outputNeed <= outputLen.uint64
  if not outResult.validInputShape:
    outResult.firstBlock = blaiDepthwiseConvInputShape
  elif not outResult.validOutputShape:
    outResult.firstBlock = blaiDepthwiseConvOutputShape
  elif not outResult.inputFits:
    outResult.firstBlock = blaiDepthwiseConvInputBuffer
  elif not outResult.kernelFits:
    outResult.firstBlock = blaiDepthwiseConvKernelBuffer
  elif not outResult.biasFits:
    outResult.firstBlock = blaiDepthwiseConvBiasBuffer
  elif not outResult.outputFits:
    outResult.firstBlock = blaiDepthwiseConvOutputBuffer
  else:
    outResult.firstBlock = blaiDepthwiseConvNoBlock
    outResult.fits = true

proc blaiReferenceDepthwiseConv2d*(plan: BlaiReferenceDepthwiseConv2d,
                                   input: openArray[uint8],
                                   kernel: openArray[uint8],
                                   biases: openArray[int32],
                                   output: var openArray[uint8]): BlaiReferenceDepthwiseConvResult =
  ## CPU fixture for SDK `riscv_depthwise_conv_u8` generic layout.
  blaiReferenceDepthwiseConvReadinessInto(
    plan, input.len, kernel.len, biases.len, output.len, result)
  if not result.fits:
    return

  for outY in 0'u32 ..< result.outputH:
    let baseY = outY.int32 * plan.strideY.int32 - plan.paddingY.int32
    for outX in 0'u32 ..< result.outputW:
      let baseX = outX.int32 * plan.strideX.int32 - plan.paddingX.int32
      for inputC in 0'u32 ..< plan.inputC:
        for mult in 0'u32 ..< plan.channelMultiplier:
          let outC = inputC * plan.channelMultiplier + mult
          var acc = biases[outC.int]
          let kernelYStart = max(0'i32, -baseY).uint32
          let kernelXStart = max(0'i32, -baseX).uint32
          let kernelYEnd = min(plan.kernelH.int32, plan.inputH.int32 - baseY).uint32
          let kernelXEnd = min(plan.kernelW.int32, plan.inputW.int32 - baseX).uint32
          for ky in kernelYStart ..< kernelYEnd:
            let inputY = baseY + ky.int32
            for kx in kernelXStart ..< kernelXEnd:
              let inputX = baseX + kx.int32
              let inputHwc =
                blaiHwcIndex(inputY.uint32, inputX.uint32, plan.inputW,
                  inputC, plan.inputC)
              if not inputHwc.valid:
                return
              let kernelTap = blaiRowMajorIndex(ky, kx, plan.kernelW)
              if not kernelTap.valid:
                return
              let kernelIndex =
                blaiRowMajorIndex(kernelTap.index, outC, result.outputC)
              if not kernelIndex.valid:
                return
              let inputValue = input[inputHwc.index.int].int32 + plan.inputOffset
              let kernelValue =
                kernel[kernelIndex.index.int].int32 + plan.filterOffset
              acc = blaiClampI32(acc.int64 + inputValue.int64 * kernelValue.int64)
          acc = blaiNmsisRequantize(acc, plan.outputMultiplier, plan.outputShift)
          acc = blaiClampI32(acc.int64 + plan.outputOffset.int64)
          acc = min(max(acc, plan.activationMin), plan.activationMax)
          let outputHwc =
            blaiHwcIndex(outY, outX, result.outputW, outC, result.outputC)
          if not outputHwc.valid:
            return
          output[outputHwc.index.int] = acc.uint8

proc blaiReferenceTfliteConvReadinessInto*(
    plan: BlaiReferenceTfliteConv2d,
    inputLen, kernelLen, biasLen, outputLen: int,
    outResult: var BlaiReferenceTfliteConvResult)

