  outResult.validStride = plan.stride != 0'u32
  outResult.validDilation = plan.dilation != 0'u32
  outResult.supported = blaiReferenceFixedMaxPoolSupported(plan)
  outResult.outputW = blaiReferenceConvOutputDim(plan.inputW, plan.stride)
  outResult.outputH = blaiReferenceConvOutputDim(plan.inputH, plan.stride)
  outResult.outputC = plan.inputC
  let inputNeed =
    blaiReferenceHwcElementCount(plan.inputW, plan.inputH, plan.inputC)
  let outputNeed =
    blaiReferenceHwcElementCount(
      outResult.outputW, outResult.outputH, plan.inputC)
  outResult.inputFits = inputNeed <= inputLen.uint64
  outResult.outputFits = outputNeed <= outputLen.uint64
  if not outResult.validInputShape:
