  outResult.outputFits = outputNeed <= outputLen.uint64
  if not outResult.validInputShape:
    outResult.firstBlock = blaiTfliteScalarMaxPoolInputShape
  elif not outResult.validStride:
    outResult.firstBlock = blaiTfliteScalarMaxPoolStride
  elif not outResult.supported:
    outResult.firstBlock = blaiTfliteScalarMaxPoolKernel
  elif not outResult.outputShapeValid:
    outResult.firstBlock = blaiTfliteScalarMaxPoolWindow
  elif not outResult.inputFits:
    outResult.firstBlock = blaiTfliteScalarMaxPoolInputBuffer
  elif not outResult.outputFits:
    outResult.firstBlock = blaiTfliteScalarMaxPoolOutputBuffer
  else:
    outResult.firstBlock = blaiTfliteScalarMaxPoolNoBlock
    outResult.fits = true

proc blaiReferenceTfliteScalarMaxPoolFits*(
