proc blaiReferenceFixedParsedEndToEndInto*(
    checked: BlaiReferenceFixedParsedCheckedModelResult,
    outputCompare: BlaiInt8OutputCompareResult,
    outResult: var BlaiReferenceFixedParsedEndToEndResult) =
  ## Combine fixed parsed-model preflight, execution, streams, and output match.
  outResult = default(BlaiReferenceFixedParsedEndToEndResult)
  outResult.preflightFits = checked.preflight.fit.fits
  outResult.executed = checked.executed
  outResult.modelValid = checked.model.modelValid
  outResult.allCompleted = checked.model.allCompleted
  outResult.allWeightsConsumed = checked.model.allWeightsConsumed
  outResult.allBiasesConsumed = checked.model.allBiasesConsumed
  outResult.outputMatched = outputCompare.matched
  outResult.completedLayerCount = checked.model.completedLayerCount
  outResult.firstBlock = checked.readiness.firstBlock
  outResult.valid =
    outResult.preflightFits and outResult.executed and outResult.modelValid and
    outResult.allCompleted and outResult.allWeightsConsumed and
    outResult.allBiasesConsumed and outResult.outputMatched

proc blaiReferenceFixedParsedEndToEnd*(
    checked: BlaiReferenceFixedParsedCheckedModelResult,
    outputCompare: BlaiInt8OutputCompareResult):
    BlaiReferenceFixedParsedEndToEndResult =
  ## Convenience wrapper for fixed parsed-model end-to-end validation.
  blaiReferenceFixedParsedEndToEndInto(checked, outputCompare, result)

