proc blaiForwardModelRunSequenceReadinessInto*(
    modelResources: BlaiForwardModelResourcePlan,
    workspace: BlaiForwardModelWorkspacePlan,
    outResult: var BlaiForwardModelRunSequenceReadiness) =
  ## Explain whether a prepared model workspace can be used for run planning.
  outResult = default(BlaiForwardModelRunSequenceReadiness)
  outResult.resourcesSupported = modelResources.supported
  outResult.workspaceSupported = workspace.supported
  outResult.workspaceFits = workspace.fits
  outResult.hasInstructionWorkspace = workspace.instruction.active
  outResult.hasDataWorkspace = workspace.data.active
  outResult.workspaceReady = outResult.workspaceSupported and
    outResult.workspaceFits and outResult.hasInstructionWorkspace and
    outResult.hasDataWorkspace
  outResult.ready = outResult.resourcesSupported and outResult.workspaceReady
  if not outResult.resourcesSupported:
    outResult.firstBlock = blaiForwardModelRunSequenceReadinessResources
  elif not outResult.workspaceReady:
    outResult.firstBlock = blaiForwardModelRunSequenceReadinessWorkspace
  else:
    outResult.firstBlock = blaiForwardModelRunSequenceReadinessNoBlock

proc blaiForwardModelRunSequenceReadiness*(
    modelResources: BlaiForwardModelResourcePlan,
    workspace: BlaiForwardModelWorkspacePlan): BlaiForwardModelRunSequenceReadiness =
  ## Convenience wrapper for model run-sequence readiness diagnostics.
  blaiForwardModelRunSequenceReadinessInto(
    modelResources, workspace, result)

proc blaiForwardModelRunSequenceConfigurabilityInto*(
    plan: BlaiForwardModelRunSequencePlan,
    outResult: var BlaiForwardModelRunSequenceConfigurability) =
  ## Derive per-layer configurability for a planned model run sequence.
  outResult = default(BlaiForwardModelRunSequenceConfigurability)
  outResult.supported = plan.supported
  outResult.workspaceReady = plan.workspaceReady
  outResult.layerCount = plan.layerCount
  outResult.expectedLayerCount = plan.expectedLayerCount
  outResult.layerStorageFits = plan.layerStorageFits
  outResult.missingLayerCount = plan.missingLayerCount
  outResult.attemptedLayerCount = plan.attemptedLayerCount
  outResult.configurableLayerCount = plan.configurableLayerCount
  outResult.blockedLayerCount = plan.blockedLayerCount
  outResult.cacheRangeCount = plan.cacheRangeCount
  outResult.firstBlockedLayer = plan.firstBlockedLayer
  outResult.lastConfigurableLayer = plan.lastConfigurableLayer
  outResult.firstBlockedRunCaptured = plan.firstBlockedRunCaptured
  outResult.firstBlockedRunConfigReadiness =
    plan.firstBlockedRunConfigReadiness
  outResult.readinessFirstBlock = plan.readinessFirstBlock
  outResult.firstBlockedRunConfigFirstBlock =
    plan.firstBlockedRunConfigFirstBlock
  if not (outResult.supported and outResult.workspaceReady):
    outResult.firstBlock = blaiForwardModelRunSequenceReadiness
  elif not outResult.layerStorageFits:
    outResult.firstBlock = blaiForwardModelRunSequenceLayerStorage
  elif outResult.blockedLayerCount != 0:
    outResult.firstBlock = blaiForwardModelRunSequenceRunConfig
  else:
    outResult.firstBlock = blaiForwardModelRunSequenceNoBlock
  outResult.configurable = outResult.supported and outResult.workspaceReady and
    outResult.layerStorageFits and outResult.blockedLayerCount == 0

proc blaiForwardModelRunSequenceConfigurability*(
    plan: BlaiForwardModelRunSequencePlan):
    BlaiForwardModelRunSequenceConfigurability =
  ## Convenience wrapper for model run-sequence configurability.
  blaiForwardModelRunSequenceConfigurabilityInto(plan, result)

proc blaiPlanForwardModelRunSequenceInto*(
    layers: openArray[BlaiCpuInstLayer64],
    modelResources: BlaiForwardModelResourcePlan,
    workspace: BlaiForwardModelWorkspacePlan,
    outResult: var BlaiForwardModelRunSequencePlan) =
  ## Build recovered per-layer run plans from a prepared layer table.
  outResult = default(BlaiForwardModelRunSequencePlan)
  outResult.layerCount = blaiOpenArrayLenU32(layers)
  outResult.expectedLayerCount = modelResources.layerCount
  outResult.layerStorageFits = outResult.layerCount >= outResult.expectedLayerCount
  if not outResult.layerStorageFits:
    outResult.missingLayerCount =
      outResult.expectedLayerCount - outResult.layerCount
  outResult.firstBlockedLayer = -1
  outResult.lastConfigurableLayer = -1
  var readiness: BlaiForwardModelRunSequenceReadiness
  blaiForwardModelRunSequenceReadinessInto(
    modelResources, workspace, readiness)
  outResult.readiness = readiness
  outResult.supported = readiness.resourcesSupported
  outResult.workspaceReady = readiness.workspaceReady
  outResult.readinessFirstBlock = readiness.firstBlock
  if not readiness.ready or not outResult.layerStorageFits:
    blaiForwardModelRunSequenceConfigurabilityInto(
      outResult, outResult.configurability)
    outResult.firstBlock = outResult.configurability.firstBlock
    outResult.allConfigurable = outResult.configurability.configurable
    return

  for layerIndex in 0 ..< layers.len:
    if layers[layerIndex].npuOn == 0:
      inc outResult.skippedLayerCount
      continue

    inc outResult.attemptedLayerCount
    var runPlan: BlaiForwardNpuRunPlan
    blaiPlanForwardNpuRunInto(
      layers[layerIndex], layerIndex.uint32,
      dataBufferBytes = workspace.data.bytes,
      instAddr = workspace.instruction.address,
      dataBufferAddr = workspace.data.address,
      runPlan,
      weightAddr = workspace.weight.address,
      biasAddr = workspace.bias.address)
    outResult.lastRun = runPlan
    outResult.cacheRangeCount += runPlan.cacheRangeCount
    if runPlan.configurable:
      inc outResult.configurableLayerCount
      outResult.lastConfigurableLayer = blaiLayerIndexValue(layerIndex)
    else:
      inc outResult.blockedLayerCount
      if outResult.firstBlockedLayer < 0:
        outResult.firstBlockedLayer = blaiLayerIndexValue(layerIndex)
        outResult.firstBlockedRunCaptured = true
        outResult.firstBlockedRunConfigReadiness =
          runPlan.configReadiness
        outResult.firstBlockedRunConfigFirstBlock =
          runPlan.configReadiness.firstBlock

  blaiForwardModelRunSequenceConfigurabilityInto(
    outResult, outResult.configurability)
  outResult.firstBlock = outResult.configurability.firstBlock
  outResult.allConfigurable = outResult.configurability.configurable

proc blaiPlanForwardModelRunSequence*(
    layers: openArray[BlaiCpuInstLayer64],
    modelResources: BlaiForwardModelResourcePlan,
    workspace: BlaiForwardModelWorkspacePlan): BlaiForwardModelRunSequencePlan =
  ## Convenience result-returning wrapper for run-sequence planning.
  blaiPlanForwardModelRunSequenceInto(
    layers, modelResources, workspace, result)

proc blaiPlanForwardModelRunSequenceInto*(
    layers: openArray[BlaiCpuParsedLayerState],
    modelResources: BlaiForwardModelResourcePlan,
    workspace: BlaiForwardModelWorkspacePlan,
    outResult: var BlaiForwardModelRunSequencePlan) =
  ## Build recovered per-layer run plans from parsed layer state.
  outResult = default(BlaiForwardModelRunSequencePlan)
  outResult.layerCount = blaiOpenArrayLenU32(layers)
  outResult.expectedLayerCount = modelResources.layerCount
  outResult.layerStorageFits = outResult.layerCount >= outResult.expectedLayerCount
  if not outResult.layerStorageFits:
    outResult.missingLayerCount =
      outResult.expectedLayerCount - outResult.layerCount
  outResult.firstBlockedLayer = -1
  outResult.lastConfigurableLayer = -1
  var readiness: BlaiForwardModelRunSequenceReadiness
  blaiForwardModelRunSequenceReadinessInto(
    modelResources, workspace, readiness)
  outResult.readiness = readiness
  outResult.supported = readiness.resourcesSupported
  outResult.workspaceReady = readiness.workspaceReady
  outResult.readinessFirstBlock = readiness.firstBlock
  if not readiness.ready or not outResult.layerStorageFits:
    blaiForwardModelRunSequenceConfigurabilityInto(
      outResult, outResult.configurability)
    outResult.firstBlock = outResult.configurability.firstBlock
    outResult.allConfigurable = outResult.configurability.configurable
    return

  for layerIndex in 0 ..< layers.len:
    if not layers[layerIndex].active or layers[layerIndex].layer.npuOn == 0:
      inc outResult.skippedLayerCount
      continue

    inc outResult.attemptedLayerCount
    var runPlan: BlaiForwardNpuRunPlan
    blaiPlanForwardNpuRunInto(
      layers[layerIndex].layer, layers[layerIndex].index,
      dataBufferBytes = workspace.data.bytes,
      instAddr = workspace.instruction.address,
      dataBufferAddr = workspace.data.address,
      runPlan,
      weightAddr = workspace.weight.address,
      biasAddr = workspace.bias.address)
    outResult.lastRun = runPlan
    outResult.cacheRangeCount += runPlan.cacheRangeCount
    if runPlan.configurable:
      inc outResult.configurableLayerCount
      outResult.lastConfigurableLayer = blaiLayerIndexValue(layerIndex)
    else:
      inc outResult.blockedLayerCount
      if outResult.firstBlockedLayer < 0:
        outResult.firstBlockedLayer = blaiLayerIndexValue(layerIndex)
        outResult.firstBlockedRunCaptured = true
        outResult.firstBlockedRunConfigReadiness =
          runPlan.configReadiness
        outResult.firstBlockedRunConfigFirstBlock =
          runPlan.configReadiness.firstBlock

  blaiForwardModelRunSequenceConfigurabilityInto(
    outResult, outResult.configurability)
  outResult.firstBlock = outResult.configurability.firstBlock
  outResult.allConfigurable = outResult.configurability.configurable

proc blaiPlanForwardModelRunSequence*(
    layers: openArray[BlaiCpuParsedLayerState],
    modelResources: BlaiForwardModelResourcePlan,
    workspace: BlaiForwardModelWorkspacePlan): BlaiForwardModelRunSequencePlan =
  ## Convenience result-returning wrapper for parsed run-sequence planning.
  blaiPlanForwardModelRunSequenceInto(
    layers, modelResources, workspace, result)

proc blaiForwardModelExecuteCompletionInto*(
    execution: BlaiForwardModelExecuteResult,
    outResult: var BlaiForwardModelExecuteCompletion) =
  ## Derive terminal completion status for prepared model execution.
  outResult = default(BlaiForwardModelExecuteCompletion)
  outResult.runnable = execution.runnable
  outResult.layerCount = execution.layerCount
  outResult.expectedLayerCount = execution.expectedLayerCount
  outResult.layerStorageFits = execution.layerStorageFits
  outResult.missingLayerCount = execution.missingLayerCount
  outResult.attemptedLayerCount = execution.attemptedLayerCount
  outResult.completedLayerCount = execution.completedLayerCount
  outResult.failedLayerCount = execution.failedLayerCount
  outResult.firstFailedLayer = execution.firstFailedLayer
  outResult.lastCompletedLayer = execution.lastCompletedLayer
  outResult.runSequenceFirstBlock = execution.runSequenceFirstBlock
  if not execution.layerStorageFits:
    outResult.firstBlock = blaiForwardModelExecuteLayerStorage
  elif not execution.runnable:
    outResult.firstBlock = blaiForwardModelExecuteRunSequence
  elif execution.failedLayerCount != 0:
    outResult.firstBlock = blaiForwardModelExecuteLayerExecution
  else:
    outResult.firstBlock = blaiForwardModelExecuteNoBlock
  outResult.completed = outResult.runnable and outResult.layerStorageFits and
    outResult.failedLayerCount == 0

proc blaiForwardModelExecuteCompletion*(
    execution: BlaiForwardModelExecuteResult): BlaiForwardModelExecuteCompletion =
  ## Convenience wrapper for prepared model execution completion.
  blaiForwardModelExecuteCompletionInto(execution, result)

proc blaiSetForwardModelExecuteRunSequence(
    sequence: BlaiForwardModelRunSequencePlan,
    outResult: var BlaiForwardModelExecuteResult) =
  outResult.expectedLayerCount = sequence.expectedLayerCount
  outResult.layerStorageFits = sequence.layerStorageFits
  outResult.missingLayerCount = sequence.missingLayerCount
  outResult.runSequenceFirstBlock = sequence.firstBlock
  outResult.runSequenceReadinessFirstBlock = sequence.readinessFirstBlock
  outResult.runSequenceFirstBlockedLayer = sequence.firstBlockedLayer
  outResult.runSequenceFirstBlockedRunCaptured =
    sequence.firstBlockedRunCaptured
  outResult.runSequenceFirstBlockedRunConfigFirstBlock =
    sequence.firstBlockedRunConfigFirstBlock
  outResult.runSequenceFirstBlockedRunConfigReadiness =
    sequence.firstBlockedRunConfigReadiness
  outResult.runnable = sequence.supported and sequence.workspaceReady and
    sequence.allConfigurable

proc blaiExecuteForwardModelRunSequenceInto*(
    layers: openArray[BlaiCpuInstLayer64],
    modelResources: BlaiForwardModelResourcePlan,
    workspace: BlaiForwardModelWorkspacePlan,
    executor: BlaiForwardLayerExecutor,
    outResult: var BlaiForwardModelExecuteResult) =
  ## Execute a prepared model's configurable run plans with a caller executor.
  outResult = default(BlaiForwardModelExecuteResult)
  outResult.layerCount = blaiOpenArrayLenU32(layers)
  outResult.firstFailedLayer = -1
  outResult.lastCompletedLayer = -1
  var sequence: BlaiForwardModelRunSequencePlan
  blaiPlanForwardModelRunSequenceInto(
    layers, modelResources, workspace, sequence)
  blaiSetForwardModelExecuteRunSequence(sequence, outResult)
  if not outResult.runnable:
    blaiForwardModelExecuteCompletionInto(outResult, outResult.completion)
    outResult.firstBlock = outResult.completion.firstBlock
    outResult.allCompleted = outResult.completion.completed
    return
  blaiPrepareForwardWorkspaceCacheInto(workspace, outResult.workspaceCache)
  if not outResult.workspaceCache.fits:
    outResult.failedLayerCount = 1
    outResult.firstFailedLayer = 0
    blaiForwardModelExecuteCompletionInto(outResult, outResult.completion)
    outResult.firstBlock = blaiForwardModelExecuteLayerExecution
    outResult.allCompleted = false
    return

  for layerIndex in 0 ..< layers.len:
    if layers[layerIndex].npuOn == 0:
      inc outResult.skippedLayerCount
      continue

    var runPlan: BlaiForwardNpuRunPlan
    blaiPlanForwardNpuRunInto(
      layers[layerIndex], layerIndex.uint32,
      dataBufferBytes = workspace.data.bytes,
      instAddr = workspace.instruction.address,
      dataBufferAddr = workspace.data.address,
      runPlan,
      weightAddr = workspace.weight.address,
      biasAddr = workspace.bias.address)
    if not runPlan.configurable:
      inc outResult.failedLayerCount
      if outResult.firstFailedLayer < 0:
        outResult.firstFailedLayer = blaiLayerIndexValue(layerIndex)
      blaiForwardModelExecuteCompletionInto(outResult, outResult.completion)
      outResult.firstBlock = outResult.completion.firstBlock
      outResult.allCompleted = outResult.completion.completed
      return

    inc outResult.attemptedLayerCount
    let execution = executor(runPlan, layerIndex.uint32)
    outResult.lastExecution = execution
    if not execution.completed and not outResult.firstFailedExecutionCaptured:
      outResult.firstFailedExecutionCaptured = true
      outResult.firstFailedExecution = execution
    if execution.completed:
      inc outResult.completedLayerCount
      outResult.lastCompletedLayer = blaiLayerIndexValue(layerIndex)
    else:
      inc outResult.failedLayerCount
      if outResult.firstFailedLayer < 0:
        outResult.firstFailedLayer = blaiLayerIndexValue(layerIndex)
      blaiForwardModelExecuteCompletionInto(outResult, outResult.completion)
      outResult.firstBlock = outResult.completion.firstBlock
      outResult.allCompleted = outResult.completion.completed
      return

  blaiForwardModelExecuteCompletionInto(outResult, outResult.completion)
  outResult.firstBlock = outResult.completion.firstBlock
  outResult.allCompleted = outResult.completion.completed

proc blaiExecuteForwardModelRunSequence*(
    layers: openArray[BlaiCpuInstLayer64],
    modelResources: BlaiForwardModelResourcePlan,
    workspace: BlaiForwardModelWorkspacePlan,
    executor: BlaiForwardLayerExecutor): BlaiForwardModelExecuteResult =
  ## Convenience result-returning wrapper for callback-driven execution.
  blaiExecuteForwardModelRunSequenceInto(
    layers, modelResources, workspace, executor, result)

proc blaiExecuteForwardModelRunSequenceInto*(
    layers: openArray[BlaiCpuParsedLayerState],
    modelResources: BlaiForwardModelResourcePlan,
    workspace: BlaiForwardModelWorkspacePlan,
    executor: BlaiForwardLayerExecutor,
    outResult: var BlaiForwardModelExecuteResult) =
  ## Execute parsed-state configurable run plans with a caller executor.
  outResult = default(BlaiForwardModelExecuteResult)
  outResult.layerCount = blaiOpenArrayLenU32(layers)
  outResult.firstFailedLayer = -1
  outResult.lastCompletedLayer = -1
  var sequence: BlaiForwardModelRunSequencePlan
  blaiPlanForwardModelRunSequenceInto(
    layers, modelResources, workspace, sequence)
  blaiSetForwardModelExecuteRunSequence(sequence, outResult)
  if not outResult.runnable:
    blaiForwardModelExecuteCompletionInto(outResult, outResult.completion)
    outResult.firstBlock = outResult.completion.firstBlock
    outResult.allCompleted = outResult.completion.completed
    return
  blaiPrepareForwardWorkspaceCacheInto(workspace, outResult.workspaceCache)
  if not outResult.workspaceCache.fits:
    outResult.failedLayerCount = 1
    outResult.firstFailedLayer = 0
    blaiForwardModelExecuteCompletionInto(outResult, outResult.completion)
    outResult.firstBlock = blaiForwardModelExecuteLayerExecution
    outResult.allCompleted = false
    return

  for layerIndex in 0 ..< layers.len:
    if not layers[layerIndex].active or layers[layerIndex].layer.npuOn == 0:
      inc outResult.skippedLayerCount
      continue

    var runPlan: BlaiForwardNpuRunPlan
    blaiPlanForwardNpuRunInto(
      layers[layerIndex].layer, layers[layerIndex].index,
      dataBufferBytes = workspace.data.bytes,
      instAddr = workspace.instruction.address,
      dataBufferAddr = workspace.data.address,
      runPlan,
      weightAddr = workspace.weight.address,
      biasAddr = workspace.bias.address)
    if not runPlan.configurable:
      inc outResult.failedLayerCount
      if outResult.firstFailedLayer < 0:
        outResult.firstFailedLayer = blaiLayerIndexValue(layerIndex)
      blaiForwardModelExecuteCompletionInto(outResult, outResult.completion)
      outResult.firstBlock = outResult.completion.firstBlock
      outResult.allCompleted = outResult.completion.completed
      return

    inc outResult.attemptedLayerCount
    let execution = executor(runPlan, layerIndex.uint32)
    outResult.lastExecution = execution
    if not execution.completed and not outResult.firstFailedExecutionCaptured:
      outResult.firstFailedExecutionCaptured = true
      outResult.firstFailedExecution = execution
    if execution.completed:
      inc outResult.completedLayerCount
      outResult.lastCompletedLayer = blaiLayerIndexValue(layerIndex)
    else:
      inc outResult.failedLayerCount
      if outResult.firstFailedLayer < 0:
        outResult.firstFailedLayer = blaiLayerIndexValue(layerIndex)
      blaiForwardModelExecuteCompletionInto(outResult, outResult.completion)
      outResult.firstBlock = outResult.completion.firstBlock
      outResult.allCompleted = outResult.completion.completed
      return

  blaiForwardModelExecuteCompletionInto(outResult, outResult.completion)
  outResult.firstBlock = outResult.completion.firstBlock
  outResult.allCompleted = outResult.completion.completed

proc blaiExecuteForwardModelRunSequence*(
    layers: openArray[BlaiCpuParsedLayerState],
    modelResources: BlaiForwardModelResourcePlan,
    workspace: BlaiForwardModelWorkspacePlan,
    executor: BlaiForwardLayerExecutor): BlaiForwardModelExecuteResult =
  ## Convenience result-returning wrapper for parsed callback execution.
  blaiExecuteForwardModelRunSequenceInto(
    layers, modelResources, workspace, executor, result)

proc blaiForwardModelWorkspaceExecuteReadinessInto*(
    modelResources: BlaiForwardModelResourcePlan,
    workspace: BlaiForwardModelWorkspacePlan,
    workspaceBytes: uint32,
    outResult: var BlaiForwardModelWorkspaceExecuteReadiness) =
  ## Explain whether reusable-workspace model execution can start safely.
  outResult = default(BlaiForwardModelWorkspaceExecuteReadiness)
  outResult.workspaceBytes = workspaceBytes
  blaiForwardModelRunSequenceReadinessInto(
    modelResources, workspace, outResult.runSequence)
  blaiForwardWorkspaceFitsInto(
    workspace, workspaceBytes, outResult.workspaceFit)
  outResult.runnable = outResult.runSequence.ready
  outResult.workspaceBacked = outResult.workspaceFit.fits
  if not outResult.runnable:
    outResult.firstBlock =
      blaiForwardModelWorkspaceExecuteReadinessRunSequence
  elif not outResult.workspaceBacked:
    outResult.firstBlock =
      blaiForwardModelWorkspaceExecuteReadinessWorkspace
  else:
    outResult.firstBlock =
      blaiForwardModelWorkspaceExecuteReadinessNoBlock
  outResult.executable = outResult.runnable and outResult.workspaceBacked

proc blaiForwardModelWorkspaceExecuteReadiness*(
    modelResources: BlaiForwardModelResourcePlan,
    workspace: BlaiForwardModelWorkspacePlan,
    workspaceBytes: uint32): BlaiForwardModelWorkspaceExecuteReadiness =
  ## Convenience wrapper for reusable-workspace execution readiness.
  blaiForwardModelWorkspaceExecuteReadinessInto(
    modelResources, workspace, workspaceBytes, result)

proc blaiForwardModelWorkspaceExecuteCompletionInto*(
    execution: BlaiForwardModelWorkspaceExecuteResult,
    outResult: var BlaiForwardModelWorkspaceExecuteCompletion) =
  ## Derive terminal completion status for reusable-workspace model execution.
  outResult = default(BlaiForwardModelWorkspaceExecuteCompletion)
  outResult.runnable = execution.runnable
  outResult.layerCount = execution.layerCount
  outResult.expectedLayerCount = execution.expectedLayerCount
  outResult.layerStorageFits = execution.layerStorageFits
  outResult.missingLayerCount = execution.missingLayerCount
  outResult.attemptedLayerCount = execution.attemptedLayerCount
  outResult.materializedLayerCount = execution.materializedLayerCount
  outResult.completedLayerCount = execution.completedLayerCount
  outResult.blockedLayerCount = execution.blockedLayerCount
  outResult.failedLayerCount = execution.failedLayerCount
  outResult.firstBlockedLayer = execution.firstBlockedLayer
  outResult.firstFailedLayer = execution.firstFailedLayer
  outResult.lastMaterializedLayer = execution.lastMaterializedLayer
  outResult.lastCompletedLayer = execution.lastCompletedLayer
  outResult.completed = outResult.runnable and
    outResult.layerStorageFits and outResult.blockedLayerCount == 0 and
    outResult.failedLayerCount == 0

proc blaiForwardModelWorkspaceExecuteCompletion*(
    execution: BlaiForwardModelWorkspaceExecuteResult):
    BlaiForwardModelWorkspaceExecuteCompletion =
  ## Convenience wrapper for reusable-workspace execution completion.
  blaiForwardModelWorkspaceExecuteCompletionInto(execution, result)

proc blaiMaterializeAndExecuteForwardModelWorkspaceInto*(
    layers: var openArray[BlaiCpuInstLayer64],
    useTflite: bool,
    ctrl: var BlaiPsramCtrl,
    stream: var openArray[BlaiInstruction],
    modelResources: BlaiForwardModelResourcePlan,
    workspace: BlaiForwardModelWorkspacePlan,
    workspaceBytes: var openArray[uint8],
    cpuWeightBytes: openArray[uint8],
    cpuBiasBytes: openArray[uint8],
    decodedWeights: var openArray[int32],
    decodedBiases: var openArray[int32],
    npuWeightBytes: var openArray[uint8],
    npuBiases: var openArray[int32],
    temporaryWeights: var openArray[int32],
    executor: BlaiForwardLayerExecutor,
    pack: uint32 = BlaiNpuWeightPack,
    c2: uint32 = 0'u32,
    includeExtra: bool = false,
    descriptorHalt: bool = false,
    midOutState: bool = false,
    outResult: var BlaiForwardModelWorkspaceExecuteResult) =
  ## Materialize each NPU layer into reusable workspace bytes, then execute it.
  ##
  ## This is the execution-oriented counterpart to
  ## `blaiMaterializeForwardModelWorkspace`: since the workspace is reused for
  ## every layer, each materialized layer is run before the next layer overwrites
  ## the instruction, weight, and bias segments.
  outResult = default(BlaiForwardModelWorkspaceExecuteResult)
  outResult.layerCount = blaiOpenArrayLenU32(layers)
  outResult.expectedLayerCount = modelResources.layerCount
  outResult.layerStorageFits = outResult.layerCount >= outResult.expectedLayerCount
  if not outResult.layerStorageFits:
    outResult.missingLayerCount =
      outResult.expectedLayerCount - outResult.layerCount
  outResult.firstBlockedLayer = -1
  outResult.firstFailedLayer = -1
  outResult.lastMaterializedLayer = -1
  outResult.lastCompletedLayer = -1
  outResult.nextWeightCursor = blaiCpuStreamCursor()
  outResult.nextBiasCursor = blaiCpuStreamCursor()
  blaiForwardModelWorkspaceExecuteReadinessInto(
    modelResources, workspace, blaiBufferLenU32(workspaceBytes.len),
    outResult.readiness)
  outResult.readinessFirstBlock = outResult.readiness.firstBlock
  outResult.runnable = outResult.readiness.runnable and
    outResult.layerStorageFits
  if not outResult.runnable:
    if not outResult.layerStorageFits:
      outResult.firstBlock = blaiForwardModelWorkspaceExecuteLayerStorage
    else:
      outResult.firstBlock = blaiForwardModelWorkspaceExecuteReadiness
    blaiForwardModelWorkspaceExecuteCompletionInto(
      outResult, outResult.completion)
    outResult.allCompleted = outResult.completion.completed
    return

  for layerIndex in 0 ..< layers.len:
    if layers[layerIndex].npuOn == 0:
      inc outResult.skippedLayerCount
      continue

    inc outResult.attemptedLayerCount
    var layerResult: BlaiForwardLayerWorkspaceMaterializeResult
    blaiMaterializeForwardLayerWorkspaceInto(
      layers, layerIndex.uint32, useTflite, ctrl, stream, modelResources,
      workspace, workspaceBytes, cpuWeightBytes, cpuBiasBytes,
      outResult.nextWeightCursor, outResult.nextBiasCursor,
      decodedWeights, decodedBiases, npuWeightBytes, npuBiases,
      temporaryWeights, pack, c2, includeExtra, descriptorHalt, midOutState,
      layerResult)
    outResult.lastLayer = layerResult
    if not layerResult.ready:
      inc outResult.blockedLayerCount
      if outResult.firstBlockedLayer < 0:
        outResult.firstBlockedLayer = blaiLayerIndexValue(layerIndex)
        outResult.firstBlockedLayerCaptured = true
        outResult.firstBlockedLayerReadiness = layerResult.readiness
        outResult.firstBlockedLayerFirstBlock = layerResult.firstBlock
        outResult.firstBlockedInstructionFirstBlock =
          layerResult.instructionFirstBlock
        outResult.firstBlockedWeightWorkspaceFirstBlock =
          layerResult.weightWorkspaceFirstBlock
      outResult.firstBlock = blaiForwardModelWorkspaceExecuteMaterialization
      blaiForwardModelWorkspaceExecuteCompletionInto(
        outResult, outResult.completion)
      outResult.allCompleted = outResult.completion.completed
      return

    inc outResult.materializedLayerCount
    outResult.lastMaterializedLayer = blaiLayerIndexValue(layerIndex)
    outResult.nextWeightCursor = layerResult.nextWeightCursor
    outResult.nextBiasCursor = layerResult.nextBiasCursor

    let runPlan = layerResult.instructions.prepared.run
    if not runPlan.configurable:
      inc outResult.failedLayerCount
      if outResult.firstFailedLayer < 0:
        outResult.firstFailedLayer = blaiLayerIndexValue(layerIndex)
      outResult.firstBlock = blaiForwardModelWorkspaceExecuteLayerExecution
      blaiForwardModelWorkspaceExecuteCompletionInto(
        outResult, outResult.completion)
      outResult.allCompleted = outResult.completion.completed
      return

    let execution = executor(runPlan, layerIndex.uint32)
    outResult.lastExecution = execution
    if not execution.completed and not outResult.firstFailedExecutionCaptured:
      outResult.firstFailedExecutionCaptured = true
      outResult.firstFailedExecution = execution
    if execution.completed:
      inc outResult.completedLayerCount
      outResult.lastCompletedLayer = blaiLayerIndexValue(layerIndex)
    else:
      inc outResult.failedLayerCount
      if outResult.firstFailedLayer < 0:
        outResult.firstFailedLayer = blaiLayerIndexValue(layerIndex)
      outResult.firstBlock = blaiForwardModelWorkspaceExecuteLayerExecution
      blaiForwardModelWorkspaceExecuteCompletionInto(
        outResult, outResult.completion)
      outResult.allCompleted = outResult.completion.completed
      return

  blaiForwardModelWorkspaceExecuteCompletionInto(
    outResult, outResult.completion)
  outResult.firstBlock = blaiForwardModelWorkspaceExecuteNoBlock
  outResult.allCompleted = outResult.completion.completed

proc blaiMaterializeAndExecuteForwardModelWorkspace*(
    layers: var openArray[BlaiCpuInstLayer64],
    useTflite: bool,
    ctrl: var BlaiPsramCtrl,
    stream: var openArray[BlaiInstruction],
    modelResources: BlaiForwardModelResourcePlan,
    workspace: BlaiForwardModelWorkspacePlan,
    workspaceBytes: var openArray[uint8],
    cpuWeightBytes: openArray[uint8],
    cpuBiasBytes: openArray[uint8],
    decodedWeights: var openArray[int32],
    decodedBiases: var openArray[int32],
    npuWeightBytes: var openArray[uint8],
    npuBiases: var openArray[int32],
    temporaryWeights: var openArray[int32],
    executor: BlaiForwardLayerExecutor,
    pack: uint32 = BlaiNpuWeightPack,
    c2: uint32 = 0'u32,
    includeExtra: bool = false,
    descriptorHalt: bool = false,
    midOutState: bool = false): BlaiForwardModelWorkspaceExecuteResult =
  ## Convenience result-returning wrapper for materialize-and-execute.
  blaiMaterializeAndExecuteForwardModelWorkspaceInto(
    layers, useTflite, ctrl, stream, modelResources, workspace, workspaceBytes,
    cpuWeightBytes, cpuBiasBytes, decodedWeights, decodedBiases, npuWeightBytes,
    npuBiases, temporaryWeights, executor, pack, c2, includeExtra,
    descriptorHalt, midOutState, result)

proc blaiParsedForwardModelExecuteReadinessInto*(
    parsed: BlaiCpuModelParseResult,
    plan: BlaiParsedForwardModelPlan,
    workspaceBytes: uint32,
    suppliedLayerCount: uint32,
    outResult: var BlaiParsedForwardModelExecuteReadiness) =
  ## Explain whether a parsed, encoded model can enter NPU workspace execution.
  outResult = default(BlaiParsedForwardModelExecuteReadiness)
  outResult.parsedComplete = parsed.complete
  outResult.planMatchesLayers = true
  outResult.workspaceReady = plan.workspaceReady
  outResult.layerCount = suppliedLayerCount
  outResult.expectedLayerCount = plan.readiness.layerCount
  outResult.layerStorageFits = plan.readiness.layerStorageFits and
    suppliedLayerCount >= outResult.expectedLayerCount
  if not outResult.layerStorageFits:
    if suppliedLayerCount < outResult.expectedLayerCount:
      outResult.missingLayerCount =
        outResult.expectedLayerCount - suppliedLayerCount
    else:
      outResult.missingLayerCount = plan.readiness.missingLayerCount
  outResult.forwardReady =
    plan.readiness.forwardReady and outResult.layerStorageFits
  blaiForwardModelWorkspaceExecuteReadinessInto(
    plan.resources, plan.workspace, workspaceBytes,
    outResult.workspaceExecution)
  outResult.workspaceFits =
    outResult.workspaceReady and outResult.workspaceExecution.workspaceBacked
  if not outResult.parsedComplete:
    outResult.firstBlock = blaiParsedForwardModelExecuteParsed
  elif not outResult.forwardReady:
    outResult.firstBlock = blaiParsedForwardModelExecuteForward
  elif not outResult.planMatchesLayers:
    outResult.firstBlock = blaiParsedForwardModelExecutePlan
  elif not outResult.workspaceReady:
    outResult.firstBlock = blaiParsedForwardModelExecuteWorkspace
  elif not outResult.workspaceFits:
    outResult.firstBlock = blaiParsedForwardModelExecuteWorkspaceBacking
  else:
    outResult.firstBlock = blaiParsedForwardModelExecuteNoBlock
  outResult.executable =
    outResult.parsedComplete and outResult.forwardReady and
    outResult.planMatchesLayers and
    outResult.workspaceReady and outResult.workspaceFits

proc blaiParsedForwardModelExecuteReadiness*(
    parsed: BlaiCpuModelParseResult,
    plan: BlaiParsedForwardModelPlan,
    workspaceBytes: uint32,
    suppliedLayerCount: uint32): BlaiParsedForwardModelExecuteReadiness =
  ## Convenience wrapper for parsed model execution readiness.
  blaiParsedForwardModelExecuteReadinessInto(
    parsed, plan, workspaceBytes, suppliedLayerCount, result)

proc blaiSameNpuNetParams(a, b: NpuNetParams): bool =
  a.unsignedInput == b.unsignedInput and
    a.reluN == b.reluN and
    a.tensorflowMode == b.tensorflowMode

proc blaiSameForwardEncodedLayerReadiness(
    a, b: BlaiForwardEncodedLayerReadiness): bool =
  a.npuLayer == b.npuLayer and
    a.patchReady == b.patchReady and
    a.instructionReady == b.instructionReady and
    a.ready == b.ready

proc blaiSameParsedForwardModelReadiness(
    a, b: BlaiParsedForwardModelReadiness): bool =
  a.parsed == b.parsed and
    a.useTflite == b.useTflite and
    blaiSameNpuNetParams(a.netParams, b.netParams) and
    a.layerCount == b.layerCount and
    a.layerStorageFits == b.layerStorageFits and
    a.missingLayerCount == b.missingLayerCount and
    a.npuLayerCount == b.npuLayerCount and
    a.readyLayerCount == b.readyLayerCount and
    a.unencodedLayerCount == b.unencodedLayerCount and
    a.firstUnencodedLayer == b.firstUnencodedLayer and
    a.lastReadyLayer == b.lastReadyLayer and
    a.firstUnencodedLayerCaptured == b.firstUnencodedLayerCaptured and
    blaiSameForwardEncodedLayerReadiness(
      a.firstUnencodedLayerReadiness, b.firstUnencodedLayerReadiness) and
    a.forwardReady == b.forwardReady

proc blaiSameCpuStreamTotals(a, b: BlaiCpuStreamTotals): bool =
  a.useTflite == b.useTflite and
    a.weightLayerCount == b.weightLayerCount and
    a.biasLayerCount == b.biasLayerCount and
    a.firstWeightLayer == b.firstWeightLayer and
    a.firstBiasLayer == b.firstBiasLayer and
    a.cpuWeightStreamBytes == b.cpuWeightStreamBytes and
    a.cpuBiasStreamBytes == b.cpuBiasStreamBytes

proc blaiSameForwardModelResourcePlan(
    a, b: BlaiForwardModelResourcePlan): bool =
  a.supported == b.supported and
    a.layerCount == b.layerCount and
    a.npuLayerCount == b.npuLayerCount and
    a.instructionBytes == b.instructionBytes and
    a.dataBufferBytes == b.dataBufferBytes and
    a.weightBufferBytes == b.weightBufferBytes and
    a.biasBufferBytes == b.biasBufferBytes and
    a.temporaryWeightElements == b.temporaryWeightElements and
    a.temporaryWeightBytes == b.temporaryWeightBytes and
    blaiSameCpuStreamTotals(a.cpuStreams, b.cpuStreams) and
    a.cpuWeightStreamBytes == b.cpuWeightStreamBytes and
    a.cpuBiasStreamBytes == b.cpuBiasStreamBytes

proc blaiParsedForwardPlanMatchesLayers(
    parsed: BlaiCpuModelParseResult,
    layers: openArray[BlaiCpuInstLayer64],
    plan: BlaiParsedForwardModelPlan): bool =
  var currentReadiness: BlaiParsedForwardModelReadiness
  blaiParsedForwardModelReadinessInto(parsed, layers, currentReadiness)
  if not blaiSameParsedForwardModelReadiness(
      currentReadiness, plan.readiness):
    return false
  var currentResources: BlaiForwardModelResourcePlan
  if currentReadiness.forwardReady:
    let layerCount = blaiBoundedU32Count(currentReadiness.layerCount, layers.len)
    if layerCount > 0:
      blaiPlanForwardModelResourcesInto(
        layers.toOpenArray(0, layerCount - 1), currentReadiness.useTflite,
        currentResources)
    else:
      currentResources.supported = true
  blaiSameForwardModelResourcePlan(currentResources, plan.resources)

proc blaiParsedForwardPlanMatchesLayers(
    parsed: BlaiCpuModelParseResult,
    layers: openArray[BlaiCpuParsedLayerState],
    plan: BlaiParsedForwardModelPlan): bool =
  var currentReadiness: BlaiParsedForwardModelReadiness
  blaiParsedForwardModelReadinessInto(parsed, layers, currentReadiness)
  if not blaiSameParsedForwardModelReadiness(
      currentReadiness, plan.readiness):
    return false
  var currentResources: BlaiForwardModelResourcePlan
  if currentReadiness.forwardReady:
    let layerCount = blaiBoundedU32Count(currentReadiness.layerCount, layers.len)
    if layerCount > 0:
      blaiPlanForwardModelResourcesInto(
        layers.toOpenArray(0, layerCount - 1), currentReadiness.useTflite,
        currentResources)
    else:
      currentResources.supported = true
  blaiSameForwardModelResourcePlan(currentResources, plan.resources)

proc blaiFinalizeParsedForwardExecuteReadiness(
    outResult: var BlaiParsedForwardModelExecuteReadiness) =
  if not outResult.parsedComplete:
    outResult.firstBlock = blaiParsedForwardModelExecuteParsed
  elif not outResult.forwardReady:
    outResult.firstBlock = blaiParsedForwardModelExecuteForward
  elif not outResult.planMatchesLayers:
    outResult.firstBlock = blaiParsedForwardModelExecutePlan
  elif not outResult.workspaceReady:
    outResult.firstBlock = blaiParsedForwardModelExecuteWorkspace
  elif not outResult.workspaceFits:
    outResult.firstBlock = blaiParsedForwardModelExecuteWorkspaceBacking
  else:
    outResult.firstBlock = blaiParsedForwardModelExecuteNoBlock
  outResult.executable =
    outResult.parsedComplete and outResult.forwardReady and
    outResult.planMatchesLayers and outResult.workspaceReady and
    outResult.workspaceFits

proc blaiParsedForwardModelExecuteReadinessInto*(
    parsed: BlaiCpuModelParseResult,
    layers: openArray[BlaiCpuInstLayer64],
    plan: BlaiParsedForwardModelPlan,
    workspaceBytes: uint32,
    outResult: var BlaiParsedForwardModelExecuteReadiness) =
  ## Explain whether a parsed model plan still matches its encoded layer table.
  blaiParsedForwardModelExecuteReadinessInto(
    parsed, plan, workspaceBytes, blaiOpenArrayLenU32(layers), outResult)
  if outResult.parsedComplete and outResult.forwardReady:
    outResult.planMatchesLayers =
      blaiParsedForwardPlanMatchesLayers(parsed, layers, plan)
    blaiFinalizeParsedForwardExecuteReadiness(outResult)

proc blaiParsedForwardModelExecuteReadiness*(
    parsed: BlaiCpuModelParseResult,
    layers: openArray[BlaiCpuInstLayer64],
    plan: BlaiParsedForwardModelPlan,
    workspaceBytes: uint32): BlaiParsedForwardModelExecuteReadiness =
  ## Convenience wrapper for layer-table checked parsed model execution readiness.
  blaiParsedForwardModelExecuteReadinessInto(
    parsed, layers, plan, workspaceBytes, result)

proc blaiParsedForwardModelExecuteReadinessInto*(
    parsed: BlaiCpuModelParseResult,
    layers: openArray[BlaiCpuParsedLayerState],
    plan: BlaiParsedForwardModelPlan,
    workspaceBytes: uint32,
    outResult: var BlaiParsedForwardModelExecuteReadiness) =
  ## Explain whether a parsed-state model plan still matches its layer table.
  blaiParsedForwardModelExecuteReadinessInto(
    parsed, plan, workspaceBytes, blaiOpenArrayLenU32(layers), outResult)
  if outResult.parsedComplete and outResult.forwardReady:
    outResult.planMatchesLayers =
      blaiParsedForwardPlanMatchesLayers(parsed, layers, plan)
    blaiFinalizeParsedForwardExecuteReadiness(outResult)

proc blaiParsedForwardModelExecuteReadiness*(
    parsed: BlaiCpuModelParseResult,
    layers: openArray[BlaiCpuParsedLayerState],
    plan: BlaiParsedForwardModelPlan,
    workspaceBytes: uint32): BlaiParsedForwardModelExecuteReadiness =
  ## Convenience wrapper for parsed-state checked model execution readiness.
  blaiParsedForwardModelExecuteReadinessInto(
    parsed, layers, plan, workspaceBytes, result)

proc blaiParsedForwardModelExecuteReadinessInto*(
    parsed: BlaiCpuModelParseResult,
    plan: BlaiParsedForwardModelPlan,
    workspaceBytes: uint32,
    outResult: var BlaiParsedForwardModelExecuteReadiness) =
  ## Explain whether a parsed, encoded model can enter NPU workspace execution.
  blaiParsedForwardModelExecuteReadinessInto(
    parsed, plan, workspaceBytes, plan.readiness.layerCount, outResult)

proc blaiParsedForwardModelExecuteReadiness*(
    parsed: BlaiCpuModelParseResult,
    plan: BlaiParsedForwardModelPlan,
    workspaceBytes: uint32): BlaiParsedForwardModelExecuteReadiness =
  ## Convenience wrapper for parsed model execution readiness.
  blaiParsedForwardModelExecuteReadinessInto(
    parsed, plan, workspaceBytes, result)

proc blaiMaterializeAndExecuteParsedForwardModelWorkspaceInto*(
    parsed: BlaiCpuModelParseResult,
    layers: var openArray[BlaiCpuInstLayer64],
    plan: BlaiParsedForwardModelPlan,
    ctrl: var BlaiPsramCtrl,
    stream: var openArray[BlaiInstruction],
    workspaceBytes: var openArray[uint8],
    cpuWeightBytes: openArray[uint8],
    cpuBiasBytes: openArray[uint8],
    decodedWeights: var openArray[int32],
    decodedBiases: var openArray[int32],
    npuWeightBytes: var openArray[uint8],
    npuBiases: var openArray[int32],
    temporaryWeights: var openArray[int32],
    executor: BlaiForwardLayerExecutor,
    pack: uint32 = BlaiNpuWeightPack,
    c2: uint32 = 0'u32,
    includeExtra: bool = false,
    descriptorHalt: bool = false,
    midOutState: bool = false,
    outResult: var BlaiParsedForwardModelExecuteResult) =
  ## Materialize and execute a parsed CPU model after workspace planning.
  ##
  ## The supplied plan must come from `blaiPlanParsedForwardModelWorkspace` for
  ## the same parsed layer table. This wrapper only checks the parsed/encoded
  ## readiness and caller-owned workspace backing size before delegating to the
  ## reusable per-layer materialize-and-execute path.
  outResult = default(BlaiParsedForwardModelExecuteResult)
  outResult.plan = plan
  blaiParsedForwardModelExecuteReadinessInto(
    parsed, layers, plan, blaiBufferLenU32(workspaceBytes.len),
    outResult.readiness)
  outResult.workspaceFits = outResult.readiness.workspaceFits
  outResult.firstBlock = outResult.readiness.firstBlock
  outResult.executable = outResult.readiness.executable
  if not outResult.executable:
    return

  let layerCount = blaiBoundedU32Count(plan.readiness.layerCount, layers.len)
  if layerCount == 0:
    outResult.execution.layerCount = 0
    outResult.execution.expectedLayerCount = plan.resources.layerCount
    outResult.execution.layerStorageFits =
      outResult.execution.layerCount >= outResult.execution.expectedLayerCount
    if not outResult.execution.layerStorageFits:
      outResult.execution.missingLayerCount =
        outResult.execution.expectedLayerCount - outResult.execution.layerCount
    outResult.execution.runnable = true
    outResult.execution.firstBlockedLayer = -1
    outResult.execution.firstFailedLayer = -1
    outResult.execution.lastMaterializedLayer = -1
    outResult.execution.lastCompletedLayer = -1
    blaiForwardModelWorkspaceExecuteCompletionInto(
      outResult.execution, outResult.execution.completion)
    if not outResult.execution.layerStorageFits:
      outResult.execution.firstBlock =
        blaiForwardModelWorkspaceExecuteLayerStorage
    else:
      outResult.execution.firstBlock =
        blaiForwardModelWorkspaceExecuteNoBlock
    outResult.execution.allCompleted =
      outResult.execution.completion.completed
    return

  blaiMaterializeAndExecuteForwardModelWorkspaceInto(
    layers.toOpenArray(0, layerCount - 1), plan.readiness.useTflite,
    ctrl, stream, plan.resources, plan.workspace, workspaceBytes,
    cpuWeightBytes, cpuBiasBytes, decodedWeights, decodedBiases,
    npuWeightBytes, npuBiases, temporaryWeights, executor, pack, c2,
    includeExtra, descriptorHalt, midOutState, outResult.execution)

proc blaiMaterializeAndExecuteParsedForwardModelWorkspace*(
    parsed: BlaiCpuModelParseResult,
    layers: var openArray[BlaiCpuInstLayer64],
    plan: BlaiParsedForwardModelPlan,
    ctrl: var BlaiPsramCtrl,
    stream: var openArray[BlaiInstruction],
    workspaceBytes: var openArray[uint8],
    cpuWeightBytes: openArray[uint8],
    cpuBiasBytes: openArray[uint8],
    decodedWeights: var openArray[int32],
    decodedBiases: var openArray[int32],
    npuWeightBytes: var openArray[uint8],
    npuBiases: var openArray[int32],
    temporaryWeights: var openArray[int32],
    executor: BlaiForwardLayerExecutor,
    pack: uint32 = BlaiNpuWeightPack,
    c2: uint32 = 0'u32,
    includeExtra: bool = false,
    descriptorHalt: bool = false,
    midOutState: bool = false): BlaiParsedForwardModelExecuteResult =
  ## Convenience result-returning wrapper for parsed CPU model execution.
  blaiMaterializeAndExecuteParsedForwardModelWorkspaceInto(
    parsed, layers, plan, ctrl, stream, workspaceBytes, cpuWeightBytes,
    cpuBiasBytes, decodedWeights, decodedBiases, npuWeightBytes, npuBiases,
    temporaryWeights, executor, pack, c2, includeExtra, descriptorHalt,
    midOutState, result)

proc blaiMaterializeAndExecuteParsedForwardModelWorkspaceInto*(
    parsed: BlaiCpuModelParseResult,
    layers: var openArray[BlaiCpuParsedLayerState],
    plan: BlaiParsedForwardModelPlan,
    ctrl: var BlaiPsramCtrl,
    stream: var openArray[BlaiInstruction],
    workspaceBytes: var openArray[uint8],
    cpuWeightBytes: openArray[uint8],
    cpuBiasBytes: openArray[uint8],
    decodedWeights: var openArray[int32],
    decodedBiases: var openArray[int32],
    npuWeightBytes: var openArray[uint8],
    npuBiases: var openArray[int32],
    temporaryWeights: var openArray[int32],
    executor: BlaiForwardLayerExecutor,
    pack: uint32 = BlaiNpuWeightPack,
    c2: uint32 = 0'u32,
    includeExtra: bool = false,
    descriptorHalt: bool = false,
    midOutState: bool = false,
    outResult: var BlaiParsedForwardModelExecuteResult) =
  ## Materialize and execute parsed layer state after workspace planning.
  outResult = default(BlaiParsedForwardModelExecuteResult)
  outResult.plan = plan
  blaiParsedForwardModelExecuteReadinessInto(
    parsed, layers, plan, blaiBufferLenU32(workspaceBytes.len),
    outResult.readiness)
  outResult.workspaceFits = outResult.readiness.workspaceFits
  outResult.firstBlock = outResult.readiness.firstBlock
  outResult.executable = outResult.readiness.executable
  if not outResult.executable:
    return

  let layerCount = blaiBoundedU32Count(plan.readiness.layerCount, layers.len)
  outResult.execution.layerCount = layerCount.uint32
  outResult.execution.expectedLayerCount = plan.resources.layerCount
  outResult.execution.layerStorageFits =
    outResult.execution.layerCount >= outResult.execution.expectedLayerCount
  if not outResult.execution.layerStorageFits:
    outResult.execution.missingLayerCount =
      outResult.execution.expectedLayerCount - outResult.execution.layerCount
  outResult.execution.firstBlockedLayer = -1
  outResult.execution.firstFailedLayer = -1
  outResult.execution.lastMaterializedLayer = -1
  outResult.execution.lastCompletedLayer = -1
  outResult.execution.nextWeightCursor = blaiCpuStreamCursor()
  outResult.execution.nextBiasCursor = blaiCpuStreamCursor()
  blaiForwardModelWorkspaceExecuteReadinessInto(
    plan.resources, plan.workspace, blaiBufferLenU32(workspaceBytes.len),
    outResult.execution.readiness)
  outResult.execution.readinessFirstBlock =
    outResult.execution.readiness.firstBlock
  outResult.execution.runnable = outResult.execution.readiness.runnable and
    outResult.execution.layerStorageFits
  if layerCount == 0:
    outResult.execution.runnable = true
    blaiForwardModelWorkspaceExecuteCompletionInto(
      outResult.execution, outResult.execution.completion)
    if not outResult.execution.layerStorageFits:
      outResult.execution.firstBlock =
        blaiForwardModelWorkspaceExecuteLayerStorage
    else:
      outResult.execution.firstBlock =
        blaiForwardModelWorkspaceExecuteNoBlock
    outResult.execution.allCompleted =
      outResult.execution.completion.completed
    return
  if not outResult.execution.runnable:
    if not outResult.execution.layerStorageFits:
      outResult.execution.firstBlock =
        blaiForwardModelWorkspaceExecuteLayerStorage
    else:
      outResult.execution.firstBlock =
        blaiForwardModelWorkspaceExecuteReadiness
    blaiForwardModelWorkspaceExecuteCompletionInto(
      outResult.execution, outResult.execution.completion)
    outResult.execution.allCompleted =
      outResult.execution.completion.completed
    return

  for layerIndex in 0 ..< layerCount:
    if not layers[layerIndex].active or layers[layerIndex].layer.npuOn == 0:
      inc outResult.execution.skippedLayerCount
      continue

    inc outResult.execution.attemptedLayerCount
    var layerResult: BlaiForwardLayerWorkspaceMaterializeResult
    blaiMaterializeForwardLayerWorkspaceInto(
      layers, layerIndex.uint32, plan.readiness.useTflite, ctrl, stream,
      plan.resources, plan.workspace, workspaceBytes, cpuWeightBytes,
      cpuBiasBytes, outResult.execution.nextWeightCursor,
      outResult.execution.nextBiasCursor, decodedWeights, decodedBiases,
      npuWeightBytes, npuBiases, temporaryWeights, pack, c2, includeExtra,
      descriptorHalt, midOutState, layerResult)
    outResult.execution.lastLayer = layerResult
    if not layerResult.ready:
      inc outResult.execution.blockedLayerCount
      if outResult.execution.firstBlockedLayer < 0:
        outResult.execution.firstBlockedLayer =
          blaiLayerIndexValue(layerIndex)
        outResult.execution.firstBlockedLayerCaptured = true
        outResult.execution.firstBlockedLayerReadiness = layerResult.readiness
        outResult.execution.firstBlockedLayerFirstBlock =
          layerResult.firstBlock
        outResult.execution.firstBlockedInstructionFirstBlock =
          layerResult.instructionFirstBlock
        outResult.execution.firstBlockedWeightWorkspaceFirstBlock =
          layerResult.weightWorkspaceFirstBlock
      outResult.execution.firstBlock =
        blaiForwardModelWorkspaceExecuteMaterialization
      blaiForwardModelWorkspaceExecuteCompletionInto(
        outResult.execution, outResult.execution.completion)
      outResult.execution.allCompleted =
        outResult.execution.completion.completed
      return

    inc outResult.execution.materializedLayerCount
    outResult.execution.lastMaterializedLayer = blaiLayerIndexValue(layerIndex)
    outResult.execution.nextWeightCursor = layerResult.nextWeightCursor
    outResult.execution.nextBiasCursor = layerResult.nextBiasCursor

    let runPlan = layerResult.instructions.prepared.run
    if not runPlan.configurable:
      inc outResult.execution.failedLayerCount
      if outResult.execution.firstFailedLayer < 0:
        outResult.execution.firstFailedLayer = blaiLayerIndexValue(layerIndex)
      outResult.execution.firstBlock =
        blaiForwardModelWorkspaceExecuteLayerExecution
      blaiForwardModelWorkspaceExecuteCompletionInto(
        outResult.execution, outResult.execution.completion)
      outResult.execution.allCompleted =
        outResult.execution.completion.completed
      return

    let execution = executor(runPlan, layerIndex.uint32)
    outResult.execution.lastExecution = execution
    if not execution.completed and
        not outResult.execution.firstFailedExecutionCaptured:
      outResult.execution.firstFailedExecutionCaptured = true
      outResult.execution.firstFailedExecution = execution
    if execution.completed:
      inc outResult.execution.completedLayerCount
      outResult.execution.lastCompletedLayer = blaiLayerIndexValue(layerIndex)
    else:
      inc outResult.execution.failedLayerCount
      if outResult.execution.firstFailedLayer < 0:
        outResult.execution.firstFailedLayer = blaiLayerIndexValue(layerIndex)
      outResult.execution.firstBlock =
        blaiForwardModelWorkspaceExecuteLayerExecution
      blaiForwardModelWorkspaceExecuteCompletionInto(
        outResult.execution, outResult.execution.completion)
      outResult.execution.allCompleted =
        outResult.execution.completion.completed
      return

  blaiForwardModelWorkspaceExecuteCompletionInto(
    outResult.execution, outResult.execution.completion)
  outResult.execution.firstBlock = blaiForwardModelWorkspaceExecuteNoBlock
  outResult.execution.allCompleted =
    outResult.execution.completion.completed

proc blaiMaterializeAndExecuteParsedForwardModelWorkspace*(
    parsed: BlaiCpuModelParseResult,
    layers: var openArray[BlaiCpuParsedLayerState],
    plan: BlaiParsedForwardModelPlan,
    ctrl: var BlaiPsramCtrl,
    stream: var openArray[BlaiInstruction],
    workspaceBytes: var openArray[uint8],
    cpuWeightBytes: openArray[uint8],
    cpuBiasBytes: openArray[uint8],
    decodedWeights: var openArray[int32],
    decodedBiases: var openArray[int32],
    npuWeightBytes: var openArray[uint8],
    npuBiases: var openArray[int32],
    temporaryWeights: var openArray[int32],
    executor: BlaiForwardLayerExecutor,
    pack: uint32 = BlaiNpuWeightPack,
    c2: uint32 = 0'u32,
    includeExtra: bool = false,
    descriptorHalt: bool = false,
    midOutState: bool = false): BlaiParsedForwardModelExecuteResult =
  ## Convenience result-returning wrapper for parsed-state model execution.
  blaiMaterializeAndExecuteParsedForwardModelWorkspaceInto(
    parsed, layers, plan, ctrl, stream, workspaceBytes, cpuWeightBytes,
    cpuBiasBytes, decodedWeights, decodedBiases, npuWeightBytes, npuBiases,
    temporaryWeights, executor, pack, c2, includeExtra, descriptorHalt,
    midOutState, result)

proc blaiApplyForwardNpuCacheRangesInto*(
    plan: BlaiForwardNpuRunPlan,
    outResult: var BlaiForwardNpuCacheApplyResult) =
  ## Apply the recovered `forward_NPU` DATA-buffer cache maintenance sequence.
  outResult = default(BlaiForwardNpuCacheApplyResult)
  outResult.runnable = plan.runnable
  outResult.configurable = plan.configurable
  outResult.fits = true
  if not plan.runnable:
    outResult.applied = true
    return
  if not plan.configurable:
    outResult.fits = false
    return
  outResult.cacheRangeCount = plan.cacheRangeCount
  for cacheIndex in 0 ..< blaiForwardCacheRangeCount(plan.cacheRangeCount):
    let applied = blaiApplyCacheRange(
      plan.layerConfig.inputBufferAddr, plan.cacheRanges[cacheIndex])
    outResult.cacheRanges[cacheIndex] = applied
    if not applied.fits:
      outResult.fits = false
      return
  when defined(bl808d0) or defined(bl808m0) or defined(bl808lp):
    when nimvm:
      discard
    else:
      outResult.applied = true

proc blaiApplyForwardNpuCacheRanges*(
    plan: BlaiForwardNpuRunPlan): BlaiForwardNpuCacheApplyResult =
  ## Convenience result-returning wrapper for forward_NPU cache ranges.
  blaiApplyForwardNpuCacheRangesInto(plan, result)

proc blaiCompactTensorBytes*(plan: BlaiTensorTransferPlan): uint32 =
  if not plan.active or plan.paddedChannels == 0'u32:
    0'u32
  else:
    (plan.elements div plan.paddedChannels) * plan.actualChannels

proc blaiCompactTensorFitsInto*(plan: BlaiTensorTransferPlan,
                                tensorBytes: uint32,
                                outResult: var BlaiCompactTensorFitResult) =
  ## Check a caller-owned compact tensor against recovered padded movement.
  outResult = default(BlaiCompactTensorFitResult)
  outResult.active = plan.active
  outResult.requiredBytes = blaiCompactTensorBytes(plan)
  outResult.tensorBytes = tensorBytes
  if not plan.active:
    outResult.fits = true
    return
  outResult.fits = tensorBytes >= outResult.requiredBytes

proc blaiCompactTensorFits*(plan: BlaiTensorTransferPlan,
                            tensorBytes: uint32): bool =
  ## Boolean wrapper for compact tensor size checks.
  var fit: BlaiCompactTensorFitResult
  blaiCompactTensorFitsInto(plan, tensorBytes, fit)
  fit.fits

proc blaiTensorRowLayout*(plan: BlaiTensorTransferPlan): BlaiTensorRowLayout =
  ## Resolve recovered compact/padded tensor dimensions once for row loops.
  result.active = plan.active
  result.rowPadded = plan.rowPadded
  if not plan.active:
    result.valid = true
    return
  if plan.actualChannels > plan.paddedChannels:
    return
  if plan.paddedChannels == 0'u32:
    result.valid = true
    return
  let rowCount = plan.elements div plan.paddedChannels
  if not blaiU32ExactIntCount(rowCount, result.rows):
    return
  if not blaiU32ExactIntCount(plan.actualChannels, result.actualChannels):
    return
  if not blaiU32ExactIntCount(plan.paddedChannels, result.paddedChannels):
    return
  result.valid = true

proc blaiTensorRowIndex*(row, stride, channel: int): BlaiTensorRowIndex =
  ## Project one row/channel position to a flat byte index without overflow.
  if row < 0 or stride <= 0 or channel < 0 or channel >= stride:
    return
  if row > (high(int) - channel) div stride:
    return
  result.row = row
  result.channel = channel
  result.stride = stride
  result.index = row * stride + channel
  result.valid = true

proc blaiTensorRowByteCursor*(plan: BlaiTensorTransferPlan,
                              row, channel: int): BlaiTensorRowByteCursor =
  ## Resolve one compact/padded tensor row byte for DATA-buffer movement.
  if row < 0 or channel < 0:
    return
  let layout = blaiTensorRowLayout(plan)
  if not layout.valid:
    return
  let
    actual = layout.actualChannels
    padded = layout.paddedChannels
  let paddedIndex = blaiTensorRowIndex(row, padded, channel)
  if not paddedIndex.valid:
    return
  if row >= layout.rows:
    return
  result.row = row
  result.channel = channel
  result.paddedIndex = paddedIndex.index
  result.compactByte = channel < actual
  result.paddingByte = not result.compactByte
  if result.compactByte:
    let compactIndex = blaiTensorRowIndex(row, actual, channel)
    if not compactIndex.valid:
      return
    result.compactIndex = compactIndex.index
  result.valid = true

proc blaiStoreCompactTensorRows(plan: BlaiTensorTransferPlan,
                                tensor: openArray[uint8],
                                dataWindow: var openArray[uint8]) =
  let layout = blaiTensorRowLayout(plan)
  doAssert layout.valid
  for row in 0 ..< layout.rows:
    for c in 0 ..< layout.actualChannels:
      let cursor = blaiTensorRowByteCursor(plan, row, c)
      doAssert cursor.valid and cursor.compactByte
      dataWindow[cursor.paddedIndex] = tensor[cursor.compactIndex]
    for c in layout.actualChannels ..< layout.paddedChannels:
      let cursor = blaiTensorRowByteCursor(plan, row, c)
      doAssert cursor.valid and cursor.paddingByte
      dataWindow[cursor.paddedIndex] = 0

proc blaiLoadCompactTensorRows(plan: BlaiTensorTransferPlan,
                               dataWindow: openArray[uint8],
                               tensor: var openArray[uint8]) =
  let layout = blaiTensorRowLayout(plan)
  doAssert layout.valid
  for row in 0 ..< layout.rows:
    for c in 0 ..< layout.actualChannels:
      let cursor = blaiTensorRowByteCursor(plan, row, c)
      doAssert cursor.valid and cursor.compactByte
      tensor[cursor.compactIndex] = dataWindow[cursor.paddedIndex]

proc blaiTensorRowPatternValue*(row, rowStride, channel: uint32,
                                outValue: var uint8): bool =
  ## Project the recovered deterministic row/channel fixture byte exactly.
  let rowBase = blaiU64SaturatedMul(row.uint64, rowStride.uint64)
  let value = blaiU64SaturatedAdd(rowBase, channel.uint64)
  if value > high(uint8).uint64:
    return false
  outValue = value.uint8
  true

proc blaiStoreTensorRowPatternToNpuBuffer*(
    plan: BlaiTensorTransferPlan,
    patchSize: uint32,
    rowStride: uint32,
    npuBuffer: var openArray[uint8]): bool =
  ## Store a deterministic row/channel byte pattern through a tensor plan.
  ##
  ## This is used by fixtures that need to seed NPU output storage while still
  ## respecting the recovered compact-vs-padded row layout.
  if not plan.active:
    return true
  let window = blaiTensorBufferWindow(plan, patchSize, npuBuffer.len)
  if not window.fits:
    return false
  if window.count <= 0:
    return true
  let layout = blaiTensorRowLayout(plan)
  if not layout.valid:
    return false
  for row in 0 ..< layout.rows:
    for c in 0 ..< layout.paddedChannels:
      let cursor = blaiTensorRowByteCursor(plan, row, c)
      if not cursor.valid:
        return false
      if cursor.compactByte:
        var value: uint8
        if not blaiTensorRowPatternValue(row.uint32, rowStride, c.uint32, value):
          return false
        blaiTensorBufferOpenArray(npuBuffer, window)[cursor.paddedIndex] =
          value
      else:
        blaiTensorBufferOpenArray(npuBuffer, window)[cursor.paddedIndex] = 0
  true

proc blaiStoreTensorToNpuBufferInto*(plan: BlaiTensorTransferPlan,
                                     patchSize: uint32,
                                     tensor: openArray[uint8],
                                     npuBuffer: var openArray[uint8],
                                     outResult: var BlaiTensorBufferMoveResult) =
  ## Store one compact tensor into a padded NPU staging buffer.
  outResult = default(BlaiTensorBufferMoveResult)
  outResult.active = plan.active
  var bufferFit: BlaiTensorBufferFitResult
  blaiTensorBufferFitsInto(
    plan, patchSize, blaiBufferLenU32(npuBuffer.len), bufferFit)
  outResult.bufferFit = bufferFit
  outResult.bufferFits = bufferFit.fits
  var tensorFit: BlaiCompactTensorFitResult
  blaiCompactTensorFitsInto(plan, blaiBufferLenU32(tensor.len), tensorFit)
  outResult.tensorFit = tensorFit
  outResult.tensorFits = tensorFit.fits
  if not plan.active:
    outResult.moved = true
    return
  if not outResult.bufferFits or not outResult.tensorFits:
    return
  let window = blaiTensorBufferWindow(plan, patchSize, npuBuffer.len)
  if not window.fits:
    return
  if window.count <= 0:
    outResult.moved = true
    return
  blaiStoreCompactTensorRows(
    plan, tensor, blaiTensorBufferOpenArray(npuBuffer, window))
  outResult.moved = true

proc blaiStoreTensorToNpuBuffer*(plan: BlaiTensorTransferPlan,
                                 patchSize: uint32,
                                 tensor: openArray[uint8],
                                 npuBuffer: var openArray[uint8]): bool =
  ## Compatibility wrapper for caller-owned tensor staging results.
  var move: BlaiTensorBufferMoveResult
  blaiStoreTensorToNpuBufferInto(plan, patchSize, tensor, npuBuffer, move)
  move.moved

proc blaiLoadTensorFromNpuBufferInto*(plan: BlaiTensorTransferPlan,
                                      patchSize: uint32,
                                      npuBuffer: openArray[uint8],
                                      tensor: var openArray[uint8],
                                      outResult: var BlaiTensorBufferMoveResult) =
  ## Load one compact tensor from a padded NPU staging buffer.
  outResult = default(BlaiTensorBufferMoveResult)
  outResult.active = plan.active
  var bufferFit: BlaiTensorBufferFitResult
  blaiTensorBufferFitsInto(
    plan, patchSize, blaiBufferLenU32(npuBuffer.len), bufferFit)
  outResult.bufferFit = bufferFit
  outResult.bufferFits = bufferFit.fits
  var tensorFit: BlaiCompactTensorFitResult
  blaiCompactTensorFitsInto(plan, blaiBufferLenU32(tensor.len), tensorFit)
  outResult.tensorFit = tensorFit
  outResult.tensorFits = tensorFit.fits
  if not plan.active:
    outResult.moved = true
    return
  if not outResult.bufferFits or not outResult.tensorFits:
    return
  let window = blaiTensorBufferWindow(plan, patchSize, npuBuffer.len)
  if not window.fits:
    return
  if window.count <= 0:
    outResult.moved = true
    return
  blaiLoadCompactTensorRows(
    plan, blaiTensorBufferOpenArray(npuBuffer, window), tensor)
  outResult.moved = true

proc blaiLoadTensorFromNpuBuffer*(plan: BlaiTensorTransferPlan,
                                  patchSize: uint32,
                                  npuBuffer: openArray[uint8],
                                  tensor: var openArray[uint8]): bool =
  ## Compatibility wrapper for caller-owned tensor loading results.
  var move: BlaiTensorBufferMoveResult
  blaiLoadTensorFromNpuBufferInto(plan, patchSize, npuBuffer, tensor, move)
  move.moved

proc blaiForwardOutputTransfer*(plan: BlaiForwardNpuPlan,
                                kind: BlaiForwardOutputKind): BlaiTensorTransferPlan =
  ## Select a recovered `Load_NPU_data_to_tensor` output transfer.
  case kind
  of blaiForwardPrimaryOutput:
    plan.output.output
  of blaiForwardMidOutput:
    plan.output.midOutput

proc blaiForwardTensorIoReadinessInto*(runnable, active, bufferFits,
                                       tensorFits: bool,
                                       outResult: var BlaiForwardTensorIoReadiness) =
  ## Explain whether a forward_NPU compact tensor movement can run.
  outResult = default(BlaiForwardTensorIoReadiness)
  outResult.runnable = runnable
  outResult.active = active
  outResult.bufferFits = bufferFits
  outResult.tensorFits = tensorFits
  if not runnable:
    outResult.firstBlock = blaiForwardTensorIoRunnable
  elif not active:
    outResult.firstBlock = blaiForwardTensorIoActive
  elif not bufferFits:
    outResult.firstBlock = blaiForwardTensorIoBuffer
  elif not tensorFits:
    outResult.firstBlock = blaiForwardTensorIoTensor
  else:
    outResult.firstBlock = blaiForwardTensorIoNoBlock
  outResult.ready = runnable and active and bufferFits and tensorFits

proc blaiForwardTensorIoReadiness*(runnable, active, bufferFits,
                                   tensorFits: bool): BlaiForwardTensorIoReadiness =
  ## Convenience wrapper for forward_NPU tensor I/O readiness.
  blaiForwardTensorIoReadinessInto(
    runnable, active, bufferFits, tensorFits, result)

proc blaiStageForwardNpuInputInto*(plan: BlaiForwardNpuPlan,
                                   inputIndex: range[0 .. 7],
                                   tensor: openArray[uint8],
                                   dataBuffer: var openArray[uint8],
                                   outResult: var BlaiForwardTensorIoResult) =
  ## Stage one compact model input into a caller-owned forward_NPU DATA buffer.
  ##
  ## This composes the recovered `Store_tensor_data_to_NPU` slot, padding, and
  ## bound checks without exposing callers to slot arithmetic.
  outResult = default(BlaiForwardTensorIoResult)
  outResult.runnable = plan.runnable
  var bufferFit: BlaiForwardNpuBufferFitResult
  blaiForwardNpuBufferFitsInto(
    plan, blaiBufferLenU32(dataBuffer.len), bufferFit)
  outResult.bufferFit = bufferFit
  outResult.bufferFits = bufferFit.fits
  let inputCursor = blaiForwardInputCursor(inputIndex.uint32)
  if not inputCursor.valid:
    blaiForwardTensorIoReadinessInto(
      outResult.runnable, outResult.active, outResult.bufferFits,
      outResult.tensorFits, outResult.readiness)
    return
  outResult.transfer = plan.inputs[inputCursor.index]
  outResult.active = outResult.transfer.active
  var tensorFit: BlaiCompactTensorFitResult
  blaiCompactTensorFitsInto(
    outResult.transfer, blaiBufferLenU32(tensor.len), tensorFit)
  outResult.tensorFit = tensorFit
  outResult.tensorFits = tensorFit.fits
  blaiForwardTensorIoReadinessInto(
    outResult.runnable, outResult.active, outResult.bufferFits,
    outResult.tensorFits, outResult.readiness)
  if outResult.readiness.ready:
    var move: BlaiTensorBufferMoveResult
    blaiStoreTensorToNpuBufferInto(
      outResult.transfer, plan.patchSize, tensor, dataBuffer, move)
    outResult.move = move
    outResult.moved = move.moved

proc blaiStageForwardNpuInput*(plan: BlaiForwardNpuPlan,
                               inputIndex: range[0 .. 7],
                               tensor: openArray[uint8],
                               dataBuffer: var openArray[uint8]): BlaiForwardTensorIoResult =
  ## Convenience result-returning wrapper for forward_NPU input staging.
  blaiStageForwardNpuInputInto(plan, inputIndex, tensor, dataBuffer, result)

proc blaiLoadForwardNpuOutputInto*(plan: BlaiForwardNpuPlan,
                                   kind: BlaiForwardOutputKind,
                                   dataBuffer: openArray[uint8],
                                   tensor: var openArray[uint8],
                                   outResult: var BlaiForwardTensorIoResult) =
  ## Load one compact model output from a caller-owned forward_NPU DATA buffer.
  ##
  ## This composes the recovered `Load_NPU_data_to_tensor` slot, padding, and
  ## bound checks without exposing callers to slot arithmetic.
  outResult = default(BlaiForwardTensorIoResult)
  outResult.runnable = plan.runnable
  var bufferFit: BlaiForwardNpuBufferFitResult
  blaiForwardNpuBufferFitsInto(
    plan, blaiBufferLenU32(dataBuffer.len), bufferFit)
  outResult.bufferFit = bufferFit
  outResult.bufferFits = bufferFit.fits
  outResult.transfer = blaiForwardOutputTransfer(plan, kind)
  outResult.active = outResult.transfer.active
  var tensorFit: BlaiCompactTensorFitResult
  blaiCompactTensorFitsInto(
    outResult.transfer, blaiBufferLenU32(tensor.len), tensorFit)
  outResult.tensorFit = tensorFit
  outResult.tensorFits = tensorFit.fits
  blaiForwardTensorIoReadinessInto(
    outResult.runnable, outResult.active, outResult.bufferFits,
    outResult.tensorFits, outResult.readiness)
  if outResult.readiness.ready:
    var move: BlaiTensorBufferMoveResult
    blaiLoadTensorFromNpuBufferInto(
      outResult.transfer, plan.patchSize, dataBuffer, tensor, move)
    outResult.move = move
    outResult.moved = move.moved

proc blaiLoadForwardNpuOutput*(plan: BlaiForwardNpuPlan,
                               kind: BlaiForwardOutputKind,
                               dataBuffer: openArray[uint8],
                               tensor: var openArray[uint8]): BlaiForwardTensorIoResult =
  ## Convenience result-returning wrapper for forward_NPU output loading.
  blaiLoadForwardNpuOutputInto(plan, kind, dataBuffer, tensor, result)

proc blaiFinishForwardWorkspaceTensorIo(
    outResult: var BlaiForwardWorkspaceTensorIoResult) =
  if not outResult.binding.bound:
    outResult.firstBlock = blaiForwardWorkspaceTensorIoBinding
  elif not outResult.dataSegmentFit.fits:
    outResult.firstBlock = blaiForwardWorkspaceTensorIoDataSegment
  elif not outResult.io.moved:
    outResult.firstBlock = blaiForwardWorkspaceTensorIoTensor
  else:
    outResult.firstBlock = blaiForwardWorkspaceTensorIoNoBlock
  outResult.moved = outResult.firstBlock == blaiForwardWorkspaceTensorIoNoBlock

proc blaiStageForwardWorkspaceInputInto*(
    binding: BlaiForwardWorkspaceBufferBinding,
    plan: BlaiForwardNpuPlan,
    inputIndex: range[0 .. 7],
    tensor: openArray[uint8],
    workspaceBytes: var openArray[uint8],
    outResult: var BlaiForwardWorkspaceTensorIoResult) =
  ## Stage compact input into the DATA segment of a bound model workspace.
  outResult = default(BlaiForwardWorkspaceTensorIoResult)
  outResult.binding = binding
  if not binding.bound:
    blaiFinishForwardWorkspaceTensorIo(outResult)
    return
  blaiForwardWorkspaceSegmentFitsInto(
    binding.workspace.data, blaiBufferLenU32(workspaceBytes.len),
    outResult.dataSegmentFit)
  if not outResult.dataSegmentFit.fits:
    blaiFinishForwardWorkspaceTensorIo(outResult)
    return
  let window =
    blaiForwardWorkspaceSegmentWindow(
      binding.workspace.data, binding.workspace.data.bytes, workspaceBytes.len)
  if not window.fits or window.count <= 0:
    blaiFinishForwardWorkspaceTensorIo(outResult)
    return
  blaiStageForwardNpuInputInto(
    plan, inputIndex, tensor,
    blaiForwardWorkspaceSegmentOpenArray(workspaceBytes, window),
    outResult.io)
  blaiFinishForwardWorkspaceTensorIo(outResult)

proc blaiStageForwardWorkspaceInput*(
    binding: BlaiForwardWorkspaceBufferBinding,
    plan: BlaiForwardNpuPlan,
    inputIndex: range[0 .. 7],
    tensor: openArray[uint8],
    workspaceBytes: var openArray[uint8]): BlaiForwardWorkspaceTensorIoResult =
  ## Convenience wrapper for whole-workspace input staging.
  blaiStageForwardWorkspaceInputInto(
    binding, plan, inputIndex, tensor, workspaceBytes, result)

proc blaiLoadForwardWorkspaceOutputInto*(
    binding: BlaiForwardWorkspaceBufferBinding,
    plan: BlaiForwardNpuPlan,
    kind: BlaiForwardOutputKind,
    workspaceBytes: openArray[uint8],
    tensor: var openArray[uint8],
    outResult: var BlaiForwardWorkspaceTensorIoResult) =
  ## Load compact output from the DATA segment of a bound model workspace.
  outResult = default(BlaiForwardWorkspaceTensorIoResult)
  outResult.binding = binding
  if not binding.bound:
    blaiFinishForwardWorkspaceTensorIo(outResult)
    return
  blaiForwardWorkspaceSegmentFitsInto(
    binding.workspace.data, blaiBufferLenU32(workspaceBytes.len),
    outResult.dataSegmentFit)
  if not outResult.dataSegmentFit.fits:
    blaiFinishForwardWorkspaceTensorIo(outResult)
    return
  let window =
    blaiForwardWorkspaceSegmentWindow(
      binding.workspace.data, binding.workspace.data.bytes, workspaceBytes.len)
  if not window.fits or window.count <= 0:
    blaiFinishForwardWorkspaceTensorIo(outResult)
    return
  blaiLoadForwardNpuOutputInto(
    plan, kind, blaiForwardWorkspaceSegmentOpenArray(workspaceBytes, window), tensor,
    outResult.io)
  blaiFinishForwardWorkspaceTensorIo(outResult)

proc blaiLoadForwardWorkspaceOutput*(
    binding: BlaiForwardWorkspaceBufferBinding,
    plan: BlaiForwardNpuPlan,
    kind: BlaiForwardOutputKind,
    workspaceBytes: openArray[uint8],
    tensor: var openArray[uint8]): BlaiForwardWorkspaceTensorIoResult =
  ## Convenience wrapper for whole-workspace output loading.
  blaiLoadForwardWorkspaceOutputInto(
    binding, plan, kind, workspaceBytes, tensor, result)

proc blaiForwardModelOutputValidationInto*(
    execution: BlaiForwardModelWorkspaceExecuteResult,
    output: BlaiForwardTensorIoResult,
    compare: BlaiUint8OutputCompareResult,
    outResult: var BlaiForwardModelOutputValidationResult) =
  ## Combine model execution, DATA-buffer output readback, and oracle comparison.
  outResult = default(BlaiForwardModelOutputValidationResult)
  outResult.executed = execution.allCompleted
  outResult.outputMoved = output.moved
  outResult.outputMatched = compare.matched
  outResult.completedLayerCount = execution.completedLayerCount
  outResult.outputTransfer = output.transfer
  outResult.executionFirstBlock = execution.firstBlock
  outResult.outputReadiness = output.readiness
  outResult.compare = compare
  outResult.expectedElements = compare.expectedElements
  outResult.actualElements = compare.actualElements
  outResult.comparedElements = compare.comparedElements
  outResult.trailingElements = compare.trailingElements
  outResult.lengthMatches = compare.lengthMatches
  outResult.mismatchCount = compare.mismatchCount
  outResult.firstMismatch = compare.firstMismatch
  outResult.expectedPresentAtFirstMismatch =
    compare.expectedPresentAtFirstMismatch
  outResult.actualPresentAtFirstMismatch =
    compare.actualPresentAtFirstMismatch
  outResult.expectedAtFirstMismatch = compare.expectedAtFirstMismatch
  outResult.actualAtFirstMismatch = compare.actualAtFirstMismatch
  if not outResult.executed:
    outResult.firstBlock = blaiForwardModelOutputValidationExecution
  elif not outResult.outputMoved:
    outResult.firstBlock = blaiForwardModelOutputValidationReadback
  elif not outResult.outputMatched:
    outResult.firstBlock = blaiForwardModelOutputValidationCompare
  else:
    outResult.firstBlock = blaiForwardModelOutputValidationNoBlock
  outResult.valid =
    outResult.executed and outResult.outputMoved and outResult.outputMatched

proc blaiForwardModelOutputValidation*(
    execution: BlaiForwardModelWorkspaceExecuteResult,
    output: BlaiForwardTensorIoResult,
    compare: BlaiUint8OutputCompareResult):
    BlaiForwardModelOutputValidationResult =
  ## Convenience wrapper for post-run forward_NPU output validation.
  blaiForwardModelOutputValidationInto(execution, output, compare, result)

proc blaiForwardModelOutputValidationInto*(
    execution: BlaiForwardModelExecuteResult,
    output: BlaiForwardTensorIoResult,
    compare: BlaiUint8OutputCompareResult,
    outResult: var BlaiForwardModelOutputValidationResult) =
  ## Combine configured-model execution, DATA readback, and oracle comparison.
  outResult = default(BlaiForwardModelOutputValidationResult)
  outResult.executed = execution.allCompleted
  outResult.outputMoved = output.moved
  outResult.outputMatched = compare.matched
  outResult.completedLayerCount = execution.completedLayerCount
  outResult.outputTransfer = output.transfer
  outResult.configuredExecutionFirstBlock = execution.firstBlock
  outResult.outputReadiness = output.readiness
  outResult.compare = compare
  outResult.expectedElements = compare.expectedElements
  outResult.actualElements = compare.actualElements
  outResult.comparedElements = compare.comparedElements
  outResult.trailingElements = compare.trailingElements
  outResult.lengthMatches = compare.lengthMatches
  outResult.mismatchCount = compare.mismatchCount
  outResult.firstMismatch = compare.firstMismatch
  outResult.expectedPresentAtFirstMismatch =
    compare.expectedPresentAtFirstMismatch
  outResult.actualPresentAtFirstMismatch =
    compare.actualPresentAtFirstMismatch
  outResult.expectedAtFirstMismatch = compare.expectedAtFirstMismatch
  outResult.actualAtFirstMismatch = compare.actualAtFirstMismatch
  if not outResult.executed:
    outResult.firstBlock = blaiForwardModelOutputValidationExecution
  elif not outResult.outputMoved:
    outResult.firstBlock = blaiForwardModelOutputValidationReadback
  elif not outResult.outputMatched:
    outResult.firstBlock = blaiForwardModelOutputValidationCompare
  else:
    outResult.firstBlock = blaiForwardModelOutputValidationNoBlock
  outResult.valid =
    outResult.executed and outResult.outputMoved and outResult.outputMatched

proc blaiForwardModelOutputValidation*(
    execution: BlaiForwardModelExecuteResult,
    output: BlaiForwardTensorIoResult,
    compare: BlaiUint8OutputCompareResult):
    BlaiForwardModelOutputValidationResult =
  ## Convenience wrapper for live configured-model output validation.
  blaiForwardModelOutputValidationInto(execution, output, compare, result)

proc blaiForwardModelOutputValidationReadinessInto*(
    validation: BlaiForwardModelOutputValidationResult,
    outResult: var BlaiForwardModelOutputValidationReadiness) =
  ## Derive the public gate summary for model output equivalence checks.
  outResult = default(BlaiForwardModelOutputValidationReadiness)
  outResult.executed = validation.executed
  outResult.outputMoved = validation.outputMoved
  outResult.outputMatched = validation.outputMatched
  outResult.completedLayerCount = validation.completedLayerCount
  outResult.outputReadiness = validation.outputReadiness
  outResult.expectedElements = validation.expectedElements
  outResult.actualElements = validation.actualElements
  outResult.comparedElements = validation.comparedElements
  outResult.trailingElements = validation.trailingElements
  outResult.lengthMatches = validation.lengthMatches
  outResult.mismatchCount = validation.mismatchCount
  outResult.firstMismatch = validation.firstMismatch
  outResult.expectedPresentAtFirstMismatch =
    validation.expectedPresentAtFirstMismatch
  outResult.actualPresentAtFirstMismatch =
    validation.actualPresentAtFirstMismatch
  outResult.expectedAtFirstMismatch = validation.expectedAtFirstMismatch
  outResult.actualAtFirstMismatch = validation.actualAtFirstMismatch
  outResult.executionFirstBlock = validation.executionFirstBlock
  outResult.configuredExecutionFirstBlock =
    validation.configuredExecutionFirstBlock
  outResult.firstBlock = validation.firstBlock
  outResult.valid = validation.valid

proc blaiForwardModelOutputValidationReadiness*(
    validation: BlaiForwardModelOutputValidationResult):
    BlaiForwardModelOutputValidationReadiness =
  ## Convenience wrapper for model output validation readiness.
  blaiForwardModelOutputValidationReadinessInto(validation, result)

proc blaiForwardModelOutputFirstMismatch*(
    validation: BlaiForwardModelOutputValidationResult): int32 =
  ## Return the first CPU-reference mismatch index from a model-output check.
  validation.compare.firstMismatch

proc blaiValidateForwardModelOutputInto*(
    execution: BlaiForwardModelWorkspaceExecuteResult,
    plan: BlaiForwardNpuPlan,
    kind: BlaiForwardOutputKind,
    dataBuffer: openArray[uint8],
    expected: openArray[uint8],
    output: var openArray[uint8],
    outResult: var BlaiForwardModelOutputValidationResult) =
  ## Read back and validate one recovered workspace-backed model output.
  ##
  ## This is the fixture-facing composition point: a caller that has already
  ## executed the model supplies the recovered forward_NPU plan and DATA buffer,
  ## then receives a typed execution/readback/compare gate.
  var outputMove: BlaiForwardTensorIoResult
  blaiLoadForwardNpuOutputInto(plan, kind, dataBuffer, output, outputMove)
  let compare = blaiCompareUint8Outputs(expected, output)
  blaiForwardModelOutputValidationInto(
    execution, outputMove, compare, outResult)

proc blaiValidateForwardModelOutput*(
    execution: BlaiForwardModelWorkspaceExecuteResult,
    plan: BlaiForwardNpuPlan,
    kind: BlaiForwardOutputKind,
    dataBuffer: openArray[uint8],
    expected: openArray[uint8],
    output: var openArray[uint8]): BlaiForwardModelOutputValidationResult =
  ## Convenience wrapper for workspace-backed output validation.
  blaiValidateForwardModelOutputInto(
    execution, plan, kind, dataBuffer, expected, output, result)

proc blaiValidateForwardModelOutputInto*(
    execution: BlaiForwardModelExecuteResult,
    plan: BlaiForwardNpuPlan,
    kind: BlaiForwardOutputKind,
    dataBuffer: openArray[uint8],
    expected: openArray[uint8],
    output: var openArray[uint8],
    outResult: var BlaiForwardModelOutputValidationResult) =
  ## Read back and validate one recovered configured live model output.
  ##
  ## The configured execution path is the one generated live NPU fixtures use
  ## after `blaiExecuteForwardModelConfigured`; this helper keeps output
  ## equivalence checks allocation-free and preserves typed first-block state.
  var outputMove: BlaiForwardTensorIoResult
  blaiLoadForwardNpuOutputInto(plan, kind, dataBuffer, output, outputMove)
  let compare = blaiCompareUint8Outputs(expected, output)
  blaiForwardModelOutputValidationInto(
    execution, outputMove, compare, outResult)

proc blaiValidateForwardModelOutput*(
    execution: BlaiForwardModelExecuteResult,
    plan: BlaiForwardNpuPlan,
    kind: BlaiForwardOutputKind,
    dataBuffer: openArray[uint8],
    expected: openArray[uint8],
    output: var openArray[uint8]): BlaiForwardModelOutputValidationResult =
  ## Convenience wrapper for configured live output validation.
  blaiValidateForwardModelOutputInto(
    execution, plan, kind, dataBuffer, expected, output, result)

proc blaiFinishForwardWorkspaceOutputValidation(
    outResult: var BlaiForwardWorkspaceOutputValidationResult) =
  outResult.workspaceOutputFirstBlock = outResult.workspaceOutput.firstBlock
  outResult.validationFirstBlock = outResult.validation.firstBlock
  outResult.compare = outResult.validation.compare
  outResult.expectedElements = outResult.validation.expectedElements
  outResult.actualElements = outResult.validation.actualElements
  outResult.comparedElements = outResult.validation.comparedElements
  outResult.trailingElements = outResult.validation.trailingElements
  outResult.lengthMatches = outResult.validation.lengthMatches
  outResult.mismatchCount = outResult.validation.mismatchCount
  outResult.firstMismatch = outResult.validation.firstMismatch
  outResult.expectedPresentAtFirstMismatch =
    outResult.validation.expectedPresentAtFirstMismatch
  outResult.actualPresentAtFirstMismatch =
    outResult.validation.actualPresentAtFirstMismatch
  outResult.expectedAtFirstMismatch =
    outResult.validation.expectedAtFirstMismatch
  outResult.actualAtFirstMismatch =
    outResult.validation.actualAtFirstMismatch
  if not outResult.validation.executed:
    outResult.firstBlock = blaiForwardWorkspaceOutputValidationExecution
  elif not outResult.workspaceOutput.moved:
    outResult.firstBlock = blaiForwardWorkspaceOutputValidationWorkspaceOutput
  elif not outResult.validation.outputMatched:
    outResult.firstBlock = blaiForwardWorkspaceOutputValidationCompare
  else:
    outResult.firstBlock = blaiForwardWorkspaceOutputValidationNoBlock
  outResult.valid =
    outResult.firstBlock == blaiForwardWorkspaceOutputValidationNoBlock

proc blaiForwardWorkspaceOutputValidationReadinessInto*(
    validation: BlaiForwardWorkspaceOutputValidationResult,
    outResult: var BlaiForwardWorkspaceOutputValidationReadiness) =
  ## Derive the public gate summary for bound-workspace output checks.
  outResult = default(BlaiForwardWorkspaceOutputValidationReadiness)
  outResult.workspaceOutputMoved = validation.workspaceOutput.moved
  blaiForwardModelOutputValidationReadinessInto(
    validation.validation, outResult.validation)
  outResult.workspaceOutputFirstBlock = validation.workspaceOutputFirstBlock
  outResult.validationFirstBlock = validation.validationFirstBlock
  outResult.expectedElements = validation.expectedElements
  outResult.actualElements = validation.actualElements
  outResult.comparedElements = validation.comparedElements
  outResult.trailingElements = validation.trailingElements
  outResult.lengthMatches = validation.lengthMatches
  outResult.mismatchCount = validation.mismatchCount
  outResult.firstMismatch = validation.firstMismatch
  outResult.expectedPresentAtFirstMismatch =
    validation.expectedPresentAtFirstMismatch
  outResult.actualPresentAtFirstMismatch =
    validation.actualPresentAtFirstMismatch
  outResult.expectedAtFirstMismatch = validation.expectedAtFirstMismatch
  outResult.actualAtFirstMismatch = validation.actualAtFirstMismatch
  outResult.firstBlock = validation.firstBlock
  outResult.valid = validation.valid

proc blaiForwardWorkspaceOutputValidationReadiness*(
    validation: BlaiForwardWorkspaceOutputValidationResult):
    BlaiForwardWorkspaceOutputValidationReadiness =
  ## Convenience wrapper for bound-workspace output validation readiness.
  blaiForwardWorkspaceOutputValidationReadinessInto(validation, result)

proc blaiValidateForwardWorkspaceOutputInto*(
    execution: BlaiForwardModelWorkspaceExecuteResult,
    binding: BlaiForwardWorkspaceBufferBinding,
    plan: BlaiForwardNpuPlan,
    kind: BlaiForwardOutputKind,
    workspaceBytes: openArray[uint8],
    expected: openArray[uint8],
    output: var openArray[uint8],
    outResult: var BlaiForwardWorkspaceOutputValidationResult) =
  ## Read and validate output through a bound whole-model workspace.
  outResult = default(BlaiForwardWorkspaceOutputValidationResult)
  blaiLoadForwardWorkspaceOutputInto(
    binding, plan, kind, workspaceBytes, output, outResult.workspaceOutput)
  let compare = blaiCompareUint8Outputs(expected, output)
  blaiForwardModelOutputValidationInto(
    execution, outResult.workspaceOutput.io, compare, outResult.validation)
  blaiFinishForwardWorkspaceOutputValidation(outResult)

