  validation.fixture.output.compare.firstMismatch

proc blaiForwardWorkspaceHardwareAddressReadinessInto*(
    binding: BlaiForwardWorkspaceBufferBinding,
    outResult: var BlaiForwardWorkspaceHardwareAddressReadiness) =
  ## Explain whether a bound workspace can configure BLAI hardware registers.
  outResult = default(BlaiForwardWorkspaceHardwareAddressReadiness)
  outResult.bound = binding.bound
  if not binding.bound:
    outResult.firstBlock = blaiForwardWorkspaceHardwareAddressBinding
    return
  outResult.instructionAddressReady =
    binding.workspace.instruction.active and
    binding.workspace.instruction.address != 0'u32
  outResult.dataAddressReady =
    (not binding.workspace.data.active) or
    binding.workspace.data.address != 0'u32
  outResult.weightAddressReady =
    (not binding.workspace.weight.active) or
    binding.workspace.weight.address != 0'u32
  outResult.biasAddressReady =
    (not binding.workspace.bias.active) or
    binding.workspace.bias.address != 0'u32
  if not outResult.instructionAddressReady:
    outResult.firstBlock = blaiForwardWorkspaceHardwareAddressInstruction
  elif not outResult.dataAddressReady:
    outResult.firstBlock = blaiForwardWorkspaceHardwareAddressData
  elif not outResult.weightAddressReady:
    outResult.firstBlock = blaiForwardWorkspaceHardwareAddressWeight
  elif not outResult.biasAddressReady:
    outResult.firstBlock = blaiForwardWorkspaceHardwareAddressBias
  else:
    outResult.firstBlock = blaiForwardWorkspaceHardwareAddressNoBlock
  outResult.ready =
    outResult.firstBlock == blaiForwardWorkspaceHardwareAddressNoBlock

proc blaiForwardWorkspaceHardwareAddressReadiness*(
    binding: BlaiForwardWorkspaceBufferBinding):
    BlaiForwardWorkspaceHardwareAddressReadiness =
  ## Convenience wrapper for workspace hardware-address readiness.
  blaiForwardWorkspaceHardwareAddressReadinessInto(binding, result)

proc blaiFinishForwardWorkspaceFixtureValidation(
    outResult: var BlaiForwardWorkspaceFixtureValidationResult) =
  outResult.bindingFirstBlock = outResult.binding.firstBlock
  outResult.hardwareAddressFirstBlock =
    outResult.hardwareAddresses.firstBlock
  outResult.inputFirstBlock = outResult.input.firstBlock
  outResult.executionFirstBlock = outResult.execution.firstBlock
  outResult.outputFirstBlock = outResult.output.firstBlock
  if not outResult.binding.bound:
    outResult.firstBlock = blaiForwardWorkspaceFixtureValidationBinding
  elif not outResult.hardwareAddresses.ready:
    outResult.firstBlock =
      blaiForwardWorkspaceFixtureValidationHardwareAddresses
  elif not outResult.input.moved:
    outResult.firstBlock = blaiForwardWorkspaceFixtureValidationInput
  elif not outResult.execution.allCompleted:
    outResult.firstBlock = blaiForwardWorkspaceFixtureValidationExecution
  elif not outResult.output.valid:
    outResult.firstBlock = blaiForwardWorkspaceFixtureValidationOutput
  else:
    outResult.firstBlock = blaiForwardWorkspaceFixtureValidationNoBlock
  outResult.valid =
    outResult.firstBlock == blaiForwardWorkspaceFixtureValidationNoBlock

proc blaiForwardWorkspaceFixtureValidationReadinessInto*(
    validation: BlaiForwardWorkspaceFixtureValidationResult,
    outResult: var BlaiForwardWorkspaceFixtureValidationReadiness) =
  ## Derive the public gate summary for raw workspace fixture validation.
  outResult = default(BlaiForwardWorkspaceFixtureValidationReadiness)
  outResult.bound = validation.binding.bound
  outResult.hardwareAddressesReady = validation.hardwareAddresses.ready
  outResult.inputMoved = validation.input.moved
  outResult.executed = validation.execution.allCompleted
  outResult.outputValid = validation.output.valid
  outResult.outputMatched = validation.output.validation.outputMatched
  outResult.expectedElements = validation.output.expectedElements
  outResult.actualElements = validation.output.actualElements
  outResult.comparedElements = validation.output.comparedElements
  outResult.trailingElements = validation.output.trailingElements
  outResult.lengthMatches = validation.output.lengthMatches
  outResult.mismatchCount = validation.output.mismatchCount
  outResult.firstMismatch = validation.output.firstMismatch
  outResult.expectedPresentAtFirstMismatch =
    validation.output.expectedPresentAtFirstMismatch
  outResult.actualPresentAtFirstMismatch =
    validation.output.actualPresentAtFirstMismatch
  outResult.expectedAtFirstMismatch = validation.output.expectedAtFirstMismatch
  outResult.actualAtFirstMismatch = validation.output.actualAtFirstMismatch
  blaiForwardWorkspaceOutputValidationReadinessInto(
    validation.output, outResult.outputReadiness)
  outResult.bindingFirstBlock = validation.bindingFirstBlock
  outResult.hardwareAddressFirstBlock = validation.hardwareAddressFirstBlock
  outResult.inputFirstBlock = validation.inputFirstBlock
  outResult.executionFirstBlock = validation.executionFirstBlock
  outResult.outputFirstBlock = validation.outputFirstBlock
  if not outResult.bound:
    outResult.firstBlock = blaiForwardWorkspaceFixtureValidationBinding
  elif not outResult.hardwareAddressesReady:
    outResult.firstBlock =
      blaiForwardWorkspaceFixtureValidationHardwareAddresses
  elif not outResult.inputMoved:
    outResult.firstBlock = blaiForwardWorkspaceFixtureValidationInput
  elif not outResult.executed:
    outResult.firstBlock = blaiForwardWorkspaceFixtureValidationExecution
  elif not outResult.outputValid:
    outResult.firstBlock = blaiForwardWorkspaceFixtureValidationOutput
  else:
    outResult.firstBlock = blaiForwardWorkspaceFixtureValidationNoBlock
  outResult.valid =
    outResult.firstBlock == blaiForwardWorkspaceFixtureValidationNoBlock

proc blaiForwardWorkspaceFixtureValidationReadiness*(
    validation: BlaiForwardWorkspaceFixtureValidationResult):
    BlaiForwardWorkspaceFixtureValidationReadiness =
  ## Convenience wrapper for raw workspace fixture validation readiness.
  blaiForwardWorkspaceFixtureValidationReadinessInto(validation, result)

proc blaiValidateForwardWorkspaceFixtureInto*(
    layers: var openArray[BlaiCpuInstLayer64],
    useTflite: bool,
    modelResources: BlaiForwardModelResourcePlan,
    tensorPlan: BlaiForwardNpuPlan,
    inputIndex: uint32,
    input: openArray[uint8],
    expectedOutput: openArray[uint8],
    output: var openArray[uint8],
    ctrl: var BlaiPsramCtrl,
    stream: var openArray[BlaiInstruction],
    workspaceBytes: var openArray[uint8],
    cpuWeightBytes: openArray[uint8],
    cpuBiasBytes: openArray[uint8],
    decodedWeights: var openArray[int32],
    decodedBiases: var openArray[int32],
    npuWeightBytes: var openArray[uint8],
    npuBiases: var openArray[int32],
    temporaryWeights: var openArray[int32],
    executor: BlaiForwardLayerExecutor,
    outResult: var BlaiForwardWorkspaceFixtureValidationResult,
    pack: uint32 = BlaiNpuWeightPack,
    c2: uint32 = 0'u32,
    includeExtra: bool = false,
    descriptorHalt: bool = false,
    midOutState: bool = false) =
  ## Bind a caller workspace, stage input, execute, and validate output.
  outResult = default(BlaiForwardWorkspaceFixtureValidationResult)
  blaiBindForwardWorkspaceBufferInto(
    modelResources, workspaceBytes, outResult.binding)
  if not outResult.binding.bound:
    blaiFinishForwardWorkspaceFixtureValidation(outResult)
    return
  blaiForwardWorkspaceHardwareAddressReadinessInto(
    outResult.binding, outResult.hardwareAddresses)
  if not outResult.hardwareAddresses.ready:
    blaiFinishForwardWorkspaceFixtureValidation(outResult)
    return
  blaiStageForwardWorkspaceInputInto(
    outResult.binding, tensorPlan, inputIndex, input, workspaceBytes,
    outResult.input)
  if not outResult.input.moved:
    blaiFinishForwardWorkspaceFixtureValidation(outResult)
    return
  blaiMaterializeAndExecuteForwardModelWorkspaceInto(
    layers, useTflite, ctrl, stream, modelResources,
    outResult.binding.workspace, workspaceBytes, cpuWeightBytes, cpuBiasBytes,
    decodedWeights, decodedBiases, npuWeightBytes, npuBiases,
    temporaryWeights, executor, pack, c2, includeExtra, descriptorHalt,
    midOutState, outResult.execution)
  if not outResult.execution.allCompleted:
    blaiFinishForwardWorkspaceFixtureValidation(outResult)
    return
  blaiValidateForwardWorkspaceOutputInto(
    outResult.execution, outResult.binding, tensorPlan, blaiForwardPrimaryOutput,
    workspaceBytes, expectedOutput, output, outResult.output)
  blaiFinishForwardWorkspaceFixtureValidation(outResult)

