    includeExtra: bool = false,
    descriptorHalt: bool = false,
    midOutState: bool = false) =
  ## Project a TFLite CPU oracle output, run a parsed address fixture, validate.
  outResult = default(BlaiTfliteParsedWorkspaceOracleAddressFixtureResult)
