    descriptorHalt: bool = false,
    midOutState: bool = false):
    BlaiFixedParsedWorkspaceOracleAddressFixtureResult =
  ## Convenience wrapper for fixed oracle parsed address fixture validation.
  blaiValidateFixedParsedWorkspaceOracleAddressFixtureInto(
    reference, referenceOutput, parsed, layers, plan, workspaceBaseAddress,
    tensorPlan, inputIndex, input, expectedWorkspaceOutput, output, ctrl,
    stream, workspaceBytes, cpuWeightBytes, cpuBiasBytes, decodedWeights,
    decodedBiases, npuWeightBytes, npuBiases, temporaryWeights, executor,
    result, pack, c2, includeExtra, descriptorHalt, midOutState)

proc blaiNpuEligibilityInto*(layer: BlaiDecodedLayer,
                             outResult: var BlaiNpuEligibilityResult) =
  ## Recovered SDK `check_BLAI_NPU_RUN` decision.
  ##
  ## This is only the pre-encoder eligibility test. It does not allocate BLAI
  ## buffers, emit instructions, or prove that the layer can be executed by this
  ## Nim driver yet.
  outResult = default(BlaiNpuEligibilityResult)
  outResult.sizeSupported = true
  outResult.dilationSupported = true
  outResult.strideSupported = true
  outResult.oddStrideSupported = true
  let oddStrideRemainder = (layer.w mod 2'u32) + (layer.h mod 2'u32)
  case layer.layerType
  of blaiConvolutional:
    outResult.knownLayer = true
    outResult.sizeSupported = layer.size <= 7'u32
    outResult.dilationSupported = layer.dilation <= 2'u32
    outResult.strideSupported = layer.stride <= 2'u32
    outResult.oddStrideSupported =
      not (layer.stride == 2'u32 and oddStrideRemainder == 1'u32)
    outResult.eligible =
      outResult.sizeSupported and outResult.dilationSupported and
      outResult.strideSupported and outResult.oddStrideSupported
  of blaiConvMax, blaiRouteConv:
    outResult.knownLayer = true
    outResult.sizeSupported = layer.size <= 7'u32
    outResult.dilationSupported = layer.dilation <= 2'u32
    outResult.strideSupported = layer.stride <= 2'u32
    outResult.eligible =
      outResult.sizeSupported and outResult.dilationSupported and
      outResult.strideSupported
  of blaiMaxpool:
    outResult.knownLayer = true
    outResult.sizeSupported = layer.size <= 3'u32
    outResult.strideSupported = layer.stride <= 2'u32
    outResult.eligible = outResult.sizeSupported and outResult.strideSupported
  of blaiRouteMax, blaiRoute, blaiRouteUpsample,
     blaiUpsample, blaiMatmul, blaiShortcut:
    outResult.knownLayer = true
    outResult.eligible = true
  else:
    discard

proc blaiCanRunOnNpu*(layer: BlaiDecodedLayer): bool =
  ## Boolean wrapper for recovered SDK `check_BLAI_NPU_RUN` decision.
  var eligibility: BlaiNpuEligibilityResult
  blaiNpuEligibilityInto(layer, eligibility)
  eligibility.eligible

proc blaiNpuEligibilityInto*(layer: BlaiCpuInstLayer64,
                             outResult: var BlaiNpuEligibilityResult) =
  ## CPU-layer ABI wrapper for recovered SDK `check_BLAI_NPU_RUN`.
  blaiNpuEligibilityInto(toDecodedLayer(layer), outResult)

proc blaiNpuEligibilityInto*(parsed: BlaiCpuParsedLayerState,
                             outResult: var BlaiNpuEligibilityResult) =
  ## Parsed-state wrapper for recovered SDK `check_BLAI_NPU_RUN`.
  blaiNpuEligibilityInto(parsed.layer, outResult)

proc blaiCanRunOnNpu*(layer: BlaiCpuInstLayer64): bool =
  ## Boolean CPU-layer ABI wrapper for recovered SDK `check_BLAI_NPU_RUN`.
  var eligibility: BlaiNpuEligibilityResult
  blaiNpuEligibilityInto(layer, eligibility)
  eligibility.eligible

proc blaiCanRunOnNpu*(parsed: BlaiCpuParsedLayerState): bool =
  ## Boolean parsed-state wrapper for recovered SDK `check_BLAI_NPU_RUN`.
  var eligibility: BlaiNpuEligibilityResult
  blaiNpuEligibilityInto(parsed, eligibility)
  eligibility.eligible

proc blaiNpuCompletionStatusInto*(
    configured, interruptObserved: bool,
    outResult: var BlaiNpuCompletionStatusResult) =
  ## Project recovered SDK completion wait state to a typed status decision.
  outResult = default(BlaiNpuCompletionStatusResult)
  outResult.configured = configured
  outResult.interruptObserved = interruptObserved
  if not configured:
    outResult.unsupported = true
    outResult.status = npuUnsupported
  elif interruptObserved:
    outResult.completed = true
    outResult.status = npuOk
  else:
    outResult.timedOut = true
    outResult.status = npuTimeout

proc blaiNpuCompletionStatusResult*(
    configured, interruptObserved: bool): BlaiNpuCompletionStatusResult =
  ## Convenience result-returning wrapper for completion wait status.
  blaiNpuCompletionStatusInto(configured, interruptObserved, result)

proc blaiNpuCompletionStatus*(configured, interruptObserved: bool): NpuError =
  ## Compatibility wrapper for the recovered SDK completion wait status.
  blaiNpuCompletionStatusResult(configured, interruptObserved).status

proc blaiNpuCompletionStartPlanInto*(
    waitPlan: BlaiNpuCompletionWaitPlan,
    outResult: var BlaiNpuCompletionStartPlan) =
  ## Resolve the pre-start completion wait gate without touching hardware.
  outResult = default(BlaiNpuCompletionStartPlan)
  outResult.waitPlan = waitPlan
  blaiNpuCompletionStatusInto(
    waitPlan.configured, interruptObserved = false, outResult.initialStatus)
  outResult.starts = waitPlan.configured

proc blaiNpuCompletionStartPlan*(
    waitPlan: BlaiNpuCompletionWaitPlan): BlaiNpuCompletionStartPlan =
  ## Convenience wrapper for completion wait pre-start planning.
  blaiNpuCompletionStartPlanInto(waitPlan, result)

proc blaiNpuCompletionExitPlanInto*(
    waitPlan: BlaiNpuCompletionWaitPlan,
    interruptObserved: bool,
    outResult: var BlaiNpuCompletionExitPlan) =
  ## Resolve wait-exit interrupt-clear and clock-gate side effects.
  outResult = default(BlaiNpuCompletionExitPlan)
  outResult.waitPlan = waitPlan
  outResult.interruptObserved = interruptObserved
  outResult.clearInterrupt = waitPlan.clearOnComplete and interruptObserved
  outResult.disableClock = waitPlan.disableClockOnExit
  outResult.valid = waitPlan.configured

proc blaiNpuCompletionExitPlan*(
    waitPlan: BlaiNpuCompletionWaitPlan,
    interruptObserved: bool): BlaiNpuCompletionExitPlan =
  ## Convenience wrapper for completion wait-exit side-effect planning.
  blaiNpuCompletionExitPlanInto(waitPlan, interruptObserved, result)

proc npuInterruptPollTerminalPlanInto*(
    timeout, polls: uint32,
    interruptObserved, finalInterruptPending: bool,
    outResult: var NpuInterruptPollTerminalPlan) =
  ## Classify the terminal state of a recovered interrupt polling loop.
  outResult = default(NpuInterruptPollTerminalPlan)
  outResult.timeout = timeout
  outResult.polls = polls
  outResult.interruptObserved = interruptObserved
  outResult.finalInterruptPending = finalInterruptPending
  outResult.exhausted = not interruptObserved and polls == timeout
  outResult.completedBeforeBudget = interruptObserved and polls <= timeout
  outResult.terminalMatchesBudget =
    (outResult.exhausted and not finalInterruptPending) or
    (outResult.completedBeforeBudget and finalInterruptPending)
  outResult.valid = polls <= timeout and outResult.terminalMatchesBudget

proc npuInterruptPollTerminalPlan*(
    timeout, polls: uint32,
    interruptObserved, finalInterruptPending: bool): NpuInterruptPollTerminalPlan =
  ## Convenience wrapper for interrupt polling terminal classification.
  npuInterruptPollTerminalPlanInto(
    timeout, polls, interruptObserved, finalInterruptPending, result)

proc blaiNpuPollingWaitEvidencePlanInto*(
    completion: BlaiNpuCompletionWaitResult,
    outResult: var BlaiNpuPollingWaitEvidencePlan) =
  ## Derive polling wait terminal evidence without mutating the public result.
  outResult = default(BlaiNpuPollingWaitEvidencePlan)
  outResult.configured = completion.configured
  outResult.pollBudget = completion.timeout
  outResult.actualPolls = completion.poll.polls
  outResult.started = completion.started
  outResult.interruptObserved = completion.interruptObserved
  outResult.finalInterruptPending = completion.poll.finalInterruptPending
  outResult.statusUnsupported = completion.statusDecision.unsupported
  outResult.statusTimedOut = completion.statusDecision.timedOut
  outResult.statusCompleted = completion.statusDecision.completed
  if not completion.configured:
    outResult.terminal = blaiNpuPollingWaitUnsupported
  elif completion.interruptObserved:
    outResult.terminal = blaiNpuPollingWaitInterruptObserved
  else:
    outResult.terminal = blaiNpuPollingWaitTimeout
  outResult.budgetExhausted =
    completion.configured and completion.started and
      not completion.interruptObserved and completion.statusDecision.timedOut
  outResult.completedBeforeBudget =
    completion.configured and completion.started and
      completion.interruptObserved and completion.poll.completedBeforeBudget
  outResult.budgetMatchesPolls =
    (outResult.budgetExhausted and
      completion.poll.exhausted and outResult.actualPolls == outResult.pollBudget) or
    (outResult.completedBeforeBudget and outResult.actualPolls <= outResult.pollBudget)
  outResult.pollTraceValid =
    (not completion.started and completion.poll.polls == 0'u32) or
    completion.poll.valid
  outResult.terminalMatchesStatus =
    (outResult.terminal == blaiNpuPollingWaitUnsupported and
      outResult.statusUnsupported and not outResult.started) or
    (outResult.terminal == blaiNpuPollingWaitInterruptObserved and
      outResult.statusCompleted and outResult.interruptObserved) or
    (outResult.terminal == blaiNpuPollingWaitTimeout and
      outResult.statusTimedOut and outResult.budgetExhausted)
  outResult.valid =
    outResult.terminalMatchesStatus and
      ((outResult.statusUnsupported and completion.status == npuUnsupported) or
       (outResult.statusTimedOut and completion.status == npuTimeout) or
       (outResult.statusCompleted and completion.status == npuOk)) and
      (outResult.budgetMatchesPolls or not completion.started) and
      outResult.pollTraceValid

proc blaiNpuPollingWaitEvidencePlan*(
    completion: BlaiNpuCompletionWaitResult): BlaiNpuPollingWaitEvidencePlan =
  ## Convenience wrapper for polling wait evidence planning.
  blaiNpuPollingWaitEvidencePlanInto(completion, result)

proc blaiNpuCompletionSideEffectPlanInto*(
    completion: BlaiNpuCompletionWaitResult,
    outResult: var BlaiNpuCompletionSideEffectPlan) =
  ## Derive wait-exit side-effect evidence without mutating public evidence.
  outResult = default(BlaiNpuCompletionSideEffectPlan)
  outResult.configured = completion.configured
  outResult.started = completion.started
  outResult.interruptObserved = completion.interruptObserved
  outResult.clearOnComplete = completion.clearOnComplete
  outResult.disableClockOnExit = completion.disableClockOnExit
  outResult.interruptCleared = completion.interruptCleared
  outResult.clockDisabled = completion.clockDisabled
  if not completion.configured:
    outResult.path = blaiNpuCompletionSideEffectUnsupported
  elif completion.interruptObserved:
    outResult.path = blaiNpuCompletionSideEffectCompleted
  else:
    outResult.path = blaiNpuCompletionSideEffectTimeout
  outResult.noSideEffects =
    not completion.started and not completion.interruptCleared and
      not completion.clockDisabled
  outResult.interruptClearSuppressed =
    not completion.interruptObserved and not completion.interruptCleared
  outResult.clockDisabledOnExit =
    (not completion.disableClockOnExit) or completion.clockDisabled
  outResult.completedSideEffectsApplied =
    completion.configured and completion.started and
      completion.statusDecision.completed and completion.interruptObserved and
      ((not completion.clearOnComplete) or completion.interruptCleared) and
      outResult.clockDisabledOnExit
  outResult.timeoutSideEffectsApplied =
    completion.configured and completion.started and
      completion.statusDecision.timedOut and
      outResult.interruptClearSuppressed and outResult.clockDisabledOnExit
  outResult.pathMatchesStatus =
    (outResult.path == blaiNpuCompletionSideEffectUnsupported and
      completion.statusDecision.unsupported and outResult.noSideEffects) or
    (outResult.path == blaiNpuCompletionSideEffectTimeout and
      outResult.timeoutSideEffectsApplied) or
    (outResult.path == blaiNpuCompletionSideEffectCompleted and
      outResult.completedSideEffectsApplied)
  outResult.valid =
    outResult.pathMatchesStatus and
      ((completion.statusDecision.unsupported and
          completion.status == npuUnsupported) or
       (completion.statusDecision.timedOut and
          completion.status == npuTimeout) or
       (completion.statusDecision.completed and completion.status == npuOk))

proc blaiNpuCompletionSideEffectPlan*(
    completion: BlaiNpuCompletionWaitResult): BlaiNpuCompletionSideEffectPlan =
  ## Convenience wrapper for wait-exit side-effect evidence planning.
  blaiNpuCompletionSideEffectPlanInto(completion, result)

proc blaiNpuRuntimeOwnershipPlan*(): BlaiNpuRuntimeOwnershipPlan =
  ## Recover SDK `blai_npu_init` / `forward_NPU` RTOS primitive ownership.
  ##
  ## The vendor runtime creates a counting semaphore for CNN interrupt delivery
  ## and a mutex for forward_NPU execution serialization. This bare-metal HAL
  ## keeps those as typed evidence while actively using a polling wait and a
  ## single-thread execution guard.
  BlaiNpuRuntimeOwnershipPlan(
    initCreatesInterruptSemaphore: true,
    initCreatesExecutionMutex: true,
    initDisablesClock: true,
    sdkInterruptWait: blaiNpuRuntimeWaitSdkCountingSemaphore,
    activeInterruptWait: blaiNpuRuntimeWaitBareMetalPolling,
    sdkExecutionLock: blaiNpuRuntimeLockSdkMutex,
    activeExecutionLock: blaiNpuRuntimeLockBareMetalSingleThread,
    forwardRunTakesExecutionLock: true,
    forwardRunReleasesExecutionLock: true,
    forwardRunStopsAfterInference: true)

proc npuPlanCompletionWait*(
    timeout: uint32 = 5_000_000,
    configured: bool = npuHasConfiguredInstructionStream,
    clearOnComplete: bool = true,
    disableClockOnExit: bool = true): BlaiNpuCompletionWaitPlan =
  ## Plan the recovered `blai_npu_inference` completion wait policy.
  BlaiNpuCompletionWaitPlan(
    configured: configured,
    timeout: timeout,
    clearOnComplete: clearOnComplete,
    disableClockOnExit: disableClockOnExit)

proc blaiPlanForwardNpuCompletionWaitInto*(
    plan: BlaiForwardNpuRunPlan,
    outResult: var BlaiNpuCompletionWaitPlan,
    timeout: uint32 = 5_000_000,
    clearOnComplete: bool = true,
    disableClockOnExit: bool = true) =
  ## Derive the recovered completion wait policy into caller-owned storage.
  outResult = BlaiNpuCompletionWaitPlan(
    configured: plan.configurable,
    timeout: timeout,
    clearOnComplete: clearOnComplete,
    disableClockOnExit: disableClockOnExit)

proc blaiPlanForwardNpuCompletionWait*(
    plan: BlaiForwardNpuRunPlan,
    timeout: uint32 = 5_000_000,
    clearOnComplete: bool = true,
    disableClockOnExit: bool = true): BlaiNpuCompletionWaitPlan =
  ## Derive the recovered completion wait policy from a checked run plan.
  blaiPlanForwardNpuCompletionWaitInto(
    plan, result, timeout, clearOnComplete, disableClockOnExit)

static:
  proc putBits(inst: var BlaiInstruction, base, len: Natural, value: uint32) =
    blaiPutBits(inst, base, len, value)

  proc fakeForwardLayerExecutor(
      plan: BlaiForwardNpuRunPlan,
      layerIndex: uint32): BlaiForwardNpuExecuteResult =
    discard layerIndex
    result.runnable = plan.runnable
    result.configurable = plan.configurable
    result.cacheApplied = plan.configurable
    result.waitPlan = blaiPlanForwardNpuCompletionWait(plan)
    result.cache = BlaiForwardNpuCacheApplyResult(
      runnable: plan.runnable,
      configurable: plan.configurable,
      fits: plan.configurable,
      applied: plan.configurable)
    result.started = plan.configurable
    result.completed = plan.configurable
    result.status = if result.completed: npuOk else: npuTimeout
    result.completion = BlaiNpuCompletionWaitResult(
      configured: plan.configurable,
      started: plan.configurable,
      interruptObserved: result.completed,
      interruptCleared: result.completed,
      clockDisabled: plan.configurable,
      statusDecision: BlaiNpuCompletionStatusResult(
        configured: plan.configurable,
        interruptObserved: result.completed,
        completed: result.completed,
        status: result.status),
      status: result.status)
    result.outcome = BlaiForwardNpuExecuteOutcome(
      runnable: result.runnable,
      configurable: result.configurable,
      cacheFits: result.cache.fits,
      started: result.started,
      waitCompleted: result.completion.statusDecision.completed,
      completed: result.completed,
      status: result.status)

  proc failingForwardLayerExecutor(
      plan: BlaiForwardNpuRunPlan,
      layerIndex: uint32): BlaiForwardNpuExecuteResult =
    discard layerIndex
    result.runnable = plan.runnable
    result.configurable = plan.configurable
    result.waitPlan = blaiPlanForwardNpuCompletionWait(plan)
    result.cache = BlaiForwardNpuCacheApplyResult(
      runnable: plan.runnable,
      configurable: plan.configurable,
      fits: plan.configurable)
    result.started = plan.configurable
    result.status = npuTimeout
    result.completion = BlaiNpuCompletionWaitResult(
      configured: plan.configurable,
      started: plan.configurable,
      interruptObserved: false,
      interruptCleared: false,
      clockDisabled: plan.configurable,
      statusDecision: BlaiNpuCompletionStatusResult(
        configured: plan.configurable,
        interruptObserved: false,
        timedOut: plan.configurable,
        status: result.status),
      status: result.status)
    result.outcome = BlaiForwardNpuExecuteOutcome(
      runnable: result.runnable,
      configurable: result.configurable,
      cacheFits: result.cache.fits,
      started: result.started,
      waitCompleted: result.completion.statusDecision.completed,
      completed: result.completed,
      status: result.status)

  proc unexpectedForwardLayerExecutor(
      plan: BlaiForwardNpuRunPlan,
      layerIndex: uint32): BlaiForwardNpuExecuteResult =
    discard plan
    discard layerIndex
    doAssert false

  var sample: BlaiInstruction
  var unsupportedCompletionStatusInto: BlaiNpuCompletionStatusResult
  blaiNpuCompletionStatusInto(
    configured = false, interruptObserved = false,
    unsupportedCompletionStatusInto)
  let unsupportedCompletionStatus =
    blaiNpuCompletionStatusResult(configured = false,
                                  interruptObserved = false)
  doAssert unsupportedCompletionStatusInto == unsupportedCompletionStatus
  doAssert unsupportedCompletionStatus.unsupported
  doAssert not unsupportedCompletionStatus.timedOut
  doAssert not unsupportedCompletionStatus.completed
  doAssert unsupportedCompletionStatus.status == npuUnsupported
  let timeoutCompletionStatus =
    blaiNpuCompletionStatusResult(configured = true,
                                  interruptObserved = false)
  doAssert timeoutCompletionStatus.configured
  doAssert timeoutCompletionStatus.timedOut
  doAssert timeoutCompletionStatus.status == npuTimeout
  let okCompletionStatus =
    blaiNpuCompletionStatusResult(configured = true,
                                  interruptObserved = true)
  doAssert okCompletionStatus.completed
  doAssert okCompletionStatus.status == npuOk
  doAssert blaiNpuCompletionStatus(configured = false,
                                   interruptObserved = false) == npuUnsupported
  doAssert blaiNpuCompletionStatus(configured = true,
                                   interruptObserved = false) == npuTimeout
  doAssert blaiNpuCompletionStatus(configured = true,
                                   interruptObserved = true) == npuOk
  let runtimeOwnership = blaiNpuRuntimeOwnershipPlan()
  doAssert runtimeOwnership.initCreatesInterruptSemaphore
  doAssert runtimeOwnership.initCreatesExecutionMutex
  doAssert runtimeOwnership.initDisablesClock
  doAssert runtimeOwnership.sdkInterruptWait ==
    blaiNpuRuntimeWaitSdkCountingSemaphore
  doAssert runtimeOwnership.activeInterruptWait ==
    blaiNpuRuntimeWaitBareMetalPolling
  doAssert runtimeOwnership.sdkExecutionLock == blaiNpuRuntimeLockSdkMutex
  doAssert runtimeOwnership.activeExecutionLock ==
    blaiNpuRuntimeLockBareMetalSingleThread
  doAssert runtimeOwnership.forwardRunTakesExecutionLock
  doAssert runtimeOwnership.forwardRunReleasesExecutionLock
  doAssert runtimeOwnership.forwardRunStopsAfterInference
  let completionPlan = npuPlanCompletionWait(
    timeout = 17, configured = true,
    clearOnComplete = false, disableClockOnExit = false)
  doAssert completionPlan.configured
  doAssert completionPlan.timeout == 17
  doAssert not completionPlan.clearOnComplete
  doAssert not completionPlan.disableClockOnExit
  let completionStartPlan = blaiNpuCompletionStartPlan(completionPlan)
  var completionStartPlanInto: BlaiNpuCompletionStartPlan
  blaiNpuCompletionStartPlanInto(completionPlan, completionStartPlanInto)
  doAssert completionStartPlanInto == completionStartPlan
  doAssert completionStartPlan.waitPlan == completionPlan
  doAssert completionStartPlan.starts
  doAssert completionStartPlan.initialStatus.timedOut
  doAssert completionStartPlan.initialStatus.status == npuTimeout
  let blockedCompletionStartPlan =
    blaiNpuCompletionStartPlan(
      npuPlanCompletionWait(timeout = 19, configured = false))
  doAssert not blockedCompletionStartPlan.starts
  doAssert blockedCompletionStartPlan.initialStatus.unsupported
  doAssert blockedCompletionStartPlan.initialStatus.status == npuUnsupported
  let completedCompletionExitPlan =
    blaiNpuCompletionExitPlan(
      npuPlanCompletionWait(
        timeout = 23, configured = true,
        clearOnComplete = true, disableClockOnExit = true),
      interruptObserved = true)
  var completedCompletionExitPlanInto: BlaiNpuCompletionExitPlan
  blaiNpuCompletionExitPlanInto(
    completedCompletionExitPlan.waitPlan, interruptObserved = true,
    completedCompletionExitPlanInto)
  doAssert completedCompletionExitPlanInto == completedCompletionExitPlan
  doAssert completedCompletionExitPlan.valid
  doAssert completedCompletionExitPlan.clearInterrupt
  doAssert completedCompletionExitPlan.disableClock
  let timedOutCompletionExitPlan =
    blaiNpuCompletionExitPlan(
      npuPlanCompletionWait(
        timeout = 29, configured = true,
        clearOnComplete = true, disableClockOnExit = true),
      interruptObserved = false)
  doAssert timedOutCompletionExitPlan.valid
  doAssert not timedOutCompletionExitPlan.clearInterrupt
  doAssert timedOutCompletionExitPlan.disableClock
  let blockedCompletionExitPlan =
    blaiNpuCompletionExitPlan(
      npuPlanCompletionWait(timeout = 31, configured = false),
      interruptObserved = false)
  doAssert not blockedCompletionExitPlan.valid
  doAssert not blockedCompletionExitPlan.clearInterrupt
  let exhaustedPollTerminal =
    npuInterruptPollTerminalPlan(
      timeout = 5, polls = 5,
      interruptObserved = false, finalInterruptPending = false)
  var exhaustedPollTerminalInto: NpuInterruptPollTerminalPlan
  npuInterruptPollTerminalPlanInto(
    timeout = 5, polls = 5,
    interruptObserved = false, finalInterruptPending = false,
    exhaustedPollTerminalInto)
  doAssert exhaustedPollTerminalInto == exhaustedPollTerminal
  doAssert exhaustedPollTerminal.exhausted
  doAssert not exhaustedPollTerminal.completedBeforeBudget
  doAssert exhaustedPollTerminal.terminalMatchesBudget
  doAssert exhaustedPollTerminal.valid
  let completedPollTerminal =
    npuInterruptPollTerminalPlan(
      timeout = 5, polls = 3,
      interruptObserved = true, finalInterruptPending = true)
  doAssert not completedPollTerminal.exhausted
  doAssert completedPollTerminal.completedBeforeBudget
  doAssert completedPollTerminal.terminalMatchesBudget
  doAssert completedPollTerminal.valid
  let invalidPollTerminal =
    npuInterruptPollTerminalPlan(
      timeout = 5, polls = 6,
      interruptObserved = false, finalInterruptPending = false)
  doAssert not invalidPollTerminal.valid
  let unsupportedPollingPlan =
    blaiNpuPollingWaitEvidencePlan(
      BlaiNpuCompletionWaitResult(
        configured: false,
        timeout: 7,
        statusDecision: BlaiNpuCompletionStatusResult(
          configured: false,
          unsupported: true,
          status: npuUnsupported),
        status: npuUnsupported))
  var unsupportedPollingPlanInto: BlaiNpuPollingWaitEvidencePlan
  blaiNpuPollingWaitEvidencePlanInto(
    BlaiNpuCompletionWaitResult(
      configured: false,
      timeout: 7,
      statusDecision: BlaiNpuCompletionStatusResult(
        configured: false,
        unsupported: true,
        status: npuUnsupported),
      status: npuUnsupported),
    unsupportedPollingPlanInto)
  doAssert unsupportedPollingPlanInto == unsupportedPollingPlan
  doAssert unsupportedPollingPlan.terminal == blaiNpuPollingWaitUnsupported
  doAssert unsupportedPollingPlan.terminalMatchesStatus
  doAssert unsupportedPollingPlan.valid
  let timedOutPollingPlan =
    blaiNpuPollingWaitEvidencePlan(
      BlaiNpuCompletionWaitResult(
        configured: true,
        timeout: 5,
        started: true,
        poll: NpuInterruptPollResult(
          timeout: 5, polls: 5, exhausted: true,
          terminalMatchesBudget: true, valid: true),
        statusDecision: BlaiNpuCompletionStatusResult(
          configured: true,
          timedOut: true,
          status: npuTimeout),
        status: npuTimeout))
  doAssert timedOutPollingPlan.terminal == blaiNpuPollingWaitTimeout
  doAssert timedOutPollingPlan.budgetExhausted
  doAssert timedOutPollingPlan.budgetMatchesPolls
  doAssert timedOutPollingPlan.valid
  let completedPollingPlan =
    blaiNpuPollingWaitEvidencePlan(
      BlaiNpuCompletionWaitResult(
        configured: true,
        timeout: 5,
        started: true,
        interruptObserved: true,
        poll: NpuInterruptPollResult(
          timeout: 5, polls: 3, interruptObserved: true,
          finalInterruptPending: true, completedBeforeBudget: true,
          terminalMatchesBudget: true, valid: true),
        statusDecision: BlaiNpuCompletionStatusResult(
          configured: true,
          interruptObserved: true,
          completed: true,
          status: npuOk),
        status: npuOk))
  doAssert completedPollingPlan.terminal == blaiNpuPollingWaitInterruptObserved
  doAssert completedPollingPlan.completedBeforeBudget
  doAssert completedPollingPlan.budgetMatchesPolls
  doAssert completedPollingPlan.valid
  let unsupportedSideEffectPlan =
    blaiNpuCompletionSideEffectPlan(
      BlaiNpuCompletionWaitResult(
        configured: false,
        statusDecision: BlaiNpuCompletionStatusResult(
          configured: false,
          unsupported: true,
          status: npuUnsupported),
        status: npuUnsupported))
  var unsupportedSideEffectPlanInto: BlaiNpuCompletionSideEffectPlan
  blaiNpuCompletionSideEffectPlanInto(
    BlaiNpuCompletionWaitResult(
      configured: false,
      statusDecision: BlaiNpuCompletionStatusResult(
        configured: false,
        unsupported: true,
        status: npuUnsupported),
      status: npuUnsupported),
    unsupportedSideEffectPlanInto)
  doAssert unsupportedSideEffectPlanInto == unsupportedSideEffectPlan
  doAssert unsupportedSideEffectPlan.path ==
    blaiNpuCompletionSideEffectUnsupported
  doAssert unsupportedSideEffectPlan.noSideEffects
  doAssert unsupportedSideEffectPlan.valid
  let timedOutSideEffectPlan =
    blaiNpuCompletionSideEffectPlan(
      BlaiNpuCompletionWaitResult(
        configured: true,
        started: true,
        disableClockOnExit: true,
        clockDisabled: true,
