proc blaiParsedForwardConfiguredWorkspaceCompletionRouteTargetEvidenceInto*(
    frontier: BlaiParsedForwardConfiguredWorkspaceActiveRecoveryFrontierEvidence,
    signal: BlaiParsedForwardConfiguredWorkspaceCompletionSignalEvidence,
    binding: NpuInterruptBindingReadiness,
    outResult:
      var BlaiParsedForwardConfiguredWorkspaceCompletionRouteTargetEvidence) =
  ## Classify the concrete IRQ route target for resolving the active frontier.
  outResult =
    default(BlaiParsedForwardConfiguredWorkspaceCompletionRouteTargetEvidence)
  outResult.frontierValid = frontier.valid
  outResult.signalValid = signal.valid
  outResult.bindingValid =
    binding.corePolicy.valid and binding.operationPlan.valid
  outResult.apiContractValid = binding.apiContract.valid
  outResult.sdkRouteRequested =
    signal.sdkSemaphoreExpected and signal.sdkCnnIrqRequested and
      binding.requested and binding.enableRequested and binding.priorityMatchesSdk
  outResult.d0RoutePreserved =
    signal.d0BindingCandidate and binding.operationPlan.d0CandidatePreserved and
      binding.d0ApuLineCandidate
  outResult.m0PollingPreserved =
    frontier.activePolling and frontier.m0PollingRequired and
      binding.operationPlan.m0PollingPreserved and binding.activeWaitIsPolling
  outResult.localBindingDeferred =
    signal.bindingBlocksIrq and binding.operationPlan.activeOperationsSuppressed and
      not binding.bindingVerified and not binding.ready
  outResult.apiCallsDeferred =
    binding.apiContract.activeCallsDeferred and
      binding.apiContract.m0PollingPreserved and
      binding.apiContract.d0RoutePreserved
  outResult.activeOperationsSuppressed =
    binding.operationPlan.activeOperationsSuppressed
  npuInterruptBindingOperationReadinessInto(
    binding.operationPlan, outResult.operationReadiness)
  outResult.firstBlockedOperation = outResult.operationReadiness.firstBlock
  outResult.hasDeferredOperation =
    outResult.operationReadiness.hasDeferredOperation
  outResult.firstDeferredOperation =
    outResult.operationReadiness.firstDeferredOperation
  let routeGlb = npuInterruptGlbRouteMap(
    NpuInterruptConfig(
      irq: binding.lineOwnership.irq,
      preemptPriority: NpuCnnIrqPreemptPriority,
      subPriority: NpuCnnIrqSubPriority,
      enable: true))
  let routeMmAggregate = npuMmAggregateInterruptRouteEvidence(
    routeGlb, npuMmAggregateInterruptSnapshotFromRaw(0'u32, 0'u32, 0'u32, 0'u32))
  outResult.glbRouteValid = routeGlb.valid
  outResult.mmAggregateRouteValid = routeMmAggregate.valid
  outResult.mmAggregateSubrouteUnknown = routeMmAggregate.subrouteUnknown
  outResult.mmAggregatePollingPreserved = routeMmAggregate.pollingPreserved
  outResult.registerHandlerDeferred =
    not binding.operationPlan.registerHandlerPlanned
  outResult.clearPendingDeferred =
    not binding.operationPlan.clearPendingPlanned
  outResult.setPriorityDeferred =
    not binding.operationPlan.setPriorityPlanned
  outResult.enableIrqDeferred =
    not binding.operationPlan.enableIrqPlanned
  outResult.routeOperationsDeferred =
    outResult.activeOperationsSuppressed and outResult.registerHandlerDeferred and
      outResult.clearPendingDeferred and outResult.setPriorityDeferred and
      outResult.enableIrqDeferred
  outResult.routeMatchesFrontier =
    frontier.completionSignalMissing and outResult.sdkRouteRequested and
      outResult.d0RoutePreserved and outResult.m0PollingPreserved and
      outResult.localBindingDeferred and outResult.apiCallsDeferred and
      outResult.routeOperationsDeferred and outResult.glbRouteValid and
      outResult.mmAggregateRouteValid and outResult.mmAggregateSubrouteUnknown and
      outResult.mmAggregatePollingPreserved
  if not outResult.frontierValid:
    outResult.firstBlock =
      blaiParsedConfiguredCompletionRouteTargetFrontier
  elif not outResult.signalValid:
    outResult.firstBlock =
      blaiParsedConfiguredCompletionRouteTargetSignal
  elif not outResult.bindingValid:
    outResult.firstBlock =
      blaiParsedConfiguredCompletionRouteTargetBinding
  elif not outResult.apiContractValid:
    outResult.firstBlock =
      blaiParsedConfiguredCompletionRouteTargetApiContract
  elif not outResult.sdkRouteRequested:
    outResult.firstBlock =
      blaiParsedConfiguredCompletionRouteTargetSdkRoute
  elif not outResult.d0RoutePreserved:
    outResult.firstBlock =
      blaiParsedConfiguredCompletionRouteTargetD0Route
  elif not outResult.m0PollingPreserved:
    outResult.firstBlock =
      blaiParsedConfiguredCompletionRouteTargetM0Polling
  elif not outResult.localBindingDeferred:
    outResult.firstBlock =
      blaiParsedConfiguredCompletionRouteTargetLocalBinding
  elif not outResult.apiCallsDeferred:
    outResult.firstBlock =
      blaiParsedConfiguredCompletionRouteTargetApiCalls
  elif not outResult.routeOperationsDeferred:
    outResult.firstBlock =
      blaiParsedConfiguredCompletionRouteTargetOperations
  elif not outResult.glbRouteValid:
    outResult.firstBlock =
      blaiParsedConfiguredCompletionRouteTargetGlbRoute
  elif not outResult.mmAggregateRouteValid:
    outResult.firstBlock =
      blaiParsedConfiguredCompletionRouteTargetMmAggregateRoute
  elif not outResult.mmAggregateSubrouteUnknown:
    outResult.firstBlock =
      blaiParsedConfiguredCompletionRouteTargetMmAggregateSubroute
  elif not outResult.mmAggregatePollingPreserved:
    outResult.firstBlock =
      blaiParsedConfiguredCompletionRouteTargetMmAggregatePolling
  else:
    outResult.firstBlock =
      blaiParsedConfiguredCompletionRouteTargetNoBlock
  outResult.valid =
    outResult.frontierValid and outResult.signalValid and
      outResult.bindingValid and outResult.apiContractValid and
      outResult.routeMatchesFrontier

