proc blaiParsedForwardConfiguredWorkspaceOutputEquivalenceFrontierEvidenceInto*(
    route:
      BlaiParsedForwardConfiguredWorkspaceCompletionRouteTargetEvidence,
    routeAggregate:
      BlaiParsedForwardConfiguredWorkspaceActiveCompletionRouteAggregateEvidence,
    gap: BlaiParsedForwardConfiguredWorkspaceActiveCompletionGapEvidence,
    outputBlocked:
      BlaiParsedForwardConfiguredWorkspaceActiveOutputBlockedEvidence,
    outResult:
      var BlaiParsedForwardConfiguredWorkspaceOutputEquivalenceFrontierEvidence) =
  ## Classify the output-equivalence frontier behind the completion route.
  outResult =
    default(BlaiParsedForwardConfiguredWorkspaceOutputEquivalenceFrontierEvidence)
  outResult.routeTargetValid = route.valid
  outResult.routeAggregateValid = routeAggregate.valid
  outResult.gapValid = gap.valid
  outResult.outputBlockedValid = outputBlocked.valid
  outResult.completionRouteDeferred =
    route.localBindingDeferred and route.routeOperationsDeferred
  outResult.liveRouteDeferred =
    routeAggregate.routeMatchesLiveAggregate and
      routeAggregate.routeTargetDeferred
  outResult.currentGapIsCompletionSignal =
    gap.reason == blaiParsedConfiguredActiveGapCompletionSignal and
      gap.completionSignalMissing and not gap.outputEquivalencePending
  outResult.outputGateKnown =
    gap.outputGateKnown and outputBlocked.outputReadinessInvalid
  outResult.outputReadbackNotStarted =
    outputBlocked.workspaceOutputNotMoved and
      outputBlocked.workspaceOutputFirstBlockNone
  outResult.compareNotStarted =
    outputBlocked.validationFirstBlockNone and
      outputBlocked.modelValidationFirstBlockNone
  outResult.noOutputMismatchObserved =
    outputBlocked.zeroCounters and outputBlocked.noMismatch
  outResult.outputEquivalenceDeferred =
    outputBlocked.outputInvalid and outputBlocked.outputUnmatched and
      outResult.outputReadbackNotStarted and outResult.compareNotStarted and
      outResult.noOutputMismatchObserved
  outResult.outputEquivalenceNextAfterCompletion =
    route.routeMatchesFrontier and outResult.liveRouteDeferred and
      outResult.currentGapIsCompletionSignal and outResult.outputGateKnown and
      outResult.outputEquivalenceDeferred
  outResult.frontierMatchesEvidence =
    outResult.completionRouteDeferred and outResult.liveRouteDeferred and
      outResult.outputEquivalenceNextAfterCompletion
  outResult.valid =
    outResult.routeTargetValid and outResult.routeAggregateValid and outResult.gapValid and
      outResult.outputBlockedValid and outResult.frontierMatchesEvidence

