  outResult.routeTargetValid = route.valid
  outResult.routeAggregateValid = routeAggregate.valid
  outResult.outputScopeValid = outputScope.valid
  outResult.outputFrontierValid = outputFrontier.valid
  outResult.routeDeferred =
    route.localBindingDeferred and route.apiCallsDeferred and
      route.routeOperationsDeferred
  outResult.liveRouteAggregate =
    routeAggregate.routeMatchesLiveAggregate and
      routeAggregate.liveAggregateSnapshotValid and
      routeAggregate.routeTargetDeferred
  outResult.primaryOnlyOutput =
    outputScope.primaryOnly and outputScope.midOutputInactive and
      outputScope.midInvalidateInactive
  outResult.readbackReady =
    outputScope.scopeMatchesReadbackPlan and outputScope.primaryInvalidateActive
  outResult.outputEquivalenceDeferred =
