  timeout: uint32 = 5_000_000) =
  ## Stage input, execute with explicit layer buffers, then validate output.
  outResult = default(BlaiParsedForwardConfiguredWorkspaceFixtureResult)
  blaiBindForwardWorkspaceFixtureAddressInto(
    modelResources, workspaceBaseAddress,
    blaiForwardWorkspaceBufferBytes(workspaceBytes.len), outResult.binding)
  blaiForwardWorkspaceHardwareAddressReadinessInto(
    outResult.binding, outResult.hardwareAddresses)
  if not outResult.hardwareAddresses.ready:
