  let blockedLayerRunPlan = npuPlanLayerRun(false, timeout = 13)
  var blockedLayerRunPlanInto: NpuLayerRunPlan
  npuPlanLayerRunInto(false, timeout = 13, blockedLayerRunPlanInto)
  doAssert blockedLayerRunPlanInto == blockedLayerRunPlan
  doAssert blockedLayerRunPlan.readiness == blockedLayerRunReadiness
  doAssert blockedLayerRunPlan.firstBlock == npuLayerRunInstructionStream
  doAssert not blockedLayerRunPlan.runnable
  doAssert not blockedLayerRunPlan.waitPlan.configured
  doAssert blockedLayerRunPlan.waitPlan.timeout == 13
  let runnableLayerRunReadiness =
    npuLayerRunReadiness(true, timeout = 17)
  doAssert runnableLayerRunReadiness.runnable
  doAssert runnableLayerRunReadiness.timeout == 17
  doAssert runnableLayerRunReadiness.firstBlock == npuLayerRunNoBlock
  let runnableLayerRunPlan = npuPlanLayerRun(true, timeout = 17)
  doAssert runnableLayerRunPlan.readiness == runnableLayerRunReadiness
  doAssert runnableLayerRunPlan.firstBlock == npuLayerRunNoBlock
  doAssert runnableLayerRunPlan.runnable
  doAssert runnableLayerRunPlan.waitPlan.configured
  doAssert runnableLayerRunPlan.waitPlan.timeout == 17
  var generalCfgDecodeInto: NpuGeneralCfgDecode
  npuGeneralCfgDecodeFromRawInto(0'u32, generalCfgDecodeInto)
  let emptyGeneralCfgDecode = npuGeneralCfgDecodeFromRaw(0'u32)
  doAssert generalCfgDecodeInto == emptyGeneralCfgDecode
  doAssert not emptyGeneralCfgDecode.unsignedInput
  doAssert emptyGeneralCfgDecode.imageInputModeKnown
  doAssert emptyGeneralCfgDecode.imageInputMode == npuInputSound
  doAssert emptyGeneralCfgDecode.activationTableIndexBase == 0'u32
  doAssert emptyGeneralCfgDecode.activationTableDataBase == 0'u32
  doAssert not emptyGeneralCfgDecode.axiWriteIdle
  doAssert not emptyGeneralCfgDecode.axiReadIdle
  doAssert emptyGeneralCfgDecode.busy
  let fullGeneralCfgDecode =
    npuGeneralCfgDecodeFromRaw(
      BlaiImgiUnsignMask or BlaiImageModeMask or
        npuPlanActivationTableBases(0x12'u32, 0x2A'u32).encoded or
        BlaiAxiWriteIdleMask or BlaiAxiReadIdleMask)
  doAssert fullGeneralCfgDecode.unsignedInput
  doAssert not fullGeneralCfgDecode.imageInputModeKnown
  doAssert fullGeneralCfgDecode.imageInputModeBits == 3'u32
  doAssert fullGeneralCfgDecode.activationTableIndexBase == 0x12'u32
  doAssert fullGeneralCfgDecode.activationTableDataBase == 0x2A'u32
  doAssert fullGeneralCfgDecode.axiWriteIdle
  doAssert fullGeneralCfgDecode.axiReadIdle
  doAssert not fullGeneralCfgDecode.busy
  var activationBaseRegisterInto: NpuActivationTableBaseRegisterPlan
  npuActivationTableBaseRegisterPlanInto(
    BlaiImgiUnsignMask or BlaiImageModeMask or BlaiAxiWriteIdleMask,
    npuPlanActivationTableBases(0x12'u32, 0x2A'u32),
    activationBaseRegisterInto)
  let activationBaseRegister =
    npuActivationTableBaseRegisterPlan(
      BlaiImgiUnsignMask or BlaiImageModeMask or BlaiAxiWriteIdleMask,
      npuPlanActivationTableBases(0x12'u32, 0x2A'u32))
  doAssert activationBaseRegisterInto == activationBaseRegister
  doAssert activationBaseRegister.valid
  doAssert activationBaseRegister.preservesOtherFields
  doAssert activationBaseRegister.decoded.activationTableIndexBase == 0x12'u32
  doAssert activationBaseRegister.decoded.activationTableDataBase == 0x2A'u32
  doAssert (activationBaseRegister.encodedGeneralCfg and
    (BlaiImgiUnsignMask or BlaiImageModeMask or BlaiAxiWriteIdleMask)) ==
    (BlaiImgiUnsignMask or BlaiImageModeMask or BlaiAxiWriteIdleMask)
  let firstActivationEntry = npuActivationTableEntryCursor(0)
  doAssert firstActivationEntry.valid
  doAssert firstActivationEntry.entryIndex == 0
  doAssert firstActivationEntry.shift == 0'u32
  doAssert npuActivationTableEntryByte(
    0x4433_2211'u32, firstActivationEntry) == 0x11'u8
  let lastActivationEntry = npuActivationTableEntryCursor(3)
  doAssert lastActivationEntry.valid
  doAssert lastActivationEntry.entryIndex == 3
  doAssert lastActivationEntry.shift == 24'u32
  doAssert npuActivationTableEntryByte(
    0x4433_2211'u32, lastActivationEntry) == 0x44'u8
  doAssert not npuActivationTableEntryCursor(-1).valid
  doAssert not npuActivationTableEntryCursor(
    BlaiActivationTableEntriesPerWord).valid
  var mergedActivationWord = 0'u32
  npuMergeActivationTableEntry(mergedActivationWord, 0x11'u8,
    firstActivationEntry)
  npuMergeActivationTableEntry(mergedActivationWord, 0x44'u8,
    lastActivationEntry)
  doAssert mergedActivationWord == 0x4400_0011'u32
  let activationWord = npuPlanActivationTableWord(
    3'u32, 0x11'u8, 0x22'u8, 0x33'u8, 0x44'u8)
  doAssert activationWord.valid
  doAssert activationWord.firstEntryIndex == 12'u32
  doAssert activationWord.registerOffset == 0x10C'u32
  doAssert activationWord.encoded == 0x4433_2211'u32
  let decodedActivationWord =
    npuActivationTableWordFromRaw(3'u32, 0x4433_2211'u32)
  doAssert decodedActivationWord.entries == activationWord.entries
  doAssert decodedActivationWord.encoded == activationWord.encoded
  var busyStatusInto: NpuBusyStatusResult
  npuBusyStatusFromGeneralCfgInto(0'u32, busyStatusInto)
  let bothBusyStatus = npuBusyStatusFromGeneralCfg(0'u32)
  doAssert busyStatusInto == bothBusyStatus
  doAssert not bothBusyStatus.axiWriteIdle
  doAssert not bothBusyStatus.axiReadIdle
  doAssert bothBusyStatus.busy
  let writeIdleBusyStatus =
    npuBusyStatusFromGeneralCfg(BlaiAxiWriteIdleMask)
  doAssert writeIdleBusyStatus.axiWriteIdle
  doAssert not writeIdleBusyStatus.axiReadIdle
  doAssert writeIdleBusyStatus.busy
  let readIdleBusyStatus =
    npuBusyStatusFromGeneralCfg(BlaiAxiReadIdleMask)
  doAssert not readIdleBusyStatus.axiWriteIdle
  doAssert readIdleBusyStatus.axiReadIdle
  doAssert readIdleBusyStatus.busy
  let idleBusyStatus =
    npuBusyStatusFromGeneralCfg(BlaiAxiWriteIdleMask or BlaiAxiReadIdleMask)
  doAssert idleBusyStatus.axiWriteIdle
  doAssert idleBusyStatus.axiReadIdle
  doAssert not idleBusyStatus.busy
  var blaiCommandStatusInto: NpuBlaiCommandStatusResult
  npuBlaiCommandStatusFromRawInto(
    BlaiCommandModeMask or 0x1234'u32,
    BlaiLimiterModeMask or 0x0042'u32,
    0x0007'u32,
    blaiCommandStatusInto)
  let blaiCommandStatus = npuBlaiCommandStatusFromRaw(
    BlaiCommandModeMask or 0x1234'u32,
    BlaiLimiterModeMask or 0x0042'u32,
    0x0007'u32)
  doAssert blaiCommandStatusInto == blaiCommandStatus
  doAssert blaiCommandStatus.valid
  doAssert blaiCommandStatus.mmCommandCount == 0x1234'u32
  doAssert blaiCommandStatus.mmCommandMode
  doAssert blaiCommandStatus.readCommandCount == 0x42'u32
  doAssert blaiCommandStatus.readCommandMode
  doAssert blaiCommandStatus.writeCommandCount == 0x7'u32
  doAssert not blaiCommandStatus.writeCommandMode
  doAssert blaiCommandStatus.anyCommandMode
  doAssert blaiCommandStatus.anyCommandCount
  let emptyBlaiCommandStatus = npuBlaiCommandStatusFromRaw(0'u32, 0'u32, 0'u32)
  doAssert emptyBlaiCommandStatus.valid
  doAssert not emptyBlaiCommandStatus.anyCommandMode
  doAssert not emptyBlaiCommandStatus.anyCommandCount

  let unsupportedCompletion = npuWaitForCompletion(
    npuPlanCompletionWait(timeout = 3, configured = false))
  var unsupportedCompletionInto: BlaiNpuCompletionWaitResult
  npuWaitForCompletionInto(
    npuPlanCompletionWait(timeout = 3, configured = false),
    unsupportedCompletionInto)
  doAssert unsupportedCompletionInto == unsupportedCompletion
  doAssert not unsupportedCompletion.configured
  doAssert unsupportedCompletion.timeout == 3
  doAssert unsupportedCompletion.clearOnComplete
  doAssert unsupportedCompletion.disableClockOnExit
  doAssert not unsupportedCompletion.started
  doAssert unsupportedCompletion.statusDecision.unsupported
  doAssert unsupportedCompletion.statusDecision.status == npuUnsupported
  doAssert unsupportedCompletion.status == npuUnsupported

  let blockedCompletion = blaiPlanForwardNpuCompletionWait(
    BlaiForwardNpuRunPlan(), timeout = 29)
  let blockedForwardRun = blaiExecuteForwardNpuRun(
    BlaiForwardNpuRunPlan(), blockedCompletion)
  var blockedForwardRunInto: BlaiForwardNpuExecuteResult
  blaiExecuteForwardNpuRunInto(
    BlaiForwardNpuRunPlan(), blockedCompletion, blockedForwardRunInto)
  doAssert blockedForwardRunInto == blockedForwardRun
  let blockedForwardRunOutcome = blaiForwardNpuExecuteOutcome(blockedForwardRun)
  var blockedForwardRunOutcomeInto: BlaiForwardNpuExecuteOutcome
  blaiForwardNpuExecuteOutcomeInto(blockedForwardRun, blockedForwardRunOutcomeInto)
  doAssert blockedForwardRunOutcomeInto == blockedForwardRunOutcome
  doAssert blockedForwardRun.outcome == blockedForwardRunOutcome
  doAssert blockedForwardRun.waitPlan == blockedCompletion
  doAssert blockedForwardRun.waitPlan.timeout == 29
  doAssert blockedForwardRun.runtimeOwnership == blaiNpuRuntimeOwnershipPlan()
  doAssert not blockedForwardRun.stopped
  doAssert not blockedForwardRun.runnable
  doAssert not blockedForwardRun.outcome.runnable
  doAssert not blockedForwardRun.outcome.stopped
  doAssert not blockedForwardRun.outcome.completed
  doAssert blockedForwardRun.status == npuUnsupported

  var invalidConfiguredLayers = [
    BlaiCpuInstLayer64(npuOn: 1, layerType: ord(blaiConvolutional).int32)]
  let invalidConfiguredResources = BlaiForwardModelResourcePlan(supported: true)
  let invalidConfiguredWorkspace = BlaiForwardModelWorkspacePlan()
  let invalidConfiguredExecution = blaiExecuteForwardModelConfigured(
    invalidConfiguredLayers, invalidConfiguredResources,
    invalidConfiguredWorkspace, timeout = 31)
  var invalidConfiguredExecutionInto: BlaiForwardModelExecuteResult
  blaiExecuteForwardModelConfiguredInto(
    invalidConfiguredLayers, invalidConfiguredResources,
    invalidConfiguredWorkspace, invalidConfiguredExecutionInto, timeout = 31)
  doAssert invalidConfiguredExecutionInto == invalidConfiguredExecution
  doAssert invalidConfiguredExecution.completion ==
    blaiForwardModelExecuteCompletion(invalidConfiguredExecution)
  doAssert not invalidConfiguredExecution.completion.completed
  doAssert invalidConfiguredExecution.allCompleted ==
    invalidConfiguredExecution.completion.completed
  doAssert not invalidConfiguredExecution.runnable
  doAssert invalidConfiguredExecution.layerStorageFits
  doAssert invalidConfiguredExecution.firstBlock ==
    blaiForwardModelExecuteRunSequence
  doAssert invalidConfiguredExecution.runSequenceFirstBlock ==
    blaiForwardModelRunSequenceReadiness
  doAssert invalidConfiguredExecution.expectedLayerCount == 0
  doAssert invalidConfiguredExecution.missingLayerCount == 0
  doAssert invalidConfiguredExecution.attemptedLayerCount == 0
  doAssert not invalidConfiguredExecution.firstFailedExecutionCaptured

  var invalidConfiguredStates = [
    BlaiCpuParsedLayerState(
      active: true, index: 0, layer: invalidConfiguredLayers[0])]
  let invalidConfiguredStateExecution = blaiExecuteForwardModelConfigured(
    invalidConfiguredStates, invalidConfiguredResources,
    invalidConfiguredWorkspace, timeout = 37)
  var invalidConfiguredStateExecutionInto: BlaiForwardModelExecuteResult
  blaiExecuteForwardModelConfiguredInto(
    invalidConfiguredStates, invalidConfiguredResources,
    invalidConfiguredWorkspace, invalidConfiguredStateExecutionInto,
    timeout = 37)
  doAssert invalidConfiguredStateExecutionInto == invalidConfiguredStateExecution
  doAssert invalidConfiguredStateExecution.completion ==
    blaiForwardModelExecuteCompletion(invalidConfiguredStateExecution)
  doAssert not invalidConfiguredStateExecution.completion.completed
  doAssert invalidConfiguredStateExecution.allCompleted ==
    invalidConfiguredStateExecution.completion.completed
  doAssert not invalidConfiguredStateExecution.runnable
  doAssert invalidConfiguredStateExecution.layerStorageFits
  doAssert invalidConfiguredStateExecution.firstBlock ==
    blaiForwardModelExecuteRunSequence
  doAssert invalidConfiguredStateExecution.runSequenceFirstBlock ==
    blaiForwardModelRunSequenceReadiness
  doAssert invalidConfiguredStateExecution.expectedLayerCount == 0
  doAssert invalidConfiguredStateExecution.missingLayerCount == 0
  doAssert invalidConfiguredStateExecution.attemptedLayerCount == 0
  doAssert not invalidConfiguredStateExecution.firstFailedExecutionCaptured
